# Who does each step. Every session is a node: the hubnode (the owner's) or a subnode, which
# takes one role on one job. Settings are numbers the tool maps to its own models and efforts:
# tier 1 is the tool's best model, a higher number a lesser one; effort 0 is its highest, each
# number up one level lower. Effort 0 is left unused so a repo can raise any role. Overridden
# per repo by config.json's "roles", each with a reason, never per task: a model would be
# choosing its own budget. "session" is where the role runs, as README's drawing says it.
ROLES = {
    "spec":   {"session": "new session", "tier": 2, "effort": 2, "steps": ["spec", "consolidate"]},
    # Before any diff exists; it ends with the spec for what it found.
    "bug":    {"session": "new session", "tier": 2, "effort": 1, "steps": ["bug"],
               "then": "the spec for what it found"},
    # One session keeps the build through every fix and sync.
    "work":   {"session": "one session per job", "tier": 2, "effort": 3, "steps": ["work", "handoff", "fix", "sync"]},
    # Always a fresh session: a reviewer who saw the build judges what it meant, not what it did.
    "review": {"session": "fresh session", "tier": 2, "effort": 2, "steps": ["review-work", "review-change"], "fresh": True},
    # Fixed commands: the complete suite (before a release too), its trace, a survey.
    "check":  {"session": "new session", "tier": 3, "effort": 4, "steps": ["check", "trace", "survey"]},
}
# The hubnode's steps are no role's: it runs at the owner's settings, which should be at least
# HUBNODE_FLOOR, ranked tier first, then effort. `jig roles --from` says so when the hubnode's
# own settings, which it maps from the tiers map, rank lower; jig can't see a session's model.
HUBNODE_STEPS = ["assign", "gate", "merge", "release", "push", "publish"]
HUBNODE_FLOOR = {"tier": 2, "effort": 1}
# A workflow is its steps with the link before each: "→" goes to a session that already
# exists (the same one, the hubnode, the job's work session); "⇢" starts a new one. A
# capitalized step is a nested workflow; "a + b" is two steps one session takes in turn.
FLOWS = {
    "Job": {"steps": "spec ⇢ work ⇢ review-work → handoff → gate ⇢ check → merge",
            "trigger": "`jig open`", "controls": "merge only on the owner's word"},
    "Fix": {"steps": "work ⇢ review-change → handoff",
            "trigger": "a review with blocking findings",
            "controls": "three strikes: a job's third blocking review starts Bug"},
    "Sync": {"steps": "work ⇢ review-change → handoff",
             "trigger": "a sync with a hand-resolved conflict", "controls": "a clean sync needs nothing"},
    "Bug": {"steps": "bug → spec ⇢ Job",
            "trigger": "a job's third blocking review, a feedback group, or the owner's `/jig:bug`",
            "controls": "never on a session's own reading that something is broken"},
    "Feedback": {"steps": "consolidate ⇢ bug + spec → consolidate ⇢ Job",
                 "trigger": "staged feedback, in the jig repo",
                 "controls": "one bug + spec per group; overlaps answered before any job opens"},
    "Batch": {"steps": "gate → merge ⇢ check → trace", "trigger": "two or more gated jobs",
              "controls": "one check on trunk; a failure is traced to its merge, then Fix on that job"},
    "Release": {"steps": "check → release → push → publish", "trigger": "the owner's word",
                "controls": "refused while a batch check is owed; push and publish only on the owner's word"},
    "Survey": {"steps": "survey ⇢ spec ⇢ Jobs", "trigger": "`/jig:survey`, `/jig:adopt`, `/jig:update`",
               "controls": ""},
    "Redocument": {"steps": "spec ⇢ Jobs ⇢ Batch ⇢ Job", "trigger": "`/jig:redocument`",
                   "controls": "the spec is the remap; the last job is the cleanup"},
}
# Whatever the config says. Everything else the hubnode may propose to change, with a reason,
# and applies only on the owner's yes.
FIXED_RULES = ["the owner's word before merge, push and publish",
               "a fresh session for every review",
               "a complete check before a release"]
# A job's blocking reviews (strikes), its first review-work counted, before Bug runs and the
# next review is refused: the owner counts failures, not the fix rounds between them.
STRIKES = 3
# The pre-roles step names, which `jig workflow` still prints for skills that read them.
# The pre-roles config key, `workflow`, is never read: an entry carries no reason, so nothing
# tells a one-run instruction written into it from the owner's choice, and update removes it.
OLD_STEPS = {"spec": "spec", "bug": "bug", "execute": "work", "review": "review",
             "recheck": "review", "check": "check"}
WORKFLOW_IGNORED = (f"note: `workflow` in .jig/config.json is not read: `jig update --apply` "
                    "removes it, and jig's standard (or `roles`) is in effect")


# ---------------------------------------------------------------- git helpers

def cwd_env(cwd) -> dict | None:
    """The environment for a git call in another checkout: inside a hook git exports GIT_DIR and
    GIT_INDEX_FILE, which would point that call back at the repo the hook runs for."""
    hooked = ("GIT_DIR", "GIT_INDEX_FILE", "GIT_WORK_TREE")
    if cwd is None or not any(k in os.environ for k in hooked):
        return None
    # The hook's own repo keeps them: its index may be a commit's temporary one.
    if Path(cwd).resolve().is_relative_to(main_root().resolve()):
        return None
    return {k: v for k, v in os.environ.items() if k not in hooked}


def git(*args: str, check: bool = False, cwd: str | None = None) -> str:
    # A tracked file may be in any encoding, and git hands its bytes back as they are. jig only
    # matches ASCII ids, paths and headings here, so a byte it can't decode becomes U+FFFD
    # rather than a crash. Text jig writes back into a file is read with git_raw instead.
    p = subprocess.run(["git", *args], capture_output=True, text=True, errors="replace", cwd=cwd, env=cwd_env(cwd))
    if check and p.returncode:
        die(f"git {' '.join(args)}: {p.stderr.strip()}", 2)
    return p.stdout.strip()


def grep_hits(*args: str, cwd: str | Path | None = None) -> list[tuple[str, str, str]]:
    """`git grep -n --null ARGS` as (path, line number, line text). Read as bytes and split on
    newlines only: text mode turns a lone CR into a line break, and splitlines() also breaks on
    form feeds and other separators a matched line may hold."""
    raw = git_raw("grep", "-n", "--null", *args, cwd=cwd)
    return [tuple(h.split("\0", 2)) for h in raw.split("\n") if h.count("\0") >= 2]


def git_raw(*args: str, errors: str = "replace", cwd: str | Path | None = None) -> str:
    """git's stdout as it is: no newline translation (text mode turns a lone CR or a CRLF into
    a line break) and nothing stripped. errors="surrogateescape" keeps bytes that aren't UTF-8,
    for text that write_raw puts back into a file unchanged."""
    return subprocess.run(["git", *args], capture_output=True, cwd=cwd, env=cwd_env(cwd)).stdout.decode(errors=errors)


def read_raw(path: Path) -> str:
    """PATH's text for jig to edit and write back with write_raw: its bytes and line endings kept."""
    return path.read_bytes().decode(errors="surrogateescape")


def write_raw(path: Path, text: str) -> None:
    path.write_bytes(text.encode(errors="surrogateescape"))


def die(msg: str, code: int = 1) -> None:
    print(f"jig: {msg}", file=sys.stderr)
    sys.exit(code)


def repo_root() -> Path:
    top = git("rev-parse", "--show-toplevel")
    if not top:
        die("not a git repository", 2)
    return Path(top)


def main_root() -> Path:
    """The primary checkout's root, even when called from a linked worktree."""
    common = Path(git("rev-parse", "--path-format=absolute", "--git-common-dir"))
    return common.parent


def worktrees_dir() -> str:
    """Where jobs are checked out, relative to the primary checkout. Inside .git/ because
    a worktree is git state, and tools that walk the repo (test runners, globbers) never
    look there — a visible folder would hand them every job's full copy of the repo."""
    common = Path(git("rev-parse", "--path-format=absolute", "--git-common-dir"))
    return Path(os.path.relpath(common / "jig" / "worktrees", main_root())).as_posix()


def is_main_worktree(root: Path) -> bool:
    """True in the primary checkout, false in a linked worktree."""
    return main_root().resolve() == root.resolve()


def glob_re(pattern: str) -> re.Pattern[str]:
    out, i = "", 0
    while i < len(pattern):
        c = pattern[i]
        if pattern.startswith("**/", i):
            out, i = out + "(?:.*/)?", i + 3
        elif pattern.startswith("**", i):
            out, i = out + ".*", i + 2
        elif c == "*":
            out, i = out + "[^/]*", i + 1
        elif c == "?":
            out, i = out + "[^/]", i + 1
        else:
            out, i = out + re.escape(c), i + 1
    return re.compile(f"^{out}$")


def matches(path: str, patterns: list[str]) -> bool:
    return any(glob_re(p).match(path) for p in patterns)


# ---------------------------------------------------------------------- board

def read_docmap_text(root: Path) -> str:
    p = root / DOCMAP
    return p.read_text(errors="replace") if p.is_file() else ""


def with_docmap(config: dict, raw: str) -> dict:
    """CONFIG with the docmap file's keys laid over it. A config.json still holding them, in a
    repo `jig update --apply` hasn't moved yet, keeps working until it does."""
    try:
        dm = json.loads(raw) if raw.strip() else {}
    except ValueError:
        dm = {}
    if isinstance(dm, dict):
        config.update({k: v for k, v in dm.items() if k in DOCMAP_KEYS})
    return config


def docmap_json(data: dict) -> str:
    """The docmap file as jig writes it: keys sorted, so two jobs' hand edits merge as text."""
    return json.dumps({k: data[k] for k in sorted(data)}, indent=2, sort_keys=True) + "\n"


def save_docmap(root: Path, data: dict) -> None:
    """Write DATA's docmap keys to the docmap file, over what it holds."""
    have = {}
    try:
        have = json.loads(read_docmap_text(root) or "{}")
    except ValueError:
        pass
    have = have if isinstance(have, dict) else {}
    have.update({k: data[k] for k in DOCMAP_KEYS if k in data})
    (root / DOCMAP).write_text(docmap_json(have))


def save_board(root: Path, data: dict) -> None:
    """Write and stage the board's config and the docmap DATA holds, each in its own file."""
    (root / CONFIG).parent.mkdir(parents=True, exist_ok=True)
    (root / CONFIG).write_text(json.dumps(config_only(data), indent=2) + "\n")
    save_docmap(root, data)
    git("add", "--", CONFIG, DOCMAP, check=True)


def config_docmap_keys(root: Path) -> list[str]:
    """The docmap keys config.json still holds, in a repo `jig update --apply` hasn't moved."""
    try:
        cfg = json.loads((root / CONFIG).read_text())
    except (OSError, ValueError):
        return []
    return [k for k in DOCMAP_KEYS if isinstance(cfg, dict) and k in cfg]


def docmap_conflicts(root: Path) -> list[str]:
    """Each key config.json and the docmap file both hold with different values: moving one
    over the other would lose a map, so the owner says which stands."""
    try:
        cfg = json.loads((root / CONFIG).read_text())
        dm = json.loads(read_docmap_text(root) or "{}")
    except (OSError, ValueError):
        return []
    return [k for k in DOCMAP_KEYS if k in cfg and k in dm and cfg[k] != dm[k]]


def docmap_in_config(root: Path) -> bool:
    """Whether config.json still holds a key the docmap file holds now, or there is no docmap file."""
    try:
        cfg = json.loads((root / CONFIG).read_text())
    except (OSError, ValueError):
        return False
    return not (root / DOCMAP).is_file() or any(k in cfg for k in DOCMAP_KEYS)


def board_moves_docmap(root: Path) -> bool:
    return (root / CONFIG).is_file() and docmap_in_config(root)


def config_only(data: dict) -> dict:
    """DATA without the docmap's keys: what config.json holds."""
    return {k: v for k, v in data.items() if k not in DOCMAP_KEYS}


def docmap_problems(raw: str) -> list[str]:
    """Why the docmap file can't be committed: a key jig doesn't know (hand-made fields aren't
    allowed), or a value of another shape than the one each key reads."""
    try:
        dm = json.loads(raw)
    except ValueError as e:
        return [f"{DOCMAP} is not JSON: {e}"]
    if not isinstance(dm, dict):
        return [f"{DOCMAP} is not a JSON object"]
    out = [f"{DOCMAP}: `{k}` is not a docmap key; it holds only {', '.join(DOCMAP_KEYS)}"
           for k in dm if k not in DOCMAP_KEYS]
    strs = lambda v: isinstance(v, list) and all(isinstance(x, str) for x in v)
    shape = {
        "docmap": (lambda v: isinstance(v, dict) and all(strs(g) for g in v.values()),
                   "an object mapping each page to a list of globs"),
        "not_docs": (strs, "a list of globs"),
        "deep_subsystems": (lambda v: isinstance(v, dict) and all(isinstance(x, str) for x in v.values()),
                            "an object mapping each folder to its rationale"),
        "boards": (strs, "a list of page paths"),
    }
    out += [f"{DOCMAP}: `{k}` must be {why}" for k, (ok, why) in shape.items()
            if k in dm and not ok(dm[k])]
    return out


class Board:
    """The config and the open jobs, read together: every rule needs both."""
    def __init__(self, root: Path, data: dict, jobs: dict):
        self.root, self.data, self.jobs = root, data, jobs

    @classmethod
    def load(cls, root: Path, *, working_tree: bool = False) -> "Board":
        """Read the board from TRUNK by default, so a branch cannot edit the rules
        it is judged by. working_tree=True is for the hubnode, who writes it."""
        base = main_root()
        if not working_tree:
            trunk = cls.trunk_name(base)
            raw = git("show", f"{trunk}:{CONFIG}")
            if raw:
                return cls(base, with_docmap(json.loads(raw), git("show", f"{trunk}:{DOCMAP}")),
                           json.loads(git("show", f"{trunk}:{JOBS}") or "{}"))
        if not (base / CONFIG).exists():
            old = old_board(base)
            die(f"an older jig's board is at {old}: run /jig:update first" if old
                else f"no board at {CONFIG}. Run: jig init", 2)
        jobs = base / JOBS
        return cls(base, with_docmap(json.loads((base / CONFIG).read_text()), read_docmap_text(base)),
                   json.loads(jobs.read_text()) if jobs.exists() else {})

    @staticmethod
    def trunk_name(root: Path) -> str:
        p = root / CONFIG
        if p.exists():
            try:
                return json.loads(p.read_text()).get("trunk", "main")
            except Exception:
                pass
        return "main"

    def save(self) -> None:
        """Only the jobs: nothing the hubnode does day to day changes the config."""
        (self.root / JOBS).write_text(json.dumps(self.jobs, indent=2) + "\n")

    @property
    def trunk(self) -> str:
        return self.data.get("trunk", "main")

    def open_jobs(self) -> dict:
        return self.jobs        # a merge deletes the entry, so every one is open

    # A job's branch is its name and its worktree is under .git/jig/worktrees/. Only a job
    # adopted on another branch, or checked out elsewhere, stores the value that differs.
    def branch(self, name: str) -> str:
        return (self.jobs.get(name) or {}).get("branch") or name

    def worktree(self, name: str) -> str:
        return (self.jobs.get(name) or {}).get("worktree") or f"{worktrees_dir()}/{self.branch(name)}"

    def job_for_branch(self, branch: str) -> tuple[str, dict] | tuple[None, None]:
        for name, job in self.jobs.items():
            if self.branch(name) == branch:
                return name, job
        return None, None


# ------------------------------------------------------------- roles and flows

def flow_steps(flow: str) -> list[tuple[str, str]]:
    """FLOW's steps in order, each with the link that leads to it ("" for the first)."""
    parts = re.split(r"\s+(→|⇢)\s+", FLOWS[flow]["steps"])
    return [("", parts[0])] + list(zip(parts[1::2], parts[2::2]))


def step_owner(step: str) -> str:
    """The node or role that does STEP; "" for a nested workflow (Job, Jobs, Batch)."""
    if step in HUBNODE_STEPS:
        return "hubnode"
    for role, r in ROLES.items():
        if step in r["steps"]:
            return role
    return ""


def role_overrides(config: dict) -> tuple[str, dict, list[str]]:
    """The config's overrides as (key, {role: entry}, problems): `roles` only."""
    over = config.get("roles") or {}
    if not isinstance(over, dict):
        return "roles", {}, ['roles: must map role names to {"tier": N, "effort": N, "reason": "..."}']
    return "roles", over, []


def role_settings(config: dict) -> tuple[dict, list[str]]:
    """Each role's tier and effort in effect, and every way the override breaks the rules. Work
    is judged against the spec it builds from; review needs a model at least as good as the one
    whose work it judges (its effort is the owner's call); a bug investigation writes a spec, so
    it gets at least the spec's budget. A `roles` entry says why it departs from the default."""
    roles = {k: {"tier": v["tier"], "effort": v["effort"]} for k, v in ROLES.items()}
    key, over, bad = role_overrides(config)
    for role, vals in over.items():
        if role not in roles:
            bad.append(f"{key}.{role}: no such role; the roles are {', '.join(roles)}")
            continue
        if not isinstance(vals, dict):
            bad.append(f"{key}.{role}: must be {{\"tier\": N, \"effort\": N, \"reason\": \"...\"}}")
            continue
        if key == "roles" and not (isinstance(vals.get("reason"), str) and vals["reason"].strip()):
            bad.append(f"roles.{role}: no reason: say why this repo departs from the default")
        for k, v in vals.items():
            least = {"tier": 1, "effort": 0}.get(k)
            if k == "reason":
                continue
            if k in ("fresh", "session", "steps", "then"):
                why = FIXED_RULES[1] if k == "fresh" or (role == "review" and k == "session") else \
                    "where a role runs and which steps it owns are jig's, not a repo's"
                bad.append(f"{key}.{role}.{k}: fixed whatever the config says: {why}")
            elif least is None:
                bad.append(f"{key}.{role}.{k}: only tier, effort and reason are set")
            elif type(v) is not int or v < least:
                bad.append(f"{key}.{role}.{k}: {v!r} is not a whole number from {least} up")
            else:
                roles[role][k] = v
    # A raised spec raises bug with it: an investigation that writes a spec never gets less.
    for k in ("tier", "effort"):
        if k not in (over.get("bug") or {}):
            roles["bug"][k] = min(roles["bug"][k], roles["spec"][k])
    sp, bg, wk, rv = roles["spec"], roles["bug"], roles["work"], roles["review"]
    lower = " (a higher number is a lower effort)"
    if bg["tier"] > sp["tier"]:
        bad.append(f"{key}.bug: tier {bg['tier']} is below the spec's tier {sp['tier']}")
    if bg["effort"] > sp["effort"]:
        bad.append(f"{key}.bug: effort {bg['effort']} is lower than the spec's "
                   f"effort {sp['effort']}{lower}")
    if wk["tier"] < sp["tier"]:
        bad.append(f"{key}.work: tier {wk['tier']} is above the spec's tier {sp['tier']}")
    if wk["effort"] <= sp["effort"]:
        bad.append(f"{key}.work: effort {wk['effort']} is not below the spec's "
                   f"effort {sp['effort']}{lower}")
    if rv["tier"] > wk["tier"]:
        bad.append(f"{key}.review: tier {rv['tier']} is below work's tier {wk['tier']}")
    return roles, bad


def settings_or_refuse(root: Path) -> dict:
    # The working tree's config, so the hubnode sees a refusal before committing the edit.
    data = Board.load(root, working_tree=True).data
    roles, bad = role_settings(data)
    if "workflow" in data:
        print(WORKFLOW_IGNORED, file=sys.stderr)
    # Refused, nothing goes to stdout: a skill copying the roles into a spec must get none.
    for b in bad:
        print(b, file=sys.stderr)
    if bad:
        sys.exit(1)
    return roles


def role_lines(roles: dict) -> str:
    return "\n".join(f"{k}: tier {v['tier']}, effort {v['effort']}" for k, v in roles.items())


def flow_lines() -> str:
    def label(step: str) -> str:
        return f"{step} ({step_owner(step)})" if step_owner(step) else step
    out = []
    for name, f in FLOWS.items():
        steps = " ".join(f"{link} {' + '.join(map(label, part.split(' + ')))}".strip()
                         for link, part in flow_steps(name))
        out.append(f"{name}: {steps}")
        out.append(f"  trigger: {f['trigger']}" + (f"; controls: {f['controls']}" if f["controls"] else ""))
    return "\n".join(out)


def setting_pair(text: str) -> dict:
    """`--from TIER,EFFORT`: a session's own settings, as numbers from the tool's tiers map."""
    try:
        tier, effort = (int(x) for x in text.split(","))
    except ValueError:
        raise argparse.ArgumentTypeError(f"{text!r} is not TIER,EFFORT, two whole numbers")
    if tier < 1 or effort < 0:
        raise argparse.ArgumentTypeError(f"{text!r}: tier counts from 1, effort from 0")
    return {"tier": tier, "effort": effort}


def ranks_below(a: dict, b: dict) -> bool:
    """A below B: tier first, then effort, so a better tier at any effort ranks above a worse
    one. Lower numbers are better for both."""
    return (a["tier"], a["effort"]) > (b["tier"], b["effort"])


def start_from(role: dict, own: dict) -> str:
    """How a session at OWN starts a ROLE session. The tool clamps a new session's model and
    its effort to the starter's one at a time, so each is compared apart: a better model never
    excuses a lower effort."""
    raise_ = [k for k in ("tier", "effort") if role[k] < own[k]]
    if not raise_:
        return "start with its settings"
    return "start, then raise " + " and ".join("model" if k == "tier" else k for k in raise_)


def cmd_roles(root: Path, args) -> int:
    """Print each role's tier and effort in effect; refuse an override that breaks a rule.
    With --from, the starting session's own settings: how to start each role from them."""
    roles = settings_or_refuse(root)
    own = getattr(args, "from_", None)
    if own is None:
        print(role_lines(roles))
        return 0
    for k, v in roles.items():
        print(f"{k}: tier {v['tier']}, effort {v['effort']}")
        print(f"  {start_from(v, own)}")
    if ranks_below(own, HUBNODE_FLOOR):
        print(f"tier {own['tier']}, effort {own['effort']} is below the hubnode floor "
              f"(tier {HUBNODE_FLOOR['tier']}, effort {HUBNODE_FLOOR['effort']})")
    return 0


def cmd_flows(root: Path, args) -> int:
    """Print each workflow's steps, the node or role that does each, and its links."""
    print(flow_lines())
    print("→ goes to a session that exists; ⇢ starts a new one")
    return 0


def cmd_workflow(root: Path, args) -> int:
    """The pre-roles command, kept until every repo's skills say `jig roles` and `jig flows`.
    Its step lines keep the old names, execute and recheck too, for the skills that read them."""
    roles = settings_or_refuse(root)
    print("\n".join(f"{step}: tier {roles[role]['tier']}, effort {roles[role]['effort']}"
                    for step, role in OLD_STEPS.items()))
    print()
    return cmd_flows(root, args)


# ---------------------------------------------------------------------- rules

AUTO_MERGE = False   # set by the pre-merge-commit hook: git has not written MERGE_HEAD yet


def base(trunk: str) -> str:
    """What a change is compared against: HEAD, or trunk while a merge of trunk is
    being finished — otherwise everything trunk brought in looks like ours."""
    if AUTO_MERGE:
        return trunk
    merge_head = git("rev-parse", "-q", "--verify", "MERGE_HEAD")
    if merge_head and subprocess.run(["git", "merge-base", "--is-ancestor", merge_head, trunk],
                                     capture_output=True).returncode == 0:
        return merge_head
    return "HEAD"


def since_trunk(trunk: str) -> str:
    """Where a branch's log and numbers are judged from: where it left trunk, so a branch is judged
    as its squash would be and a later commit may correct an earlier one. On trunk, on a detached
    HEAD (the gate's scratch merge), or finishing a merge of trunk, it is base()."""
    b = base(trunk)
    if b != "HEAD" or git("branch", "--show-current") in (trunk, ""):
        return b
    return git("merge-base", trunk, "HEAD") or b


def changed_paths(trunk: str, staged: bool, removed: bool = False) -> list[str]:
    """What the change writes: a rename shows under its new path only, and a delete not at all,
    which is what a rule on content judges. With REMOVED, every path it adds, edits or removes,
    both sides of a rename included: a rule guarding a path counts taking it away as changing it."""
    args = (["-c", "core.quotePath=false", "diff", "--name-only", "--no-renames"] if removed
            else ["diff", "--name-only", "--diff-filter=ACMRT"])
    args += [base(trunk), *(["--cached"] if staged else [])]
    return [p for p in git(*args).splitlines() if p]


def at_rev(rev: str, path: str) -> str:
    return git("show", f"{rev}:{path}")


def in_index(path: str, staged: bool) -> str:
    if not staged:
        return Path(path).read_text(errors="replace") if Path(path).exists() else ""
    return git("show", f":{path}")


def roadmap_raw(rev: str = "", staged: bool = False, cwd: Path | None = None) -> str:
    """The roadmap file's own text: at REV, in the index (STAGED), or in the work tree."""
    if rev:
        return git("show", f"{rev}:{ROADMAP}", **({"cwd": str(cwd)} if cwd else {}))
    if staged:
        return git("show", f":{ROADMAP}")
    p = (cwd or main_root()) / ROADMAP
    return p.read_text(errors="replace") if p.is_file() else ""


def has_log(trunk: str) -> bool:
    """Whether trunk keeps the decision log. A repo `jig update` hasn't moved to it yet keeps
    the rules it had: a metarepo's CHANGELOG.md and its register of rows."""
    return bool(git("ls-tree", "--name-only", trunk, "--", LOG))


def holds_old_log(text: str, path: str, prefix: str | None) -> bool:
    """Whether a file still is a log from before .jig/decisions.md: a CHANGELOG.md with its
    sections, or a register with rows. What the merge leaves behind (a preamble, a note) isn't."""
    if path == CHANGELOG:
        return bool(re.search(r"^## ", text, re.M))
    return bool(rows_in(text, prefix))


def migrated_here(trunk: str, staged: bool, meta: dict | None) -> bool:
    """This change is the merge into the log: it adds the log and no longer holds CHANGELOG.md's
    sections or a register's rows. A change that adds a log beside the old files is no merge,
    and the old rules still judge it."""
    if not in_index(LOG, staged):
        return False
    entry = (meta or {}).get("entry_files", [])
    prefix = (meta or {}).get("decision_prefix")
    olds = [f for f in git("ls-tree", "-r", "--name-only", trunk).splitlines()
            if f == CHANGELOG or (f.endswith(".md") and not f.startswith(f"{DIR}/")
                                  and (f in entry or Path(f).name.lower() == "decisions.md"))]
    return not any(holds_old_log(in_index(f, staged), f, prefix) for f in olds)


def changelog_only_grows(trunk: str, staged: bool) -> bool:
    """CHANGELOG.md is still there and this change deletes none of its lines."""
    if not in_index(CHANGELOG, staged):
        return False
    stat = git("diff", "--numstat", base(trunk), *(["--cached"] if staged else []), "--", CHANGELOG)
    return all(line.split("\t")[1] == "0" for line in stat.splitlines() if line)


def existed_on_trunk(trunk: str, path: str) -> bool:
    return bool(git("ls-tree", "-r", "--name-only", trunk, "--", path))


def check_rules(root: Path, board: Board, *, staged: bool) -> list[str]:
    """Return a list of refusals. Empty means pass."""
    out: list[str] = []
    branch = git("branch", "--show-current")
    trunk = board.trunk
    name, job = board.job_for_branch(branch)
    paths = changed_paths(trunk, staged)
    guarded = changed_paths(trunk, staged, removed=True)
    meta = load_meta(trunk)
    if meta is not None:
        out += meta_rules(root, board, meta, staged)
    para = load_para(trunk)
    if para is not None:
        out += para_rules(root, board, para, staged)
    if LOG in guarded:
        out += log_rules(trunk, staged, on_trunk(trunk, branch))
        out += move_rules(trunk, staged, meta)
    if LOG in guarded or GLOSSARY in guarded:
        out += open_label_problems(trunk, staged)
    # A glossary change re-checks the ideas' labels, as it does the roadmap's: a term dropped or
    # renamed re-points the label in the same commit.
    if IDEAS in guarded or ((LOG in guarded or GLOSSARY in guarded) and in_index(IDEAS, staged)):
        out += ideas_rules(trunk, staged, on_trunk(trunk, branch))

    # R1 the trunk checkout stays on trunk (only when jobs are open: solo, one checkout
    # with a feature branch is normal and nobody else's tree is being moved)
    if board.open_jobs() and is_main_worktree(root) and branch and branch != trunk:
        out.append(
            f"R1 the {trunk} checkout stays on {trunk}; it is on {branch}. "
            f"Work in a worktree: {worktrees_dir()}/{branch}"
        )

    # R5 the board is the hubnode's
    for f in (CONFIG, DOCMAP, JOBS):
        if f in guarded and branch != trunk:
            out.append(f"R5 the board is the hubnode's: {f} is edited on {trunk} only")
    # A phase or a scope is the owner's decision: the roadmap changes on trunk alone.
    for f in (ROADMAP, OLD_ROADMAP):
        # A pararepo's change to its products' sections reaches a metarepo only by its
        # `propose/` branch, merged on trunk on the owner's yes: the one other place it may be.
        if f in guarded and branch != trunk and not (f == ROADMAP and meta is not None
                                                     and proposed_branch(branch, trunk)):
            out.append(f"R5 the roadmap is the owner's: {f} is edited on {trunk} only"
                       + (", or on a propose/ branch `jig propose` opened that isn't merged yet"
                          if meta is not None and f == ROADMAP else ""))
    # A spec takes only what it builds: what it leaves stays on the roadmap, unspecced, where any
    # later spec can take it. A `Later:` line would hold it in a file that closes with the spec.
    for f in paths:
        if is_spec(f) and later_line(in_index(f, staged) or ""):
            out.append(f"{f} has a `Later:` line: work a spec doesn't build stays on the roadmap, "
                       "unspecced, and a partly built scope is split by a roadmap change. Delete the line")
    if meta is not None and (GLOSSARY in paths or ROADMAP in paths):
        now = term_owners(in_index(GLOSSARY, staged))
        if GLOSSARY in paths and (branch == trunk or proposed_branch(branch, trunk)):
            # A product's term and the phases it owns land in one merge (`jig move-in`): its
            # headings are read by the commit's own glossary, as by the commit's own roadmap.
            family(main_root(), trunk).owners = now
    if GLOSSARY in paths or meta is not None and ROADMAP in paths:
        out += glossary_rules(meta is not None, staged)
    out += roadmap_rules(board, branch, staged, paths, guarded)
    out += boundary_rules(trunk, branch, staged, paths, meta, board.data.get("not_docs") or [])
    out += page_form_rules(root, board, trunk, staged, guarded)
    out += heading_rules(trunk, staged, paths, board.data.get("not_docs") or [])
    if CONFIG in paths and (raw := in_index(CONFIG, staged)):
        try:
            new_cfg = json.loads(raw)
            out += role_settings(new_cfg)[1] + queue_problems(new_cfg)
            # The old key isn't read: a commit carrying it keeps a setting that looks in effect
            # and isn't. `jig update --apply` removes it.
            if "workflow" in new_cfg:
                out.append(f"{CONFIG}: `workflow` is the pre-roles key, and jig doesn't read it: "
                           "remove it (`jig update --apply` does), and write an override the owner "
                           "says is standing under `roles`, with its reason")
            # Only a key the commit adds: a repo `jig update --apply` hasn't moved yet still
            # edits its config, and update's own commit moves the keys out.
            try:
                had = json.loads(at_rev(trunk, CONFIG) or "{}")
            except ValueError:
                had = {}
            out += [f"{CONFIG}: `{k}` lives in {DOCMAP} now: move it there "
                    "(`jig update --apply` does)" for k in DOCMAP_KEYS if k in new_cfg and k not in had]
        except ValueError as e:
            out.append(f"{CONFIG} is not JSON: {e}")
    if DOCMAP in paths and (raw := in_index(DOCMAP, staged)):
        out += docmap_problems(raw)
    # A remap that keeps a page where survey moves it overrides jig's rule: the owner's
    # exception must be on record first, or one line of prose approves it unseen.
    if REMAP in paths and (raw := in_index(REMAP, staged)):
        cfg = board.data
        if (CONFIG in paths or DOCMAP in paths) and branch == trunk:
            try:
                cfg = with_docmap(json.loads(in_index(CONFIG, staged)), in_index(DOCMAP, staged))
            except ValueError:
                pass
        out += [f"the remap contradicts survey: {contradiction_fix(c, trunk)}"
                for c in remap_contradictions(root, tracked(root), cfg, raw)]

    # R7 a workaround needs its ledger row — job or not; code only, prose may quote it. Only
    # the marker right after a comment opener is the comment the rule names: a string or regex
    # that mentions it isn't. jig's own checker is skipped too, since the previous checker,
    # which may match the marker anywhere, judges every update of it.
    code = [p for p in paths if (p.endswith(CODE_EXT) or Path(p).name == "Kconfig")
            and p != f"{DIR}/jig.py"]
    # Raw, so a lone CR can't split one added line into a "+" line and an unmarked one; counted
    # by net_added, so a comment only moved within its file (functions reordered) isn't new.
    diff = git_raw("-c", "core.quotePath=false", "diff", "-U0", "--no-ext-diff", "--no-color",
                   "--src-prefix=a/", "--dst-prefix=b/", base(trunk), *(["--cached"] if staged else []),
                   "--", *code) if code else ""
    marked = re.compile(r"(?:.*(?:#|//|/\*)|\s*\*)\s*WORKAROUND:")
    if any(marked.match(t) for _, _, t in net_added(diff, set(code))) and WORKAROUNDS not in paths:
        # The ledger is made by its first row, so the refusal says where that row goes.
        out.append(f"R7 the diff adds a WORKAROUND: comment but {WORKAROUNDS} is not staged: "
                   f"add its row there in this commit (the first row creates the file from "
                   f"jig's ledger template)")

    # R6 on a job branch always; on trunk only while jobs are open, since solo
    # there is nobody to collide with and the numbers are yours
    held: dict[str, set[int]] = {}
    who = f"job {name}"
    for k, v in held_numbers(job or {}).items():
        held.setdefault(k, set()).update(v)
    if job is None and branch == trunk:
        # Merging a job brings in the numbers it holds: trunk takes them by merging it.
        tips = set(merging_commits())
        for n, l in board.jobs.items():
            if tips and git("rev-parse", "-q", "--verify", f"refs/heads/{board.branch(n)}") in tips:
                for k, v in held_numbers(l).items():
                    held.setdefault(k, set()).update(v)
                who = "the job being merged"
        # The numbers the merge itself gave the job's new entries are the job's too.
        given = numbers_given(trunk) if tips else set()
        for k, v in (board.data.get("reserve") or {}).items():
            if given and isinstance(v, dict) and matches(LOG, v.get("files") or []):
                held.setdefault(k, set()).update(given)
    head = git("rev-parse", "HEAD") if job is None and not branch else ""
    if head and subprocess.run(["git", "merge-base", "--is-ancestor", head, trunk],
                               capture_output=True).returncode:
        # A detached HEAD off trunk is the gate's scratch checkout of a job's commit: it holds
        # what the job holds, or its merge of trunk would take every number the job built. A
        # detached trunk holds nothing, or a fast-forward could carry a held number onto it.
        for n, l in board.jobs.items():
            if subprocess.run(["git", "merge-base", "--is-ancestor", head,
                               f"refs/heads/{board.branch(n)}"], capture_output=True).returncode == 0:
                for k, v in held_numbers(l).items():
                    held.setdefault(k, set()).update(v)
                who = f"job {n}"
    # Working alone the numbers are yours, but a second migration 17 still breaks a database:
    # "unique" applies with no jobs open too.
    out += reserved_refusals(root, board, held, who, staged,
                             takes=job is not None or bool(board.open_jobs()))

    if job is None:
        # A metarepo's propose/ branch is on no job by design: `jig propose` makes it from the
        # pararepo, which can't open a metarepo job, and the metarepo takes it in by a merge
        # whose own checks judge ownership.
        proposal = meta is not None and branch.startswith("propose/")
        if branch and branch != trunk and board.open_jobs() and not proposal:
            out.append(
                f"R2 branch {branch} is on no job. Ask the hubnode to open one, "
                f"or work on {trunk}"
            )
        return out

    # R2 a job is built in its worktree
    wt = board.worktree(name)
    expect = (main_root() / wt).resolve()
    here = Path(git("rev-parse", "--show-toplevel")).resolve()
    if expect.exists() and here != expect:
        out.append(f"R2 job {name} is built in {wt}, not here")

    common = board.data.get("common", [])
    owns, shares = job.get("owns", []), job.get("shares", [])
    others = {n: l for n, l in board.open_jobs().items() if n != name}

    # A note's pair lines are answered when committed, not first at the gate: the gate is
    # the costliest place to find a blank. Only this job's own notes: a sync brings in other
    # jobs' notes, which this job can't fix.
    own = re.compile(rf"{re.escape(file_safe(name))}-\d{{4}}-\d{{2}}-\d{{2}}(?:-\d+)?\.md")
    if staged:
        for p in git("-c", "core.quotePath=false", "diff", "--cached", "--name-only",
                     "--diff-filter=AM", "--", f"{DIR}/handoffs/").splitlines():
            if not own.fullmatch(Path(p).name):
                continue
            sec = re.search(r"^## Fold-in\n(.*?)(?=^## |\Z)", in_index(p, staged), re.S | re.M)
            for l in (sec.group(1).splitlines() if sec else []):
                if why := pair_problem(l):
                    out.append(f"{p}: fold-in line `{l.strip()}`: {why}")

    for p in guarded:
        if p.startswith(f"{DIR}/handoffs/"):
            continue
        # R4 another open job's owns wins, even over this job's lists
        for on, ol in others.items():
            if matches(p, ol.get("owns", [])):
                out.append(f"R4 {p} is owned by job {on}: ask the hubnode before touching it")
                break
        else:
            # Any job may record a decision or a change, whatever its lists say, since M3 asks
            # a metarepo job for its line. It only adds (a log not folded yet still lets its open
            # entries change in place): a rewrite would take what others recorded with it.
            # Ideas change in place and leave when decided or dropped, so any job may edit them.
            if p == IDEAS:
                continue
            if p == LOG:
                since = since_trunk(trunk)
                now = in_index(LOG, staged)
                if now and not outside_open_deleted(at_rev(since, LOG), now):
                    continue
                # A log the branch added and then removed was never trunk's.
                if not now and not at_rev(since, LOG):
                    continue
                out.append(f"R3 {LOG}: a job adds to the log; what changes in place is an idea, "
                           f"in {IDEAS}")
                continue
            # R3 only this job's files, or a file new to the repository. Removing a file is
            # changing it: one trunk has must be declared; one only this job added never was trunk's.
            if matches(p, owns) or matches(p, shares) or matches(p, common):
                continue
            # Before the log, M3 asks every metarepo job for a CHANGELOG.md line, so every one may
            # add lines to it. Only add: a rewrite would take the released history with it.
            if meta is not None and p == CHANGELOG and not has_log(trunk) and changelog_only_grows(trunk, staged):
                continue
            if not existed_on_trunk(trunk, p):
                continue
            out.append(f"R3 {p} is not job {name}'s: ask the hubnode to add it to shares")

    return out


# ------------------------------------------------------------------- commands

def doc_owners(board: "Board", path: str) -> list[str]:
    """Every docmap page that covers this file. A file can have several — its system page,
    a seam page, the page of the board it runs on — and each must be asked about."""
    return [page for page, globs in (board.data.get("docmap") or {}).items()
            if matches(path, globs)]


def highest_on_trunk(board: "Board", counter: str, spec: dict) -> int:
    """The highest value of a counter actually present on trunk, so a number taken
    outside the board is never handed out again."""
    if not isinstance(spec, dict) or not spec.get("pattern"):
        return 0
    pat = re.compile(spec["pattern"], re.M)
    top = 0
    for f in git("ls-tree", "-r", "--name-only", board.trunk).splitlines():
        if f and matches(f, spec.get("files") or ["**"]):
            for m in pat.finditer(git("show", f"{board.trunk}:{f}")):
                try:
                    top = max(top, int(m.group(1)))
                except ValueError:
                    pass
    return top


def held_numbers(job: dict) -> dict[str, set[int]]:
    """What a job holds, per counter. `jig reserve` turns one value into a list."""
    out: dict[str, set[int]] = {}
    for k, v in (job.get("reserved") or {}).items():
        out.setdefault(k, set()).update(int(x) for x in (v if isinstance(v, list) else [v])
                                        if str(x).isdigit())
    return out


def next_number(board: "Board", counter: str, spec: dict) -> int:
    """The next free number: above everything trunk has and everything an open job holds,
    so two jobs open at once never get the same one."""
    held = [n for l in board.jobs.values() for n in held_numbers(l).get(counter, ())]
    return max([highest_on_trunk(board, counter, spec), *held]) + 1


def reserved_refusals(root: Path, board: "Board", holds: dict[str, set[int]],
                      who: str, staged: bool, takes: bool = True) -> list[str]:
    """R6. A scarce number (migration step, schema version) belongs to one job.
    A number is taken when the base has no match for it in the counter's files and the
    index adds one. A dotted number under a whole number the base already has takes nothing,
    and editing or moving a match nets to zero. A counter with "unique" also refuses a number
    whose count rises past one: a second migration 17 is a collision of its own. Numbers
    compare as ints, so D-002 is the 2 a job holds; a refusal shows the text it matched.
    With TAKES false (no job open, so nobody to collide with) only "unique" is checked."""
    out: list[str] = []
    # A counter without a pattern matches nothing; update refuses one.
    counters = {k: v for k, v in (board.data.get("reserve") or {}).items()
                if isinstance(v, dict) and v.get("pattern") and (takes or v.get("unique"))}
    if not counters:
        return out
    at = since_trunk(board.trunk)
    touched = git("diff", "--name-only", "--no-renames", at,
                  *(["--cached"] if staged else [])).splitlines()
    tree = git("ls-tree", "-r", "--name-only", at).splitlines()
    for counter, spec in counters.items():
        pat = re.compile(spec["pattern"], re.M)
        globs = spec.get("files") or ["**"]
        held = holds.get(counter)
        files = {p for p in touched if p and matches(p, globs)}
        # Counted over every file the counter covers at the base, so a number defined in a
        # file this change doesn't touch is still one the base has.
        before: dict[int, int] = {}
        after: dict[int, int] = {}
        shown: dict[int, str] = {}

        def count(text: str, *into: dict[int, int]) -> None:
            for m in pat.finditer(text):
                try:
                    n = int(m.group(1))
                except ValueError:
                    continue
                shown.setdefault(n, m.group(1))
                for d in into:
                    d[n] = d.get(n, 0) + 1

        for p in tree:
            if p and matches(p, globs):
                count(at_rev(at, p), before, *([] if p in files else [after]))
        for p in files:
            count(in_index(p, staged), after)
        for n in sorted(after):
            got = shown[n]
            if spec.get("unique") and after[n] > max(1, before.get(n, 0)):
                out.append(f"R6 {counter} {got} already exists: a {counter} is unique, and this "
                           f"change adds another" if n in before else
                           f"R6 {counter} {got} appears twice in this change: a {counter} is unique")
            if n in before or not takes:
                continue
            if not held:
                out.append(f"R6 this change takes {counter} {got}, but this branch holds no "
                           f"{counter}: ask the hubnode to reserve one")
            elif n not in held:
                out.append(f"R6 this change takes {counter} {got}, but {who} holds "
                           f"{counter} {', '.join(str(h) for h in sorted(held))}")
    return out


def old_board(root: Path) -> str | None:
    """An older jig's board, at any path update knows how to move."""
    return next((p for p in LAYOUT[0][1] if (root / p).exists()), None)


def cmd_init(root: Path, args) -> int:
    # A second board beside an old one is what update refuses as "two boards", and the hooks
    # would run a trunk .jig/jig.py that doesn't exist yet: so nothing is written at all.
    old = old_board(root)
    if old:
        die(f"refused: {old} is an older jig's board, and init would write a second one beside "
            f"it. Run `jig update` (then --apply), commit, then run this same `jig init` again", 2)
    (root / DIR).mkdir(exist_ok=True)
    ensure_staging(root)
    ensure_inbox(root)
    path = root / CONFIG
    if path.exists():
        print(f"{CONFIG} already exists")
    else:
        data = json.loads(json.dumps(BOARD_DEFAULTS))
        data["trunk"] = args.trunk
        data["name"] = main_root().name
        path.write_text(json.dumps(data, indent=2) + "\n")
        print(f"wrote {CONFIG}")
    if not (root / JOBS).exists():
        (root / JOBS).write_text("{}\n")
        print(f"wrote {JOBS}")
    if not (root / DOCMAP).exists() and (held := config_docmap_keys(root)):
        # Written now, its defaults would stand over the map config.json still holds.
        print(f"{DOCMAP} not written: {CONFIG} still holds {', '.join(held)}; "
              "`jig update --apply` moves them there")
    elif not (root / DOCMAP).exists():
        (root / DOCMAP).write_text(docmap_json(json.loads(json.dumps(DOCMAP_DEFAULTS))))
        print(f"wrote {DOCMAP}")
    if not (root / LOG).exists() and old_log_files(root):
        # A seed here would leave nothing for the merge to fill: the old files go in first.
        print(f"{LOG} not written: {', '.join(f for f, _ in old_log_files(root))} merge into it "
              "with `jig update --merge-log`, on the owner's yes")
    elif not (root / LOG).exists():
        (root / LOG).write_text(LOG_SEED)
        print(f"wrote {LOG}")
    if not (root / IDEAS).exists():
        (root / IDEAS).write_text(IDEAS_SEED)
        print(f"wrote {IDEAS}")
    # A stand-alone repo's glossary starts with its software product, named for the board, so
    # control and `--owner` work from the start; a metarepo's init writes its own.
    if not (root / GLOSSARY).exists() and not getattr(args, "meta", False) and getattr(args, "para", None) is None:
        name = json.loads((root / CONFIG).read_text()).get("name") or root.name
        (root / GLOSSARY).parent.mkdir(parents=True, exist_ok=True)
        (root / GLOSSARY).write_text(glossary_seed(name))
        print(f"wrote {GLOSSARY}")
    rc = 0
    if getattr(args, "no_hooks", False):
        print("hooks not installed (--no-hooks). Run `jig install-hooks` to cut over.")
    else:
        rc = cmd_install_hooks(root, args)
    # A metarepo or pararepo is a repo with one more file, so it is made by the same init.
    if getattr(args, "meta", False):
        rc = cmd_meta_init(root, args)
    elif getattr(args, "para", None) is not None:
        args.meta = args.para
        rc = cmd_para_init(root, args)
    # After those, so a pararepo's para.json is there to say it plans from its metarepo's.
    ensure_roadmap(root, init=True)
    write_templates(root)
    write_rules(root)
    return rc


HOOK = """#!/bin/sh
# jig hook ({dir}/jig.py). Delete to disable; `jig install-hooks` rewrites it.
# Runs TRUNK's copy of the checker, so a branch cannot weaken its own rules.
# git hands pre-push the pushed refs on stdin, once: read here, a chained .local hook
# (git-lfs) and jig each get them, where the first reader would otherwise take them all.
if [ {name} = pre-push ]; then refs=$(cat); fi
feed() {{ if [ {name} = pre-push ]; then printf '%s\n' "$refs" | "$@"; else "$@"; fi; }}
[ -x "$0.local" ] && {{ feed "$0.local" "$@" || exit $?; }}
copy=$(mktemp "${{TMPDIR:-/tmp}}/jig.XXXXXX") || exit 0
git show {trunk}:{dir}/jig.py > "$copy" 2>/dev/null || {{ rm -f "$copy"; exit 0; }}
feed python3 "$copy" hook {name} "$@"
status=$?
rm -f "$copy"
exit $status
"""


HOOKS = ("pre-commit", "pre-merge-commit", "pre-push", "post-checkout", "post-merge",
         "commit-msg")
# ai-dev was jig under its old name, and claude-lane the tool jig grew from: their hooks are
# ours to rewrite, not a predecessor's to keep.
HOOK_MARKERS = ("# jig hook", "# aidev hook", "claude-lane.py")


def git_common() -> Path:
    return Path(git("rev-parse", "--path-format=absolute", "--git-common-dir"))


def foreign_hooks() -> list[str]:
    """Hooks in this clone that jig didn't write."""
    hooks = git_common() / "hooks"
    if not hooks.exists():
        return []
    return sorted(h.name for h in hooks.iterdir()
                  if h.is_file() and not h.name.endswith(".sample")
                  and not any(m in h.read_text(errors="replace") for m in HOOK_MARKERS))


def cmd_install_hooks(root: Path, args) -> int:
    # The old board's hooks still work; these would run a trunk .jig/jig.py that isn't there.
    # Update installs them itself, once the board has moved.
    old = old_board(root)
    if old:
        die(f"refused: {old} is an older jig's board, and these hooks would replace its own with "
            f"ones that check nothing. Run `jig update` (then --apply) instead: it installs them", 2)
    trunk = Board.trunk_name(root)
    common = git_common()
    hooks = common / "hooks"
    hooks.mkdir(parents=True, exist_ok=True)
    for name in HOOKS:
        t = hooks / name
        if t.exists() and not any(m in t.read_text(errors="replace") for m in HOOK_MARKERS):
            if getattr(args, "replace", False):
                t.unlink()
                print(f"removed predecessor hook {name}")
            else:
                t.rename(hooks / f"{name}.local")
                print(f"kept existing {name} as {name}.local; it runs first")
        if getattr(args, "replace", False) and (hooks / f"{name}.local").exists():
            (hooks / f"{name}.local").unlink()
            print(f"removed {name}.local")
        t.write_text(HOOK.format(dir=DIR, trunk=trunk, name=name))
        t.chmod(0o755)
    # Opt-in marker for the Claude Code plugin's own hooks. It lives in .git/, which is
    # never cloned or committed, so a repo you fetched cannot enable them for itself.
    (common / "jig").mkdir(exist_ok=True)
    (common / "jig" / "enabled").write_text("jig hooks enabled for this checkout\n")
    print(f"hooks installed in {hooks}")
    return 0


def run_setup(root: Path) -> None:
    """Make this checkout runnable with its own .jig/scripts/setup.sh — the checkout's copy, not
    trunk's: it judges nothing, and must match the files checked out. Its output goes to
    stderr so whoever made the checkout sees it. A failure is reported and fails nothing,
    because the checkout exists either way."""
    # A pararepo's cache of the pinned metarepo docs is gitignored, so a new worktree has none,
    # and a merge of trunk's pin bump leaves it at the old pin. The main checkout's is refilled
    # before that bump is committed, so copying it needs no metarepo.
    cache, main_cache = root / CACHE, main_root() / CACHE
    if (root / PARA).exists() and main_cache.exists() and cache != main_cache:
        try:
            pin = json.loads((root / PARA).read_text()).get("pin")
        except ValueError:
            pin = None
        def at(c: Path) -> str | None:
            return (c / "PIN").read_text().split("\n")[0] if (c / "PIN").exists() else None
        # Copying a cache at some other pin would only trade one stale cache for another.
        if (not cache.exists() or at(cache) != pin) and at(main_cache) == pin:
            shutil.rmtree(cache, ignore_errors=True)
            shutil.copytree(main_cache, cache)
    script = root / DIR / "scripts" / "setup.sh"
    if not script.exists():
        return
    print(f"jig: setting up {root} with {DIR}/scripts/setup.sh", file=sys.stderr)
    rc = run_repo_script(root, script)
    if rc:
        print(f"jig: {DIR}/scripts/setup.sh exited {rc} in {root}. Fix it, then run it again "
              f"in {root}.", file=sys.stderr)


def run_repo_script(root: Path, script: Path) -> int:
    # The same script runs from a hook, from sync, or by hand: none of git's hook variables.
    env = {k: v for k, v in os.environ.items()
           if k not in ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_PREFIX")}
    cmd = [str(script)] if os.access(script, os.X_OK) else ["bash", str(script)]
    return subprocess.run(cmd, cwd=root, env=env, stdout=sys.stderr).returncode


DERIVE = f"{DIR}/scripts/derive.sh"


def derived_files(root: Path, board: "Board") -> list[str]:
    """The paths the board's derived_files globs match, tracked or not, deleted or not."""
    globs = board.data.get("derived_files", [])
    if not globs:
        return []
    out = git("ls-files", "-z", cwd=str(root)) + "\0" + \
        git("ls-files", "--others", "--exclude-standard", "-z", cwd=str(root))
    return sorted({f for f in out.split("\0") if f and matches(f, globs)})


def run_derive(root: Path, board: "Board") -> tuple[int, list[str]]:
    """Run the repo's derive.sh on the merged tree and stage the paths the board declares
    derived, as they are now: what the merge commits is a state the repo named, never a guess
    at what the script touched. Staged even when it fails, so `git merge --abort` resets them.
    Returns its exit code and the derived files the merge commit changes."""
    script = root / DERIVE
    if not script.exists():
        return 0, []
    rc = run_repo_script(root, script)
    files = derived_files(root, board)
    if files:
        # Literal and from stdin: a name like `[slug].md` or `:x` is a path, and a long list
        # never meets the argument limit.
        p = subprocess.run(["git", "--literal-pathspecs", "add", "-A", "--pathspec-from-file=-",
                            "--pathspec-file-nul"], cwd=root, input="\0".join(files),
                           capture_output=True, text=True, errors="replace")
        if p.returncode:
            die(f"git add {', '.join(files)}: {p.stderr.strip()}", 2)
    globs = board.data.get("derived_files", [])
    wrote = sorted(f for f in git("diff", "--cached", "--name-only", "-z", "HEAD", cwd=str(root)).split("\0")
                   if f and matches(f, globs))
    # A glob that matches nothing is most likely a typo (`docs/reference` for
    # `docs/reference/**`), and the outputs it meant stay out of every merge commit.
    now = derived_files(root, board)
    for g in globs if not rc else []:
        if not any(matches(f, [g]) for f in now):
            print(f"jig: derived_files glob {g} matches no file after {DERIVE} ran", file=sys.stderr)
    return rc, wrote


def setup_and_derive(root: Path, board: "Board", name: str) -> bool:
    """The merge's last writes before its commit: setup.sh, so derive.sh runs in an environment
    built from the merged manifests, then derive.sh. False when derive.sh failed."""
    run_setup(root)
    rc, wrote = run_derive(root, board)
    if rc:
        print(f"jig: {DERIVE} exited {rc}; the merge isn't committed. Fix it, then "
              f"`jig merge --number` and `git commit`; or `git merge --abort`, which puts "
              f"{name}'s entry back.", file=sys.stderr)
        return False
    if wrote:
        print(f"derived: {', '.join(wrote)}")
    # The merge started from a clean tree, so a tracked change left unstaged is setup.sh's or
    # an output derive_files doesn't name: neither is committed, and both leave trunk dirty.
    left = sorted(filter(None, git("diff", "--name-only", "-z", cwd=str(root)).split("\0")))
    if left:
        print(f"jig: changed and not committed: {', '.join(left)}. {DIR}/scripts/setup.sh must "
              f"leave tracked files alone; a file {DERIVE} writes goes in {CONFIG}'s derived_files. "
              f"`git checkout -- <files>` drops them.", file=sys.stderr)
    return True


def cmd_hook(root: Path, args) -> int:
    name = args.name
    # git just brought another commit's files into this checkout: a new worktree (its
    # previous ref is all zeros) or a merge. Neither needs the board.
    if name == "post-merge":
        run_setup(root)
        return 0
    if name == "post-checkout" and args.rest and set(args.rest[0]) == {"0"}:
        run_setup(root)
    try:
        board = Board.load(root)
    except SystemExit:
        return 0
    if name == "post-checkout":
        if board.open_jobs() and is_main_worktree(root):
            b = git("branch", "--show-current")
            if b and b != board.trunk:
                print(f"jig: the {board.trunk} checkout is on {b}. "
                      f"Work in {worktrees_dir()}/{b}.", file=sys.stderr)
        return 0
    meta = load_meta(board.trunk)
    if name == "commit-msg":
        refusals = check_subject(args.rest[0], meta) if meta and args.rest else []
        for r in refusals:
            print(f"jig: {r}", file=sys.stderr)
        return 1 if refusals else 0
    if name == "pre-push":
        # git names what is pushed on stdin: `<local ref> <sha> <remote ref> <sha>`. What goes
        # to the remote's trunk is judged, not the local trunk: `git push origin HEAD:main`
        # from a detached checkout sends a commit the local ref never had.
        pushed = [l.split()[1] for l in (sys.stdin.read().splitlines() if meta else [])
                  if len(l.split()) == 4 and l.split()[2] == f"refs/heads/{board.trunk}"
                  and set(l.split()[1]) != {"0"}]
        problems = []
        for rev in pushed or ([""] if meta else []):
            problems += [p for p in meta_problems(root, meta, board.trunk, rev) if p not in problems]
        for p in problems:
            print(f"jig: refused: {p}", file=sys.stderr)
        return 1 if problems else 0
    if name == "pre-merge-commit":
        global AUTO_MERGE
        AUTO_MERGE = True
    refusals = check_rules(root, board, staged=True)
    for r in refusals:
        print(f"jig: {r}", file=sys.stderr)
    return 1 if refusals else 0


def cmd_status(root: Path, args) -> int:
    board = Board.load(root)
    trunk = board.trunk
    if not board.jobs:
        print("no jobs open")
    else:
        print(f"trunk: {trunk}")
    for name, l in board.jobs.items():
        br = board.branch(name)
        behind = git("rev-list", "--count", f"{br}..{trunk}") or "?"
        wt = main_root() / board.worktree(name)
        dirty = ""
        if wt.exists():
            dirty = " dirty" if git("status", "--porcelain", cwd=str(wt)) else " clean"
        notes = handoff_notes(br, name)
        print(f"  {name:<20} {l.get('state',''):<9} behind:{behind}{dirty}"
              f"  handoffs:{len(notes)}  after:{','.join(l.get('after',[])) or '-'}")
    for k, v in (board.data.get("reserve") or {}).items():
        if isinstance(v, dict) and v.get("pattern"):
            print(f"reserve {k}: next free {next_number(board, k, v)}")
    # What a complete check costs here, so a plan for parallel jobs knows its price.
    recs = checked_records()
    if recs:
        print(f"last complete check: {recs[-1]['seconds']}s on {recs[-1]['date']} "
              f"({recs[-1]['commit'][:12]})" + (f" on CI: {recs[-1]['url']}" if recs[-1]["url"] else ""))
    return 0


def file_safe(name: str) -> str:
    """A job or branch name as one file or folder name. git allows `/` in a branch; the notes
    and the gate's scratch stay flat, so `a/b` and `a-b` share a stem, and a note's header,
    not its file name, says whose it is."""
    return name.replace("/", "-")


def handoff_notes(branch: str, name: str) -> list[str]:
    """The notes a job has filed, read from its branch, oldest first: the record of a handoff
    is the note."""
    # The names `jig handoff` writes: <job>-<date>.md, then -2, -3 the same day. By name alone
    # "-" sorts before ".", putting the day's first note last; and job X-y's notes start "X-".
    note = re.compile(rf"{re.escape(file_safe(name))}-(\d{{4}}-\d{{2}}-\d{{2}})(?:-(\d+))?\.md")
    listing = git("ls-tree", "--name-only", branch, "--", f"{DIR}/handoffs/")
    found = [(m.group(1), int(m.group(2) or 1), n) for n in listing.splitlines()
             if (m := note.fullmatch(Path(n).name))
             and git("show", f"{branch}:{n}").split("\n", 1)[0] == f"# Handoff: {name}"]
    return [n for *_, n in sorted(found)]


def opened(board: "Board", name: str) -> str:
    """The day the job's entry reached trunk. git keeps that, so the record doesn't."""
    # Newest first: a name opened again after a merge has its latest entry.
    days = git("log", "--format=%as", "-S", f'"{name}": {{', board.trunk, "--", JOBS)
    return days.splitlines()[0] if days else ""


def cmd_open(root: Path, args) -> int:
    board = Board.load(root, working_tree=True)
    if git("branch", "--show-current") != board.trunk:
        die(f"open a job from {board.trunk} (the hubnode's checkout)")
    if args.name in board.jobs:
        die(f"job {args.name} already exists")
    # A merged job's bug spec names the job: left on trunk, it would be read as a new job's of
    # that name, listed in its refusal and closed by its merge as its own.
    if old := sorted(bug_specs_at(board.trunk, args.name)):
        die(f"{old[0]} on {board.trunk} is the bug spec of an earlier job {args.name}: `jig rig --close` "
            "removes it, then open the job")
    if file_safe(args.name).startswith("gate-"):
        die(f"a job name can't start with gate-: worktrees/{file_safe(args.name)} is where "
            f"`jig gate {args.name[5:]}` checks out, and removes when that job is gated")
    # Notes and gate scratch are named file_safe(job): two open jobs sharing that stem would
    # each commit the same note path the same day, an add/add conflict at the second merge.
    twin = [n for n in board.jobs if file_safe(n) == file_safe(args.name)]
    if twin:
        die(f"job {args.name} and open job {twin[0]} share the file name {file_safe(args.name)} "
            "for their handoff notes and gate checkout: pick another name")
    branch = args.branch or args.name
    owns = args.owns or []
    spec_file = root / spec_key(root, args.spec) if args.spec and args.spec.endswith(".md") else None
    spec_text = spec_file.read_text(errors="replace") if spec_file and spec_file.is_file() else ""
    # Overlapping specs get one answer before any becomes a job: one job, or kept apart on purpose.
    if spec_text and (group := group_of(root, board, args.spec)):
        die(group_refusal(group, args.spec))
    # R4 pre-check: a file another open job already changed is shared, never owned
    conflicts = []
    for p in owns:
        for on in board.open_jobs():
            # A file the job moved away is as much its change as one it edited.
            changed = git("-c", "core.quotePath=false", "diff", "--name-only", "--no-renames",
                          f"{board.trunk}...{board.branch(on)}").splitlines()
            if any(matches(c, [p]) for c in changed):
                conflicts.append(f"{p} (changed by open job {on})")
    if conflicts:
        die("these cannot be owns; put them in shares:\n  " + "\n  ".join(conflicts))

    existing = bool(git("rev-parse", "--verify", "-q", f"refs/heads/{branch}"))
    reserve = {}
    for kv in args.reserve or []:
        k, _, explicit = kv.partition("=")
        spec = (board.data.get("reserve") or {}).get(k)
        if not (isinstance(spec, dict) and spec.get("pattern") and spec.get("files")):
            die(f"counter '{k}' needs a \"pattern\" and \"files\" in reserve.{k} of {CONFIG}: "
                "the pattern is how jig knows which numbers are taken")
        # An adopted branch may already hold a number: it is recorded as held, and held
        # numbers are never handed out again while its job is open.
        reserve[k] = int(explicit) if explicit else next_number(board, k, spec)
        holder = [n for n, l in board.jobs.items() if reserve[k] in held_numbers(l).get(k, ())]
        if holder:
            die(f"{k} {reserve[k]} is held by open job {holder[0]}: one number, one job")
    # A merged job's entry is gone, so a name that isn't open reads as merged to R8: a typo
    # here would never gate anything.
    unknown = [a for a in args.after or [] if a not in board.jobs]
    if unknown:
        die(f"--after names no open job: {', '.join(unknown)}")

    default = f"{worktrees_dir()}/{branch}"
    worktree = args.worktree or default
    state = args.state or ("building" if existing else "claimed")
    record = {"spec": args.spec or "", "state": state, "after": args.after or [],
              "owns": owns, "shares": args.shares or [], "reserved": reserve}
    if branch != args.name:
        record["branch"] = branch
    if worktree != default:
        record["worktree"] = worktree
    board.jobs[args.name] = record
    board.save()

    if not (root / worktree).exists():
        if existing:
            if git("worktree", "list", "--porcelain").find(f"refs/heads/{branch}") >= 0:
                die(f"branch {branch} is checked out somewhere already: pass --worktree <path>")
            add = ["worktree", "add", worktree, branch]
        else:
            add = ["worktree", "add", "-b", branch, worktree, board.trunk]
        # stderr passes through: the post-checkout hook sets the worktree up, and what
        # setup.sh printed, or why it failed, belongs in front of whoever opened the job.
        subprocess.run(["git", *add], stdout=subprocess.DEVNULL)
    verb = "adopted" if existing else "opened"
    print(f"job {args.name} {verb}. worktree: {worktree}  state: {state}")
    if reserve:
        print("reserved: " + ", ".join(f"{k}={v}" for k, v in reserve.items()))
    # A warning, not a refusal: Touches is prose, and the hubnode may have meant to leave a path out.
    if missed := uncovered_touches(board, spec_text, owns, args.shares or []):
        print(f"warning: the spec's Touches names what {args.name} can't change, in neither owns, "
              f"shares nor common: {', '.join(missed)}. `jig share {args.name} <path>…` adds them.")
    proposals = proposal_branches(spec_text)
    # Synced first: a merge in a job is judged against trunk, and a new job's branch doesn't
    # hold the commit that opened it, so the board would read as the job's change.
    merges = (f"Run `jig sync`, then merge each proposal into {branch} in this order: "
              f"{', '.join(proposals)}.\n" if proposals else "")
    print(f"\n--- kickoff ---\nJob: {args.name}\nBranch: {branch}\nWorktree: {worktree}\n"
          f"Spec: {args.spec or '(see board)'}\n"
          f"Owns: {', '.join(owns) or '-'}\nShares: {', '.join(args.shares or []) or '-'}\n"
          f"{merges}Read {RULES_DIR}/rules-jobs.md, rules-handoff.md and rules-workflow.md, and the "
          f"rulesets your role's skill names, then `python3 {DIR}/jig.py rules`.\n"
          f"When you write or change a Proposed idea in {IDEAS}, or meet a question only the "
          "owner can answer, message the hubnode then, with the rule sentence and the "
          "alternative you rejected, and keep building.")
    return 0


def cmd_reserve(root: Path, args) -> int:
    """Another number for an open job, by the rule `open --reserve` uses: a hand edit of the
    board is checked by nothing, so a number taken that way can collide."""
    board = Board.load(root, working_tree=True)
    if git("branch", "--show-current") != board.trunk:
        die(f"reserve from {board.trunk} (the hubnode's checkout)")
    job = board.jobs.get(args.name)
    if job is None:
        die(f"no open job {args.name}")
    spec = (board.data.get("reserve") or {}).get(args.counter)
    if not (isinstance(spec, dict) and spec.get("pattern") and spec.get("files")):
        die(f"counter '{args.counter}' needs a \"pattern\" and \"files\" in reserve.{args.counter} "
            f"of {CONFIG}: the pattern is how jig knows which numbers are taken")
    n = next_number(board, args.counter, spec)
    reserved = job.setdefault("reserved", {})
    had = reserved.get(args.counter)
    reserved[args.counter] = n if had is None else [*(had if isinstance(had, list) else [had]), n]
    board.save()
    print(f"job {args.name}: {args.counter} {n} reserved. Commit {JOBS} on {board.trunk}.")
    return 0


# ---------------------------------------------------------------- consolidate

def spec_section(text: str, *names: str) -> str | None:
    """The body of a spec's first section named one of NAMES, or None. The one reader of a
    spec section: a bug role nests the template's sections under its own steps (`## 5. Spec`
    / `### Touches`), so any level from `##` down counts, and the body runs to the next
    heading at that level or higher. Never `# `: that is the spec's title."""
    alt = "|".join(re.escape(n) for n in names)
    m = re.search(rf"^(#{{2,}}) (?:{alt})[ \t]*\n", text, re.M)
    if not m:
        return None
    rest = text[m.end():]
    # From `##`: a `# ` line inside a section is a fenced shell comment, never its end.
    end = re.search(rf"^#{{2,{len(m.group(1))}}} ", rest, re.M)
    return rest[:end.start()] if end else rest


def touches_spans(text: str) -> list[str]:
    """The backticked paths in a spec's Touches section, a `<page> § <term>` kept whole. A span
    with neither a slash nor an extension is a function or a flag, not a path."""
    out = []
    for span in re.findall(r"`([^`\n]+)`", spec_section(text, "Touches") or ""):
        page = span.split("§")[0].strip()
        # A folder is everything under it; a skill's /name is a command, not a path.
        page = page + "**" if page.endswith("/") else page
        if page and not page.startswith("/") and not re.search(r"\s", page) \
                and ("/" in page or re.search(r"\.\w+$", page)):
            out.append(f"{page} § {span.split('§', 1)[1].strip()}" if "§" in span else page)
    return out


def touches_meet(a: str, b: str) -> bool:
    """Two Touches entries name one place: one path, a glob covering the other's path, or the
    same `<page> § <term>`. A whole page meets any term on it; two terms on one page don't."""
    pa, _, ta = a.partition(" § ")
    pb, _, tb = b.partition(" § ")
    if ta and tb:
        return pa == pb and ta == tb
    return pa == pb or matches(pa, [pb]) or matches(pb, [pa])


def spec_key(root: Path, spec: str) -> str:
    """One spelling per spec: `./.jig/specs/a.md`, an absolute path and `.jig/specs/a.md` are one."""
    p = Path(spec)
    if p.is_absolute() and p.is_relative_to(root):
        p = p.relative_to(root)
    return os.path.normpath(p.as_posix())


def spec_name(spec: str) -> str:
    """One key per spec, however a record names it: its path, its file name and its bare name.
    Only the folder and a trailing `.md` go: `Path.stem` cuts a bare dotted name
    (`app-1.2-fixes`) at its last dot, so it would match no spec."""
    return Path(spec).name.removesuffix(".md")


def release_tag(trunk: str) -> str:
    """The newest release on trunk: a vX.Y.Z tag `jig release` made."""
    tags = [t for t in git("tag", "--merged", trunk).splitlines() if re.fullmatch(r"v\d+(\.\d+)*", t)]
    return latest_tag(tags)


def bug_for(text: str) -> str:
    """The job a spec names itself the bug spec for, or "": `Bug-for: <job>` on a line of its
    own, outside fenced code. The one reader of the line, so a spec quoting it in an example,
    or a template's `<job>` placeholder, is no bug spec anywhere."""
    lines = text.splitlines()
    for line, out in zip(lines, unfenced(lines)):
        if out and (b := re.fullmatch(r"Bug-for:[ \t]*([^<>\s]+)[ \t]*", line)):
            return b.group(1)
    return ""


def waiting_specs(root: Path, board: "Board") -> dict[str, str]:
    """Specs no job has taken yet, path → text: no open job names it, no handoff note's
    `Spec:` line names it, and the newest release doesn't hold it. The tag bounds it, so a
    spec whose solo work merged long ago, with no note, isn't waiting."""
    named = {spec_key(root, j["spec"]) for j in board.jobs.values() if j.get("spec")}
    notes = root / HANDOFFS
    for n in notes.glob("*.md") if notes.is_dir() else []:
        named |= {spec_key(root, s) for s in
                  re.findall(r"^Spec:[ \t]*(\S+)", n.read_text(errors="replace"), re.M)}
    tag = release_tag(board.trunk)
    out = {}
    for f in sorted((root / SPECS).glob("*.md")):
        rel = f.relative_to(root).as_posix()
        if not is_spec(rel) or rel in named:
            continue
        if tag and git("cat-file", "-t", f"{tag}:{rel}"):
            continue
        text = f.read_text(errors="replace")
        # A bug spec is built in the job it names and reaches trunk only with that job's merge.
        # A spec listing buffer rows (`jig propose --buffer`, `jig move-in`), or a move's spec
        # whose proposal was withdrawn, is a proposal's record, not work: no job ever takes it.
        if bug_for(text) or listed_rows(text) or (MOVE_RECORD.search(text) and WITHDRAWN.search(text)):
            continue
        out[rel] = text
    return out


def kept_separate(text: str) -> set[str]:
    """The specs this one is kept apart from, by a `Kept separate from <spec>: <reason>` line,
    each as its spec_name."""
    return {spec_name(m.group(1).strip("`")) for m in
            re.finditer(r"^[ \t]*(?:[-*][ \t]*)?Kept separate from (\S+?):[ \t]*\S", text, re.M)}


def overlap_groups(root: Path, board: "Board") -> list[tuple[list[str], dict]]:
    """Unanswered groups of waiting specs: specs joined by an overlap no `Kept separate` line
    answers, with the shared Touches per pair. A merged spec answers by replacing its inputs."""
    specs = waiting_specs(root, board)
    touches = {s: touches_spans(t) for s, t in specs.items()}
    kept = {s: kept_separate(t) for s, t in specs.items()}
    names = sorted(specs)
    edges: dict[tuple[str, str], list[str]] = {}
    for i, a in enumerate(names):
        for b in names[i + 1:]:
            if spec_name(b) in kept[a] or spec_name(a) in kept[b]:
                continue
            shared = list(dict.fromkeys(x for x in touches[a] if any(touches_meet(x, y) for y in touches[b])))
            shared += [y for y in touches[b] if y not in shared
                       and any(touches_meet(x, y) for x in touches[a]) and y not in touches[a]]
            if shared:
                edges[(a, b)] = shared
    groups, seen = [], set()
    for s in names:
        if s in seen or not any(s in e for e in edges):
            continue
        group, todo = [], [s]
        while todo:
            x = todo.pop()
            if x in seen:
                continue
            seen.add(x)
            group.append(x)
            todo += [b if a == x else a for a, b in edges if x in (a, b)]
        group.sort()
        groups.append((group, {e: v for e, v in edges.items() if e[0] in group}))
    return groups


def group_of(root: Path, board: "Board", spec: str) -> tuple[list[str], dict] | None:
    want = spec_key(root, spec)
    return next((g for g in overlap_groups(root, board) if want in g[0]), None)


def group_refusal(group: tuple[list[str], dict], what: str) -> str:
    specs, edges = group
    return (f"{what} is in a group of waiting specs whose Touches overlap: {', '.join(specs)}. "
            "Answer it first: merge them into one spec (the spec role's consolidate, /jig:spec), or add "
            "`Kept separate from <spec>: <reason>` to one spec of each pair. `jig consolidate` lists it.")


def cmd_consolidate(root: Path, args) -> int:
    board = Board.load(root, working_tree=True)
    groups = overlap_groups(root, board)
    if not groups:
        print("no waiting specs overlap: each can open as its own job")
        return 0
    for n, (specs, edges) in enumerate(groups, 1):
        print(f"group {n}: {len(specs)} specs, proposed as one job")
        for s in specs:
            print(f"  {s}")
        for (a, b), shared in edges.items():
            print(f"    {spec_name(a)} and {spec_name(b)} share: {', '.join(shared)}")
    print("\nAnswer each group before opening any of it: the spec role's consolidate (/jig:spec) merges a group into one "
          "spec, or one spec of a pair says `Kept separate from <spec>: <reason>`.")
    return 0


def uncovered_touches(board: "Board", spec_text: str, owns: list[str], shares: list[str]) -> list[str]:
    """Touches paths the job could not change: in neither its owns, its shares, nor common.
    A glob in Touches is covered when it is listed as is."""
    lists = [*owns, *shares, *(board.data.get("common") or [])]
    out = []
    for t in touches_spans(spec_text):
        page = t.partition(" § ")[0]
        if page not in lists and not matches(page, lists) and page not in out:
            out.append(page)
    return out


def proposal_branches(text: str) -> list[str]:
    """The metarepo proposals a consolidated spec takes in, in its Proposals section's order."""
    return re.findall(r"`(propose/[^`\s]+)`", spec_section(text, "Proposals") or "")


def cmd_share(root: Path, args) -> int:
    """Add paths to an open job's shares: what its Touches needed and its kickoff left out."""
    board = Board.load(root, working_tree=True)
    if git("branch", "--show-current") != board.trunk:
        die(f"share from {board.trunk} (the hubnode's checkout)")
    job = board.jobs.get(args.name)
    if job is None:
        die(f"no open job {args.name}")
    taken = [f"{p} (owned by open job {n})" for p in args.paths for n, j in board.jobs.items()
             if n != args.name and any(p == o or matches(p, [o]) or matches(o, [p]) for o in j.get("owns") or [])]
    if taken:
        die("these are another job's to change; that job shares them first, or they wait:\n  "
            + "\n  ".join(taken))
    shares = job.setdefault("shares", [])
    added = [p for p in args.paths if p not in shares]
    shares += added
    board.save()
    print(f"job {args.name}: shares {', '.join(added) or 'unchanged'}. Commit {JOBS} on {board.trunk}.")
    return 0


def gate_scratch(name: str) -> str:
    """Where `jig gate` checks a job out, relative to the primary checkout."""
    return f"{worktrees_dir()}/gate-{file_safe(name)}"


def gate_holds(board: "Board", name: str, where: Path) -> str | None:
    """Why the gate checkout at WHERE doesn't hold the commit job NAME's newest note names, or
    None when it does. A gate's check counts only for that commit: `jig gate` checks it out and
    merges trunk in, so HEAD is the note's commit or a merge whose first parent is."""
    branch = board.branch(name)
    notes = handoff_notes(branch, name)
    m = re.search(r"^Commit: (\w+)", git("show", f"{branch}:{notes[-1]}"), re.M) if notes else None
    if not m:
        return None
    want = git("rev-parse", "-q", "--verify", f"{m.group(1)}^{{commit}}") or m.group(1)
    head = git("rev-parse", "HEAD", cwd=str(where))
    # First parent only of the merge `jig gate` makes: a commit added on top of the note's
    # commit in the checkout has it as first parent too, and holds what no note named.
    merged = git("rev-parse", "-q", "--verify", "HEAD^2", cwd=str(where))
    first = git("rev-parse", "-q", "--verify", "HEAD^1", cwd=str(where)) if merged else ""
    if want in (head, first):
        return None
    return (f"{gate_scratch(name)} holds {head[:12]}, not {want[:12]} that {notes[-1]} names: "
            f"`jig gate {name}`")


def gate_scratch_problem(where: Path, shown: str) -> str | None:
    """Why the checkout at WHERE can't be removed as gate scratch, or None when it can. The
    gate's checkout is detached; anything on a branch at that path is someone's work. Untracked
    files are setup's (a venv, a build) and go with it."""
    top = git("rev-parse", "--show-toplevel", cwd=str(where))
    if not top or Path(top).resolve() != where.resolve():
        return f"{shown} is not a checkout jig's gate made: look at it, then delete it"
    branch = git("symbolic-ref", "-q", "--short", "HEAD", cwd=str(where))
    if branch:
        return (f"{shown} has branch {branch} checked out, so it isn't a gate's scratch: "
                "jig leaves it alone")
    remove = f"`git worktree remove --force {shown}`"
    if git("rev-parse", "-q", "--verify", "MERGE_HEAD", cwd=str(where)):
        return f"{shown} has a merge in progress: look at it, then {remove}"
    edited = git("diff", "--name-only", "HEAD", cwd=str(where)).splitlines()
    if edited:
        # An install in setup.sh can rewrite a tracked lockfile after a passing check.
        return (f"{shown} has tracked changes ({', '.join(edited[:5])}), from setup.sh or a hand "
                f"edit: copy any edit to the job's branch, then {remove}")
    return None


def remove_checkout(where: Path) -> bool:
    ok = subprocess.run(["git", "worktree", "remove", "--force", str(where)],
                        capture_output=True).returncode == 0
    # A folder deleted by hand leaves git's record; prune it so the next gate and update agree.
    git("worktree", "prune")
    return ok and not where.exists()


def remove_gate_scratch(name: str, why: str) -> None:
    """Remove the job's gate checkout once it is spent. jig made it, so jig removes it: a
    printed remove command was run by nobody."""
    scratch = gate_scratch(name)
    where = main_root() / scratch
    git("worktree", "prune")
    if not where.exists():
        return
    problem = gate_scratch_problem(where, scratch)
    if problem:
        die(f"{problem}, and {why} again")
    if not remove_checkout(where):
        die(f"git couldn't remove {scratch}: `git worktree remove --force {scratch}`, and {why} again")
    print(f"removed the gate's scratch checkout {scratch}")


def cmd_mark(root: Path, args) -> int:
    board = Board.load(root, working_tree=True)
    if args.name not in board.jobs:
        die(f"no job {args.name}")
    if args.state == "merged":
        die(f"a job is merged by `jig merge {args.name}`, which deletes its entry in the merge commit")
    if args.state not in STATES:
        die(f"state must be one of {', '.join(STATES)}")
    if args.batch and args.state != "gated":
        die("--batch goes with gated: `jig mark <job> gated --batch`")
    if args.state == "gated" and args.batch:
        # Its check is owed by the batch: one complete run on trunk once the batch has merged.
        board.jobs[args.name]["check"] = "batch"
        remove_gate_scratch(args.name, f"`jig mark {args.name} gated --batch`")
    elif args.state == "gated":
        # Gated means the complete check passed on the commit the gate checked out, and
        # `jig checked` there said so: the checkout it ran in is then spent.
        scratch = gate_scratch(args.name)
        where = main_root() / scratch
        git("worktree", "prune")
        if not where.exists():
            die(f"no gate checkout for {args.name}: `jig gate {args.name}`, run the complete "
                f"check it prints there, then `jig checked` there")
        problem = gate_scratch_problem(where, scratch)
        if problem:
            die(f"{problem}, and `jig mark {args.name} gated` again")
        stale = gate_holds(board, args.name, where)
        if stale:
            die(f"{stale}, run the complete check there, `jig checked` there, then "
                f"`jig mark {args.name} gated`")
        head = git("rev-parse", "HEAD", cwd=str(where))
        if not any(r["commit"] == head for r in checked_records()):
            die(f"no complete check is recorded for {head[:12]} in {scratch}: run the check "
                f"`jig gate {args.name}` printed there, then `jig checked` there")
        remove_gate_scratch(args.name, f"`jig mark {args.name} gated`")
        board.jobs[args.name].pop("check", None)
    board.jobs[args.name]["state"] = args.state
    board.save()
    print(f"{args.name}: {args.state}")
    return 0


def checked_log() -> Path:
    """Where `jig checked` records each complete check: shared by every worktree, so a record
    made in the gate's checkout is read from trunk's, and never committed."""
    return Path(git("rev-parse", "--path-format=absolute", "--git-common-dir")) / "jig" / "checked.log"


def checked_records() -> list[dict]:
    """Every recorded complete check, oldest first."""
    log = checked_log()
    out = []
    for line in (log.read_text().splitlines() if log.exists() else []):
        f = line.split("\t")
        # A sixth field is the CI run's URL: a run on GitHub Actions jig read through gh.
        if len(f) in (5, 6) and all(x.isdigit() for x in f[1:4]):
            out.append({"commit": f[0], "tier": int(f[1]), "effort": int(f[2]),
                        "seconds": int(f[3]), "date": f[4], "url": f[5] if len(f) == 6 else ""})
    return out


def last_checked_on(rev: str) -> str | None:
    """The newest commit on REV's first-parent line that has a complete check recorded."""
    have = {r["commit"] for r in checked_records()}
    # `--` on every call naming trunk: a branch named like a folder (firmware's main/) is
    # otherwise ambiguous to git, which fails, and git() reads that as nothing found.
    for c in git("rev-list", "--first-parent", rev, "--").splitlines():
        if c in have:
            return c
    return None


def batch_merges(trunk: str) -> list[tuple[str, str]]:
    """The first-parent merges on TRUNK since its last complete check whose job's check was
    owed by the batch (`Check: batch`), oldest first, as (commit, subject)."""
    since = last_checked_on(trunk)
    out = []
    for line in git("log", "--first-parent", "--merges", "--reverse", "--format=%H%x09%s%x09%(trailers:key=Check,valueonly,separator=%x2C)",
                    f"{since}..{trunk}" if since else trunk, "--").splitlines():
        c, subject, check = (line.split("\t") + ["", ""])[:3]
        if check.strip() == "batch":
            out.append((c, subject))
    return out


def check_levels_review(root: Path) -> list[tuple[str, str]]:
    """A check.sh with one level runs everything on every stop, the complete suite included:
    the repo's to split, since only it knows which of its tests are quick."""
    path = f"{DIR}/scripts/check.sh"
    f = root / path
    if not f.is_file() or "--full" in f.read_text(errors="replace"):
        return []
    agents = root / "AGENTS.md"
    test = re.search(r"(?m)^\s*-\s*test:\s*`([^`]+)`", agents.read_text(errors="replace")) \
        if agents.is_file() else None
    # The repo's own test command is a candidate, not the answer: only the repo knows which
    # of its tests are quick, and some run their whole suite on every stop on purpose.
    named = (f"; AGENTS.md's test command, `{test.group(1)}`, is the candidate for the --full part"
             if test and "TODO" not in test.group(1) else "")
    return [(path, "never reads --full: split it into a quick part (lint, type-check, unit "
             "tests: what runs on every stop) and a complete part run only with --full (the "
             "full suite, slow or end-to-end tests: what the gate's check step runs)" + named)]


def ci_run_passed(url: str, head: str) -> str:
    """URL, once gh says its run finished and passed on HEAD. jig never records a run it
    didn't read: a URL handed to it is a claim, and the run's own result is the evidence."""
    m = re.search(r"github\.com/([^/\s]+/[^/\s]+)/actions/runs/(\d+)", url)
    if not m:
        die(f"--ci takes a GitHub Actions run's URL (https://github.com/<owner>/<repo>/actions/runs/<id>), not {url!r}")
    origin = re.search(r"github\.com[:/]([^/\s]+/[^/\s]+?)(?:\.git)?/?$", git("remote", "get-url", "origin"))
    if not origin:
        die("this repo has no GitHub origin: a CI run is recorded only from the repo it ran on")
    if origin.group(1).casefold() != m.group(1).casefold():
        die(f"run {m.group(2)} is {m.group(1)}'s, not this repo's origin, {origin.group(1)}")
    if not shutil.which("gh"):
        die("gh is not installed or not on PATH: jig checked --ci reads the run through gh, "
            "and records nothing it can't read")
    p = subprocess.run(["gh", "run", "view", m.group(2), "--repo", m.group(1),
                        "--json", "headSha,conclusion,status,url,workflowName,headBranch"],
                       capture_output=True, text=True)
    try:
        run = json.loads(p.stdout) if p.returncode == 0 else None
    except ValueError:
        run = None
    if not isinstance(run, dict):
        die(f"gh could not read run {m.group(2)}: {(p.stderr or p.stdout).strip() or f'exit {p.returncode}'}")
    if run.get("headSha") != head:
        die(f"run {m.group(2)} ran {str(run.get('headSha'))[:12]}, not HEAD {head[:12]}: "
            "record it in a checkout of the commit it ran")
    # Any green run on HEAD isn't the complete check: a lint workflow passes on the same
    # commit, even one that also runs on the check branch.
    branch = f"{CHECK_BRANCH}/{git('rev-parse', '--short=12', 'HEAD')}"
    if run.get("workflowName") != CHECK_WORKFLOW or run.get("headBranch") != branch:
        die(f"run {m.group(2)} is {run.get('workflowName')!r} on {run.get('headBranch')!r}: the complete "
            f"check is the {CHECK_WORKFLOW!r} workflow on {branch}")
    if run.get("status") != "completed":
        die(f"run {m.group(2)} is {run.get('status')}, not completed: record it once it passes")
    if run.get("conclusion") != "success":
        die(f"run {m.group(2)} concluded {run.get('conclusion')}, not success: nothing to record")
    return run.get("url") or url


def gate_job(root: Path) -> None:
    """Refuse a check recorded in a job's gate checkout that doesn't hold the commit the job's
    newest note names: `jig mark gated` and `jig merge` would read it as covering that note."""
    here = Path(git("rev-parse", "--show-toplevel") or ".").resolve()
    board = Board.load(root)
    for name in board.jobs:
        if here == (main_root() / gate_scratch(name)).resolve():
            stale = gate_holds(board, name, here)
            if stale:
                die(f"nothing recorded: {stale}, and run the complete check in the new checkout")
            return


def cmd_checked(root: Path, args) -> int:
    """Record that the complete check passed on HEAD; with --trace, how to find the merge that
    broke trunk since its last recorded one. jig records and prints; it never runs a check."""
    if args.trace is not None:
        trunk = Board.load(root).trunk
        # A check session runs outside the trunk checkout, in a detached checkout of its tip.
        # The hubnode may merge again while a batch's check runs, so any commit of trunk's will do.
        on_trunk = git("branch", "--show-current") == trunk or (
            not git("branch", "--show-current")
            and subprocess.run(["git", "merge-base", "--is-ancestor", "HEAD", trunk]).returncode == 0)
        if not on_trunk:
            die(f"--trace reads {trunk}'s history: run it on {trunk}, or in a detached checkout "
                f"of a commit of {trunk}'s")
        good = last_checked_on("HEAD")
        rng = f"{good}..HEAD" if good else "HEAD"
        merges = git("log", "--first-parent", "--merges", "--reverse", "--format=%h %s", rng).splitlines()
        print(f"merges since the last complete check ({good[:12] if good else 'none recorded'}), oldest first:")
        for m in merges or ["(none)"]:
            print(f"  {m}")
        if not good:
            print(f"no complete check is recorded on {trunk}: bisect needs a known good commit")
            return 1
        # Through sh -c, so a command with `&&` or `cd` is run whole at each step.
        cmd = f"sh -c {shlex.quote(args.trace)}" if args.trace else "<the failing command>"
        # --first-parent steps over merges only, so each step costs one run of one command.
        print("\nFind the merge that broke it, running only the failing command at each step:")
        print(f"  git bisect start --first-parent HEAD {good}")
        print(f"  git bisect run {cmd}")
        print("  git bisect reset")
        return 0
    if args.tier is None or args.effort is None or args.seconds is None:
        die("usage: jig checked --tier N --effort N --seconds S [--ci <run url>], or jig checked --trace [command]", 2)
    head = git("rev-parse", "HEAD")
    if not head:
        die("no commit to record")
    gate_job(root)
    url = ci_run_passed(args.ci, head) if args.ci else ""
    log = checked_log()
    log.parent.mkdir(parents=True, exist_ok=True)
    with log.open("a") as f:
        f.write(f"{head}\t{args.tier}\t{args.effort}\t{args.seconds}\t{date.today().isoformat()}"
                + (f"\t{url}" if url else "") + "\n")
    print(f"checked {head[:12]}: tier {args.tier}, effort {args.effort}, {args.seconds}s"
          + (f", on CI: {url}" if url else ""))
    step = role_settings(Board.load(root).data)[0]["check"]
    if (args.tier, args.effort) != (step["tier"], step["effort"]):
        print(f"warning: recorded tier {args.tier}, effort {args.effort}; the check step is "
              f"tier {step['tier']}, effort {step['effort']}", file=sys.stderr)
    return 0


# ------------------------------------------------------------------- the queue

# The queue's config keys. `overflow` is the one key that amends a fixed rule: with it, the
# check role pushes and deletes jig-check/* branches on the owner's standing yes.
QUEUE_KEYS = ("width", "slots", "max_load", "overflow")
CHECK_BRANCH = "jig-check"
CHECK_WORKFLOW = "jig check"         # the `name:` in templates/github/jig-check.yml
# `jig queue --full` exits with this when the complete check overflows to CI: neither a pass
# (0) nor the command's own failure (1), and not a usage error (2).
OVERFLOW_EXIT = 3


def queue_problems(config: dict) -> list[str]:
    """Every way the config's `queue` breaks the rules. The overflow key is the owner's standing
    yes for a push, so like a `roles` entry it carries the owner's words as its reason."""
    q = config.get("queue")
    if q is None:
        return []
    if not isinstance(q, dict):
        return ['queue: must be {"width": N or "all", "slots": N, "max_load": X, "overflow": {...}}']
    bad = []
    for k, v in q.items():
        if k not in QUEUE_KEYS:
            bad.append(f"queue.{k}: no such key; the keys are {', '.join(QUEUE_KEYS)}")
        elif k == "width" and v != "all" and not (type(v) is int and v >= 1):
            bad.append(f'queue.width: {v!r} is not a whole number from 1 up, or "all"')
        elif k == "slots" and not (type(v) is int and v >= 1):
            bad.append(f"queue.slots: {v!r} is not a whole number from 1 up")
        elif k == "max_load" and not (type(v) in (int, float) and v >= 0):
            bad.append(f"queue.max_load: {v!r} is not a load per core from 0 up")
        elif k == "overflow":
            if not isinstance(v, dict) or v.get("to") != "github":
                bad.append('queue.overflow: must be {"to": "github", "reason": "<the owner\'s words>"}')
            elif not (isinstance(v.get("reason"), str) and v["reason"].strip()):
                bad.append("queue.overflow: no reason: quote the owner's yes to pushing "
                           f"{CHECK_BRANCH}/* branches without asking each time")
            elif set(v) - {"to", "reason"}:
                bad.append(f"queue.overflow.{sorted(set(v) - {'to', 'reason'})[0]}: only to and reason are set; "
                           f"the standing yes covers {CHECK_BRANCH}/* branches and nothing wider")
    return bad


def queue_slots(q: dict) -> tuple[int, str]:
    """The number of slots, and how it was reached: the cores over the cores one run uses."""
    cores = os.cpu_count() or 1
    if "slots" in q:
        return q["slots"], "queue.slots"
    width = cores if q.get("width", 1) == "all" else q.get("width", 1)
    return max(1, cores // width), f"{cores} cores / width {q.get('width', 1)}"


def queue_dir() -> Path:
    """Shared by every worktree of the repo, like checked.log: the machine's runs, not a branch's."""
    return Path(git("rev-parse", "--path-format=absolute", "--git-common-dir")) / "jig" / "queue"


def try_lock(path: Path):
    """An open file holding PATH's lock, or None if another process holds it. The OS frees the
    lock when its holder dies, however it dies, so a killed run leaves nothing to clean up."""
    import fcntl
    f = path.open("a+")
    try:
        fcntl.flock(f, fcntl.LOCK_EX | fcntl.LOCK_NB)
        return f
    except BlockingIOError:
        f.close()
        return None


def stamp(f, cmd: list[str], full: bool) -> None:
    f.seek(0)
    f.truncate()
    f.write(json.dumps({"cmd": shlex.join(cmd), "where": os.getcwd(), "pid": os.getpid(),
                        "since": int(time.time()), "full": full}))
    f.flush()


def held(path: Path) -> dict | None:
    """What holds PATH's lock, or None when nothing does."""
    probe = try_lock(path)
    if probe is not None:
        probe.close()
        return None
    try:
        return json.loads(path.read_text() or "{}")
    except (OSError, ValueError):
        return {}


def queue_state(qdir: Path, slots: int) -> tuple[list[dict], list[dict], dict | None]:
    """(the runs holding a slot, the runs waiting, the complete check holding the full lock)."""
    running = [h for i in range(slots) if (h := held(qdir / f"slot-{i}.lock")) is not None]
    waiting = []
    for w in sorted(qdir.glob("wait-*.lock")):
        h = held(w)
        if h is None:
            w.unlink(missing_ok=True)      # its waiter died before removing it
        else:
            waiting.append(h)
    return running, waiting, held(qdir / "full.lock")


def over_load(q: dict) -> bool:
    """Read only when the repo set a threshold: a browser or a build spikes the load, and the
    right number differs per machine, so queue depth alone is the default."""
    if "max_load" not in q:
        return False
    return os.getloadavg()[0] / (os.cpu_count() or 1) > q["max_load"]


def run_line(h: dict) -> str:
    age = int(time.time()) - int(h.get("since") or time.time())
    return f"{h.get('cmd', '?')}  in {h.get('where', '?')}  for {age}s" + ("  [complete check]" if h.get("full") else "")


def overflow_route(q: dict, root: Path) -> None:
    short = git("rev-parse", "--short=12", "HEAD")
    branch = f"{CHECK_BRANCH}/{short}"
    remote = "origin" if "origin" in git("remote").split() else (git("remote").split() or ["<remote>"])[0]
    step = role_settings(Board.load(root).data)[0]["check"]
    print(f"the queue is full or a complete check is running: this complete check overflows to "
          f"GitHub Actions, on the owner's standing yes (queue.overflow: "
          f"\"{q['overflow']['reason']}\"). The check role:")
    print(f"  git push {remote} HEAD:refs/heads/{branch}")
    print(f"  gh run list --branch {branch} --workflow jig-check.yml      (the run's id and URL: setup.sh, then check.sh --full)")
    print(f"  gh run watch <id> --exit-status")
    print(f"  python3 {DIR}/jig.py checked --ci <run url> --tier {step['tier']} --effort {step['effort']} --seconds <s>"
          "      (s: the run's own duration)")
    print(f"  git push {remote} --delete {branch}")


def cmd_queue(root: Path, args) -> int:
    """Run a command holding one of the machine's slots, and return its exit code; with no
    command, print who holds and who waits. jig holds the slot; it never chooses what runs."""
    q = Board.load(root).data.get("queue") or {}
    if bad := queue_problems({"queue": q}):
        die("; ".join(bad))
    slots, how = queue_slots(q)
    qdir = queue_dir()
    qdir.mkdir(parents=True, exist_ok=True)
    cmd = args.command[1:] if args.command[:1] == ["--"] else args.command
    if not cmd:
        if args.full:
            die("usage: jig queue --full -- <command…>", 2)
        running, waiting, full = queue_state(qdir, slots)
        print(f"slots: {slots} ({how})" + (f", no new slot above load {q['max_load']} per core" if "max_load" in q else ""))
        print(f"running: {len(running)}")
        for h in running:
            print(f"  {run_line(h)}")
        print(f"waiting: {len(waiting)}")
        for h in waiting:
            print(f"  {run_line(h)}")
        print(f"complete check: {'running' if full is not None else 'none'}")
        return 0

    locks = []      # held for the command's length: closing them, or dying, frees them
    wait_file = None
    said = False
    misses = 0
    try:
        while True:
            if args.full and not any(l.name.endswith("full.lock") for l in locks):
                f = try_lock(qdir / "full.lock")
                if f is not None:
                    locks.append(f)
            have_full = not args.full or bool(locks)
            slot = None
            if have_full:
                for i in range(slots):
                    if (slot := try_lock(qdir / f"slot-{i}.lock")) is not None:
                        break
            # The machine is full only when every slot or the full lock is held. A wait for
            # the load alone is a wait: a busy browser is no reason to push a check.
            full_queue = slot is None
            if slot is not None and over_load(q):
                slot.close()
                slot = None
            if slot is not None:
                locks.append(slot)
                break
            if full_queue and args.full and "overflow" in q:
                # A run that just ended frees its slot a moment before the next takes it:
                # look once more before sending a check off the machine.
                misses += 1
                if misses >= 2:
                    for l in locks:
                        l.close()
                    overflow_route(q, root)
                    return OVERFLOW_EXIT
                time.sleep(0.2)
                continue
            if wait_file is None:
                wait_file = try_lock(qdir / f"wait-{os.getpid()}-{int(time.time() * 1000)}.lock")
                if wait_file is not None:
                    stamp(wait_file, cmd, args.full)
            if not said:
                running, waiting, _ = queue_state(qdir, slots)
                print(f"waiting for a slot: {len(running)} running, {len(waiting)} waiting", file=sys.stderr, flush=True)
                said = True
            time.sleep(0.5)
        if wait_file is not None:
            Path(wait_file.name).unlink(missing_ok=True)
            wait_file.close()
            wait_file = None
        for l in locks:
            stamp(l, cmd, args.full)
        try:
            # The command never inherits the locks: a process it leaves behind would hold the
            # slot long after the run. The trade is that a jig killed outright frees it early.
            proc = subprocess.Popen(cmd)
        except OSError as e:
            die(f"cannot run {cmd[0]}: {e.strerror}", 127)
        # A stop sent to jig reaches the command too, so the slot is never freed under a run
        # that is still going.
        import signal
        def forward(sig, _frame):
            proc.send_signal(sig)
        for sig in (signal.SIGTERM, signal.SIGHUP):
            signal.signal(sig, forward)
        while True:
            try:
                rc = proc.wait()
                # A command killed by a signal exits as a shell reports it: 128 + the signal.
                return 128 - rc if rc < 0 else rc
            except KeyboardInterrupt:
                continue        # the terminal sent it to the command as well; wait for its exit
    finally:
        if wait_file is not None:
            Path(wait_file.name).unlink(missing_ok=True)
            wait_file.close()
        for l in locks:
            l.close()


def cmd_merge(root: Path, args) -> int:
    """Merge a job into trunk and delete its entry in the same commit: trunk never holds a
    merged job, and the merge commit is the record of it."""
    os.chdir(root)        # its git paths (the notes, the entry, derived files) are the whole repo's
    board = Board.load(root, working_tree=True)
    trunk, name = board.trunk, args.name
    if not args.number:
        ensure_roadmap(root, trunk)
    if args.number:
        # The conflicted merge's last step before its commit: the ids it brings in get numbers.
        if not git("rev-parse", "-q", "--verify", "MERGE_HEAD"):
            die("no merge in progress: `jig merge <job>` numbers its ids itself")
        if git("diff", "--name-only", "--diff-filter=U"):
            die("resolve and `git add` the conflicted files first")
        for line in number_placeholders(root, trunk) or ["nothing to number"]:
            print(f"numbered {line}" if "→" in line else line)
        # The conflicted merge's last step before its commit, so it closes what a clean one does;
        # a merge stopped after its close (derive.sh failed) has its close in the index already.
        close_merged(root, board, trunk)
        sort_glossary(root)
        return 0 if setup_and_derive(root, board, "the job") else 1
    if not name:
        die("usage: jig merge <job> [-m msg] [--subject ids], or jig merge --number", 2)
    if git("branch", "--show-current") != trunk:
        die(f"merge from {trunk} (the hubnode's checkout)")
    if name not in board.jobs:
        die(f"no job {name}")
    # Gated is the record that the complete check passed, or that a batch owes it: a job merged
    # without it leaves `jig release` nothing to see.
    if board.jobs[name].get("state") != "gated":
        die(f"job {name} is {board.jobs[name].get('state') or 'in no state'}, not gated: gate it "
            f"first. `jig gate {name}`, the check it prints, then `jig mark {name} gated` "
            f"(or `jig mark {name} gated --batch`, and one check on {trunk} after the batch)")
    if git("status", "--porcelain", "--untracked-files=no"):
        die("commit or stash first: the merge commit carries the job and its entry, nothing else")
    # The merge stages whatever derived_files matches, so an untracked file there (a draft, a
    # stray output) would be committed as derived.
    globs = board.data.get("derived_files", [])
    stray = sorted(f for f in git("ls-files", "--others", "--exclude-standard", "-z",
                                  cwd=str(root)).split("\0") if f and matches(f, globs)) if globs else []
    if stray:
        die(f"untracked {', '.join(stray)} "
            f"{'matches' if len(stray) == 1 else 'match'} derived_files: remove or commit "
            f"{'it' if len(stray) == 1 else 'them'}")
    waiting = [d for d in board.jobs[name].get("after", []) if d in board.jobs]
    if waiting:
        die(f"R8 job {name} builds after {', '.join(waiting)}, which has not merged")
    branch = board.branch(name)
    # The gate checked the commit the latest note names; anything built since is unchecked.
    notes = handoff_notes(branch, name)
    if not notes:
        die(f"{name} has filed no handoff note on {branch}: hand off and gate it first")
    m = re.search(r"^Commit: (\w+)", git("show", f"{branch}:{notes[-1]}"), re.M)
    since = changed_since(m.group(1) if m else branch, branch, board)
    if since:
        die(f"{branch} has changed since the commit {notes[-1]} names ({', '.join(since[:5])}): "
            "hand off again and gate that, or merge the gated commit by hand")
    # A job marked gated --batch may still have a gate checkout: nothing of it stays behind.
    remove_gate_scratch(name, f"`jig merge {name}`")
    # The subject ends in `merge <job>` either way: the gate's deleted-branch fallback finds
    # the job by it. A caller who already wrote it out isn't given it twice.
    subject = args.subject or ""
    if not re.search(rf"(?:^|: )merge {re.escape(name)}$", subject):
        subject = (f"{subject}: " if subject else "") + f"merge {name}"
    msg = subject + (f"\n\n{args.message}" if args.message else "")
    # Trunk's history is the record of a check the batch owes: `jig release` reads it there.
    if board.jobs[name].get("check") == "batch":
        msg += "\n\nCheck: batch"
    p = subprocess.run(["git", "merge", "--no-ff", "--no-commit", "-m", msg, branch],
                       capture_output=True, text=True, errors="replace")
    merging = bool(git("rev-parse", "-q", "--verify", "MERGE_HEAD"))
    if p.returncode and not merging:
        die(f"git merge {branch}: {(p.stderr or p.stdout).strip()}")
    conflicted = git("diff", "--name-only", "--diff-filter=U").splitlines()
    appends = [f for f in conflicted if matches(f, append_globs(board))]
    resolved = sync_resolutions(branch, appends) if p.returncode and appends == conflicted else None
    if resolved:
        # Taken from a replay of the job's sync, not resolved here: on trunk the job is
        # `theirs`, and the rows must come out as the sync and the gate order them.
        for f, text in resolved.items():
            write_raw(Path(f), text)
            git("add", "--", f, check=True)
        # --no-edit keeps the comment lines git added for the conflicts it saw; none is left.
        merge_msg = Path(git("rev-parse", "--path-format=absolute", "--git-path", "MERGE_MSG"))
        merge_msg.write_text(re.sub(r"\n*# Conflicts:\n(#\t.*\n)*", "\n", merge_msg.read_text()))
        print(f"resolved {', '.join(appends)} as `jig sync` would: trunk's lines, then {name}'s")
        p.returncode = 0
    elif p.returncode and appends:
        # Anything sync would stop on is the job's to resolve, beside its checks.
        git("merge", "--abort")
        die(f"merging {branch} conflicts in append files ({', '.join(appends)}): "
            f"`jig sync` the job, then merge again")
    # A job holding a later number of a counter this one used lands after it: its numbers
    # were reserved past this one's, and syncing first shows it what trunk now holds.
    used = held_numbers(board.jobs[name])
    later = []
    for on, ol in board.jobs.items():
        if on == name:
            continue
        for k, nums in held_numbers(ol).items():
            if used.get(k) and any(n > max(used[k]) for n in nums):
                later.append(f"job {on} holds {k} {', '.join(map(str, sorted(nums)))}, after "
                             f"{name}'s {', '.join(map(str, sorted(used[k])))}: it syncs before "
                             "its next handoff")
    del board.jobs[name]
    board.save()
    git("add", "--", JOBS, check=True)
    # A branch writes D-?<slug>, so no job waits on the hubnode for a number: they are given
    # here, in the merge commit, where no two branches can take the same one.
    numbered = [] if p.returncode else number_placeholders(root, trunk)
    # R5 keeps the roadmap on trunk, so a page the job moved is re-pointed in every
    # (touches …) naming it here, in the merge commit, rather than on the branch. A list item
    # the job built stays, read done from its spec: in a pararepo no merge writes the roadmap.
    roadmap = main_root() / ROADMAP
    if roadmap.is_file():
        raw = read_raw(roadmap)
        fam = family()
        kept = retarget_touches(raw, page_moves("HEAD"),
                                lambda h: fam.ours(product_of(h.removesuffix(" " + NO_PHASE), fam.owners)))
        # A page the job moved to another repo takes its items there in this same commit.
        kept = items_follow_moves(kept, fam)
        if not same_roadmap(kept, raw):
            write_raw(roadmap, kept)
            git("add", "--", ROADMAP, check=True)
    if not p.returncode:
        sort_glossary(root)
    snap = Snapshot(where="index")
    # A merged job leaves nothing in flight: its spec and bug specs leave in the merge commit,
    # their scopes kept on the note. A conflicted merge closes at `jig merge --number` instead.
    closed = [] if p.returncode else close_specs(
        finished_specs(snap, board, name, job_specs(branch, name, trunk)), snap)
    if p.returncode:
        print(f"conflicts merging {branch}; {name}'s entry is already deleted in the index. "
              f"Resolve these, `git add` each, `jig merge --number` (it numbers the job's "
              f"D-?<slug> ids and runs setup.sh and derive.sh), then `git commit`:",
              file=sys.stderr)
        for f in conflicted:
            print(f"  {f}", file=sys.stderr)
        for l in later:
            print(l)
        return 1
    for line in numbered:
        print(f"numbered {line}")
    for line in closed:
        print(line)
    # git runs post-merge only for a merge it commits itself, not this one.
    # This commit isn't a merge, so a metarepo's M4 would refuse derived files in it, and derive
    # doesn't run. A hand merge brought the job's sources in without it, so they may be stale.
    if not merging:
        run_setup(root)
        if board.data.get("derived_files"):
            now = "" if (root / META).exists() else f", or run {DERIVE} and commit now"
            print(f"jig: {DERIVE} didn't run: a hand merge leaves derived files stale until the "
                  f"next `jig merge`{now}", file=sys.stderr)
    elif not setup_and_derive(root, board, name):
        return 1
    commit = ["git", "commit", "-q", "--no-edit"] if merging else \
        ["git", "commit", "-q", "-m", f"{msg}: already in {trunk}, entry deleted"]
    if subprocess.run(commit).returncode:
        # A refusal of the job's own change (a page's form, say) is the job's to fix: amended
        # on trunk, the fix would never be gated.
        print(f"the merge isn't committed. If the hook refused {name}'s own change, `git merge "
              f"--abort`, which puts {name}'s entry back, fix it on {branch}, and hand "
              f"off and gate again; if it refused the merge alone, fix that, then `git commit`",
              file=sys.stderr)
        return 1
    print(f"merged {name}; its entry is gone from {JOBS} in the same commit. Sync the clean jobs.")
    clean_up_job(name, branch)
    # Sessions are the host's, so jig only says it: the hubnode closes them with its tool.
    print(f"close the sessions that worked on {name}")
    for l in later:
        print(l)
    return 0


def job_specs(rev: str, name: str, trunk: str) -> set[str]:
    """The specs this run of job NAME handed off, by its notes on REV that TRUNK doesn't have: a
    job opened again under an earlier one's name inherits that one's notes, and its specs."""
    return {m.group(1) for n in handoff_notes(rev, name) if not git("cat-file", "-t", f"{trunk}:{n}")
            if (m := re.search(r"^Spec: (\S+)", git("show", f"{rev}:{n}"), re.M))}


def close_merged(root: Path, board: "Board", trunk: str) -> None:
    """In a merge being finished by hand, close what its job leaves, as a clean merge does:
    the job is named by the merge's subject, and its notes are on MERGE_HEAD."""
    first = Path(git("rev-parse", "--path-format=absolute", "--git-path", "MERGE_MSG")).read_text().split("\n", 1)[0]
    m = re.search(r"(?:^|: )merge (\S+)$", first)
    if not m:
        return
    snap = Snapshot(where="index")
    lines = close_specs(finished_specs(snap, board, m.group(1), job_specs("MERGE_HEAD", m.group(1), trunk)), snap)
    for line in lines:
        print(line)


def clean_up_job(name: str, branch: str) -> None:
    """After a job's merge commit: remove its worktree when nothing is left in it, then its
    branch, which the merge holds. Anything left (an uncommitted edit, an untracked file) is
    named and nothing is removed: it may be work no commit carries."""
    where = None
    for block in git("worktree", "list", "--porcelain").split("\n\n"):
        lines = block.splitlines()
        if f"branch refs/heads/{branch}" in lines:
            where = lines[0].removeprefix("worktree ")
    if where:
        left = git("status", "--porcelain", cwd=where)
        if left:
            print(f"left {where} and its branch {branch}: it holds {len(left.splitlines())} "
                  f"uncommitted or untracked file(s). Save what matters, then `git worktree "
                  f"remove {where}` and `git branch -d {branch}`")
            return
        # git status leaves ignored files out, and the removal deletes them: name what goes.
        ignored = git("ls-files", "--others", "--ignored", "--exclude-standard", "--directory",
                      cwd=where).splitlines()
        p = subprocess.run(["git", "worktree", "remove", where], capture_output=True, text=True)
        if p.returncode:
            print(f"left {where} and its branch {branch}: git worktree remove: "
                  f"{(p.stderr or p.stdout).strip()}")
            return
    p = subprocess.run(["git", "branch", "-d", branch], capture_output=True, text=True)
    if p.returncode:
        print(f"left the branch {branch}: git branch -d: {(p.stderr or p.stdout).strip()}")
        return
    print(f"removed {name}'s " + ("worktree and " if where else "") + f"branch {branch}")
    if where and ignored:
        print(f"  with the worktree went {len(ignored)} ignored file(s) or folder(s): "
              + ", ".join(ignored[:5]) + (", …" if len(ignored) > 5 else ""))


def append_globs(board: "Board") -> list[str]:
    """The board's append files, and the decision log and ideas file in every repo: any job
    may add to them, so two jobs' entries at one spot are the conflict sync resolves by itself."""
    return [*board.data.get("append_files", []), LOG, IDEAS]


def cmd_rules(root: Path, args) -> int:
    board = Board.load(root)
    refusals = check_rules(root, board, staged=args.staged)
    for r in refusals:
        print(r)
    if not refusals:
        print("ok")
    return 1 if refusals else 0


def cmd_job(root: Path, args) -> int:
    board = Board.load(root)
    name, job = board.job_for_branch(git("branch", "--show-current"))
    if not name:
        print("no job for this branch")
        return 1
    print(json.dumps({name: {**job, "branch": board.branch(name), "worktree": board.worktree(name),
                             "opened": opened(board, name)}}, indent=2))
    return 0


# --------------------------------------------------------------- sync + merge

CONFLICT = re.compile(
    r"^<<<<<<< .*?\n(?P<ours>.*?)^\|\|\|\|\|\|\| .*?\n(?P<base>.*?)^=======\r?\n"
    r"(?P<theirs>.*?)^>>>>>>> .*?\n",
    re.S | re.M,
)


def resolve_appends(path: Path) -> bool:
    """Resolve conflicts where both sides only added at the same spot. True if clean."""
    text, ok = resolved_appends(read_raw(path))
    write_raw(path, text)
    return ok


def resolved_appends(text: str) -> tuple[str, bool]:
    out, pos, ok = [], 0, True
    for m in CONFLICT.finditer(text):
        out.append(text[pos:m.start()])
        if m.group("base").strip() == "":
            out.append(m.group("theirs") + m.group("ours"))  # trunk's lines, then ours
        else:
            ok = False
            out.append(m.group(0))
        pos = m.end()
    out.append(text[pos:])
    return "".join(out), ok


def cmd_sync(root: Path, args) -> int:
    board = Board.load(root)
    trunk = board.trunk
    branch = git("branch", "--show-current")
    name, job = board.job_for_branch(branch)
    # Sync brings in this checkout's upstream: trunk for a job, the metarepo for a pararepo's
    # trunk. A plain repo's or a metarepo's trunk has nothing upstream.
    if getattr(args, "answered", None):
        if name or branch != trunk or not (root / PARA).exists():
            die("--answered closes rows of a pararepo's sync buffer: run it on that pararepo's trunk", 2)
        return sync_answered(root, args.answered, args.answered_in, args.reason)
    if not name and branch == trunk and (root / PARA).exists():
        return sync_meta(root)
    if not name:
        die("not on a job branch")
    # Only the merge needs a clean tree; the metarepo step writes only the untracked cache.
    if git("status", "--porcelain"):
        die("commit or stash first: the tree is dirty")
    stuck = merge_trunk(board, root)
    if stuck is None:
        print(f"merged {trunk}; nothing to resolve")
        return 0
    if stuck:
        print(f"resolve by hand, then `git commit` and `./{DIR}/scripts/setup.sh`:", file=sys.stderr)
        for f in stuck:
            print(f"  {f}", file=sys.stderr)
        return 1
    print(f"merged {trunk}; append conflicts resolved automatically")
    return 0


def merge_trunk(board: "Board", here: Path) -> list[str] | None:
    """Merge trunk into the checkout at HERE, resolving append-only conflicts in append_files.
    None: git merged it cleanly. []: resolved and committed. Otherwise the files left for a
    hand, with the merge still in progress."""
    p = subprocess.run(["git", "-c", "merge.conflictStyle=diff3", "merge", "--no-edit", board.trunk],
                       stdout=subprocess.PIPE, text=True, errors="replace", cwd=here)
    if p.returncode == 0:
        return None
    append_files = append_globs(board)
    stuck = []
    for f in git("diff", "--name-only", "--diff-filter=U", cwd=str(here)).splitlines():
        if matches(f, append_files) and resolve_appends(here / f):
            git("add", "--", f, cwd=str(here))
        else:
            stuck.append(f)
    if stuck:
        return stuck
    git("commit", "--no-edit", check=True, cwd=str(here))
    # git runs post-merge only for a merge it finished itself, not this one.
    run_setup(here)
    return []


def git_version() -> tuple[int, ...]:
    m = re.search(r"(\d+)\.(\d+)", git("version"))
    return (int(m.group(1)), int(m.group(2))) if m else (0, 0)


def blob(rev: str, path: str) -> str:
    """PATH at REV, its bytes kept: a merge writes the resolution built from it into the file."""
    return git_raw("show", f"{rev}:{path}", errors="surrogateescape")


def replay_sync(job: str, trunk: str) -> tuple[str, list[str]] | None:
    """git's half of `jig sync` merging TRUNK into JOB, written nowhere: the tree, with conflict
    markers in diff3 style, and the conflicted files. None when git can't (older than 2.38)."""
    p = subprocess.run(["git", "-c", "merge.conflictStyle=diff3", "merge-tree", "--write-tree",
                        "--name-only", "--no-messages", job, trunk], capture_output=True, text=True, errors="replace")
    tree, *conflicted = p.stdout.splitlines() or [""]
    return (tree, conflicted) if p.returncode in (0, 1) and tree else None


def sync_resolutions(job: str, files: list[str]) -> dict[str, str] | None:
    """FILES as `jig sync` would leave them after merging trunk (HEAD) into JOB, or None if
    the sync would stop on any of them, or any isn't a conflict where both sides only added: a
    file one side deleted is conflicted with no markers, and resolving it would keep the file."""
    replay = replay_sync(job, "HEAD")
    if not replay:
        return None
    tree, conflicted = replay
    out = {}
    for f in files:
        raw = blob(tree, f)
        text, ok = resolved_appends(raw)
        if f not in conflicted or not CONFLICT.search(raw) or not ok:
            return None
        out[f] = text
    return out


def changed_since(commit: str, branch: str, board: "Board") -> list[str]:
    """What a job did after the commit that was checked: the files its own commits changed,
    and what a merge of trunk carries beyond what `jig sync` makes of that merge. Trunk's
    changes aren't the job's, a hand edit hidden in a resolution is. Handoff notes, and the
    deferred.md rows the review's untaken findings get beside them, are bookkeeping made after
    the check by design. deferred.md is judged by its net change over the whole range, not
    commit by commit: a row edited and restored later deleted nothing. A line the job's net
    change deletes rewrites a disposition no one checked, so it counts; one trunk deleted,
    brought in by a sync, is trunk's."""
    trunk, appends = board.trunk, append_globs(board)
    out: list[str] = []
    deferred = False

    def job_changes(old: str, new: str) -> list[str]:
        nonlocal deferred
        files = git("-c", "core.quotePath=false", "diff", "--name-only", "--no-renames", old, new).splitlines()
        deferred |= DEFERRED in files
        return [f for f in files if f != DEFERRED]

    for line in git("rev-list", "--first-parent", "--parents", f"{commit}..{branch}").splitlines():
        c, *parents = line.split()
        if len(parents) > 1 and subprocess.run(["git", "merge-base", "--is-ancestor", parents[1], trunk],
                                               capture_output=True).returncode == 0:
            # Replay the sync: git's merge, then the append rule, compared with what was committed.
            replay = replay_sync(parents[0], parents[1])
            if not replay:
                if git_version() < (2, 38):
                    die(f"comparing a synced job needs git 2.38 or later (`git merge-tree "
                        f"--write-tree`); this is git {'.'.join(map(str, git_version()))}")
                # No replay to compare with: everything the merge changed counts as the job's.
                replay = (parents[0], [])
            tree, conflicted = replay
            files = []
            for f in job_changes(tree, c):
                if f in conflicted and matches(f, appends):
                    text, ok = resolved_appends(blob(tree, f))
                    if ok and text == blob(c, f):
                        continue
                files.append(f)
        else:
            files = job_changes(parents[0], c)
        out += [f for f in files if f and not f.startswith(f"{DIR}/handoffs/") and f not in out]
    if deferred and deferred_deleted(commit, branch, trunk):
        out.append(DEFERRED)
    return out


def deferred_deleted(commit: str, branch: str, trunk: str) -> bool:
    """Whether the job's net change to deferred.md from COMMIT to BRANCH deletes a line: one
    COMMIT had that BRANCH lacks, unless trunk deleted it between the two syncs."""
    def rows(rev: str) -> Counter:
        return Counter(l for l in blob(rev, DEFERRED).splitlines() if l.strip()) if rev else Counter()
    gone = rows(commit) - rows(branch)
    if gone:
        gone -= rows(git("merge-base", commit, trunk)) - rows(git("merge-base", branch, trunk))
    return bool(gone)


# ---------------------------------------------------------- review + handoff

def review_marker(root: Path) -> Path:
    common = Path(git("rev-parse", "--path-format=absolute", "--git-common-dir"))
    d = common / "jig" / "reviewed"
    d.mkdir(parents=True, exist_ok=True)
    return d / (git("branch", "--show-current") or "detached").replace("/", "%")


def review_log() -> list[tuple[str, dict]]:
    """Every `jig reviewed` record in this clone, oldest first: the commit, and what it ran at
    with its kind. A line written before records carried data is the commit alone."""
    log = git_common() / "jig" / "reviewed.log"
    out = []
    for line in (log.read_text().splitlines() if log.exists() else []):
        sha, _, rest = line.strip().partition(" ")
        if not sha:
            continue
        try:
            data = json.loads(rest) if rest else {}
        except ValueError:
            data = {}
        out.append((sha, data if isinstance(data, dict) else {}))
    return out


def job_chain(head: str, board: "Board") -> list[str]:
    """HEAD's first-parent commits, newest first, that belong to this piece of work, so a
    review of other work is never taken for it: on a job, those trunk doesn't hold; working
    alone, those since the last commit that added a handoff note, which ended the last task."""
    branch = git("branch", "--show-current")
    name, _ = board.job_for_branch(branch)
    if name and branch != board.trunk:
        # `--`: a trunk named like a folder (firmware's main/) is otherwise ambiguous to git.
        return git("rev-list", "--first-parent", head, f"^{board.trunk}", "--").splitlines()
    # HEAD's own note doesn't end its chain: a handoff from the note commit is the same task.
    # A merge bringing trunk's notes in, or a note renamed, ended no task.
    ended = git("log", "--first-parent", "--no-merges", "-M", "--diff-filter=A", "--format=%H",
                "-1", f"{head}^", "--", f"{DIR}/handoffs/") if git("rev-parse", "-q", "--verify",
                                                                    f"{head}^") else ""
    return git("rev-list", "--first-parent", head, *([f"^{ended}"] if ended else []), "--").splitlines()


def last_review(chain: list[str], kind: str | None = None) -> tuple[str, dict] | None:
    """The newest record on CHAIN, of KIND when given ("full" or "change"); the newest record
    of a commit wins, so a commit reviewed twice reads as its later review."""
    # Per kind too: a review-change recorded on the full review's own commit mustn't hide it.
    recs: dict[tuple[str, str | None], dict] = {}
    for sha, data in review_log():
        recs[(sha, None)] = recs[(sha, review_kind(data))] = data
    for c in chain:
        if (c, kind) in recs:
            return c, recs[(c, kind)]
    return None


def review_kind(data: dict) -> str:
    # "recheck" is what records written before review-change was named say.
    return "change" if data.get("kind") in ("change", "recheck") else "full"


def this_part(chain: list[str]) -> list[str]:
    """CHAIN (newest first) cut at its newest commit adding a handoff note, a `--partial` one
    too: the commits of the job's current part."""
    if not chain:
        return chain
    # --no-merges: a sync bringing trunk's notes in ended no part of this job.
    noted = set(git("log", "--first-parent", "--no-merges", "--diff-filter=A", "--format=%H",
                    chain[0], "--", f"{DIR}/handoffs/").splitlines())
    cut = next((i for i, c in enumerate(chain) if c in noted), None)
    return chain[:cut] if cut is not None else chain


def blocking_reviews(chain: list[str]) -> int:
    """How many reviews of this part's commits recorded blocking findings, full or change: a
    review recorded either way is a strike. A part ends at a commit adding a handoff note (a
    `--partial` one too), so each part's strikes start again at 0. A clean review between
    strikes resets nothing."""
    on = set(this_part(chain))
    latest: dict[str, dict] = {}
    for sha, data in review_log():
        if sha in on:
            latest[sha] = data
    return sum(1 for d in latest.values() if isinstance(d.get("blocking"), int) and d["blocking"] > 0)


def bug_spec_for(job: str, chain: list[str]) -> str:
    """The bug spec for JOB written in the current part of CHAIN (newest first), or "": a spec
    a commit of the part added or changed that names JOB as the part's tip has it, and that
    didn't name JOB at the part's base. It lifts the strike limit for that part only: an earlier
    part's spec, edited or moved, would otherwise leave every later part's strikes unlimited.
    A draft that gets its line in a later commit counts; read at the tip, a line removed later
    in the part counts for nothing."""
    part = this_part(chain)
    if not part:
        return ""
    base = git("rev-parse", "-q", "--verify", f"{part[-1]}^")
    earlier = bug_specs_at(base, job) if base else set()
    # A `git mv` of an earlier part's spec is that spec still, under its old path at the base.
    moved = {}
    if base:
        for line in git("-c", "core.quotePath=false", "diff", "-M", "--name-status", "--diff-filter=R",
                        base, part[0], "--", f"{DIR}/specs/").splitlines():
            _, old, new = line.split("\t")
            moved[new] = old
    on, commit, touched = set(part), "", []
    for line in git("-c", "core.quotePath=false", "log", "--first-parent", "--no-merges", "--no-renames",
                    "--diff-filter=AM", "--name-only", "--format=%x00%H", part[0], "--",
                    f"{DIR}/specs/").splitlines():
        if line.startswith("\0"):
            commit = line[1:]
            if commit not in on:
                break
        elif line and line not in touched:
            touched.append(line)
    return next((f for f in touched if moved.get(f, f) not in earlier
                 and bug_for(git_raw("show", f"{part[0]}:{f}")) == job), "")


def bug_specs_at(rev: str, job: str) -> set[str]:
    """The specs at REV that name themselves the bug spec for JOB."""
    paths = {h[0].split(":", 1)[-1] for h in grep_hits("-F", "Bug-for:", rev, "--", f"{DIR}/specs/")}
    return {f for f in paths if bug_for(git_raw("show", f"{rev}:{f}")) == job}


def cmd_reviewed(root: Path, args) -> int:
    """Record that HEAD has had its adversarial review, what it ran at, and how many blocking
    findings it left. Called by the review role. A review-change reviews only what changed
    since the last recorded review, so it needs a full review of the job under it."""
    if (args.tier is None) != (args.effort is None):
        die("give --tier and --effort together")
    if args.tier is not None and (args.tier < 1 or args.effort < 0):
        die("tier counts from 1, effort from 0")
    if args.blocking is not None and args.blocking < 0:
        die("--blocking counts findings, from 0")
    change = args.change or args.recheck
    head = git("rev-parse", "HEAD")
    board = Board.load(root)
    chain = job_chain(head, board)
    if change and not last_review(chain, "full"):
        die("no full review of this job on HEAD's first-parent chain: a review-change reviews "
            "what changed since one. Run review-work, then `jig reviewed` without --change")
    strikes = blocking_reviews(chain)
    name = board.job_for_branch(git("branch", "--show-current"))[0] or \
        git("branch", "--show-current") or "work"
    # Any review, full or change: a review past the last strike is refused whichever way it's recorded.
    if strikes >= STRIKES and not bug_spec_for(name, chain):
        part = this_part(chain)
        base = git("rev-parse", "-q", "--verify", f"{part[-1]}^") if part else ""
        earlier = sorted(bug_specs_at(base, name)) if base else []
        die(f"{strikes} reviews of this job recorded blocking findings: strike {STRIKES} starts "
            f"Bug, and the next review is refused. Commit the bug role's spec for this part, with "
            f"`Bug-for: {name}` on a line of its own, then review again"
            + (f". {', '.join(earlier)} named the job before this part began, so editing or moving "
               f"it counts for nothing: write this part's spec at a new path" if earlier else ""))
    ran = {k: v for k, v in (("tier", args.tier), ("effort", args.effort), ("ran", args.ran),
                             ("blocking", args.blocking)) if v is not None}
    if change:
        ran["kind"] = "change"
    review_marker(root).write_text(head + "\n" + (json.dumps(ran) + "\n" if ran else ""))
    # Every review ever, for a metarepo's gate (a merge's second parent must be one of them),
    # for a review-change's handoff, which reads the full review's settings back from here,
    # and for the strikes, counted from the blocking findings recorded.
    with open(git_common() / "jig" / "reviewed.log", "a") as log:
        log.write(head + (" " + json.dumps(ran, separators=(",", ":")) if ran else "") + "\n")
    print(f"recorded {'review-change' if change else 'review'} of {head[:12]}"
          + (f", {args.blocking} blocking" if args.blocking else ""))
    if args.blocking:
        # The log now holds this record, so it is counted.
        n = blocking_reviews(chain)
        if n < STRIKES:
            print(f"Strike {n} of {STRIKES}: the work session fixes them, then review-change")
        elif not bug_spec_for(name, chain):
            print(f"Strike {STRIKES} of {STRIKES}: Bug runs next; the next review is refused until "
                  f"the bug role's spec, with `Bug-for: {name}`, is committed")
        else:
            # At or past the limit with the bug spec already committed, which is what `jig
            # next` reads too: the fixing goes on.
            print(f"Strike {n}, under the bug role's spec: the work session fixes them, then "
                  f"review-change")
    return 0


def next_step(root: Path, board: "Board", name: str) -> tuple[str, str, str, str]:
    """(step, who, session, why) for job NAME, read from records jig already keeps: the board's
    state, the handoff notes, the review log, the gate's checkout and the check log."""
    trunk, branch, state = board.trunk, board.branch(name), board.jobs[name].get("state")
    hub = "continue the hubnode"
    notes = handoff_notes(branch, name) if state == "gated" else []
    m = re.search(r"^Commit: (\w+)", git("show", f"{branch}:{notes[-1]}"), re.M) if notes else None
    if state == "gated":
        # `jig merge`'s own test: a branch moved past the commit its newest note names is refused.
        if not (m and changed_since(m.group(1), branch, board)):
            why = "Job; on the owner's word"
            if board.jobs[name].get("check") == "batch":
                why = "Batch; on the owner's word, then one check on " + trunk + " for the batch"
            return "merge", "hubnode", hub, why
        # The board still says gated, so the gate's check would read as covering the new commits.
        step, who, session, _ = chain_step(board, name)
        return step, who, session, (f"Job; gated at {m.group(1)[:12]}, changed since: mark it "
                                    f"back; review-change, handoff, gate again")
    return chain_step(board, name)


def chain_step(board: "Board", name: str) -> tuple[str, str, str, str]:
    """next_step for a job not gated, read from its branch."""
    trunk, branch = board.trunk, board.branch(name)
    hub = "continue the hubnode"
    if not git("rev-parse", "-q", "--verify", f"refs/heads/{branch}"):
        return "work", "work", "new session", f"Job; no branch {branch} yet"
    chain = git("rev-list", "--first-parent", branch, f"^{trunk}", "--").splitlines()
    if not chain:
        return "work", "work", "new session", "Job"
    notes = handoff_notes(branch, name)
    note = git("show", f"{branch}:{notes[-1]}") if notes else ""
    m = re.search(r"^Commit: (\w+)", note, re.M)
    if m and not changed_since(m.group(1), branch, board):
        if re.search(r"^Partial: yes", note, re.M):
            return "work", "work", "continue the work session", "Job; the spec's next part"
        scratch = gate_scratch(name)
        where = main_root() / scratch
        if not where.exists():
            return "gate", "hubnode", hub, f"Job; `jig gate {name}`"
        # Before the check log: a check of a checkout built from an older note covers nothing.
        stale = gate_holds(board, name, where)
        if stale:
            return "gate", "hubnode", hub, f"Job; {stale}"
        head = git("rev-parse", "HEAD", cwd=str(where))
        if not any(r["commit"] == head for r in checked_records()):
            return "check", "check", "new session", f"Job; the complete check in {scratch}"
        return "gate", "hubnode", hub, f"Job; checked: `jig mark {name} gated`"
    found = last_review(chain)
    if not found:
        return "review-work", "review", "new session", "Job; once the work's checks pass"
    reviewed, ran = found
    strikes = blocking_reviews(chain)
    blocked = isinstance(ran.get("blocking"), int) and ran["blocking"] > 0
    if strikes >= STRIKES and not bug_spec_for(name, chain):
        return "bug", "bug", "new session", (f"Bug; a job's third blocking review: {strikes} "
                                             f"strikes, and the next review is refused")
    if changed_since(reviewed, branch, board):
        flow = f"Fix, strike {strikes}" if blocked else "Fix or Sync"
        return ("review-change", "review", "new session",
                f"{flow}; once the checks pass, of what changed since {reviewed[:12]}")
    if blocked:
        return "fix", "work", "continue the work session", f"Fix, strike {strikes}; " \
            f"{ran['blocking']} blocking finding{'s' if ran['blocking'] != 1 else ''}"
    return "handoff", "work", "continue the work session", "Job"


def cmd_next(root: Path, args) -> int:
    """The next step of a job (this branch's, or each open job's on trunk): the node or role
    that does it, and whether it continues a session or starts one."""
    board = Board.load(root)
    if args.name:
        if args.name not in board.jobs:
            die(f"no job {args.name}")
        names = [args.name]
    else:
        here = board.job_for_branch(git("branch", "--show-current"))[0]
        names = [here] if here else list(board.jobs)
    if not names:
        print("no open jobs: the next job starts at `jig open`")
        return 0
    for name in names:
        step, who, session, why = next_step(root, board, name)
        print(f"{name}: {step} — {who}, {session}" + (f" ({why})" if why else ""))
    return 0


NOTE = """# Handoff: {job}

Commit: {head}
Date: {today}
Spec: {spec}
{partial}{ran}
## Built
<!-- what this delivers, in a few lines -->

## Done-when evidence
<!-- one line per spec item: the command run and what it printed -->

## Review
<!-- findings from the adversarial review, and what you did about each -->

## Fold-in
<!-- Every documentation page that covers code this changed: does it still describe the
     code? Replace each ___ and tick the box: the stale sentences are edited (deleting
     counts), or none went stale and this says why. Each roadmap item naming one of those
     pages (a No phase item not done, or a taken scope) has its own line: keep one answer,
     built, untouched or departed: <why>. An item stays in the roadmap, read done once a
     spec taking it is complete. The gate refuses an unanswered line. An UNOWNED file has no page
     covering it: add it to docmap in .jig/docmap.json, or say why it needs none. A pair line
     (`<id> vs <log> § <ids> (<page>): ___`) is answered after its colon, once for every id
     on it: agrees, narrows: <how>, or conflicts: <resolution>; on a line of several ids,
     narrows and conflicts name at least one of them. jig reads the rest of the line, so it
     stays as jig wrote it. -->
{foldin}

## Shared files changed
<!-- each shared/common file, and why this job had to touch it -->

## Test by hand
<!-- what a person should click or watch -->

## Left
<!-- what remains on this job -->
"""


def page_sections(text: str) -> list[tuple[str, list[str]]]:
    """A page's `## ` sections in order, each with its lines; what precedes the first is ''.
    Fenced code is skipped, so a page quoting a heading inside ``` doesn't gain a section."""
    out, fence = [("", [])], False
    for line in text.splitlines():
        if line.lstrip().startswith(("```", "~~~")):
            fence = not fence
        m = None if fence else re.match(r"^ {0,3}##[ \t]+(.*?)[ \t#]*$", line)
        if m:
            out.append((m.group(1).strip(), []))
        else:
            out[-1][1].append(line)
    return out


def section_items(lines: list[str]) -> list[str]:
    """The top-level list items of a section, each as its first line without the marker."""
    return [re.sub(r"^[-*+][ \t]+", "", l).strip() for l in lines if re.match(r"^[-*+][ \t]+\S", l)]


# The fold-in line for one roadmap item a change reached. The gate and merge parse it back,
# so a change here changes ITEM_LINE too.
CLIP = 60
ITEM_LINE = re.compile(r'^- \[[ xX]\] (No phase|Up next|Scope) `([^`]+)` \(([^()]*)\): "(.*)" — '
                       r'((?:(?!" — ).)*?)\s*$')


def item_answer(answer: str) -> str:
    """Why an item line's answer doesn't count yet, or "" when it does: built, untouched or
    departed (with its why), in any case, and anything after it."""
    a = answer.strip()
    if not a or "___" in a:
        return "blank: keep one of built, untouched, departed: <why>"
    if re.match(r"\w+\s*/", a):
        return "more than one answer kept: keep one"
    word = re.match(r"[A-Za-z]+", a)
    kind = word.group(0).lower() if word else ""
    if kind not in ("built", "untouched", "departed"):
        return "not built, untouched or departed"
    if kind == "departed" and not re.search(r"\w", a[len(kind):]):
        return "departed needs its why"
    return ""


def clip(text: str) -> str:
    return text if len(text) <= CLIP else text[:CLIP].rstrip() + "…"


def unreachable_line() -> str:
    """What a roadmap reader says when its family names a repo it couldn't read, "" if none."""
    gone = family().unreachable
    return (f"not read: {', '.join(gone)} can't be reached here (`jig repos`), so the roadmap "
            "items its trunk holds or takes aren't shown") if gone else ""


def roadmap_items(rev: str, states: tuple[str, ...] = ("taken",)) -> list[tuple[str, str, str, list[str]]]:
    """(kind, id, what, pages) for every item of the one list not done, and every scope in
    STATES, in REV's roadmap: the project work that names a page with `(touches …)`."""
    fam = family()
    full = roadmap_full(Snapshot(rev), fam)
    if not full:
        return []
    # The pages a product section names are its owning repo's: this repo reads its own.
    out = [(NO_PHASE, i["id"], i["plain"], i["touches"]) for i in full[1]
           if i["touches"] and i["state"] != "done" and fam.ours(i["product"])]
    for p in [p for p in full[0] if fam.ours(p["product"])]:
        for sc in p["scopes"]:
            if sc["state"] in states:
                out.append(("Scope", sc["id"], sc["bare"], sc["touches"]))
    return out


def foldin_lines(root: Path, board: Board, branch: str) -> str:
    """One line per documentation page covering the code this branch changed."""
    trunk = board.trunk
    base = trunk if branch and branch != trunk else "HEAD~1"
    rng = f"{trunk}...HEAD" if base == trunk else "HEAD~1..HEAD"
    # Both sides of a rename: the page that covered the old path describes it there.
    changed = [f for f in git("-c", "core.quotePath=false", "diff", "--name-only", "--no-renames",
                              rng).splitlines()
               if f and not f.startswith((".", f"{DIR}/"))]
    at_head = set(git("-c", "core.quotePath=false", "ls-tree", "-r", "--name-only", "HEAD").splitlines())
    # A file docmap names is asked about whatever its type (sdkconfig, a devicetree
    # overlay); only source files are flagged when no page covers them.
    pages, unowned = {}, []
    for f in changed:
        owners = [page_in(p, at_head) for p in doc_owners(board, f)]
        for page in owners:
            pages.setdefault(page, []).append(f)
        if not owners and f.endswith(SRC_EXT) and f in at_head:
            unowned.append(f)
    cited = decision_citers(root, trunk, rng)
    pairs = pair_lines(root, trunk, rng)
    if not pages and not unowned and not cited and not pairs:
        return "- [ ] no code changed — nothing to fold in"
    out = []
    for page in sorted(set(pages) | set(cited)):
        fs, ids = pages.get(page, []), cited.get(page, [])
        why = ([f"{len(fs)} file{'s' if len(fs) > 1 else ''}"] if fs else []) + ids
        out.append(f"- [ ] {page} — updated / no change because ___   ({', '.join(why)})")
    # Project work that names a page this change reached asks whether the change built it.
    # A page asked only for a decision it cites changed no code, so built nothing.
    asked: dict[tuple[str, str, str], list[str]] = {}
    for kind, iid, what, touches in roadmap_items(trunk):
        hit = [page for page in sorted(pages) if any(same_page(t, page) for t in touches)]
        if hit:
            asked[(kind, iid, what)] = hit
    out += [f'- [ ] {kind} `{iid}` ({", ".join(hit)}): "{clip(what)}" — built / untouched / departed: ___'
            for (kind, iid, what), hit in asked.items()]
    if gone := unreachable_line():
        out.append(gone)
    out += [f"- [ ] UNOWNED {f} — add to docmap (a new page starts from {PAGE_TEMPLATE}), "
            "or no page needed because ___ (the repository's own tooling, its build, CI, release "
            "and dev scripts, needs none)"
            for f in sorted(unowned)]
    return "\n".join(out + pairs)


def cmd_handoff(root: Path, args) -> int:
    board = Board.load(root)
    # A job's worktree: it says where the roadmap is written, and writes nothing.
    ensure_roadmap(root, board.trunk, write=False)
    branch = git("branch", "--show-current")
    name, job = board.job_for_branch(branch)
    if not name:
        name = branch or "work"          # solo: no job, the branch is the unit
    # The trunk checkout's jobs too: `jig mark gated` writes them there before the hubnode
    # commits them, and a note filed in between would merge on the older note's check. A copy
    # that doesn't parse may hold just that mark, mid-write or hand-edited: wait for it.
    marked = None
    if job is not None:
        try:
            marked = (json.loads((main_root() / JOBS).read_text()).get(name) or {}).get("state")
        except FileNotFoundError:
            pass
        except (OSError, ValueError, AttributeError):
            die(f"the trunk checkout's {JOBS} doesn't parse: hand off once the hubnode's edit is done")
    if job is not None and "gated" in (job.get("state"), marked):
        # Gated covers the note it was gated on; a newer note would merge on that gate's check.
        die(f"{name} is gated on {board.trunk}: the hubnode marks it back (`jig mark {name} ready`) "
            "before a new handoff, which is gated again")
    if git("status", "--porcelain"):
        die("commit everything first: a handoff names one commit")
    head = git("rev-parse", "HEAD")
    # The review needn't be HEAD itself: a clean `jig sync` merge of a reviewed commit, or the
    # bookkeeping after it, adds nothing of the job's that a reviewer didn't see.
    chain = job_chain(head, board)
    found = last_review(chain)
    since = changed_since(found[0], head, board) if found else []
    if not found or since:
        if found:
            die(f"{', '.join(since[:5])} changed since the review of {found[0][:12]}: a fix or a "
                f"hand-resolved sync gets a review-change. Review `git diff {found[0][:12]}..HEAD` "
                f"(a sync: `git show --remerge-diff <merge>` and what follows it), then: "
                f"python3 {DIR}/jig.py reviewed --change --tier N --effort N (the review role's)")
        die("no adversarial review on record for this commit.\n"
            f"  Review {head[:12]}, then: python3 {DIR}/jig.py reviewed")
    reviewed, ran = found
    if isinstance(ran.get("blocking"), int) and ran["blocking"] > 0:
        die(f"the review of {reviewed[:12]} recorded {ran['blocking']} blocking finding"
            f"{'s' if ran['blocking'] != 1 else ''}: Fix first. The work session fixes them, then "
            f"a review-change records what is left: python3 {DIR}/jig.py reviewed --change "
            "--blocking 0 --tier N --effort N")
    if not ran:
        # A record written before the log carried data: the marker holds what it ran at.
        marker = review_marker(root)
        lines = marker.read_text().splitlines() if marker.exists() else []
        if lines and lines[0].strip() == reviewed and len(lines) > 1 and lines[1].strip():
            ran = json.loads(lines[1])
    change = ran if review_kind(ran) == "change" else None
    if change:
        full = last_review(chain[chain.index(reviewed):], "full")
        ran = full[1] if full else {}
    (root / DIR / "handoffs").mkdir(parents=True, exist_ok=True)
    # handoff_notes reads these names back in order; a change here changes its pattern.
    path = root / DIR / "handoffs" / f"{file_safe(name)}-{date.today().isoformat()}.md"
    i = 2
    while path.exists():
        path = root / DIR / "handoffs" / f"{file_safe(name)}-{date.today().isoformat()}-{i}.md"
        i += 1
    # The roadmap matches a note to its spec by path from the repo root, so that is what is
    # written; a job's spec on the board stands in for a bare `jig handoff`.
    spec = args.spec or (job or {}).get("spec") or ""
    if spec:
        at = (Path.cwd() / spec).resolve()
        if not at.is_relative_to(root.resolve()):
            die(f"--spec {spec} is outside this repo: give the spec's path in it")
        spec = at.relative_to(root.resolve()).as_posix()
    # jig gate reads the Review lines back against the spec's Roles section.
    ran_lines = (f"Review: tier {ran['tier']}, effort {ran['effort']}\n" if "tier" in ran
                 else "Review: tier and effort not recorded\n")
    if ran.get("ran"):
        ran_lines += f"Ran: {ran['ran']}\n"
    if change:
        ran_lines += (f"Review-change: tier {change['tier']}, effort {change['effort']}\n"
                      if "tier" in change else "Review-change: tier and effort not recorded\n")
        if change.get("ran"):
            ran_lines += f"Review-change ran: {change['ran']}\n"
    path.write_text(NOTE.format(job=name, head=head, today=date.today().isoformat(),
                                spec=spec or "(none)", ran=ran_lines,
                                partial="Partial: yes\n" if args.partial else "",
                                foldin=foldin_lines(root, board, branch)))
    print(f"wrote {path.relative_to(root)}")
    if job is not None:
        print("Fill every heading, commit it, then tell the hubnode the job and the commit.")
    else:
        print(f"Fill every heading, commit it, then: python3 {DIR}/jig.py gate")
    return 0


# rules-metarepo.md (Every copy): a spec changing a claim lists every place that states it. jig finds the
# places that name it; a copy in other words is the spec writer's to find.
CLAIM_MARKS = ("home", "pointer", "copy")


def claim_texts(root: Path) -> list[tuple[str, list[str]]]:
    """(path, lines) for each tracked text file in the working tree: a binary or a blob over a
    megabyte holds no claim a reader restates. Under the jig folder only the log, specs and
    ledgers: jig's own files define the names, and a handoff records what was true then."""
    out = []
    for f in tracked(root):
        if f.startswith(f"{DIR}/") and not f.startswith((f"{DIR}/specs/", f"{DIR}/ledgers/", LOG, IDEAS, PROCESS)):
            continue
        p = root / f
        if not p.is_file() or p.stat().st_size > 1 << 20:
            continue
        data = p.read_bytes()
        if b"\0" in data:
            continue
        out.append((f, data.decode(errors="replace").splitlines()))
    return out


def unfenced(lines: list[str]) -> list[bool]:
    """For each line, whether it is outside fenced code: an example quoting a term states nothing."""
    out, fence = [], ""
    for line in lines:
        mark = re.match(r"[ \t]*(`{3,}|~{3,})", line)
        if mark and not fence:
            fence = mark.group(1)
            out.append(False)
        elif fence:
            # Only a run of the opening fence's own character, as long, closes it.
            if mark and mark.group(1)[0] == fence[0] and len(mark.group(1)) >= len(fence) \
                    and not line.strip()[len(mark.group(1)):].strip():
                fence = ""
            out.append(False)
        else:
            out.append(True)
    return out


LINK_STOP = re.compile(r"[)\s]")


def link_spans(line: str, blank_ends: bool = True) -> list[tuple[int, int, int, int, str]]:
    r"""(start, end, text start, text end, target) of each Markdown link in LINE, in order: the
    matches re.finditer(r"\[([^\]]*)\]\(([^)\s]*)\)") gives, or without BLANK_ENDS, the target
    `[^)]*`, found in one pass. That regex retries every `[` and rescans to the next `]` or `)`
    from each, so a minified line of brackets takes it minutes. A try from a `[` is settled by
    the first `]` after it, so every `[` before that `]` settles the same way and only the first
    needs trying; and the first stop after a `](` is shared by every later `](` before it."""
    out = []
    stop_from, stop = -1, None
    p = line.find("[")
    while p != -1:
        q = line.find("]", p + 1)
        if q == -1:
            break
        if line[q + 1:q + 2] == "(":
            s = q + 2
            if stop_from < 0 or s < stop_from or (stop is not None and s > stop):
                if blank_ends:
                    m = LINK_STOP.search(line, s)
                    found = m.start() if m else -1
                else:
                    found = line.find(")", s)
                stop_from, stop = s, (found if found != -1 else None)
            if stop is not None and line[stop] == ")":
                out.append((p, stop + 1, p + 1, q, line[s:stop]))
                p = line.find("[", stop + 1)
                continue
        p = line.find("[", q + 1)
    return out


def claim_mark(line: str, pat: re.Pattern, home: str) -> str:
    """pointer when any name PAT finds in LINE is a `§` reference or a link's text whose target
    is HOME's file: a line that points sends its reader home. copy otherwise. The home itself
    is marked by its caller, which knows its line."""
    name = Path(home).name
    # In order and apart, so the one link a name could sit in is the last starting at or before it.
    links = [(a, b) for _, _, a, b, target in link_spans(line) if name in target]
    starts = [a for a, _ in links]
    for m in pat.finditer(line):
        at = bisect.bisect_right(starts, m.start()) - 1
        if at >= 0 and m.start() < links[at][1]:
            return "pointer"
        # Read back from the name, and only as far as the mark needs, never forward from the
        # line's start: on a minified bundle's long runs either is once per name, and never finishes.
        i = m.start()
        while i and line[i - 1] in " \t`":
            i -= 1
        if not i or line[i - 1] != "§":
            continue
        j = i - 1
        while j and line[j - 1] in " \t":
            j -= 1
        if j and line[j - 1] == "`":
            j -= 1
        # The page is the word before the `§`, less "`(" at either end. `other.md § mote` names a
        # heading of another page: only the home's file, or no file, points home. So only its
        # last characters count: does it end in .md, and is its last path part the home's name?
        e = j
        while e and line[e - 1] in "`(":
            e -= 1
        if not e or line[e - 1].isspace() or line[max(0, e - 3):e] != ".md":
            return "pointer"
        st = e - len(name)
        if st >= 0 and line[st:e] == name:
            b = st
            while b and line[b - 1] in "`(":
                b -= 1
            if not b or line[b - 1].isspace() or line[st - 1] == "/":
                return "pointer"
    return "copy"


def claims_of_id(root: Path, want: str, prefix: str) -> tuple[list[str], list[tuple]]:
    """Notes and (file, line, mark, text, why) hits for decision id WANT, an entry or an idea."""
    text = read_entries_text(root)
    entries = log_entries(text, prefix)
    notes = []
    entry = next((e for e in entries if decision_id(e["id"]) == decision_id(want)), None)
    ids = [entry["id"] if entry else want]
    # A superseded id hops to its successor, as `jig decision` walks it: a line naming the old id
    # is a copy of a claim the successor now holds. A removed id is found by the log's spelling,
    # D-004 for D-4, since a supersedes line and git's history name it that way.
    num = re.fullmatch(rf"{re.escape(prefix)}0*(\d+)", want)
    widths = {len(e["id"]) - len(prefix) for e in entries if e["id"][len(prefix):].isdigit()}
    spellings = [ids[0]] + ([f"{prefix}{num.group(1).zfill(w)}" for w in sorted(widths)] if num and not entry else [])
    by = None
    for spelt in dict.fromkeys(spellings):
        if by := holds_now(spelt, text, prefix, "HEAD", str(root)):
            ids = hold_chain(spelt, text, prefix, "HEAD", str(root))
            break
    if by and "/" in by:
        # Moved down to a pararepo: its home is there now, and every line here naming it is a copy.
        ids = ids[:-1]
        notes.append(f"{ids[-1]} moved to {by}: lines naming any of {', '.join(ids)} are listed.")
        entry = None
    elif by:
        notes.append(f"{ids[0]} is superseded; what holds now is {by}: lines naming any of "
                     f"{', '.join(ids)} are listed.")
        entry = next((e for e in entries if e["id"] == by), None)
    elif not entry:
        notes.append(f"no entry {want} in {LOG} or {IDEAS}, or in their history: lines naming it are listed.")
    if entry and entry["file"] == IDEAS:
        notes.append(f"{entry['id']} is an idea, not decided yet: its home is {IDEAS}:{entry['line']}.")
    if entry and (frm := moved_from_in(text).get(entry["id"])):
        notes.append(f"{entry['id']} moved from {frm}.")

    def id_re(i: str) -> str:
        # D-2 and D-002 are one decision, as R6 counts it; whole ids only, D-7 is not D-70.
        num = re.fullmatch(rf"{re.escape(prefix)}0*(\d+)", i)
        body = rf"{re.escape(prefix)}0*{num.group(1)}" if num else re.escape(i)
        return rf"(?<![\w-]){body}(?![\w?-])"
    pat = re.compile("|".join(id_re(i) for i in ids))
    # The entry is the home, its status line naming what it supersedes included.
    lines_in = len(text.splitlines())
    homes = ({(entry["file"], entry["line"] + k)
              for k in range((entry["end"] if entry["end"] is not None else lines_in) - entry["start"])}
             if entry else set())
    hits = []
    for f, lines in claim_texts(root):
        for n, line in enumerate(lines, 1):
            if not pat.search(line):
                continue
            mark = "home" if (f, n) in homes else claim_mark(line, pat, entry["file"] if entry else LOG)
            why = "cites it as its source" if re.search(r"(?i)\bsources?\b", line) else ""
            hits.append((f, n, mark, line, why))
    if entry:
        names = touch_names(root, Board.load(root).trunk)
        mine = touching_entries(text, prefix, SELF, LOG, names)
        me = next((e for e in mine if e["id"] == entry["id"]), None)
        for o, ptr in peers_of(me, mine, prefix) if me else []:
            hits.append((o["file"], o["line"], "copy", f"### {o['id']} {o['title']}", f"peers by Touches on {ptr}"))
    return notes, hits


def claims_of_term(root: Path, term: str, prefix: str) -> tuple[list[str], list[tuple]]:
    """Notes and (file, line, mark, text, why) hits for glossary term TERM."""
    notes, hits = [], []
    key = term.casefold()
    gloss = root / GLOSSARY
    home = None
    if gloss.exists():
        for shown, at in heading_lines(gloss.read_text(errors="replace")).items():
            if shown.casefold() == key:
                home = (GLOSSARY, at[0][0])
                term = shown
    if not home:
        notes.append(f"no entry {term} in {GLOSSARY}: lines using it are listed.")
    word = re.compile(rf"(?<!\w){re.escape(term)}(?!\w)", re.I)
    slug = re.sub(r"[^\w -]", "", term.lower()).replace(" ", "-")
    for f, lines in claim_texts(root):
        # A page or an entry states a term; a spec, a handoff or code only uses it.
        page = f == LOG or (f.endswith(".md") and not f.startswith(f"{DIR}/"))
        for n, (line, prose) in enumerate(zip(lines, unfenced(lines)), 1):
            if (f, n) == home:
                hits.append((f, n, "home", line, ""))
                continue
            if not prose:
                continue
            m = word.search(line)
            anchor = re.search(rf"glossary\.md#{re.escape(slug)}(?![\w-])", line)
            if m and claim_mark(line, word, GLOSSARY) == "pointer" or anchor:
                hits.append((f, n, "pointer", line, ""))
            elif m and page:
                hits.append((f, n, "copy", line, ""))
    path = root / LOG
    text = path.read_text(errors="replace") if path.exists() else ""
    for e in live_entries(text, prefix):
        if any(pointer_term(p)[1].casefold() == key for p in entry_touches(e["block"]) or []):
            hits.append((LOG, e["line"], "copy", f"### {e['id']} {e['title']}", "its Touches names it"))
    return notes, hits


def print_claims(root: Path, claims: list[str]) -> int:
    """`reading-list --claims`: for each decision id or glossary term, every tracked place
    naming it, marked home, pointer or copy."""
    prefix = log_prefix(Board.load(root).trunk)
    for i, claim in enumerate(claims):
        is_id = re.fullmatch(log_id_re(prefix), claim)
        notes, hits = (claims_of_id if is_id else claims_of_term)(root, claim, prefix)
        print(("\n" if i else "") + f"Every copy of {claim}:")
        for note in notes:
            print(f"  ({note})")
        seen: dict[tuple[str, int], int] = {}
        rows = []
        for f, n, mark, line, why in hits:
            # One line once: a peer entry naming the id, say, is listed with both reasons.
            if (f, n) in seen:
                row = rows[seen[(f, n)]]
                if why and why not in row[4]:
                    row[4] = f"{row[4]}; {why}" if row[4] else why
                continue
            seen[(f, n)] = len(rows)
            rows.append([f, n, mark, line, why])
        rows.sort(key=lambda r: (CLAIM_MARKS.index(r[2]), r[0], r[1]))
        for f, n, mark, line, why in rows:
            print(f"  {mark:<8} {f}:{n}  {clip(line.strip())}" + (f"   ({why})" if why else ""))
        if not rows:
            print("  (no tracked line names it)")
    print("\nThese are the places that name each claim. One stated in other words is yours to find.")
    return 0


def cmd_docmap(root: Path, args) -> int:
    """`jig docmap <page or path>…`: a page docmap names prints its globs and whether it is a
    board or an approved deep subsystem; any other path prints the pages covering it. Only the
    map: `reading-list` adds the pages above and what to read first."""
    data = Board.load(root).data
    docmap = data.get("docmap") if isinstance(data.get("docmap"), dict) else {}
    deep = data.get("deep_subsystems") if isinstance(data.get("deep_subsystems"), dict) else {}
    boards = board_pages(data)
    for i, arg in enumerate(args.paths):
        if i:
            print()
        # Only a page is a board or a deep subsystem: a figure in a deep folder is a covered file.
        is_page = arg.endswith(".md") or page_forms(arg) != (arg,)
        kinds = [w for w, yes in (("board", is_page and any(same_page(arg, b) for b in boards)),
                                  ("deep subsystem", is_page and any(os.path.dirname(f).rstrip("/") in
                                                         {d.rstrip("/") for d in deep}
                                                         for f in page_forms(arg)))) if yes]
        # A page boards or deep_subsystems names is a page whether or not docmap maps it yet.
        if kinds or any(same_page(arg, k) for k in docmap):
            print(f"{arg}: page" + (f" ({', '.join(kinds)})" if kinds else ""))
            globs = page_globs(docmap, arg)
            for g in globs:
                print(f"  {g}")
            if not globs:
                print(f"  no globs: {DOCMAP} maps no files to it")
            continue
        pages = [p for p, globs in docmap.items() if isinstance(globs, list) and matches(arg, globs)]
        print(f"{arg}: " + ("covered by" if pages else f"no page in {DOCMAP} covers it"))
        for p in pages:
            print(f"  {p}")
    return 0


def cmd_reading_list(root: Path, args) -> int:
    """Given the files a task will touch, print the docmap pages to read first."""
    if args.claims:
        return print_claims(root, args.paths)
    board = Board.load(root)
    ensure_roadmap(root, board.trunk)
    want, unowned = [], []
    for pattern in args.paths:
        hits = [f for f in tracked(root) if matches(f, [pattern])] or [pattern]
        for f in hits:
            # A docmap key names the page in either form; list the one on disk.
            # A docmap page named itself is the page a task takes on: it is read too.
            pages = doc_owners(board, f) + [p for p in board.data.get("docmap") or {} if same_page(f, p)]
            owners = [q for p in dict.fromkeys(pages)
                      if (q := next((g for g in page_forms(p) if (root / g).exists()), ""))]
            want += [p for p in owners if p not in want]
            if not owners and f.endswith(SRC_EXT):
                unowned.append(f)
    print("Read first:")
    for core in ("AGENTS.md", RULES_DIR):
        if (root / core).exists():
            print(f"  {core}/" if core == RULES_DIR else f"  {core}")
    # A subsystem's page names only its own files in docmap, so its system page, where the
    # shared facts live, is reached by the docs tree, not the globs.
    have = set(tracked(root))
    deep = board.data.get("deep_subsystems")
    deep = deep if isinstance(deep, dict) else {}
    shown: set[str] = set()
    # A flat page in a system's folder is that system's, so it climbs like any subsystem's page. A seam's
    # page lives in the nearest folder both its systems share, docs/ for two, with none above.
    named = named_pages(board.data)
    flat = frozenset(p for p in want if flat_page(
        p, have, named, lambda f: (root / f).read_text(errors="replace")))
    # The project work naming a page is the context a page itself never carries.
    items = roadmap_items("HEAD", ("open", "taken"))
    if gone := unreachable_line():
        print(f"  ({gone})")
    # And the research still open on it: a spec taking a page sees what is undecided there.
    ideas_text = (root / IDEAS).read_text(errors="replace") if (root / IDEAS).is_file() else ""
    ideas = [(e, [pointer_term(t)[0] for t in entry_touches(e["block"]) or []])
             for e in idea_entries(ideas_text, log_prefix(board.trunk))]

    def show(page: str, line: str) -> None:
        """Print PAGE once, wherever it first appears, with the items that name it."""
        if page in shown:
            return
        print(line)
        shown.add(page)
        for kind, iid, what, touches in items:
            if any(same_page(t, page) for t in touches):
                print(f"      {kind.lower()} `{iid}`: {what}   ({ROADMAP})")
        for e, touches in ideas:
            if any(same_page(t, page) for t in touches):
                print(f"      idea {e['id']}: {e['title']}   ({IDEAS})")
    for page in want:
        show(page, f"  {page}")
        for up, below in pages_above(page, have, deep, flat):
            # a page that covers a named file needs no reason to be listed
            show(up, f"  {up}" if up in want else f"  {up}   (parent of {below})")
    if not want:
        print("  (no documentation page covers these files)")
    if unowned:
        print("\nNot covered by any page — the work may be undocumented:")
        for f in sorted(set(unowned)):
            print(f"  {f}")
    return 0


def review_shortfall(root: Path, branch: str, name: str, note: str) -> str:
    """What the note's review fell short of in the spec's Roles section, or "". A warning
    for now: it becomes a refusal only if weak reviews keep reaching the gate."""
    # The board's spec before the note's, and trunk's copy before the branch's, so a branch
    # can't edit what it is judged by. Only a spec trunk lacks (solo work) is read from the
    # branch.
    trunk_board = Board.load(root)
    m = re.search(r"^Spec: (\S+)", note, re.M)
    paths = [(trunk_board.jobs.get(name) or {}).get("spec") or "", m.group(1) if m else ""]
    text = ""
    for path in filter(None, paths):
        text = git("show", f"{trunk_board.trunk}:{path}") or git("show", f"{branch}:{path}")
        if text:
            break
    # A spec from before roles has `## Workflow`, with execute and recheck lines; a newer one
    # has `## Roles`, where review-change runs at review's line.
    sec = spec_section(text, "Roles", "Workflow")
    out = []
    for step, label, lines in (("review", "Review", ("review",)),
                               ("review-change", "Review-change|Recheck", ("recheck", "review"))):
        if label != "Review" and not re.search(rf"^(?:{label}):", note, re.M):
            break
        asked = None
        for line in lines:
            asked = asked or (re.search(rf"^{line}: tier (\d+), effort (\d+)", sec, re.M)
                              if sec else None)
        if not asked:
            continue
        want = f"the spec asks for tier {asked.group(1)}, effort {asked.group(2)}"
        got = re.search(rf"^(?:{label}): tier (\d+), effort (\d+)", note, re.M)
        if not got:
            out.append(f"the {step}'s tier and effort are not recorded; {want}")
        elif int(got.group(1)) > int(asked.group(1)) or int(got.group(2)) > int(asked.group(2)):
            out.append(f"{step} ran at tier {got.group(1)}, effort {got.group(2)}; {want}")
    return "; ".join(out)


def proposed_added(trunk: str, commit: str) -> list[dict]:
    """The decision entries COMMIT adds or changes beyond trunk that are still Proposed: a
    ruling the owner hasn't made, which the hubnode sends up while the job builds."""
    since = git("merge-base", trunk, commit)
    prefix = log_prefix(trunk)
    before = {e["id"]: e["block"] for e in log_entries(entries_at(since), prefix)} if since else {}
    return [e for e in log_entries(entries_at(commit), prefix)
            if e["status"].startswith("Proposed") and before.get(e["id"]) != e["block"]]


def built_untaken(where: Path, trunk: str, note: str, body: str, fold: str, specs: set[str]) -> list[str]:
    """Each fold-in line of FOLD answering built on a `## No phase` item that no spec of the job
    takes, read in the gate's merged checkout WHERE, with why: no spec takes it (add its
    `Scope:` line), or the item is gone from the merged roadmap (sync, then hand off again).
    SPECS are the job's, the note's own `Spec:` added; the note's `Scope:` lines count too."""
    named = re.search(r"^Spec: (\S+)", body, re.M)
    read = lambda f: (where / f).read_text(errors="replace") if (where / f).is_file() else ""
    took = {sc for f in specs | ({named.group(1)} if named else set()) for sc in spec_scopes(read(f))} \
        | set(scopes_in(note, body))
    fam = family()
    there = roadmap_scopes(fam.text) if fam.reads_meta else roadmap_scopes(read(ROADMAP))
    out = []
    for l in fold.splitlines():
        u = ITEM_LINE.match(l.strip())
        if not u or u.group(1) != NO_PHASE or u.group(2) in took or item_answer(u.group(5)) \
                or not u.group(5).strip().lower().startswith("built"):
            continue
        out.append(f"{l.strip()}   <- built, but " + (
            f"no spec of this job takes {u.group(2)}: add `Scope: {u.group(2)}` to the spec, so the "
            "item reads done" if u.group(2) in there else
            f"{u.group(2)} is gone from {trunk}'s roadmap: `jig sync`, then hand off again"))
    return out


def cmd_gate(root: Path, args) -> int:
    """Hubnode-side verification. Prints what to run; refuses what it can decide."""
    board = Board.load(root, working_tree=True)
    trunk = board.trunk
    ensure_roadmap(root, trunk)
    name = args.name or git("branch", "--show-current") or trunk
    job = board.jobs.get(name)
    if args.name and job is None:
        die(f"no job {args.name}")
    bad = []
    for dep in (job or {}).get("after", []):
        if dep in board.jobs:
            bad.append(f"R8 job {name} builds after {dep}, which has not merged")
    branch = board.branch(name) if job is not None else name
    notes = handoff_notes(branch, name)
    if not notes:
        bad.append(f"{name} has filed no handoff note on {branch}: run `jig handoff`")
    for b in bad:
        print(b, file=sys.stderr)
    if bad:
        return 1
    note = notes[-1]
    body = git("show", f"{branch}:{note}")
    sec = re.search(r"^## Fold-in\n(.*?)(?=^## )", body, re.S | re.M)
    if sec:
        # checklist items only — the instructions above them contain ___ by design
        open_lines = [l for l in sec.group(1).splitlines()
                      if l.strip().startswith("- [")
                      and (l.strip().startswith("- [ ]") or "___" in l)]
        # Each item line needs one answer; anything after it is the answerer's to say.
        for l in sec.group(1).splitlines():
            u = ITEM_LINE.match(l.strip())
            if u and l not in open_lines and (why := item_answer(u.group(5))):
                open_lines.append(f"{l.strip()}   <- {why}")
        for l in sec.group(1).splitlines():
            if l not in open_lines and (why := pair_problem(l)):
                open_lines.append(f"{l.strip()}   <- {why}")
        # Code a registered board page covers runs on that board: "no page needed" is not an
        # answer for it. The note's UNOWNED line predates the board's docmap entry (trunk's,
        # read here), or was written by hand. An unregistered page has no such teeth.
        docmap = board.data.get("docmap") or {}
        for l in sec.group(1).splitlines():
            u = re.search(r"UNOWNED (.+?) — .*no page needed", l, re.I)
            if not u or l in open_lines:
                continue
            for page in board_pages(board.data):
                if matches(u.group(1), page_globs(docmap, page)):
                    open_lines.append(f"{l.strip()}   <- {page} is a board page covering it: "
                                      "code that runs on a board needs its page")
        if open_lines:
            print(f"the fold-in in {note} is unanswered:", file=sys.stderr)
            for l in open_lines[:10]:
                print(f"  {l.strip()}", file=sys.stderr)
            if len(open_lines) > 10:
                print(f"  … and {len(open_lines) - 10} more", file=sys.stderr)
            return 1
    m = re.search(r"^Commit: (\w+)", body, re.M)
    commit = m.group(1) if m else branch
    unpaged = board_refusals(board.data, trunk, commit)
    if unpaged:
        for u in unpaged:
            print(u, file=sys.stderr)
        return 1
    para = load_para(trunk)
    if para is not None:
        spec = re.search(r"^Spec: (\S+)", body, re.M)
        unready = unreleased_proposals(root, para, trunk, commit,
                                       [(job or {}).get("spec") or "", spec.group(1) if spec else ""])
        if unready:
            for u in unready:
                print(u, file=sys.stderr)
            return 1
    label = f"job {name}" if job is not None else name
    print(f"{label}: gate {commit[:12]} from {note} on {branch}")
    weak = review_shortfall(root, branch, name, body)
    if weak:
        print(f"warning: {weak}", file=sys.stderr)
    for e in proposed_added(trunk, commit):
        print(f"warning: {e['file']} § {e['id']} {e['title']} is Proposed: it merges unruled unless "
              "the owner said to gate it as proposed", file=sys.stderr)
    # The commit the note names, never the job's live worktree, which may have moved on; and
    # trunk merged in the way `jig sync` merges it, so the gate checks the merge a sync makes.
    scratch = gate_scratch(name)
    where = main_root() / scratch
    # A gate whose checks failed is gated again after a new handoff, with no mark between.
    remove_gate_scratch(name, f"`jig gate {name}`")
    subprocess.run(["git", "worktree", "add", "--detach", str(where), commit], stdout=subprocess.DEVNULL)
    if not where.exists():
        die(f"git worktree add {scratch} {commit[:12]} failed")
    try:
        stuck = merge_trunk(board, where)
    except SystemExit:
        # The merge failed without conflicts; the checkout holds nothing of anyone's.
        if not remove_checkout(where):
            print(f"jig: remove the checkout: git worktree remove --force {scratch}", file=sys.stderr)
        raise
    if stuck:
        # Nothing in it is anyone's: the half-done merge is jig's own.
        gone = remove_checkout(where)
        print(f"merging {trunk} into {scratch} needs a hand in {', '.join(stuck)}: the job resolves "
              f"that by `jig sync` and hands off again. "
              + ("The checkout is removed." if gone else
                 f"Remove the checkout: git worktree remove --force {scratch}"), file=sys.stderr)
        return 1
    # A list item reads done only through a spec that takes it, so a built answer with no such
    # spec would leave built work open, offered again. The spec is read as this merge leaves
    # it, in the checkout: a merge needing a hand is refused above, since the sync it asks for
    # brings trunk's spec into the job.
    unbuilt = built_untaken(where, trunk, note, body, sec.group(1) if sec else "",
                            job_specs(branch, name, trunk))
    if unbuilt:
        gone = remove_checkout(where)
        print(f"the fold-in in {note} is unanswered:", file=sys.stderr)
        for l in unbuilt:
            print(f"  {l}", file=sys.stderr)
        if not gone:
            print(f"Remove the checkout: git worktree remove --force {scratch}", file=sys.stderr)
        return 1
    # Pairs are found at handoff against the trunk of then; a job merged since may rule on the
    # same page, and the merge here is where the two first meet.
    base = git("merge-base", trunk, commit)
    left, new, other = gate_pairs(where, trunk, sec.group(1) if sec else "", base, commit)
    if left or new or other:
        gone = remove_checkout(where)
        # The merge itself went through, so answering is all the job owes: no sync, no new
        # review, no new handoff. The note is bookkeeping a merge doesn't count as a change.
        print(f"the note doesn't answer these pairs: add each to the fold-in of {note} on {branch}, "
              f"ticked and answered agrees, narrows: <how> or conflicts: <resolution> (on a line of "
              f"several ids, naming one), commit the note alone, and gate again. `jig sync` only when "
              f"the merge itself needs a hand" + ("." if gone else
              f". Remove the checkout: git worktree remove --force {scratch}"), file=sys.stderr)
        # Each list names the cause jig found: a pair it listed at the handoff asks about an
        # entry the job already read; one new on trunk asks about one it has never seen.
        for head, lines in (("left out of the note, though jig listed them at the handoff:", left),
                            (f"new on {trunk} since the job's base:", new),
                            ("in another repo's log, read as it stands now:", other)):
            if lines:
                print(head, file=sys.stderr)
                for l in lines:
                    print(f"  {l}", file=sys.stderr)
        return 1
    print(f"{scratch} holds {commit[:12]} with {trunk} merged in. Run the project checks there; "
          "jig never runs them:\n")
    # As the hooks run it: itself when executable (any language), through bash when not.
    check = f"./{DIR}/scripts/check.sh"
    # A subshell: a shell left inside the checkout would sit in a deleted folder once it's removed.
    # The complete level: the gate is the check step's, the one place it runs per job.
    # Through the queue: two complete checks at once each run slower than both in turn.
    print(f"  (cd {scratch} && python3 {DIR}/jig.py queue --full -- "
          f"{'' if os.access(where / check, os.X_OK) else 'bash '}{check} --full)")
    step = role_settings(board.data)[0]["check"]
    print(f"\nThe check step runs it: tier {step['tier']}, effort {step['effort']}. When it passes, "
          f"record it there, with the seconds it took:")
    print(f"  (cd {scratch} && python3 {DIR}/jig.py checked --tier {step['tier']} "
          f"--effort {step['effort']} --seconds <s>)")
    print()
    # The merge closes the job's spec and its `Bug-for:` specs alike (close_specs).
    closing = []
    if job is not None:
        own = list(dict.fromkeys(x for x in [(job or {}).get("spec") or ""] + [
            f for f in git("-c", "core.quotePath=false", "ls-tree", "-r", "--name-only", commit, "--",
                           SPECS).splitlines() if is_spec(f) and bug_for(git("show", f"{commit}:{f}")) == name] if x))
        for f in own:
            lines = closes_with(git("show", f"{commit}:{f}"))
            closing += ([f"{f}:"] + [f"  {l}" for l in lines]) if lines and len(own) > 1 else lines
    if closing:
        # The merge deletes the spec: this is the owner's last look at what goes with it.
        print("Closes with the spec at merge:")
        for l in closing:
            print(f"  {l}")
        print()
    if job is not None:
        print(f"Then: jig mark {name} gated, which removes {scratch}, and on the owner's word: "
              f"jig merge {name}")
    else:
        # No job, no state change to hang the removal on.
        print("Then merge it, and remove the checkout (no job: solo work, so there is no board "
              f"state to mark):\n  git worktree remove --force {scratch}")
    return 0



def closes_with(spec: str) -> list[str]:
    """What the merge closes along with SPEC: every `## Out of scope` line, gone with the spec.
    Work not built stays on the roadmap, unspecced: nothing of it closes here."""
    if not spec:
        return []
    prose = re.sub(r"<!--.*?-->", "", spec_section(spec, "Out of scope") or "", flags=re.S)
    return [f"out of scope  {l.strip()}" for l in prose.splitlines() if l.strip()]


# --------------------------------------------------------------------- survey

# The vendor documents a page leans on (datasheets, a dev board's spec sheet, app notes) sit in
# a folder of this name inside the page's folder; one two pages use sits in the datasheets/ of
# the nearest folder both share, docs/datasheets/ at the top: a per-page copy would drift.
# Reserved at any depth: never a subsystem, never a page's home.
DATASHEETS = "datasheets"
# The layout before boards were systems: pages at docs/hardware/<board>.md, a board's files in
# docs/hardware/<board>/, parts in docs/hardware/components/<part>/. Read only to say where each
# file goes now; nothing writes there.
OLD_BOARDS = "docs/hardware/"
OLD_PARTS = f"{OLD_BOARDS}components/"
# Board-build files, by name. A branch adding or changing one builds for a board, and a board
# has a page: the gate refuses one no registered board page's docmap covers. /jig:init also
# reads a main/ with C as firmware, which no file name can say, so this list is the gate's own.
BOARD_BUILD = ("sdkconfig*", "platformio.ini", "idf_component.yml", "west.yml", "*.ino", "*.overlay")
# Where each kind of document lives: a file by name, a folder by its trailing "/".
DOC_HOMES = {
    "AGENTS.md": "rules, always loaded",
    "CLAUDE.md": "pointer to AGENTS.md",
    "README.md": "for people outside",
    "docs/": f"what the code is now: docs/<system>.md each system, a board as much as any, docs/<system>/<subsystem>.md its subsystems one level down (deeper only where {DOCMAP} deep_subsystems approves it); a page holding other files moves into a folder named for it, docs/<system>/<system>.md, beside the files it links; any other file there has no home",
    f"docs/…/{DATASHEETS}/": "the vendor documents a page leans on, in that page's folder; one two pages use, in the nearest folder both share",
    f"docs/{DATASHEETS}/": "a vendor document two systems use: reference files only, never a page",
    f"{DIR}/specs/": "a task in flight",
    f"{DIR}/process.md": "how the repo is worked where no other home takes it, one section per topic, read on demand",
    f"{DIR}/ledgers/": "workarounds.md patches that are in the code; deferred.md review findings that are not",
    f"{TEMPLATES}/": "the shape each record starts from, jig's, rewritten by every update",
    f"{DIR}/staging/": "chat-born files waiting to be resolved (untracked)",
}
# Tooling directories, jig's own among them. Their contents are a tool's own records, not
# documents looking for a home, so the stray check skips them entirely.
TOOL_DIRS = (f"{DIR}/", ".claude/", ".github/", ".gitlab/", ".vscode/", ".devcontainer/")
SRC_EXT = (".c", ".h", ".cpp", ".ino", ".rs", ".ts", ".tsx", ".js", ".jsx", ".py", ".go", ".swift")
CODE_EXT = SRC_EXT + (".sh", ".cmake", ".kconfig")


def tracked(root: Path) -> list[str]:
    # At the root, so a command run from a subfolder still sees every file, by its path from the root.
    return [p for p in git("ls-files", cwd=str(root)).splitlines() if p]


def naming(root: Path, path: str, files: list[str]) -> dict[str, list[int]]:
    """The tracked files that name PATH, each with its line numbers: by path, or by bare name
    when no other tracked file has that name, since a bare `AGENTS.md` could mean any of them.
    A match needs a path boundary on both sides, so `ui.md` is not `touch_ui.md` and
    `docs/ui.md` is not `app/docs/ui.md`; a leading `./` or `../` still counts.
    A handoff records what was true then, and jig's own files define the names, so neither cites."""
    base = Path(path).name
    pats = [path] + ([base] if base != path and [Path(f).name for f in files].count(base) == 1 else [])
    bound = re.compile(r"(?:(?<![\w./-])|(?<=\./))(?:" + "|".join(map(re.escape, pats)) + r")(?![\w/-])")
    # -I: a datasheet or firmware image that happens to hold the bytes is no citation.
    out: dict[str, list[int]] = {}
    for f, line, text in grep_hits("-I", "-F", *[a for p in pats for a in ("-e", p)], "--", ".", cwd=root):
        if (not line.isdigit() or f == path or "/handoffs/" in f"/{f}"
                or f in (*TOOL_FILES, CONFIG, DOCMAP, JOBS) or not bound.search(text)):
            continue
        out.setdefault(f, []).append(int(line))
    return out


def inbound(root: Path, path: str, files: list[str]) -> int:
    return len(naming(root, path, files))


# A root CHANGELOG.md is a home until `jig update` merges it into .jig/decisions.md.
ROOT_DOCS = ("AGENTS.md", "CLAUDE.md", "GEMINI.md", "README.md", "CHANGELOG.md")
# Agent instruction files under their standard names. Off root, each is a second rulebook
# that an agent opening that folder may load in place of the real one.
RULES_NAMES = ("AGENTS.md", "CLAUDE.md", "GEMINI.md")
# The page shape jig used before the descriptive contract: a page with all three is in it.
PAGE_HEADS = re.compile(r"^ {0,3}#{1,6}[ \t]+(Now|Rules|Checks)\b", re.M)
# Sections only the page contract has, so a file carrying one is a page wherever it sits.
CONTRACT_HEADS = re.compile(r"^ {0,3}##[ \t]+(Invariants|Undefined)[ \t#]*$", re.M)


def old_contract(text: str) -> bool:
    return set(PAGE_HEADS.findall(text)) == {"Now", "Rules", "Checks"}


def page_problems(text: str) -> list[str]:
    """What a page at home does against the page contract (rules-docs.md, Documentation)."""
    if old_contract(text):
        return ["old contract — convert: Now / Rules / Checks; fold what it says into "
                "description, delete what no longer holds, keep as Invariants only what has a "
                "why and a holder"]
    out, secs = [], page_sections(text)
    lead = [l.strip() for l in secs[0][1] if l.strip() and not l.lstrip().startswith("<!--")]
    # The title is the page's one `# ` line; whatever follows it first is the lead, or isn't.
    if lead and lead[0].startswith("# "):
        lead = lead[1:]
    if not lead or lead[0].startswith("#"):
        out.append("no lead paragraph: open with what the system is and why it exists")
    for name, lines in secs:
        if name == "Invariants":
            for item in section_items(lines):
                if " — " not in item or "held by" not in item.lower():
                    out.append(f'invariant without a why (" — ") or a holder ("held by"): {clip(item)}')
                elif holder_names_review(item):
                    out.append("invariant whose holder names review, which holds nothing on a page (no "
                               "step reads a page's Invariants): for what review covers, name a test or "
                               "what is seen on screen (on a board, on the board), or move it to the "
                               f"body; where a test holds it all, drop review: {clip(item)}")
    return out


# Review reads a diff, its spec and AGENTS.md, never a page's Invariants, so it holds none of them.
# Whether review is an entry's only holder is English no pattern reads ("test_x and review of
# `Y` for the rest"), so an entry whose holder names review is listed and the writer judges it,
# as the `.jig/` path listing beside it does. A word, never a path, file or compound name.
REVIEW_NAMED = re.compile(r"(?<![\w/.-])review(?:s|ed|er|ers|ing)?\b(?![-/.]\w)", re.I)


def holder_names_review(item: str) -> bool:
    """Whether the holder clause, "held by" to the line's end with inline code removed, names review."""
    m = re.search(r"\bheld by\b(.*)$", item, re.I)
    return bool(m and REVIEW_NAMED.search(re.sub(r"`[^`]*`", "", m.group(1))))


# A page names how the repository is worked when it names jig's own files: a `.jig/` path. The
# decision log is the one a page may cite, and the plan's paths are listed as the project.
# Words ("jig", "CI", "pytest") may be the product's own, so nothing searches for them.
PROCESS_PATH = re.compile(r"(?<![\w/.~-])(?:\.\.?/)*\.jig/(?!decisions\.md|specs/|handoffs/|roadmap\.md)[\w./-]*")
PROCESS_HOMES = (f"AGENTS.md for a rule every task needs, {DIR}/scripts/ for a step a script runs, "
                 f"a skill for a procedure an agent runs, {DIR}/process.md for the rest ({RULES_DIR}/rules-docs.md, "
                 "Homes)")


def process_prose(text: str) -> list[tuple[int, str]]:
    """(line number, path) for each `.jig/` path a page names outside fenced code and HTML
    comments: how the repository is worked, which a page never holds (rules-docs.md, Documentation:
    Product and process). Listed, never refused: a product that reads jig's files names them."""
    out, fence, comment = [], False, False
    for n, line in enumerate(text.splitlines(), 1):
        if not comment and line.lstrip().startswith(("```", "~~~")):
            fence = not fence
            continue
        if fence:
            continue
        kept = ""
        while line:
            if comment:
                end = line.find("-->")
                if end < 0:
                    line = ""
                else:
                    comment, line = False, line[end + 3:]
            else:
                # A comment opens only outside inline code: `<!--` quoted in prose hides nothing.
                code = [m.span() for m in re.finditer(r"`[^`]*`", line)]
                start = next((m.start() for m in re.finditer("<!--", line)
                              if not any(a <= m.start() < b for a, b in code)), -1)
                if start < 0:
                    kept, line = kept + line, ""
                else:
                    kept, line, comment = kept + line[:start], line[start + 4:], True
        out += [(n, m.group(0)) for m in PROCESS_PATH.finditer(kept)]
    return out


def process_lines(root: Path, files: list[str]) -> list[tuple[str, int, str]]:
    """(page, line number, path) for each `.jig/` path in a page under docs/."""
    return [(f, n, path) for f in product_pages(root, files) if f.startswith("docs/") and (root / f).is_file()
            for n, path in process_prose((root / f).read_text(errors="replace"))]


# The one project heading survey and update list: jig's own retired `## Undefined`, which no
# product names. `## Status` or `## Roadmap` may be the product's own word (a status call, a
# state machine), so old text is not searched for them: whoever writes a page judges it.
def project_sections(text: str) -> list[str]:
    where = (f"parked work → an item under ## {NO_PHASE} in {ROADMAP} naming this page; "
             f"an open question → an idea in {IDEAS}")
    return [f"## {name} is the project's: {where}"
            for name, _ in page_sections(text)[1:] if name.lower() == "undefined"]


def project_prose(text: str, sids: list[str] = ()) -> list[str]:
    """Lines naming the plan, outside fenced code, by what the hook refuses on an added line: a
    spec, handoff or roadmap path, or a scope id SIDS holds in code quotes. Old text predates
    the hook, and these are never product text; words that may be ("phase 3", a bare id,
    ROADMAP.md) aren't searched for."""
    out, fence = [], False
    finds = [PROJECT_PATHS, *scope_quoted(list(sids))]
    for n, line in enumerate(text.splitlines(), 1):
        if line.lstrip().startswith(("```", "~~~")):
            fence = not fence
        elif not fence:
            out += [f'line {n}: "{m.group(0).strip("`")}" names the plan: say what the product does '
                    f"today, and leave when to {ROADMAP}" for r in finds for m in r.finditer(line)]
    return out


def sentences(text: str) -> set[str]:
    """Prose sentences long enough that a match is a copy, not a common phrase."""
    flat = re.sub(r"\s+", " ", text)
    return {s.strip() for s in re.split(r"(?<=[.!?])\s+(?=[A-Z`*-])", flat) if len(s.strip()) > 25}


def reference_file(path: str, have: set[str] | None = None) -> bool:
    """Under a datasheets/ folder: a vendor's document, never a page. Given HAVE, only where
    rules-docs.md homes one, in a page's folder or at docs/datasheets/: an orphan datasheets/ folder
    is reported, not invisible. Without HAVE, any datasheets/ folder under docs/, which is
    enough to say a file is no page."""
    parts = path.split("/")
    if parts[0] != "docs" or DATASHEETS not in parts[1:-1]:
        return False
    if have is None:
        return True
    i = parts.index(DATASHEETS, 1)
    return i == 1 or bool(folder_owner("/".join(parts[:i]), have))


def reserved_page(path: str) -> bool:
    """A page named for a folder called datasheets: a system or subsystem under the reserved
    name, which would be read as reference files."""
    parts = path.split("/")
    return parts[0] == "docs" and len(parts) >= 3 and parts[-2] == DATASHEETS == Path(path).stem


def old_board_rows(files: list[str], read) -> list[dict]:
    """Every file in the old docs/hardware/ layout, as {path, to, board, why}: a page to
    docs/<board>.md, or docs/<board>/<board>.md when files go with it (BOARD: its boards entry); a board's files into that folder, its
    vendor PDFs into the folder's datasheets/; a part's files into the datasheets/ of the one
    board page that links the part, or docs/datasheets/ when two do, or none. A part's folder
    goes: a datasheet is a file in a page's datasheets/. Two files bound for one place, or one
    bound for a file already there, are named for where they came from (the part, the board).
    TO is None, and WHY says so, for a file with no one place to go: the owner places it."""
    pages = [f for f in files if f.startswith(OLD_BOARDS) and f.endswith(".md")
             and "/" not in f[len(OLD_BOARDS):]]
    users = {}
    for page in pages:
        for t in link_targets(page, read(page)):
            if t.startswith(OLD_PARTS) and "/" in t[len(OLD_PARTS):]:
                users.setdefault(t[len(OLD_PARTS):].split("/")[0], set()).add(Path(page).stem)
    rows = []
    for f in (f for f in files if f.startswith(OLD_BOARDS)):
        rest, to, board, why, origin = f[len(OLD_BOARDS):], None, False, "", ""
        if f in pages:
            to, board = f"docs/{Path(f).stem}/{Path(f).stem}.md", True
            if to == f:
                to, board, why = None, False, "the old layout's own index, not a board: fold it in or drop it"
        elif f.startswith(OLD_PARTS):
            origin = f[len(OLD_PARTS):].split("/")[0]
            who = sorted(users.get(origin, ()))
            to = (f"docs/{who[0]}/{DATASHEETS}/" if len(who) == 1 else f"docs/{DATASHEETS}/") + Path(f).name
        elif "/" in rest:
            origin = rest.split("/", 1)[0]
            if f"{OLD_BOARDS}{origin}.md" not in pages:
                why = f"{OLD_BOARDS}{origin}/ has no board page beside it: place it by hand"
            elif f.lower().endswith(".pdf"):
                to = f"docs/{origin}/{DATASHEETS}/{Path(f).name}"
            else:
                to = f"docs/{rest}"
        else:
            why = "names no board: place it by hand"
        rows.append({"path": f, "to": to, "board": board, "fold": False, "why": why, "origin": origin})
    # A page is flat until it holds another file (rules-docs.md, Documentation).
    for r in (r for r in rows if r["board"]):
        d = os.path.dirname(r["to"])
        if not any(o["to"] and o["to"].startswith(f"{d}/") for o in rows if o is not r):
            r["to"] = f"{d}.md"
    there = {f for f in files if not f.startswith(OLD_BOARDS)}
    for r in (r for r in rows if r["board"] and set(page_forms(r["to"])) & there):
        r["to"], r["board"], r["why"] = None, False, f"{page_in(r['to'], there)} is there already: fold the two by hand"
    for _ in range(2):
        bound = {}
        for r in rows:
            if r["to"]:
                bound.setdefault(r["to"], []).append(r)
        for to, rs in bound.items():
            if len(rs) < 2 and to not in there:
                continue
            for r in (r for r in rs if not r["board"]):
                if r["origin"] and not Path(to).name.startswith(f"{r['origin']}-"):
                    r["to"] = f"{os.path.dirname(to)}/{r['origin']}-{Path(to).name}"
                else:
                    r["to"], r["why"] = None, f"would land on {to}, which another file takes: place it by hand"
    for r in rows:
        del r["origin"]
    return rows


# A metarepo's docs tree has one level more than a code repo's: docs/<genre>/<page>, where a
# genre categorizes the ecosystem it defines (rules-metarepo.md, A metarepo's docs tree). None in a code
# repo; in a metarepo, the genres meta.json declares, or () when any folder under docs/ is one.
# Set from the repo once, by doc_homes, so the tree helpers below read one layout throughout.
GENRES: tuple[str, ...] | None = None
# `jig init --meta --genres product-ecosystem`: the categories an ecosystem's definition takes.
GENRE_TEMPLATES = {"product-ecosystem": ("products", "features", "principles", "concepts")}


def load_genres(root: Path) -> None:
    global GENRES
    GENRES = None
    if (root / META).exists():
        try:
            g = json.loads((root / META).read_text() or "{}").get("genres")
        except (ValueError, AttributeError):
            g = None
        GENRES = tuple(x for x in g if isinstance(x, str)) if isinstance(g, list) else ()


def genre_level(d: str) -> bool:
    """docs/<x> in a metarepo: a genre's place, which holds pages but is no page's folder."""
    return GENRES is not None and d.startswith("docs/") and d.count("/") == 1


def genre_dir(d: str) -> bool:
    """A metarepo's genre folder, declared, or any when meta.json declares none."""
    return genre_level(d) and (not GENRES or d[len("docs/"):] in GENRES)


def page_root(d: str) -> bool:
    """Where a top-level page sits flat: docs/ in a code repo, a genre folder in a metarepo."""
    return genre_dir(d) if GENRES is not None else d == "docs"


def old_layout(path: str) -> bool:
    """Under docs/hardware/, the layout before boards were systems. In a metarepo that folder
    is a genre like any other."""
    return GENRES is None and path.startswith(OLD_BOARDS)


def folder_page(path: str) -> bool:
    """docs/<...>/<name>/<name>.md: a page named for its folder, the shape of a page that holds
    other files. A page with nothing else to hold is flat (flat_page)."""
    parts = path.split("/")
    return (parts[0] == "docs" and len(parts) >= 3 and parts[-2] == Path(path).stem
            and not reference_file(path))


def page_shaped(text: str) -> bool:
    """Sections only a page has, in the contract's shape or the old one."""
    return old_contract(text) or bool(CONTRACT_HEADS.search(text))


def flat_spot(path: str, have: set[str]) -> bool:
    """Where a flat page can sit: directly in docs/, or beside the page of the folder it is in.
    Nothing in the path tells such a page from a note beside it; flat_page says which."""
    parent, name = os.path.dirname(path), os.path.basename(path)
    return (path.startswith("docs/") and path.endswith(".md") and not folder_page(path)
            and not reference_file(path) and not old_layout(path)
            and name not in RULES_NAMES and Path(path).stem != DATASHEETS
            and (page_root(parent) or bool(folder_owner(parent, have))))


def flat_page(path: str, have: set[str], docmap, read) -> bool:
    """docs/<name>.md or docs/<...>/<name>.md: a page with no folder of its own, which the
    board names (DOCMAP: named_pages) or its own sections make a page. Any other file there is
    one of its folder page's. A genre has no page, so a file directly in it is a page."""
    return flat_spot(path, have) and (path in docmap or genre_dir(os.path.dirname(path))
                                      or page_shaped(read(path)))


def page_folder(path: str) -> str:
    """The folder a page stands for, which the depth rule counts: docs/a/b for docs/a/b/b.md
    and for a flat docs/a/b.md alike."""
    return os.path.dirname(path) if folder_page(path) else path[:-len(".md")]


def folder_owner(d: str, have: set[str]) -> str:
    """The page that folder D stands for, in either form: d/<name>.md, or d.md still flat
    beside the folder it has started to fill (survey says to move it in). Empty for none."""
    name = os.path.basename(d)
    if name == DATASHEETS or "/" not in d or genre_level(d):
        return ""
    return next((p for p in (f"{d}/{name}.md", f"{d}.md") if p in have), "")


def page_forms(path: str) -> tuple[str, ...]:
    """A docs page's two forms, flat and in its folder: one page, whichever the tree holds.
    docmap keys and boards entries name it in either, so a branch can grow the folder with a
    git mv alone, since docmap.json is trunk's (R5)."""
    if not (path.startswith("docs/") and path.endswith(".md")) or reference_file(path):
        return (path,)
    d = page_folder(path)
    return (f"{d}.md", f"{d}/{os.path.basename(d)}.md")


def same_page(a: str, b: str) -> bool:
    return a in page_forms(b)


def page_in(path: str, have) -> str:
    """The form of page PATH that HAVE holds, PATH itself when it holds neither."""
    return next((f for f in page_forms(path) if f in have), path)


def page_globs(docmap: dict, page: str) -> list[str]:
    """Every glob docmap gives PAGE, under a key in either of its forms."""
    return [g for k, gs in docmap.items() if same_page(k, page) and isinstance(gs, list) for g in gs]


def owner_page(path: str, have: set[str], deep: dict) -> str:
    """The page whose folder PATH sits in, nearest first: its own folder's page holds the
    files it links. Empty when no folder above PATH has a page."""
    parts = path.split("/")
    for i in range(len(parts) - 1, 1, -1):
        d = "/".join(parts[:i])
        if (page := folder_owner(d, have)) and depth_ok(d, deep):
            return page
    return ""


def pages_above(page: str, have: set[str], deep: dict,
                flat: frozenset[str] = frozenset()) -> list[tuple[str, str]]:
    """Each page above PAGE in the docs tree, nearest first, as (page above, page below it).
    A page named for its folder climbs, and a flat page in FLAT; any other docmap key, a file
    outside the docs tree, has no page above it. A seam's page sits in the folder its two
    systems share, so what is above it is above both."""
    out, below = [], page
    while ((folder_page(below) or below in flat)
           and (up := owner_page(page_folder(below), have, deep))):
        out.append((up, below))
        below = up
    return out


def depth_ok(folder: str, deep: dict) -> bool:
    """A docs folder may hold a page: docs/<system> and docs/<system>/<subsystem> always, each
    level below that only with the owner's rationale in docmap.json's deep_subsystems. The key
    is trunk-only (R5), so the agent proposing a level can't approve it. Every level needs its
    own entry: approving docs/a/b/c says nothing about docs/a/b/c/d."""
    return not unapproved(folder, deep)


def unapproved(folder: str, deep: dict) -> list[str]:
    """Each level of FOLDER below a subsystem that deep_subsystems doesn't approve."""
    parts = folder.split("/")
    if parts[0] != "docs":
        return []
    # A genre adds no depth: its pages are systems, as docs/<system> is in a code repo.
    first = 4 if GENRES is None else 5
    return [d for i in range(first, len(parts) + 1) if not (
        isinstance(r := deep.get(d := "/".join(parts[:i])), str) and r.strip())]


def deep_fix(h: dict, deep: dict, level: dict | None = None) -> str:
    """A deep page's choices, shared by survey and update. LEVEL is its page_levels entry,
    None where there is none. A section covers no file, so it is no subsystem by rules-docs.md's
    definition, no rationale can hold, and the fold is the one choice; a shared page gets
    level_line's one answer; a subsystem's own files are the rationale's evidence."""
    move = f"{'fold it into' if h['fold'] else 'move it to'} {h['to']}"
    if level and level["level"] == "section":
        return f"{move}: it owns no files, so it is a section, not a subsystem"
    if level and level["level"] in ("shared", "unmapped"):
        return level_line(level)
    own = level["own"] if level and level["level"] == "subsystem" else []
    ask = " and ".join(unapproved(page_folder(h["path"]), deep))
    have = (f", naming the files it has of its own ({', '.join(own[:3])}{' …' if len(own) > 3 else ''})"
            if own else "")
    return f"{move}, or ask the owner to approve {ask} in {DOCMAP} deep_subsystems, with its rationale{have}"


def at_home(path: str, registers: list[str], deep: dict, have: set[str] = frozenset()) -> bool:
    """rules-docs.md (Documentation) lists these homes; a change there changes this. A file in a
    page's folder that isn't a page is one of that page's files, wherever it sits below it."""
    return (path in ROOT_DOCS or reference_file(path, have) or path in registers
            or (folder_page(path) and depth_ok(os.path.dirname(path), deep) and system_above(path, have, deep))
            or (not folder_page(path) and bool(owner_page(path, have, deep))))


def system_above(page: str, have: set[str], deep: dict) -> bool:
    """A folder page sits where a page may: its folder is a system's, flat in the page root,
    or inside a folder a page owns. A folder no page owns is no system, so a page below it is
    misplaced, the test a flat page passes through owner_page."""
    up = os.path.dirname(os.path.dirname(page))
    return page_root(up) or bool(owner_page(os.path.dirname(page), have, deep))


def page_home(path: str, have: set[str], deep: dict) -> str:
    """Flat beside the nearest page that has a folder, as a subsystem's page sits in its
    system's folder; else a system of its own, flat in docs/. A page of that name already
    there, flat or in its folder, is where it folds. Where the page would be deeper than the
    docs tree allows, the nearest page itself: fold it in. In a metarepo, the system of its own
    is flat in its genre folder. A page in its own folder moves with that folder, so it climbs
    from the folder above and lands in its folder unless the flat form is there to fold into,
    or the folder holds nothing else: a lone page lands flat, the form the hook lets in."""
    stem, folders = Path(path).stem, path.split("/")[:-1]
    own = folder_page(path)
    if own:
        folders = folders[:-1]
    lone = own and not any(f.startswith(f"{page_folder(path)}/") and f != path for f in have)

    def there(d: str) -> str:
        flat, inner = f"{d}/{stem}.md", f"{d}/{stem}/{stem}.md"
        return flat if (own and (flat in have or lone)) or (not own and inner not in have) else inner
    for i in range(len(folders), 1, -1):
        d = "/".join(folders[:i])
        if (page := folder_owner(d, have)) and depth_ok(d, deep):
            return there(d) if depth_ok(f"{d}/{stem}", deep) else page
    return there("/".join(folders[:2]) if GENRES is not None and len(folders) >= 2 else "docs")


def deep_home(path: str, deep: dict, have: set[str] = frozenset()) -> str:
    """The page of the nearest folder above PATH's own that the docs tree allows: in that
    folder, or flat beside it when only that one is there."""
    d = os.path.dirname(page_folder(path))
    while not depth_ok(d, deep):
        d = os.path.dirname(d)
    page = f"{d}/{os.path.basename(d)}.md"
    return f"{d}.md" if page not in have and f"{d}.md" in have else page


def meta_registers(root: Path, files: list[str], read) -> list[str]:
    """A metarepo's decision registers. entry_files says what pararepos cite, not where pages
    live; a register is no page, and stays wherever it is."""
    return [f for f in files if GENRES is not None and f.endswith(".md")
            and (Path(f).name == "DECISIONS.md" or bool(decision_rows(read(f), root)))]


def meta_hidden(root: Path, files: list[str], not_docs: list[str], read) -> list[dict]:
    """Each not_docs glob that hides a metarepo's pages from survey, as {glob, pages}: Markdown
    outside docs/ that is no root document and no register is a page to convert, and a glob
    left over from a code repo's reading of the tree keeps it out of sight."""
    if GENRES is None:
        return []
    regs = set(meta_registers(root, files, read))
    md = [f for f in files if f.endswith(".md") and not f.startswith(("docs/", *TOOL_DIRS))
          and f not in ROOT_DOCS and f not in regs]
    return [{"glob": g, "pages": hit} for g in not_docs if (hit := [f for f in md if matches(f, [g])])]


# Rulebook sentences jig reworded, as they stood: a copy that froze before the rewording still
# shares them. A rewording adds the old sentence here in the same commit.
RETIRED_RULES = ("The tree names the product's own parts, not its files, so a rule that touches several files lives once.",)


def doc_homes(root: Path, files: list[str], not_docs: list[str],
              read=None, deep: dict | None = None, docmap=None,
              only: set[str] | None = None, names: bool = True) -> list[dict]:
    """Every tracked Markdown file with no home, as {path, kind, to, fold, naming, named_at}.
    Kinds: `rules` an agent instruction file off root, `genre` a metarepo page under docs/ but
    in no genre folder, `board` a file in the old docs/hardware/
    layout (TO is where it goes), `reserved` a page named datasheets, `deep` a page named for its folder below
    a subsystem that deep_subsystems doesn't approve, flat or not, `page` a page, old shape or
    new, in the wrong place (in a folder with no page of its own), `copy` three or more
    sentences of jig's rulesets word for word, `stray` anything else.
    DEEP is the board's deep_subsystems, DOCMAP the pages it names (named_pages): a flat
    file there is a page.
    READ maps a path to its text, for update, which judges the files where they will be.
    ONLY limits the files judged, and NAMES false leaves naming empty: the hook asks only
    whether the few pages a change touches have a home, and reading every file that might name
    each would cost it the whole repo."""
    read = read or (lambda f: (root / f).read_text(errors="replace") if (root / f).is_file() else "")
    rules_dir = Path(__file__).resolve().parent / "rules"
    rules = " ".join([*(re.sub(r"\s+", " ", f.read_text()) for f in sorted(rules_dir.glob("rules-*.md"))),
                      *RETIRED_RULES]) if rules_dir.is_dir() else ""
    load_genres(root)
    registers = meta_registers(root, files, read)
    # Until `--merge-log` takes them, a register and a folder of decision records are at home,
    # as a root CHANGELOG.md is: the log is where they go, and update says so.
    registers += [f for f in files if f.endswith(".md") and Path(f).name.lower() == "decisions.md"
                  and not f.startswith(TOOL_DIRS) and f not in registers and rows_in(read(f), None)]
    # The hook judges a few files: only their folders are read for records.
    near = files if only is None else [f for f in files if os.path.dirname(f) in {os.path.dirname(o) for o in only}]
    registers += [f for d, info in record_folders(root, near, read).items()
                  for f in [*(x for _, x in info["records"]), *info["other"]]]
    deep = deep if isinstance(deep, dict) else {}
    docmap = docmap or set()
    have = set(files)
    old = {} if GENRES is not None else {r["path"]: r["to"] for r in old_board_rows(files, read)}
    out = []

    def naming_of(f: str) -> dict[str, list[int]]:
        return naming(root, f, files) if names else {}
    for f in files:
        if (not f.endswith(".md") or f.startswith(TOOL_DIRS) or matches(f, not_docs)
                or (only is not None and f not in only)):
            continue
        # The glossary is a docs file but no system's page: it is at home, in a metarepo too.
        if f == GLOSSARY:
            continue
        if f == "GLOSSARY.md":
            named = naming_of(f)
            out.append({"path": f, "kind": "stray", "to": GLOSSARY,
                        "fold": False, "naming": sorted(named),
                        "named_at": [f"{n}:{i}" for n in sorted(named) for i in named[n]]})
            continue
        # A metarepo's pages are all under docs/<genre>/, wherever entry_files finds them,
        # and in whatever shape: outside docs/, only a root document or a register is at home.
        if GENRES is not None and (
                (f.startswith("docs/") and not at_home(f, registers, deep, have)
                 and (f.count("/") == 1 or not genre_dir("/".join(f.split("/")[:2]))))
                or (not f.startswith("docs/") and f not in registers
                    and ("/" in f or not at_home(f, registers, deep, have)))):
            named = naming_of(f)
            top = f.split("/")[0] if "/" in f and not f.startswith("docs/") else ""
            to = page_in(f"docs/{top}/{Path(f).stem}.md", have) if top else None
            out.append({"path": f, "kind": "genre" if f.startswith("docs/") else "page", "to": to,
                        "fold": bool(to and (to in have or (root / to).exists())),
                        "naming": sorted(named),
                        "named_at": [f"{n}:{i}" for n in sorted(named) for i in named[n]]})
            continue
        if f in old or reserved_page(f):
            named = naming_of(f)
            out.append({"path": f, "kind": "board" if f in old else "reserved", "to": old.get(f),
                        "fold": False, "naming": sorted(named),
                        "named_at": [f"{n}:{i}" for n in sorted(named) for i in named[n]]})
            continue
        # A README is its folder's own document for outsiders: docmap naming one asks it on
        # every change, so it is read, and it stays where it is.
        if f in docmap and Path(f).name == "README.md":
            continue
        flat = flat_page(f, have, docmap, read)
        # A page's own files are at home, but a page-shaped file in a subfolder with no page
        # of its own is a page in the wrong place.
        shaped = (not flat and not folder_page(f) and not reference_file(f)
                  and f.startswith("docs/") and owner_page(f, have, deep)
                  and (f in docmap or page_shaped(read(f))))
        if flat and depth_ok(page_folder(f), deep):
            continue
        if not flat and at_home(f, registers, deep, have) and not shaped:
            continue
        text, to = read(f), None
        # A page first: one that quotes the rulebook is still the repo's page, not a copy.
        if "/" in f and Path(f).name in RULES_NAMES:
            kind = "rules"
        elif folder_page(f) and not system_above(f, have, deep):
            kind, to = "page", page_home(f, have, deep)
        elif folder_page(f) or flat:
            kind, to = "deep", deep_home(f, deep, have)
        # The board naming a file makes it a page in any format and anywhere: fold-in asks
        # it on every change, so it is no stray, whatever its sections are called.
        elif f in docmap or (f.startswith("docs/") and page_shaped(text)):
            kind, to = "page", page_home(f, have, deep)
        elif rules and len([s for s in sentences(text) if s in rules]) >= 3:
            kind = "copy"
        else:
            kind = "stray"
        named = naming_of(f)
        out.append({"path": f, "kind": kind, "to": to,
                    "fold": bool(to and (to in have or (root / to).exists())),
                    "naming": sorted(named),
                    "named_at": [f"{n}:{i}" for n in sorted(named) for i in named[n]]})
    return out


def page_shapes(root: Path, files: list[str], not_docs: list[str], docmap: set[str],
                skip: set[str], read, sections: frozenset[str] = frozenset(),
                only: set[str] | None = None) -> list[dict]:
    """Pages in the wrong one of their two shapes, as {path, to, into, fold, named}: a page
    named for its folder with nothing else there to hold, which goes flat beside its parent's
    page (INTO false), and a flat page with a folder of its own name, which goes into it (INTO
    true). SKIP are the files with no home, reported already. NAMED is false where the flat
    page would be neither in DOCMAP nor page-shaped, so read as a note. SECTIONS are pages that
    cover no file (page_levels): each folds into the page above it, so its form is moot, unless
    its other form is there too. ONLY limits the pages judged; company is still the whole tree's."""
    have, out = set(files), []
    def company(f: str) -> bool:
        # An ignored datasheet isn't tracked, but the folder on disk or the page's link says it's there.
        d = page_folder(f)
        return (any(g.startswith(f"{d}/") and g != f for g in have) or (root / d / DATASHEETS).is_dir()
                or any(t.startswith(f"{d}/") for t in link_targets(f, read(f))))
    for f in files:
        if f in skip or matches(f, not_docs) or (only is not None and f not in only):
            continue
        if folder_page(f) and not old_layout(f):
            to = f"{page_folder(f)}.md"
            if not company(f) and to not in have and flat_spot(to, have) and f not in sections:
                out.append({"path": f, "kind": "shape", "to": to, "into": False, "fold": False,
                            "named": f in docmap or page_shaped(read(f))})
        elif flat_page(f, have, docmap, read) and company(f):
            to = f"{page_folder(f)}/{Path(f).stem}.md"
            # Both forms present are one page twice, folded whatever its level.
            if f in sections and to not in have:
                continue
            out.append({"path": f, "kind": "shape", "to": to, "into": True, "fold": to in have, "named": True})
    return out


def misfiled_seams(files: list[str], board: dict) -> list[dict]:
    """Each page filed in a system's folder whose docmap globs cover a file another system's
    page also covers, as {path, other}: a seam filed under one side, which the reading list
    would climb from as that side's subsystem. A board page under a system is its system's, whatever
    its globs reach, so none is listed."""
    docmap = board.get("docmap") if isinstance(board.get("docmap"), dict) else {}
    boards = board_pages(board)
    # A system is docs/<system> in a code repo, docs/<genre>/<page> in a metarepo.
    n = 1 if GENRES is None else 2

    def system_of(k: str) -> str:
        return "/".join(page_folder(k).split("/")[:n + 1])
    tops = {k: system_of(k) for k in docmap
            if k.startswith("docs/") and k.endswith(".md") and page_folder(k).count("/") == n}
    have, out = set(files), []
    for p, globs in docmap.items():
        if (not isinstance(globs, list) or not p.startswith("docs/") or page_folder(p).count("/") < n + 1
                or any(same_page(b, p) for b in boards)):
            continue
        system = system_of(p)
        # A folder no page owns is no system: the page is misplaced, which doc_homes reports.
        if not folder_owner(system, have):
            continue
        other = next((t for f in files if matches(f, globs)
                      for t, s in tops.items() if s != system and matches(f, docmap[t] or [])), "")
        if other:
            out.append({"path": p, "other": other})
    return out


# The old page contract outside the pages (rules-docs.md, Documentation): jig shipped a check, a
# counter and an AGENTS.md line with it, and converting the pages alone leaves them refusing
# the new shape. Each is keyed on a shape jig itself retired, as LAYOUT keys on its old paths.
OLD_HEADS = ("Now", "Rules", "Checks")
# The three headings as one list literal or alternation: `["Now", "Rules", "Checks"]`,
# `(Now|Rules|Checks)`. A fixture that writes an old page puts text between them, and checks nothing.
OLD_HEADS_RUN = re.compile(r"\b(?:Now|Rules|Checks)\b(?:[\"'`,|\[\]() \t]+(?:Now|Rules|Checks)\b){2,}")
OLD_PAIR = re.compile(r"\b(Now|Rules|Checks)\s*(?:and|or|/|,|&)\s*(Now|Rules|Checks)\b")
# The template's sentence and its rewordings.
OLD_BIND = re.compile(r"(?i:bind as if they stood)")
# A page cited by rule number: a page's name right before `§2`, `§87` or `### 1.1`, as in
# "core §2" or "docs/core/core.md §2". Any other name before a § is another document's: "RFC
# 9111 §5.2", "CLA §4". The template's placeholder, `§N.M` or `### N.M`, is the old contract
# wherever it is.
CITE_AFTER = r"\s*(?:§\s*\d+(?:\.\d+)*\b|#{2,6}[ \t]+\d+\.\d+)"
OLD_CITE_PLACEHOLDER = re.compile(r"§\s*N\.M\b|#{2,6}[ \t]+N\.M\b")
# A page's Rules and Checks: the words right after a page's name or a system's or page's
# possessive, as in "each system's Rules and Checks"; "the billing system gained Rules and
# Checks" is the repo's own words.
HEADS_AFTER = r"\s+(?:Now|Rules|Checks)\b"
# Page names that are no system's: what a repo calls its changelog or its index.
NOT_SYSTEM_NAMES = ("readme", "index", "changelog", "glossary", "contributing")
HEADING_SAMPLES = ("# 1 x", "## 1 x", "## 1. x", "### 1.1 x", "### 12.3 x", "#### 1.1.1 x")


def contract_holders(root: Path, files: list[str], board: dict, read=None) -> list[dict]:
    """Each check, counter and always-loaded line that still holds the old page contract, as
    {path, line, kind, label, fix}; a counter that numbers nothing, with no /jig:redocument run
    under way, is also `removable`, which update carries out. A file under not_docs ships as
    code: its text is the product's, not a check of this repo's pages. jig's own folder, under
    any name it has had, defines the shapes, so it holds nothing. READ gives a file's text as
    FILES names it (update's, after its moves); by default the working tree's."""
    not_docs = board.get("not_docs") or []
    tool = tuple({os.path.dirname(f) + "/" for f in files
                  if Path(f).name in ("jig.py", "aidev.py") and "/" in f} | {f"{DIR}/"})
    have, named = set(files), named_pages(board)
    # A remap on trunk is a run under way: its cleanup is still ahead (redocument's resume rule).
    run = bool(at_rev(Board.trunk_name(root), REMAP))

    if read is None:
        def read(f: str) -> str:
            return (root / f).read_text(errors="replace") if (root / f).is_file() else ""
    # A docs page's own name names it too: "core §2" for docs/core.md. Only a page's, in any
    # case; a name of one or two letters is a word in any sentence.
    stems = sorted({Path(f).stem for f in files if f.startswith("docs/") and f.endswith(".md")
                    and len(Path(f).stem) > 2 and Path(f).stem.lower() not in NOT_SYSTEM_NAMES
                    and (folder_page(f) or flat_page(f, have, named, read))})
    page_name = r"(?i:docs/[\w./-]+" + "".join(f"|\\b{re.escape(t)}\\b" for t in stems) + ")"
    cites_page = re.compile(page_name + CITE_AFTER)
    pages_heads = re.compile(rf"(?:{page_name}|\b(?:system|page)'s){HEADS_AFTER}")

    def theirs(f: str) -> bool:
        return f in have and not f.startswith(tool) and not matches(f, not_docs)
    out = []
    for f, line, text in grep_hits("-I", "-w", "-e", "Checks", "--", ".", cwd=root):
        if (line.isdigit() and not f.endswith(".md") and theirs(f)
                and any(set(re.findall(r"Now|Rules|Checks", m)) == set(OLD_HEADS)
                        for m in OLD_HEADS_RUN.findall(text))):
            out.append({"path": f, "line": int(line), "kind": "check", "label": f"{f}:{line}",
                        "fix": "checks the old page shape: it converts with the pages, accepting "
                               "both shapes while a /jig:redocument run is under way and only the "
                               "new one once no page is in the old shape"})
    reserve = board.get("reserve") if isinstance(board.get("reserve"), dict) else {}
    for name, c in reserve.items():
        if not isinstance(c, dict):
            continue
        globs = [g for g in c.get("files") or [] if isinstance(g, str)]
        try:
            rx = re.compile(str(c.get("pattern") or ""), re.M)
        except re.error:
            continue
        # A register or the decision log is no page: a counter over them numbers entries. A
        # page is what survey reads as one; a folder of ADRs with no page of its own is not.
        pages = [f for f in files if f.endswith(".md") and matches(f, globs) and f.startswith("docs/")
                 and Path(f).name not in ("DECISIONS.md", "CHANGELOG.md", *ROOT_DOCS)
                 and (folder_page(f) or flat_page(f, have, named, read))]
        if ("#" in rx.pattern and any(rx.search(s) for s in HEADING_SAMPLES)
                and (pages or matches("docs/x/x.md", globs))):
            # A fix names a condition, never an event: a cleanup that already ran can't be waited on.
            held = [(f, text[:m.start()].count("\n") + 1) for f in files if matches(f, globs)
                    for text in [read(f)] for m in [rx.search(text)] if m]
            why = ("the contract cites a page by its heading, and the hook refuses a page's "
                   f"second heading of one name ({RULES_DIR}/rules-docs.md (Documentation))")
            if held:
                more = f" and {len(held) - 1} more" if len(held) > 1 else ""
                fix = (f"numbers page headings, and {held[0][0]}:{held[0][1]}{more} holds one: "
                       "`jig update --apply` removes it once no line matches and no "
                       f"/jig:redocument run is under way: {why}")
            elif run:
                fix = ("numbers page headings: drop it at /jig:redocument's cleanup, once no "
                       f"page holds a numbered heading: {why}")
            else:
                fix = f"numbers page headings, and no line holds one: `jig update --apply` removes it: {why}"
            out.append({"path": CONFIG, "line": 0, "kind": "counter", "label": f"{CONFIG} reserve.{name}",
                        "name": name, "fix": fix, "removable": not held and not run})
    for f in RULES_NAMES:
        if f not in have or not (root / f).is_file():
            continue
        for i, text in enumerate((root / f).read_text(errors="replace").splitlines(), 1):
            # The line's own heading marks are its heading, not a citation: `## 1.1 Setup`.
            body = re.sub(r"^\s*#{1,6}\s+", "", text)
            pair = [(x, y) for x, y in OLD_PAIR.findall(body) if x != y]
            # Now in the pair is the old contract's alone; Rules and Checks are only a page's.
            if (OLD_BIND.search(body) or OLD_CITE_PLACEHOLDER.search(body) or any("Now" in q for q in pair)
                    or cites_page.search(body) or (pair and pages_heads.search(body))):
                out.append({"path": f, "line": i, "kind": "line", "label": f"{f}:{i}",
                            "fix": "holds the old page contract: replace it with the template's "
                                   f"Documentation line (`{RULES_DIR}/rules-docs.md` (Documentation)), and cite "
                                   "a page by its heading"})
    return out


# A structure map is a hand-kept file; a JSON file past this is data, not a map.
MAP_MAX_BYTES = 1_000_000
# Build manifests: a folder holding one builds on its own, found by presence, never parsed.
MANIFESTS = ("package.json", "Cargo.toml", "go.mod", "pyproject.toml", "setup.py",
             "CMakeLists.txt", "idf_component.yml", "library.json")
OWNER_FILES = ("CODEOWNERS", ".github/CODEOWNERS", ".gitlab/CODEOWNERS", "docs/CODEOWNERS")
PY_EXT, JS_EXT = (".py",), (".js", ".jsx", ".ts", ".tsx", ".mjs", ".cjs")
C_EXT = (".c", ".h", ".cc", ".cpp", ".hpp", ".hh", ".cxx", ".ino")
JS_SPEC = re.compile(r"""(?:from\s+|import\s*\(\s*|require\s*\(\s*|import\s+)['"](\.{1,2}/[^'"]+)['"]""")
C_INCLUDE = re.compile(r'^\s*#\s*include\s+"([^"]+)"', re.M)


def level_pages(files: list[str], board: dict, read) -> list[str]:
    """The docs pages a level is worked out for: a board page is what `boards` makes it."""
    have, named = set(files), named_pages(board)
    boards, not_docs = board_pages(board), board.get("not_docs") or []
    return [f for f in files if f.startswith("docs/") and f.endswith(".md") and not reference_file(f)
            and not matches(f, not_docs) and not any(same_page(b, f) for b in boards)
            and Path(f).name not in RULES_NAMES and (folder_page(f) or flat_page(f, have, named, read))]


def page_cover(files: list[str], docmap: dict, pages: list[str]) -> dict[str, set[str]]:
    """The tracked files each page's docmap globs cover, in either of its forms."""
    # Each key's globs under both forms of its page, once: page_globs per page is every key
    # against every page, which a docs tree of hundreds of pages pays for in seconds.
    forms: dict[str, list] = {}
    for k, gs in docmap.items():
        for f in page_forms(k) if isinstance(gs, list) else ():
            forms.setdefault(f, []).extend(gs)
    out = {}
    for p in pages:
        rxs = [glob_re(g) for g in forms.get(p, []) if isinstance(g, str)]
        out[p] = {f for f in files if any(r.match(f) for r in rxs)}
    return out


def subsequence(want: list[str], path: list[str]) -> bool:
    it = iter(path)
    return all(w in it for w in want)


def structure_maps(root: Path, files: list[str], pages: list[str], cover: dict, read) -> list[dict]:
    """Each tracked JSON file whose entries name two docs pages or more, as {path, declares,
    differs, naming}. An entry names a page when the page's folder names appear in order in
    its key path, ending on the last (`systems.a.parts.b` → docs/a/b.md); its files are the
    tracked files its own lists' strings match. DIFFERS are the declared pages whose files the
    docmap gives otherwise. A map that agrees is a second declaration all the same. It counts as
    a map only when two of its entries name tracked files."""
    names = {p: page_folder(p).split("/")[1:] for p in pages}
    by_last: dict[str, list[str]] = {}
    for p, n in names.items():
        if n:
            by_last.setdefault(n[-1], []).append(p)
    out = []
    for f in files:
        if (not f.endswith(".json") or f.startswith(TOOL_DIRS) or Path(f).name in MANIFESTS
                or f.endswith("-lock.json") or "node_modules/" in f
                or (root / f).is_file() and (root / f).stat().st_size > MAP_MAX_BYTES):
            continue
        text = read(f)
        # A map names two pages as keys; a file holding fewer of their names as strings can't.
        if sum(f'"{n}"' in text for n in by_last) < 2:
            continue
        try:
            data = json.loads(text)
        except (ValueError, RecursionError):
            continue
        found: dict[str, set[str]] = {}

        def walk(node, path: list[str]) -> None:
            if not isinstance(node, dict):
                return
            for k, v in node.items():
                if not isinstance(v, dict):
                    continue
                kp = path + [str(k)]
                hit = max((p for p in by_last.get(kp[-1], ()) if subsequence(names[p], kp)),
                          key=lambda p: len(names[p]), default="")
                if hit and hit not in found:
                    rxs = [glob_re(s) for lst in v.values() if isinstance(lst, list)
                           for s in lst if isinstance(s, str)]
                    found[hit] = {t for t in files if any(r.match(t) for r in rxs)}
                walk(v, kp)
        try:
            walk(data, [])
        except RecursionError:
            continue
        # Entries whose lists name tracked files: keys that happen to match page names, as a
        # locale file's do, name none.
        if sum(bool(v) for v in found.values()) >= 2:
            out.append({"path": f, "declares": sorted(found),
                        "differs": sorted(p for p in found if found[p] != cover.get(p, set())),
                        "naming": sorted(naming(root, f, files))})
    return out


def named_by(naming: list[str]) -> str:
    """The files that name a map: the code that reads or writes it by name, then a count of
    the prose that mentions it."""
    code = [f for f in naming if not f.endswith(".md")]
    prose = len(naming) - len(code)
    return (f"; named by {', '.join(code)}" if code else "; named by" if prose else "") + (
        f"{' and' if code else ''} {prose} Markdown file{'s' if prose > 1 else ''}" if prose else "")


def code_owners(files: list[str], read) -> list[tuple[re.Pattern[str], list[str]]]:
    """CODEOWNERS rules, last match wins, as gitignore-style globs read with jig's matcher."""
    f = next((o for o in OWNER_FILES if o in files), "")
    rules = []
    for line in read(f).splitlines() if f else []:
        parts = line.split("#", 1)[0].split()
        if len(parts) < 2:
            continue
        pat = parts[0].lstrip("/") if parts[0].startswith("/") else (
            parts[0] if "/" in parts[0].rstrip("/") else f"**/{parts[0]}")
        pat = pat + "**" if pat.endswith("/") else pat
        rules.append((glob_re(pat), parts[1:]))
    return rules


def import_edges(files: list[str], read) -> dict[str, set[str]]:
    """file → the tracked files it imports: Python by ast, JS/TS by relative specifier, C/C++
    by quoted include. Aliases, dynamic imports and runtime interfaces are not read."""
    import ast
    have, edges = set(files), {}
    mods: dict[str, list[str]] = {}
    for f in files:
        if f.endswith(PY_EXT):
            parts = f[:-3].split("/")
            parts = parts[:-1] if parts[-1] == "__init__" else parts
            for i in range(len(parts)):
                mods.setdefault(".".join(parts[i:]), []).append(f)
    base_of: dict[str, list[str]] = {}
    for f in files:
        base_of.setdefault(Path(f).name, []).append(f)
    for f in files:
        to: set[str] = set()
        if f.endswith(PY_EXT):
            try:
                tree = ast.parse(read(f))
            except (SyntaxError, ValueError):
                continue
            for n in ast.walk(tree):
                wanted = []
                if isinstance(n, ast.Import):
                    wanted = [a.name for a in n.names]
                elif isinstance(n, ast.ImportFrom):
                    mod = n.module or ""
                    if n.level:
                        pkg = f.split("/")[:-n.level]
                        mod = ".".join(pkg + ([mod] if mod else []))
                    wanted = [mod] + [f"{mod}.{a.name}" for a in n.names]
                to |= {t for m in wanted for t in mods.get(m, [])}
        elif f.endswith(JS_EXT):
            for s in JS_SPEC.findall(read(f)):
                b = os.path.normpath(os.path.join(os.path.dirname(f), s))
                to |= {next((c for c in (b, *[b + e for e in JS_EXT], *[f"{b}/index{e}" for e in JS_EXT])
                             if c in have), "")} - {""}
        elif f.endswith(C_EXT):
            for s in C_INCLUDE.findall(read(f)):
                b = os.path.normpath(os.path.join(os.path.dirname(f), s))
                alone = [c for c in base_of.get(Path(s).name, []) if c.endswith(s)]
                to |= {b} if b in have else set(alone[:1]) if len(alone) == 1 else set()
        if to - {f}:
            edges[f] = to - {f}
    return edges


def page_levels(root: Path, files: list[str], board: dict, read, imports: bool = False,
                maps: list[dict] | None = None, only: set[str] | None = None) -> list[dict]:
    """Each page below a system with its level (rules-docs.md, Documentation: a subsystem has files
    of its own), as {path, level, into, own, covered, shared_with, evidence}. Own files are
    the files its docmap globs cover that no page but those above it covers. Levels:
    `unmapped`, with no docmap key, so its files are unknown (INTO is the page above);
    `section`, a key whose globs cover no tracked file, a section of INTO; `shared`, every file it covers
    covered by another page, a sibling (INTO, the same subsystem) or another system's (a seam,
    which misfiled_seams names); `subsystem`, with own files. Evidence is read-only: structure
    maps, CODEOWNERS and build manifests always, imports with IMPORTS. A metarepo has no code,
    and a system whose pages cover no file has no docmap to read. ONLY limits the pages judged,
    with no evidence and sharing weighed within their own systems: the hook asks whether a
    touched page is a section, which nothing outside its system decides."""
    if GENRES is not None:
        return []
    have = set(files)
    docmap = board.get("docmap") if isinstance(board.get("docmap"), dict) else {}
    deep = board.get("deep_subsystems") if isinstance(board.get("deep_subsystems"), dict) else {}
    pages = level_pages(files, board, read)

    def system_of(p: str) -> str:
        return "/".join(page_folder(p).split("/")[:2])
    if only is not None:
        maps, imports = [], False
        systems = {system_of(p) for p in only}
        pages = [p for p in pages if system_of(p) in systems]
    flats = frozenset(p for p in pages if not folder_page(p))
    cover = page_cover(files, docmap, pages)
    maps = structure_maps(root, files, pages, cover, read) if maps is None else maps
    owners = code_owners(files, read) if only is None else []
    units = {os.path.dirname(f) for f in files if Path(f).name in MANIFESTS and "/" in f}
    edges = import_edges(files, read) if imports else {}
    # A system the docmap maps nothing in gives no files to compare: its pages are not judged.
    mapped = {system_of(p) for p in pages if cover[p]}
    out = []
    for p in pages:
        # A folder no page owns is no system: the page is misplaced, which doc_homes reports.
        if (only is not None and p not in only) or page_folder(p).count("/") < 2 or system_of(p) not in mapped or not folder_owner(system_of(p), have):
            continue
        above = [u for u, _ in pages_above(p, have, deep, flats)]
        # Both forms of one page, flat and in its folder, are one page, not each other's sharer.
        others = [q for q in pages if not same_page(q, p) and q not in above]
        mine = cover[p]
        own = mine - set().union(*(cover[q] for q in others))
        sharers = sorted(q for q in others if cover[q] & mine)
        system = system_of(p)
        siblings = [q for q in sharers if system_of(q) == system]
        up = above[0] if above else folder_owner(system, have)
        # No docmap key says nothing about its files; a key whose globs match none says they are none.
        if not any(same_page(k, p) for k in docmap):
            level, into = "unmapped", up
        elif not mine:
            level, into = "section", up
        elif not own:
            level, into = "shared", siblings[0] if siblings else ""
        else:
            level, into = "subsystem", ""
        ev = []
        if level == "subsystem":
            ev.append(f"{len(own)} own file{'s' if len(own) > 1 else ''}"
                      + (f", {len(mine - own)} shared with {', '.join(sharers)}" if sharers else ""))
        if imports and own:
            rest = set().union(*(cover[q] for q in pages if system_of(q) == system and q != p)) - mine
            code = sorted(f for f in own if f.endswith((*PY_EXT, *JS_EXT, *C_EXT)))
            reached = {b: {a for a in rest if b in edges.get(a, ())} for b in code}
            reached = sorted(((b, len(a)) for b, a in reached.items() if a), key=lambda x: (-x[1], x[0]))
            if reached:
                ev.append("reached through " + "; ".join(
                    f"{b}, from {n} file{'s' if n > 1 else ''}" for b, n in reached[:5])
                    + (f" (and {len(reached) - 5} more)" if len(reached) > 5 else ""))
            elif code:
                ev.append(f"reached through none of its {len(code)} code files")
            unread = sorted({Path(f).suffix for f in own if f.endswith(SRC_EXT)
                             and not f.endswith((*PY_EXT, *JS_EXT, *C_EXT))})
            ev += [f"no import evidence for {e}" for e in unread]
        ev += [f"declared in {m['path']}" for m in maps if p in m["declares"]]
        who = sorted({o for f in own for o in next((who for rx, who in reversed(owners) if rx.match(f)), [])})
        if who:
            ev.append(f"owned by {', '.join(who)} (CODEOWNERS)")
        built = sorted(u for u in units if any(f.startswith(f"{u}/") for f in own)
                       and all(f in own for f in files if f.startswith(f"{u}/")))
        if built:
            ev.append(f"builds on its own: {', '.join(built)}")
        out.append({"path": p, "level": level, "into": into, "own": sorted(own), "covered": len(mine),
                    "shared_with": sharers, "evidence": ev})
    return out


def level_line(e: dict) -> str:
    """A page's level and its evidence, as survey and redocument's seed show it."""
    if e["level"] == "unmapped":
        head = f"unmapped: no docmap key: name its files in docmap, or fold it into {e['into'] or 'its system page'}"
    elif e["level"] == "section":
        head = (f"section: covers no file: a section of {e['into'] or 'its system page'}; fold it "
                "in on the owner's yes")
    elif e["level"] == "shared":
        head = (f"shared: every file it covers is {e['into']}'s too: the same subsystem, fold one "
                "into the other" if e["into"] else
                f"shared: every file it covers is another system's too ({', '.join(e['shared_with'])}): "
                "a seam, which lives in the folder both systems share")
    else:
        return "subsystem: " + "; ".join(e["evidence"])
    return "; ".join([head, *e["evidence"]])


def shape_fix(e: dict) -> str:
    """What to do with a page in the wrong shape, shared by survey and update."""
    if e["into"]:
        return (f"has a folder of its own name, {page_folder(e['path'])}/: "
                f"{'fold it into' if e['fold'] else 'move it to'} {e['to']}")
    return (f"flat at {e['to']}: its folder holds nothing else"
            + ("" if e["named"] else "; name it in docmap, or it reads as a note there"))


# rules-docs.md (Documentation, The findings record): the owner's answer to each file finding, kept
# on trunk so a yes outlives the chat it was given in. An id is `<kind>:<path>`, the kind as
# survey's --json gives it, so a new kind of finding needs no new record.
REMAP = f"{DIR}/redocument.md"
# The kinds survey and update both show with an id, so both count the same findings. A stray,
# a genre and an old board file go to redocument's remap, not to an answer here.
# A page's level is a finding too when it isn't a subsystem: a section to fold, a page sharing
# another's files, a page docmap doesn't map.
LEVEL_KINDS = ("section", "shared", "unmapped")
FINDING_KINDS = ("rules", "copy", "reserved", "page", "deep", "shape", "contract", *LEVEL_KINDS)
# The findings jig carries out itself on a recorded yes: a rename, never an edit.
MOVE_KINDS = ("shape", "page")


def finding_id(e: dict) -> str:
    return f"{e['kind']}:{e['path']}"


def is_finding(e: dict) -> bool:
    """Whether E is one survey and update show with an id. A page with no destination (a
    metarepo page in no genre) is the remap's, and a page whose only problem is the old
    contract is redocument's: update lists neither."""
    if e.get("kind") not in FINDING_KINDS:
        return False
    if e["kind"] == "page":
        return bool(e.get("to"))
    if e["kind"] == "contract":
        return any(not p.startswith("old contract") for p in e.get("problems", []))
    return True


def entry_problem(i: str, v) -> str:
    """Why a findings entry is no answer, or "" when it is one."""
    if not isinstance(v, str):
        return "not a string"
    kind, colon, path = i.partition(":")
    if i != i.strip() or path != path.strip() or not colon:
        return "the id has stray space or no kind: write it as survey prints it, <kind>:<path>"
    if kind not in FINDING_KINDS:
        return (f"no finding has the kind {kind}: survey gives ids only to "
                + ", ".join(FINDING_KINDS))
    v = v.strip()
    if i.startswith("deep:") and v.startswith("exception:"):
        # One exception record per finding: the homes check reads deep_subsystems.
        return f"a deep page's exception is its folder in {DOCMAP} deep_subsystems, with its rationale"
    if v == "approved" or any(v.startswith(p) and v[len(p):].strip() for p in ("deferred:", "exception:")):
        return ""
    if any(v.startswith(p) for p in ("deferred:", "exception:")):
        return "nothing after its colon: say where, or the owner's reason"
    return 'not "approved", "deferred: <where>" or "exception: <the owner\'s reason>"'


def findings_record(board: dict) -> dict[str, str]:
    """The board's findings entries that count as answers."""
    rec = board.get("findings")
    return ({k: v.strip() for k, v in rec.items() if not entry_problem(k, v)}
            if isinstance(rec, dict) else {})


def outcome_label(outcome: str | None) -> str:
    return "not answered" if outcome is None else "approved, not done" if outcome == "approved" else outcome


def tagged(e: dict, rec: dict) -> dict:
    """E with its id and its recorded outcome, as survey's --json carries them."""
    if not is_finding(e):
        return e
    i = finding_id(e)
    return {**e, "id": i, "outcome": rec.get(i)}


def state_tag(e: dict, rec: dict) -> str:
    return f"  [{finding_id(e)}: {outcome_label(rec.get(finding_id(e)))}]" if is_finding(e) else ""


def level_findings(levels: list[dict], homes: set[str], seams: set[str]) -> list[dict]:
    """The page levels that are findings, as entries of their level's kind: a page with no home
    or a misfiled seam is answered under its own heading, once."""
    return [{**e, "kind": e["level"]} for e in levels
            if e["level"] in LEVEL_KINDS and e["path"] not in homes and e["path"] not in seams]


def file_findings(root: Path, files: list[str], board: dict, read) -> dict[str, dict]:
    """Every file finding survey and update show with an id, by id: the homes, the shapes and
    the page contract, judged on FILES as READ gives them."""
    not_docs = board.get("not_docs") or []
    deep = board.get("deep_subsystems") if isinstance(board.get("deep_subsystems"), dict) else {}
    docmap = named_pages(board)
    homes = doc_homes(root, files, not_docs, read, deep, docmap)
    out = {finding_id(h): h for h in homes if is_finding(h)}
    # A page that is a section of its parent is one page twice, folded, not moved: as update reads it.
    levels = page_levels(root, files, board, read)
    sections = frozenset(e["path"] for e in levels if e["level"] == "section")
    out.update({finding_id(e): e for e in page_shapes(root, files, not_docs, docmap,
                                                      {h["path"] for h in homes}, read, sections)})
    out.update({finding_id(e): e for e in level_findings(
        levels, {h["path"] for h in homes}, {e["path"] for e in misfiled_seams(files, board)})})
    at, have = {h["path"]: h for h in homes}, set(files)
    for f in files:
        if (f.endswith(".md") and (folder_page(f) or flat_page(f, have, docmap, read))
                and (f not in at or at[f]["kind"] == "deep") and not matches(f, not_docs)):
            e = {"path": f, "kind": "contract", "problems": page_problems(read(f))}
            if is_finding(e):
                out[finding_id(e)] = e
    return out


def remap_rows(text: str) -> list[tuple[list[str], list[str]]]:
    """The remap table's rows as (old paths, new paths), read by its `Old path(s)` and `New
    path` columns: `same` keeps each old path where it is."""
    cols, out = None, []
    for line in text.splitlines():
        if not line.lstrip().startswith("|"):
            cols = None
            continue
        cells = table_cells(line)
        if cols is None:
            low = [c.lower() for c in cells]
            o = next((i for i, c in enumerate(low) if c.startswith("old path")), None)
            n = next((i for i, c in enumerate(low) if c.startswith("new path")), None)
            cols = (o, n) if o is not None and n is not None else False
            continue
        if not cols or SEPARATOR.match(line.strip()) or len(cells) <= max(cols):
            continue
        olds = re.findall(r"`([^`]+)`", cells[cols[0]])
        new = cells[cols[1]]
        out.append((olds, olds if new.strip().lower() == "same" else re.findall(r"`([^`]+)`", new)))
    return out


def remap_end(root: Path, files: list[str], rows: list) -> tuple[list[str], "callable"]:
    """The tracked files as the remap will leave them, and a reader for them: a row's old paths
    give way to its new ones, and a new page reads as its one old page did. A page alone in its
    folder today may get company from another row, which makes its folder form right."""
    gone, born = set(), {}
    for olds, news in rows:
        if olds == news:
            continue
        gone.update(o for o in olds if o not in news)
        for n in news:
            if n not in files:
                born.setdefault(n, olds[0] if len(olds) == 1 else "")
    end = [f for f in files if f not in gone] + [n for n in born if n not in files]

    def read(f: str) -> str:
        p = root / (born.get(f) or f)
        return p.read_text(errors="replace") if born.get(f, f) and p.is_file() else ""
    return end, read


def remap_contradictions(root: Path, files: list[str], board: dict, text: str) -> list[dict]:
    """Each page the remap keeps at a path survey moves it from, judged on the tree the remap
    leaves, with no exception recorded."""
    rows = remap_rows(text)
    kept = [p for olds, news in rows for p in news if p in olds or p in files]
    if not kept:
        return []
    end, read = remap_end(root, files, rows)
    found, rec, out = file_findings(root, end, board, read), findings_record(board), []
    for p in dict.fromkeys(kept):
        for kind in MOVE_KINDS:
            e = found.get(f"{kind}:{p}")
            if e and e.get("to") and not rec.get(f"{kind}:{p}", "").startswith("exception:"):
                out.append({"id": f"{kind}:{p}", "path": p, "to": e["to"]})
    return out


def contradiction_fix(c: dict, trunk: str) -> str:
    return (f"{REMAP} keeps {c['path']} where it is, and survey moves it to {c['to']}: move it "
            f"in the remap, or record the owner's exception on {trunk} in {CONFIG} findings, "
            f"\"{c['id']}\": \"exception: <the owner's reason>\"")


def approved_moves(root: Path, files: list[str], board: dict,
                   read) -> tuple[list[dict], list[str], list[str]]:
    """The approved moves jig can carry out now; the approvals and deferrals whose finding no
    longer fires; and the approved moves held back, each with why. A kind this jig doesn't
    compute is never dropped: another jig may."""
    raw = board.get("findings") if isinstance(board.get("findings"), dict) else {}
    if not raw:
        return [], [], []
    rec, found = findings_record(board), file_findings(root, files, board, read)
    moves, held, dests = [], [], {}
    for i, e in found.items():
        if not (rec.get(i) == "approved" and e["kind"] in MOVE_KINDS and e.get("to")
                and not e.get("fold") and not (root / e["to"]).exists()):
            continue
        # Two pages approved onto one path: the first goes, the next would find it taken.
        # Case folded: on a case-insensitive disk docs/B.md and docs/b.md are one path.
        dest = e["to"].casefold()
        if dest in dests:
            held.append(f"{i}: {e['to']} is also {dests[dest]}'s destination, which moves first; "
                        "this one stays recorded: answer it again once that move is committed")
            continue
        dests[dest] = i
        moves.append(e)
    # jig changes an entry only where it acted itself: its own move (carry_out), or an approval
    # or deferral whose finding no longer fires, which is settled. An exception is the owner's
    # reason, which no tree can rebuild: it stays until the owner drops it or records it again
    # at the page's new path, and survey lists it while it answers nothing.
    # An entry survey lists as no answer stays listed: dropping it would hide the typo.
    gone = [i for i, v in raw.items() if i.partition(":")[0] in FINDING_KINDS and i not in found
            and not entry_problem(i, v) and not v.strip().startswith("exception:")]
    return moves, gone, held


def move_entries(rec: dict, moves: list[dict]) -> list[str]:
    """Move each moved page's other entries in REC to its new path, never onto an id already
    recorded: one answer never overwrites another. Returns the entries left at their old id."""
    kept = []
    for e in moves:
        moved = {k: f"{k.partition(':')[0]}:{e['to']}" for k in rec
                 if k.partition(":")[2] == e["path"] and k != finding_id(e)}
        for k, n in moved.items():
            if n in rec:
                kept.append(f"{k}: left at its old id, since {n} is already recorded; drop one on trunk")
            else:
                rec[n] = rec.pop(k)
    return kept


def settle(rec: dict, moves: list[dict], gone: list[str]) -> list[str]:
    """The record as --apply leaves it, in REC: each move's own entry and each gone one dropped,
    then the moved pages' other entries moved. Shared by --apply and its dry run, so the two
    say the same. Returns the entries left at their old id."""
    for i in [finding_id(e) for e in moves] + gone:
        rec.pop(i, None)
    return move_entries(rec, moves)


def carry_out(root: Path, board: dict, moves: list[dict], gone: list[str]) -> list[str]:
    """Make each approved move with git mv, rename the board keys naming it, drop its entry and
    every gone one from BOARD, and move the other entries on its old path to its new one, so an
    exception recorded for the page goes with it. Returns the entries it left at their old id
    because the new one was taken: one answer never overwrites another."""
    rec = board.get("findings") if isinstance(board.get("findings"), dict) else {}
    kept = settle(rec, moves, gone)
    for e in moves:
        (root / e["to"]).parent.mkdir(parents=True, exist_ok=True)
        git("mv", e["path"], e["to"], check=True)
        for d in (root / e["path"]).parents:
            if d == root or any(d.iterdir()):
                break
            d.rmdir()
        if isinstance(board.get("docmap"), dict) and e["path"] in board["docmap"]:
            board["docmap"] = {(e["to"] if k == e["path"] else k): v for k, v in board["docmap"].items()}
        if isinstance(board.get("boards"), list):
            board["boards"] = [e["to"] if b == e["path"] else b for b in board["boards"]]
    if rec:
        board["findings"] = rec
    else:
        board.pop("findings", None)
    return kept


# rules-docs.md (Documentation): a repo's terms are a docs file, docs/glossary.md, so pages that cite
# a term point at a doc, never at the README, which is for outsiders. Its one form: the
# `# Glossary` title, `# Basic terms`, then a product per H1, a feature per H2 and a term per H3.
# Each heading below the title but `Basic terms` is a term, so `docs/glossary.md § <term>` names
# one at any of the three levels.
GLOSSARY = "docs/glossary.md"
# The old home, a section of the root README, which update moves out (`--glossary`).
README_GLOSSARY = "## Glossary"
GLOSSARY_TITLE = "Glossary"
# The first STAMP whose checker takes the title: 0.17.0's, on trunk, refuses a commit adding it.
GLOSSARY_TITLE_STAMP = 14
BASIC_TERMS = "Basic terms"
# The field lines a glossary heading may carry: a product H1 its `Repo:` (the repo that builds
# it, or `none`) and `Kind:`, a term in a metarepo's glossary `Binds:`. `Owner:` is the field
# `Repo:` replaced, read only to refuse it and by update's rewrite.
GLOSSARY_FIELD = re.compile(r"^(Repo|Kind|Binds|Owner):[ \t]*(.*?)[ \t]*$")
PRODUCT_KINDS = ("software", "hardware")


def glossary_seed(name: str = "") -> str:
    """The glossary init writes: the title, `Basic terms`, and in a stand-alone repo its software
    product, named for the board's NAME, so control and `--owner` work from the start."""
    out = (f"# {GLOSSARY_TITLE}\n\n# {BASIC_TERMS}\n\n"
           "<!-- A term every product uses, as an ### heading: what it means, and what it is not. -->\n")
    if name:
        out += (f"\n# {name}\n\nRepo: {name}\nKind: software\n\n<!-- What {name} is. Its features "
                "are ## headings under it, and its terms ### headings: under it before its first "
                "feature, or under the feature they belong to. -->\n")
    return out
# A term written as a bold word opening its paragraph, then a dash or colon on that line:
# `**mote** — …`, `**operation** (registry op) — …`, `**seam:** …`.
BOLD_TERM = re.compile(r"^\*\*([^*]+?)(:?)\*\*(.*)$")
TERM_MARK = re.compile(r"\s[—–-]\s|[—–]|:")
TABLE_RULE = re.compile(r"^\s*\|?\s*:?-{3,}:?\s*(\|\s*:?-{3,}:?\s*)*\|?\s*$")


def readme_glossary(text: str) -> list[str] | None:
    """The lines of a README's Glossary section, the old home, or None when it holds no term:
    a section left with only a link to docs/glossary.md is the README pointing into docs."""
    lines = text.splitlines()
    start = next((i for i, l in enumerate(lines) if l.strip() == README_GLOSSARY), None)
    if start is None:
        return None
    end = next((j for j in range(start + 1, len(lines)) if re.match(r"#{1,2}\s", lines[j])), len(lines))
    section = lines[start + 1:end]
    if not (any(re.match(r"#{3,6}\s", l) for l in section) or bold_terms(section) or table_terms(section)):
        return None
    return section


def old_glossary(text: str) -> list[str] | None:
    """A README's Glossary section without its blank lines, which git's output may have trimmed."""
    section = readme_glossary(text)
    return None if section is None else [l for l in section if l.strip()]


def term_text(text: str) -> str:
    """A term as a heading or a first cell writes it: a link's text, without code marks or
    emphasis, so `| [mote](#mote) |` and `## **mote**` both name mote."""
    out, at = [], 0
    for start, end, a, b, _ in link_spans(text, blank_ends=False):
        out += [text[at:start], text[a:b]]
        at = end
    return plain("".join(out) + text[at:])


def bold_terms(lines: list[str]) -> list[tuple[int, str]]:
    """(index, term) for each paragraph in LINES that opens with a bold term, not a heading. A
    paragraph right under a term heading is that term's text, already named; a title is no term."""
    out = []
    for i, line in enumerate(lines):
        starts = i == 0 or not lines[i - 1].strip()
        above = next((l for l in reversed(lines[:i]) if l.strip()), "")
        m = BOLD_TERM.match(line.strip()) if starts and not re.match(r"#{2,6}\s", above) else None
        if m and (m.group(2) or TERM_MARK.search(m.group(3))):
            out.append((i, m.group(1).strip()))
    return out


def table_terms(lines: list[str]) -> list[tuple[int, str]]:
    """(index, term) for each body row of the tables in LINES: its first cell, read as a
    heading's text is. A table is a run of `|` lines whose second is the separator; its first
    is the header."""
    out, run = [], []
    for i, line in enumerate([*lines, ""]):
        if line.lstrip().startswith("|"):
            run.append(i)
            continue
        if len(run) > 2 and TABLE_RULE.match(lines[run[1]]):
            out += [(j, t) for j in run[2:] if (t := term_text(table_cells(lines[j])[0]))]
        run = []
    return out


def glossary_entries(text: str) -> list[dict]:
    """Each heading of a glossary file, in order, fenced code skipped: its `level`, `name` (the
    term), 1-based `line`, the indices `start` and `end` of its own lines (to the next heading
    of any level), its `fields` ({key: value} of its field lines; a key written twice keeps
    the first), the `product` and `feature` it sits under ("" for none), whether it is the
    `title` (a first H1 named `Glossary`) and whether it sits `under_title`."""
    lines = text.splitlines()
    out: list[dict] = []
    product = feature = ""
    seen_h1 = under_title = False
    for i, (line, prose) in enumerate(zip(lines, unfenced(lines))):
        m = re.match(r"^ {0,3}(#{1,6})[ \t]+(.*?)[ \t#]*$", line) if prose else None
        if not m:
            continue
        level, name = len(m.group(1)), term_text(m.group(2))
        if out:
            out[-1]["end"] = i
        title = level == 1 and not seen_h1 and name == GLOSSARY_TITLE
        if level == 1:
            product, feature = name, ""
            seen_h1, under_title = True, title
        elif level == 2:
            feature = name
        out.append({"level": level, "name": name, "line": i + 1, "start": i, "end": len(lines),
                    "product": product if level > 1 else "", "feature": feature if level > 2 else "",
                    "title": title, "under_title": under_title and level > 1, "fields": {}})
    prose_at = unfenced(lines)
    for e in out:
        for j in range(e["start"] + 1, e["end"]):
            if prose_at[j] and (f := GLOSSARY_FIELD.match(lines[j].strip())):
                e["fields"].setdefault(f.group(1), f.group(2))
    return out


def in_form(entries: list[dict]) -> bool:
    """Whether a glossary is in the one form, as far as its products are read: its first H1
    after any title is `Basic terms`, so one still lacking the title keeps its products. Until
    it is, any heading carrying `Repo:` reads as a product, so an older glossary keeps its
    products after update's rewrite."""
    return next((e["name"] for e in entries if e["level"] == 1 and not e["title"]), "") == BASIC_TERMS


def glossary_products(text: str) -> dict[str, dict[str, str]]:
    """{product: its fields} for each product of a glossary: an H1 other than `Basic terms`,
    or out of the form any heading carrying `Repo:`. The title is never one."""
    entries = glossary_entries(text)
    form = in_form(entries)
    return {e["name"]: e["fields"] for e in entries if not e["title"]
            and (e["level"] == 1 and e["name"] != BASIC_TERMS if form else "Repo" in e["fields"])}


def glossary_terms(text: str) -> list[str]:
    """The terms of a glossary file, in order: its H1, H2 and H3 headings, a product, a feature
    and a term each one. The title and `Basic terms`, which heads the shared terms, are none."""
    return [e["name"] for e in glossary_entries(text)
            if e["level"] <= 3 and not e["title"] and e["name"] != BASIC_TERMS]


def cmd_glossary_term(root: Path, args) -> int:
    """`jig glossary "<term>"`: the term asked of jig, not read from the file; `jig glossary add`
    writes one where it sorts (glossary_add), unstaged, for the commit the hook checks."""
    words = args.words
    path = root / GLOSSARY
    text = read_raw(path) if path.is_file() else ""
    if words[0] == "add" and len(words) == 2:
        name = words[1]
        if not args.text:
            die('usage: jig glossary add "<term>" --text "<definition>" [--under <product>[/<feature>]] '
                '[--binds a,b], or --repo <repo|none> --kind <software|hardware> for a product', 2)
        if args.repo is not None:
            if not args.kind or args.under or args.binds:
                die("a product takes --repo and --kind, and no --under or --binds", 2)
            new = glossary_add(text or glossary_seed(), name, args.text, repo=args.repo, kind=args.kind)
        else:
            if args.kind:
                die("--kind is a product's: give --repo too", 2)
            binds = [b.strip() for b in (args.binds or "").split(",") if b.strip()]
            new = glossary_add(text or glossary_seed(), name, args.text, args.under or "", binds)
        path.parent.mkdir(parents=True, exist_ok=True)
        write_raw(path, new)
        print(f"wrote {name} in {GLOSSARY}" + (f", under {args.under}" if args.under else ""))
        return 0
    if len(words) != 1 or any(getattr(args, a) for a in ("under", "text", "binds", "repo", "kind")):
        die('usage: jig glossary "<term>", or jig glossary add "<term>" …', 2)
    want = label_fold(words[0])
    entries = glossary_entries(text)
    e = next((x for x in entries if x["level"] <= 3 and not x["title"] and label_fold(x["name"]) == want),
             None)
    if e is None:
        die(f"{GLOSSARY} has no term {words[0]}", 1)
    lines = text.splitlines()
    body = [l for l, keep in zip(lines[e["start"] + 1:e["end"]], unfenced(lines)[e["start"] + 1:e["end"]])
            if not (keep and GLOSSARY_FIELD.match(l.strip()))]
    definition = re.sub(r"<!--.*?-->", "", "\n".join(body), flags=re.S).strip()
    me = own_name(main_root())
    owners = term_owners(text)
    product = e["name"] if e["level"] == 1 else e["product"]
    control = (owners.get(product) or me) if product in owners else me
    print(" > ".join(x for x in (e["product"], e["feature"], e["name"]) if x))
    if definition:
        print(definition)
    for f in (("Repo", "Kind") if e["level"] == 1 else ("Binds",)):
        if f in e["fields"]:
            print(f"{f}: {e['fields'][f]}")
    print(f"controlled by: {control}")
    return 0


def sort_glossary(root: Path) -> None:
    """The merge's re-sort of the glossary (glossary_sorted), staged in the merge commit: two
    jobs each appending a term merge as text, and the order is restored here, where no two
    branches write it at once. One already in order is left untouched."""
    path = root / GLOSSARY
    # A glossary out of the form isn't sorted: its order is the owner's until its rebuild.
    if path.is_file() and in_form(glossary_entries(was := read_raw(path))) and (now := glossary_sorted(was)) != was:
        write_raw(path, now)
        git("add", "--", GLOSSARY, check=True, cwd=str(root))
        print(f"sorted {GLOSSARY}")


def glossary_tree(text: str) -> tuple[list[str], dict]:
    """TEXT's lines (ends kept) and its entries as a tree: the root's children are the H1s (and
    any H2 or H3 above the first one), an H1's are its own H3s and its H2s, an H2's its H3s.
    Each node holds its `lines`, from its heading to the next heading of the three levels; a
    deeper heading is text of the entry above it."""
    lines = text.splitlines(keepends=True)
    heads = [e for e in glossary_entries(text) if e["level"] <= 3]
    root: dict = {"level": 0, "name": "", "kids": [], "start": 0}
    if not heads:
        return lines, root
    root["pre"] = lines[:heads[0]["start"]]
    stack = [root]
    for e, nxt in zip(heads, heads[1:] + [None]):
        node = {"level": e["level"], "name": e["name"], "title": e["title"], "start": e["start"], "kids": [],
                "lines": lines[e["start"]:nxt["start"] if nxt else len(lines)]}
        while stack[-1]["level"] >= node["level"]:
            stack.pop()
        stack[-1]["kids"].append(node)
        stack.append(node)
    return lines, root


def sibling_key(node: dict, parent: dict) -> tuple:
    """Where NODE sorts among PARENT's children: under the root the title first, then `Basic
    terms`, then the products; under an entry its own terms (H3) first, then its features (H2);
    each set in alphabetical order, case folded. A heading above the first H1 keeps its place."""
    if parent["level"] == 0:
        if node["level"] != 1:
            return (-1, "", node["start"])
        rank = 0 if node["title"] else 1 if node["name"] == BASIC_TERMS else 2
        return (rank, node["name"].casefold(), 0)
    return (0 if node["level"] == 3 else 1, node["name"].casefold(), 0)


def glossary_sorted(text: str) -> str:
    """TEXT, a glossary, in its order (sibling_key): whole entries move, each within its parent,
    and no word changes. One already in order comes back byte for byte. Moved, each entry's
    trailing blank lines become one, so no two run together."""
    lines, root = glossary_tree(text)
    if not root["kids"]:
        return text
    def walk(node: dict, out: list[dict]) -> None:
        for kid in sorted(node["kids"], key=lambda k: sibling_key(k, node)):
            out.append(kid)
            walk(kid, out)
    def flat(node: dict, out: list[dict]) -> None:
        for kid in node["kids"]:
            out.append(kid)
            flat(kid, out)
    was, now = [], []
    flat(root, was)
    walk(root, now)
    if [n["start"] for n in was] == [n["start"] for n in now]:
        return text
    pre = "".join(root["pre"])
    blocks = ["".join(n["lines"]).rstrip("\n") + "\n" for n in now]
    return (pre.rstrip("\n") + "\n\n" if pre.strip() else "") + "\n".join(blocks)


def glossary_add(text: str, name: str, definition: str, under: str = "", binds: list[str] | None = None,
                 repo: str | None = None, kind: str | None = None) -> str:
    """TEXT with NAME written in its sorted place: a product H1, with its `Repo:` (REPO) and
    `Kind:` lines, when REPO is given; else a term H3 under UNDER, `<product>` or
    `<product>/<feature>` (`Basic terms` when empty), with its `Binds:` line for BINDS. Dies on
    a name the glossary already has, as a term folds, or a parent it lacks."""
    if any(label_fold(t) == label_fold(name) for t in glossary_terms(text) + [BASIC_TERMS]):
        die(f"{GLOSSARY} already has {name}: a term is written once", 2)
    lines, root = glossary_tree(text)
    if repo is not None:
        fields = f"Repo: {repo}\n" + (f"Kind: {kind}\n" if kind else "")
        block, level, parent = f"# {name}\n\n{fields}\n{definition}\n", 1, root
    else:
        path = [p.strip() for p in (under or BASIC_TERMS).split("/")]
        # Nothing is written into the title.
        parent = next((k for k in root["kids"] if k["level"] == 1 and not k["title"]
                       and k["name"].casefold() == path[0].casefold()), None)
        if parent is not None and len(path) > 1:
            parent = next((k for k in parent["kids"] if k["level"] == 2 and k["name"].casefold() == path[1].casefold()), None)
        if parent is None or len(path) > 2:
            die(f"{GLOSSARY} has no {under or BASIC_TERMS} to put {name} under: "
                f"--under <product> or <product>/<feature>, a heading it has", 2)
        block = f"### {name}\n\n" + (f"Binds: {', '.join(binds)}\n\n" if binds else "") + f"{definition}\n"
        level = 3
    new = {"level": level, "name": name, "title": False, "start": -1, "kids": []}
    key = sibling_key(new, parent)
    after = [k for k in parent["kids"] if sibling_key(k, parent) < key]
    def end_of(node: dict) -> int:
        return end_of(node["kids"][-1]) if node["kids"] else node["start"] + len(node["lines"])
    at = end_of(after[-1]) if after else (parent["start"] + len(parent["lines"]) if parent is not root
                                          else len(root.get("pre", [])))
    if parent is root and not after and not root["kids"]:
        at = len(lines)
    head = "".join(lines[:at])
    tail = "".join(lines[at:])
    head = head.rstrip("\n") + "\n\n" if head.strip() else ""
    return head + block + ("\n" + tail.lstrip("\n") if tail.strip() else "")


def glossary_problems(text: str, meta: bool) -> list[tuple[str, str]]:
    """(key, problem) for each way TEXT, a glossary, is out of the one form. The key names the
    problem apart from its line, so a commit is refused only for one it adds. META: the glossary
    is a metarepo's, where a term may carry `Binds:`."""
    entries = glossary_entries(text)
    out: list[tuple[str, str]] = []
    h1s = [e for e in entries if e["level"] == 1]
    if not h1s or not h1s[0]["title"]:
        out.append(("title", f"the first # heading is {h1s[0]['name'] if h1s else 'missing'}, not "
                             f"`# {GLOSSARY_TITLE}`: the title comes first, then `# {BASIC_TERMS}` and "
                             "each product"))
    form = in_form(entries)
    if not form:
        found = next((e["name"] for e in h1s if not e["title"]), "missing")
        out.append(("shared", f"the # heading after the title is {found}, not `# {BASIC_TERMS}`: shared terms "
                              "come first, then each product"))
    lines = text.splitlines()
    prose = unfenced(lines)
    # Out of the form a product is a heading carrying `Repo:`, or the `Owner:` update rewrites
    # to it, so the rewrite adds no problem: its `Owner:` and missing `Repo:`/`Kind:` were there.
    products = []
    for e in entries:
        where = f"line {e['line']}: {'#' * e['level']} {e['name']}"
        if e["level"] > 3:
            out.append((f"deep {e['name']}", f"{where} is deeper than ###: a product is #, a feature ##, "
                                             "a term ###"))
        if e["title"]:
            # One key whatever the field, so update's `Owner:` rewrite adds no problem here.
            if e["fields"]:
                out.append(("title fields", f"{where} carries " + ", ".join(f"`{f}:`" for f in sorted(e["fields"]))
                            + ": the title carries no field line"))
            continue
        # Out of the form, headings under a title are the older glossary's terms.
        if form and e["under_title"]:
            out.append((f"titled {e['name']}", f"{where} is under `# {GLOSSARY_TITLE}`, which holds no term: "
                                               f"a shared term is a ### under `# {BASIC_TERMS}`"))
        if e["level"] == 2 and e["product"] == BASIC_TERMS:
            out.append((f"basic {e['name']}", f"{where} is a feature under `# {BASIC_TERMS}`, which holds "
                                              "only ### terms"))
        product = (e["level"] == 1 and e["name"] != BASIC_TERMS if form
                   else bool({"Repo", "Owner"} & set(e["fields"])))
        if product:
            products.append(e)
        allowed = {"Repo", "Kind"} if product else {"Binds"} if e["level"] == 3 and meta else set()
        for f in sorted(set(e["fields"]) - allowed):
            fix = " (`Owner:` became `Repo:`, the repo that builds the product, or none)" if f == "Owner" else ""
            out.append((f"field {e['name']} {f}", f"{where} carries `{f}:`, which a "
                        + ("product" if product else "feature" if e["level"] == 2 else
                           "term outside a metarepo's glossary" if e["level"] == 3 else "heading here")
                        + f" may not{fix}"))
        if product:
            for f in ("Repo", "Kind"):
                if f not in e["fields"]:
                    out.append((f"lacks {e['name']} {f}", f"{where} is a product with no `{f}:` line"))
            if "Kind" in e["fields"] and e["fields"]["Kind"] not in PRODUCT_KINDS:
                out.append((f"kind {e['name']}", f"{where} has `Kind: {e['fields']['Kind']}`: a kind is "
                                                 f"{' or '.join(PRODUCT_KINDS)}"))
    if any(l.lstrip().startswith("|") and TABLE_RULE.match(n) for l, n, p in zip(lines, lines[1:], prose) if p):
        out.append(("table", "a table is no glossary form: each term is a heading, a product #, a feature ##, a term ###"))
    seen: dict[str, dict] = {}
    for e in entries:
        if e["level"] <= 3 and not e["title"]:
            k = label_fold(e["name"])
            if k in seen:
                out.append((f"twice {k}", f"line {e['line']}: {e['name']} and line {seen[k]['line']}: "
                                          f"{seen[k]['name']} are one term, as a label or pointer reads it"))
            else:
                seen[k] = e
    heads = {label_fold(e["name"]) for e in entries
             if e["level"] in (1, 2) and not e["title"] and e["name"] != BASIC_TERMS}
    for e in entries:
        for b in [x.strip().strip("`") for x in e["fields"].get("Binds", "").split(",") if x.strip()]:
            if label_fold(b) not in heads:
                out.append((f"binds {e['name']} {b}", f"line {e['line']}: {e['name']} binds {b}, which is "
                                                      "no product or feature heading of the glossary"))
    software: dict[str, list[str]] = {}
    for e in products:
        repo = e["fields"].get("Repo", "").strip().strip("`")
        if e["fields"].get("Kind") == "software" and repo.casefold() not in ("", "none"):
            software.setdefault(repo.casefold(), []).append(e["name"])
    out += [(f"software {r}", f"products {', '.join(ps)} name one repo, {r}, each `Kind: software`: a "
                              "repo builds one software product; the other is hardware, or another repo's")
            for r, ps in software.items() if len(ps) > 1]
    return out


def glossary_term_in(section: str, terms: list[str]) -> str:
    """The term of TERMS that SECTION, a pointer's section text, names: the whole of it, or its
    start up to a word's end, the longest such term. Empty for none."""
    hits = [t for t in terms if section == t or re.match(rf"{re.escape(t)}(?!\w)", section)]
    return max(hits, key=len) if hits else ""


def glossary_unheaded(text: str) -> list[str]:
    """Terms in a glossary file that are bold words in a paragraph, not headings or rows."""
    return [t for _, t in bold_terms(text.splitlines())]


def home_fix(h: dict) -> str:
    """What to do with a rules file or a copy, shared by survey and update."""
    at = ", ".join(h["named_at"]) or "nothing"
    if h["kind"] == "reserved":
        return (f"a page under the reserved name {DATASHEETS}/, which holds vendor documents: "
                f"rename its folder, and repoint what names it ({at})")
    if h["kind"] == "rules":
        return ("a second rulebook: sort it line by line by the test in "
                f"{RULES_DIR}/rules-docs.md (Homes): a rule every task needs into AGENTS.md, the rest of how "
                f"the repo is worked into {DIR}/process.md, and only a fact the product must keep "
                f"into its page's Invariants; repoint what names it ({at}), then delete it. A package's own rules file may "
                "stay on the owner's word: ask, don't presume the delete")
    return (f"a copy of jig's rules in {RULES_DIR}/, which update keeps current: delete it, and point what "
            f"names it ({at}) at the ruleset in {RULES_DIR}/ that holds it")


# What a repo may already have for coordinating parallel work, under its standard
# name, and the jig concept each one maps to. The survey reports these so that
# adoption speaks the repo's language, not jig's.
COORDINATION = [
    ("CODEOWNERS", "owns / shares",
     ["CODEOWNERS", ".github/CODEOWNERS", "docs/CODEOWNERS", ".gitlab/CODEOWNERS"]),
    ("pull-request template", "the handoff note",
     [".github/PULL_REQUEST_TEMPLATE.md", ".github/pull_request_template.md",
      ".gitlab/merge_request_templates"]),
    ("git hooks (husky / pre-commit / lefthook)", "the hooks",
     [".husky", ".pre-commit-config.yaml", "lefthook.yml", ".lefthook.yml"]),
    ("agent instructions", "AGENTS.md",
     ["CLAUDE.md", "AGENTS.md", ".cursorrules", ".cursor/rules", ".windsurfrules",
      ".github/copilot-instructions.md", "GEMINI.md", ".kiro/steering"]),
    ("decision records (ADRs)", f"{DIR}/decisions.md: `jig update --merge-log` merges a folder of "
     "decision records into it", ["docs/adr", "docs/decisions", "doc/adr", "adr", "decisions"]),
    ("changelog", f"{DIR}/decisions.md: `jig update --merge-log` merges a root CHANGELOG.md into it",
     ["CHANGELOG.md", "CHANGES.md", "HISTORY.md"]),
    ("handoff / round records", f"{DIR}/handoffs/",
     [".claude/handoffs", "handoffs", "docs/handoffs", "records", "docs/records"]),
    ("skills directory", ".claude/skills/ (kept as is)",
     [".claude/skills", "skills", ".cursor/skills"]),
]


def coordination_report(root: Path) -> dict:
    out: dict = {"found": [], "worktrees": 0, "open_branches": [], "homebrew_boards": [],
                 "git_hooks": []}
    folders = list(record_folders(root, tracked(root)))
    for label, maps_to, paths in COORDINATION:
        hits = [p for p in paths if (root / p).exists()]
        if label.startswith("decision records"):
            # A folder is one by what it holds, wherever it is: adr-tools writes doc/adr.
            hits = [*folders, *(p for p in hits if p not in folders)]
        if hits:
            out["found"].append({"what": label, "maps_to": maps_to, "at": hits})
    out["worktrees"] = max(0, len([l for l in git("worktree", "list", "--porcelain").splitlines()
                                   if l.startswith("worktree ")]) - 1)
    trunk = Board.trunk_name(root)
    out["open_branches"] = [b.strip("* ").strip() for b in
                            git("branch", "--no-merged", trunk).splitlines() if b.strip()]
    out["git_hooks"] = foreign_hooks()
    out["homebrew_boards"] = board_like_json(root, tracked(root))
    return out


def board_like_json(root: Path, files: list[str]) -> list[str]:
    """Tracked JSON in any root dot-folder whose entries carry owns, shares or lanes: a
    homebrew board, or jig's own under a name this copy doesn't know. Not only the tooling
    dirs — ai-dev kept its board in .aidev/, and a narrower check missed it."""
    out = []
    for f in files:
        if f.endswith(".json") and f.startswith(".") and "/" in f and f not in (CONFIG, DOCMAP, JOBS):
            try:
                txt = (root / f).read_text(errors="replace")
            except OSError:
                continue
            if '"owns"' in txt or '"shares"' in txt or '"lanes"' in txt:
                out.append(f)
    return out


def board_build(f: str) -> bool:
    return any(fnmatch.fnmatchcase(Path(f).name, b) for b in BOARD_BUILD)


def unpaged_build(board: dict, files: list[str]) -> list[tuple[str, str]]:
    """Each board-build file in FILES no registered board page's docmap covers, with the page
    docmap maps it to when there is one: that page is the board's, missing only from boards
    (an old-layout repo after update), and needs listing, not writing."""
    docmap = board.get("docmap") if isinstance(board.get("docmap"), dict) else {}
    pages = board_pages(board)
    globs = [g for p in pages for g in page_globs(docmap, p)]
    return [(f, next((p for p, gs in docmap.items() if isinstance(gs, list) and matches(f, gs)), ""))
            for f in files if board_build(f) and not matches(f, globs)]


def unpaged_fix(f: str, page: str) -> str:
    if page:
        return f"docmap maps {f} to {page}, which {DOCMAP} boards doesn't list: add it to boards"
    return (f"write the board's page with /jig:hardware, list it in {DOCMAP} boards, and map "
            f"{f} to it in docmap")


def board_refusals(board: dict, trunk: str, at: str) -> list[str]:
    """Every board has a page: a board-build file the branch adds or changes that no registered
    board page's docmap covers, and a registered board page the branch deletes or moves. A
    boards entry naming a page that is nowhere yet is survey's to report: the page may be on
    another job's branch, and refusing here would hold every job until that one merges. A repo
    that builds for no board has nothing here to refuse."""
    rng = f"{trunk}...{at}"
    changed = git("-c", "core.quotePath=false", "diff", "--name-only", "--no-renames",
                  "--diff-filter=AM", rng).splitlines()
    out = [f"{f} builds for a board no page covers: {unpaged_fix(f, page)}"
           for f, page in unpaged_build(board, changed)]
    gone = set(git("-c", "core.quotePath=false", "diff", "--name-only", "--no-renames",
                   "--diff-filter=D", rng).splitlines())
    # Flat to folder or back is the same page: boards names it in either form.
    there = set(git("-c", "core.quotePath=false", "ls-tree", "-r", "--name-only", at).splitlines())
    out += [f"{p} is a board page {DOCMAP} boards lists, and this branch deletes or moves it: "
            "keep it, or move its boards and docmap entries with it on trunk first"
            for p in board_pages(board) if set(page_forms(p)) & gone and not set(page_forms(p)) & there]
    return out


def board_pages(board: dict) -> list[str]:
    """The pages docmap.json's boards names: a board is what a page is, never where it sits."""
    boards = board.get("boards")
    return [b for b in boards if isinstance(b, str)] if isinstance(boards, list) else []


def named_pages(board: dict) -> set[str]:
    """The files the board names as pages, docmap's keys and boards: a flat file is a page
    when one of these names it, whatever its sections."""
    docmap = board.get("docmap") if isinstance(board.get("docmap"), dict) else {}
    return {f for p in set(docmap) | set(board_pages(board)) for f in page_forms(p)}


# Markdown link targets: inline `[t](target "title")` and reference definitions `[d]: target`.
# A target may sit in <...> so it can hold spaces; a bare one with a space is accepted too,
# because a board page is read by people, and a link that renders for them counts.
# A bare target may hold one level of balanced parentheses, as CommonMark allows: a vendor's
# `qx-20(rev1).pdf` is one file, not `qx-20(rev1`.
MD_INLINE = re.compile(r"""\]\(\s*(<[^>]*>|(?:[^()\n]|\([^()\n]*\))*?)(?:\s+"[^"]*"|\s+'[^']*')?\s*\)""")
MD_REFDEF = re.compile(r"""^ {0,3}\[[^\]]+\]:\s*(<[^>]*>|.*?)(?:\s+"[^"]*"|\s+'[^']*')?\s*$""", re.M)


def link_targets(page: str, text: str) -> list[str]:
    """Every local link in a page, as a repo-relative path. A leading / is the repo root."""
    out = []
    for raw in MD_INLINE.findall(text) + MD_REFDEF.findall(text):
        target = urllib.parse.unquote(raw.strip().strip("<>").split("#")[0])
        if not target or "://" in target or target.startswith("mailto:"):
            continue
        base = "" if target.startswith("/") else os.path.dirname(page)
        out.append(os.path.normpath(os.path.join(base, target.lstrip("/"))))
    return out


def shared_home(a: str, b: str, have: set[str]) -> str:
    """The datasheets/ of the nearest folder above both A and B that has a page of its own,
    docs/datasheets/ at the top."""
    common = os.path.commonpath([a, b]).split("/")
    while len(common) > 1 and not folder_owner("/".join(common), have):
        common.pop()
    return f"{'/'.join(common)}/{DATASHEETS}/"


def datasheet_links(root: Path, files: list[str], pages: list[str], deep: dict,
                    not_docs: list[str]) -> tuple[list[str], list[tuple[str, str]], list[tuple[str, str, str]]]:
    """Files in a page's folder, or in docs/datasheets/, that no page or note there links;
    links into a datasheets/ folder that point at nothing on disk (disk, not git: an ignored
    datasheet that was fetched is present); and links into the datasheets/ of a page that is
    not the linker's own or above it, with the shared folder the file belongs in."""
    have = set(files)
    notes = [f for f in files if f.endswith(".md") and f not in pages and f.startswith("docs/")
             and not reference_file(f) and not matches(f, not_docs) and owner_page(f, have, deep)]
    linked, missing, misplaced = set(), [], []
    for page in pages + notes:
        text = (root / page).read_text(errors="replace") if (root / page).exists() else ""
        for path in link_targets(page, text):
            linked.add(path)
            if not reference_file(path):
                continue
            if not (root / path).exists() and (page, path) not in missing:
                missing.append((page, path))
            owner = path[:path.index(f"/{DATASHEETS}/")]
            here = page_folder(page) if page in pages else os.path.dirname(page)
            if here != owner and not here.startswith(f"{owner}/"):
                misplaced.append((page, path, shared_home(owner, here, have)))
    pool = f"docs/{DATASHEETS}/"
    unlinked = [f for f in files if f not in linked and f not in pages and not matches(f, not_docs)
                and not f.startswith(OLD_BOARDS)
                and (f.startswith(pool) or (f.startswith("docs/") and not folder_page(f)
                                            and owner_page(f, have, deep)))]
    return unlinked, missing, misplaced


def cmd_survey(root: Path, args) -> int:
    files = tracked(root)
    md = [f for f in files if f.endswith(".md")]
    src = [f for f in files
           if f.endswith(SRC_EXT)
           and not f.startswith((".", f"{DIR}/"))
           and not re.search(r"(^|/)\.", f)
           and not re.search(r"(^|/)(tests?|__tests__|node_modules|vendor|build|dist|scripts)/", f)
           and not re.search(r"\.(test|spec)\.", f)]
    # Survey runs on repos that have no board yet; then nothing is declared.
    try:
        board = Board.load(root).data
    except SystemExit:
        board = {}
    if board:
        ensure_roadmap(root)
    not_docs = board.get("not_docs") or []
    report: dict = {"markdown": [], "homeless": [], "oversized": [], "present": {},
                    "src_count": len(src), "not_docs": not_docs,
                    # "docs-src/" reads like a directory but matches nothing; say so, or
                    # the files it meant to cover are back on the homeless list unexplained.
                    "not_docs_unmatched": [g for g in not_docs
                                          if not any(matches(f, [g]) for f in files)]}

    deep = board.get("deep_subsystems") if isinstance(board.get("deep_subsystems"), dict) else {}
    # A trailing slash or a missing docs/ approves no folder, silently; say so.
    report["deep_unmatched"] = [k for k in deep if not any(f.startswith(f"{k}/") or f == f"{k}.md" for f in files)]
    docmap = named_pages(board)
    homes = {h["path"]: h for h in doc_homes(root, files, not_docs, deep=deep, docmap=docmap)}
    for f in md:
        raw = (root / f).read_text(errors="replace").splitlines() if (root / f).exists() else []
        n = len([l for l in raw
                 if l.strip() and not l.lstrip().startswith(("#", "<!--", "-->", "|"))])
        last = git("log", "-1", "--format=%ad", "--date=short", "--", f)
        home = homes.get(f)
        entry = {"path": f, "lines": n, "last_commit": last,
                 "inbound": len(home["naming"]) if home else inbound(root, f, files)}
        report["markdown"].append(entry)
        if home:
            report["homeless"].append({**entry, **{k: home[k] for k in ("kind", "to", "fold", "naming", "named_at")}})
        if f in ("AGENTS.md", "CLAUDE.md") and n > 40:  # rule lines, not raw lines
            report["oversized"].append(entry)

    report["long_rules"] = [{"path": f.relative_to(root).as_posix(), "lines": n}
                            for f in sorted((root / RULES_DIR).glob("*.md"))
                            if (n := len(f.read_text(errors="replace").splitlines())) > RULES_CAP]

    # The spec template and the ledgers are made on first use, so their absence is no gap.
    for name in ("AGENTS.md", "CLAUDE.md", f"{DIR}/scripts/check.sh", f"{DIR}/scripts/setup.sh",
                 f"{DIR}/jig.py", RULES_DIR, CONFIG, DOCMAP, JOBS):
        report["present"][name] = (root / name).exists()
    common = Path(git("rev-parse", "--path-format=absolute", "--git-common-dir"))
    hook = common / "hooks" / "pre-commit"
    report["present"]["git hooks"] = hook.exists() and "jig hook" in hook.read_text()

    report["coordination"] = coordination_report(root)
    report["docmap_present"] = bool(board.get("docmap"))
    # The fold-in asks about a page only when docmap names it, so a board page left out
    # of docmap is never checked against the code that targets that board.
    boards = board_pages(board)
    report["boards_unmapped"] = [f for f in boards if not any(same_page(k, f) for k in (board.get("docmap") or {}))]
    report["boards_missing"] = [f for f in boards if page_in(f, set(files)) not in files]
    report["boards_unpaged"] = [{"path": f, "page": p} for f, p in unpaged_build(board, files)]
    have = set(files)

    def read(f: str) -> str:
        return (root / f).read_text(errors="replace") if (root / f).is_file() else ""
    flats = {f for f in md if flat_page(f, have, docmap, read)}
    pages = [f for f in md if (folder_page(f) or f in flats) and f not in homes and not matches(f, not_docs)]
    # The repo's own files that hold its docs structure are evidence too, not only its pages.
    report["contract_holders"] = contract_holders(root, files, board)
    bmap = board.get("docmap") if isinstance(board.get("docmap"), dict) else {}
    lpages = level_pages(files, board, read) if GENRES is None else []
    report["structure_maps"] = structure_maps(root, files, lpages, page_cover(files, bmap, lpages), read)
    report["levels"] = page_levels(root, files, board, read, args.levels, report["structure_maps"])
    sections = frozenset(e["path"] for e in report["levels"] if e["level"] == "section")
    report["page_shapes"] = page_shapes(root, files, not_docs, docmap, set(homes), read, sections)
    report["seams_misfiled"] = misfiled_seams(files, board)
    report["datasheets_unlinked"], report["datasheets_missing"], report["datasheets_misplaced"] = datasheet_links(
        root, files, pages, deep, not_docs)
    report["datasheets_orphan"] = [f for f in files if reference_file(f) and not f.endswith(".md")
                                   and not f.startswith(OLD_BOARDS) and not matches(f, not_docs)
                                   and not reference_file(f, have)]
    report["old_boards"] = [] if GENRES is not None else old_board_rows(
        files, lambda f: (root / f).read_text(errors="replace") if (root / f).is_file() else "")
    report["genres"] = None if GENRES is None else list(GENRES)
    report["not_docs_hiding"] = meta_hidden(root, files, not_docs, read)
    report["decision_placement"] = placement_hints(root, Board.trunk_name(root))
    readme = root / "README.md"
    gloss = read(GLOSSARY) if GLOSSARY in files else ""
    report["glossary_terms"] = glossary_terms(gloss)
    report["glossary_unheaded"] = glossary_unheaded(gloss)
    # The old home, which update moves: a repo already on docs/glossary.md has no finding.
    report["readme_glossary"] = ("README.md" in files and readme.is_file()
                                 and readme_glossary(readme.read_text(errors="replace")) is not None)
    report["page_contract"] = [
        {"path": f, "problems": probs} for f in md
        if (folder_page(f) or f in flats) and (f not in homes or homes[f]["kind"] == "deep")
        and not matches(f, not_docs) and f != GLOSSARY
        and (probs := page_problems((root / f).read_text(errors="replace") if (root / f).exists() else ""))]
    product = product_pages(root, md)
    sids = scope_ids(at_rev(Board.trunk_name(root), ROADMAP))
    report["project_in_product"] = [
        {"path": f, "problems": probs} for f in product
        if (probs := (project_sections(read(f)) if f != LOG else []) + project_prose(read(f), sids))]
    report["process_in_pages"] = [{"path": f, "line": n, "names": p} for f, n, p in process_lines(root, product)]
    report["root_docs_named"] = [
        {"path": f, "lines": hits} for f in product if f == LOG or f.startswith("docs/")
        if (hits := root_doc_mentions(f, read(f), released_lines(read(f)) if f == LOG else set()))]
    rec = findings_record(board)
    report["homeless"] = [tagged(e, rec) for e in report["homeless"]]
    report["page_shapes"] = [tagged(e, rec) for e in report["page_shapes"]]
    report["page_contract"] = [tagged({**e, "kind": "contract"}, rec) for e in report["page_contract"]]
    report["level_findings"] = [tagged(e, rec) for e in level_findings(
        report["levels"], set(homes), {e["path"] for e in report["seams_misfiled"]})]
    finds = {e["id"]: e for e in report["homeless"] + report["page_shapes"] + report["page_contract"]
             + report["level_findings"] if "id" in e}
    report["remap_contradictions"] = remap_contradictions(
        root, files, board, at_rev(Board.trunk_name(root), REMAP))
    raw_rec = board.get("findings") if isinstance(board.get("findings"), dict) else {}
    report["findings_not_counted"] = [{"id": k, "why": w} for k, v in raw_rec.items()
                                      if (w := entry_problem(k, v))]
    # An exception jig never drops, so one whose finding is gone waits for the owner. During a
    # redocument run the pages are mid-move and its step 6 settles them: not listed until then.
    report["exceptions_unused"] = [] if at_rev(Board.trunk_name(root), REMAP) else [
        {"id": k, "outcome": v} for k, v in rec.items()
        if v.startswith("exception:") and k.partition(":")[0] in FINDING_KINDS and k not in finds]
    if args.json:
        print(json.dumps(report, indent=2))
        return 0

    print(f"{len(md)} markdown files ({len(src)} source files). Line counts are rule lines:\n"
          "blank lines, headings and table rows are not counted.\n")
    missing = [k for k, v in report["present"].items() if not v]
    print("jig pieces present: " + (", ".join(k for k, v in report["present"].items() if v) or "none"))
    if missing:
        print("                 missing: " + ", ".join(missing))
    if report["oversized"]:
        print(f"\nToo long to be always-loaded: cut to 40 lines. A rule every task needs stays; the "
              f"rest of how the repo is\nworked, code style included, goes to a section of "
              f"{DIR}/process.md, a release step to {DIR}/scripts/release.sh,\na fact about the "
              "product to its system's page, history to git. How the repo is worked never goes "
              "to a page:")
        for e in report["oversized"]:
            print(f"  {e['path']:<40} {e['lines']} lines")
    if report["long_rules"]:
        print(f"\nRulesets over {RULES_CAP} lines, each loaded whole by the roles that read it: a refine "
              "pass may cut what no role needs. Reported, never refused:")
        for e in report["long_rules"]:
            print(f"  {e['path']:<40} {e['lines']} lines")
    for kind, title in (("rules", "Agent instruction files off root"),
                        ("copy", f"Copies of jig's rules in {RULES_DIR}/"),
                        ("reserved", f"Pages named {DATASHEETS}, a reserved name")):
        found = [e for e in report["homeless"] if e["kind"] == kind]
        if found:
            print(f"\n{title}:")
            for e in found:
                print(f"  {e['path']}: {home_fix(e)}{state_tag(e, rec)}")
    misplaced = [e for e in report["homeless"] if e["kind"] == "page"]
    if misplaced:
        have = set(files)
        print(f"\nPages outside the docs tree ({RULES_DIR}/rules-docs.md, Documentation); move each, "
              "or nest it\nunder its system's folder if it is a subsystem:")
        for e in misplaced:
            # A folder page owns its own folder: what it sits in is the folder above.
            p = e["path"]
            inside = owner_page(os.path.dirname(p) if folder_page(p) else p, have, deep)
            # At a metarepo's root, nothing in the path says which genre: the remap picks one.
            to = e["to"] or f"docs/<genre>/{Path(e['path']).name}"
            print(f"  {e['path']} → {to}{' (fold it in: that page exists)' if e['fold'] else ''}"
                  + (f" (a subsystem candidate: it sits in {inside}'s folder)" if inside else "")
                  + state_tag(e, rec))
    if report["decision_placement"]:
        print("\nPages two pararepos' decisions touch, and no decision here does: the ruling is "
              "probably the metarepo's:")
        for line in report["decision_placement"]:
            print(f"  {line}")
    for e in report["not_docs_hiding"]:
        print(f"\n`not_docs` glob {e['glob']} hides {len(e['pages'])} page{'s' if len(e['pages']) > 1 else ''} "
              f"of this metarepo ({', '.join(e['pages'][:3])}{' …' if len(e['pages']) > 3 else ''}): "
              "drop it from not_docs so they convert")
    ungenred = [e for e in report["homeless"] if e["kind"] == "genre"]
    if ungenred:
        print(f"\nPages under docs/ in no genre folder ({RULES_DIR}/rules-metarepo.md, A metarepo's docs tree): "
              "a metarepo's\npages are docs/<genre>/<name>.md:")
        for e in ungenred:
            g = e["path"].split("/")[1] if e["path"].count("/") > 1 else ""
            print(f"  {e['path']}: " + (f"{g}/ is no genre {META} declares ({', '.join(GENRES or ())}): "
                                        f"move it under one, or add {g} to genres" if g else
                                        f"needs a genre: move it to docs/<genre>/{Path(e['path']).name}"))
    if report["old_boards"]:
        print(f"\nBoard files in the old {OLD_BOARDS} layout ({RULES_DIR}/rules-docs.md, Documentation): each "
              "board is a\nsystem now. Move each file (/jig:redocument carries the moves), and list "
              f"each page\nunder boards in {DOCMAP}:")
        for e in report["old_boards"]:
            print(f"  {e['path']} → {e['to'] or '? (' + e['why'] + ')'}"
                  + (f"   + boards: {e['to']}" if e["board"] else ""))
    if report["page_shapes"]:
        print(f"\nPages in the wrong shape ({RULES_DIR}/rules-docs.md, Documentation): a page is one file, "
              "flat in its\nparent's folder, until it holds another; then it moves into a folder "
              "named for it:")
        for e in report["page_shapes"]:
            print(f"  {e['path']}: {shape_fix(e)}{state_tag(e, rec)}")
    if report["seams_misfiled"]:
        print(f"\nPages in one system's folder that cover another's files ({RULES_DIR}/rules-docs.md, "
              "Documentation):")
        for e in report["seams_misfiled"]:
            print(f"  {e['path']}: covers files of two systems (also {e['other']}'s): a seam "
                  "lives in their nearest shared folder")
    below = [e for e in report["homeless"] if e["kind"] == "deep"]
    if below:
        print(f"\nPages below a subsystem ({RULES_DIR}/rules-docs.md, Documentation). Each line says what to do; "
              f"only a page\nwith files of its own may be proposed to the owner for {DOCMAP} deep_subsystems:")
        levels = {e["path"]: e for e in report["levels"]}
        for e in below:
            print(f"  {e['path']}: {deep_fix(e, deep, levels.get(e['path']))}{state_tag(e, rec)}")
    # One answer per page: a deep page and a misfiled seam are answered under their own headings.
    nofiles = report["level_findings"]
    if nofiles:
        print(f"\nPages below a system that own no files, or that docmap doesn't map ({RULES_DIR}/rules-docs.md, "
              "Documentation:\na subsystem has files of its own):")
        for e in nofiles:
            print(f"  {e['path']}: {level_line(e)}{state_tag(e, rec)}")
    if report["structure_maps"]:
        print("\nFiles that declare the docs structure: one that declares the docmap's files is a second "
              "declaration,\nand the two must change together: keep one, or derive one from the other:")
        for m in report["structure_maps"]:
            print(f"  {m['path']}: declares {', '.join(m['declares'])}; "
                  + (f"differs from the docmap for {', '.join(m['differs'])}" if m["differs"]
                     else "the same files as the docmap")
                  + named_by(m["naming"]))
    if args.levels:
        print("\nPage levels, from evidence (own files, structure maps, CODEOWNERS, manifests, imports):")
        for e in report["levels"]:
            print(f"  {e['path']}: {level_line(e)}")
    strays = [e for e in report["homeless"] if e["kind"] == "stray" and not e["to"]]
    for e in (e for e in report["homeless"] if e["kind"] == "stray" and e["to"]):
        print(f"\n{e['path']} → {e['to']}: a repo's terms are a section of its README, one "
              f"### heading per term ({RULES_DIR}/rules-docs.md, Documentation)")
    if strays:
        linked = sorted((e for e in strays if e["inbound"] > 0),
                        key=lambda e: -e["inbound"])
        cold = sorted((e for e in strays if e["inbound"] == 0),
                      key=lambda e: -e["lines"])
        if linked:
            print("\nNo home in the taxonomy, but other files point at them — these are"
                  "\nmisfiled, not stale. Give each a home; do not drop them:")
            for e in linked:
                print(f"  {e['path']:<44} {e['lines']:>5} lines  {e['inbound']:>4} inbound"
                      f"  last {e['last_commit'] or '?'}")
        if cold:
            print("\nNo home and nothing links them — written once, never read since."
                  "\nGive each a job or let git keep it:")
            for e in cold:
                print(f"  {e['path']:<44} {e['lines']:>5} lines  last {e['last_commit'] or '?'}")
        print(f"\nIf a directory ships markdown as code, list it under `not_docs` in {DOCMAP}"
              " as a glob such as `dir/**`.")
    if report["deep_unmatched"]:
        print(f"\n{DOCMAP} deep_subsystems keys that name no tracked folder (no trailing /, "
              "and the path starts at docs/):")
        for k in report["deep_unmatched"]:
            print(f"  {k}")
    if report["not_docs_unmatched"]:
        print("\n`not_docs` globs that match no tracked file (a directory needs `/**`):")
        for g in report["not_docs_unmatched"]:
            print(f"  {g}")
    if src and not report["docmap_present"]:
        print("\nNo docmap: handoff cannot tell which docs page a change touches."
              f"\nMap pages to globs in {DOCMAP} (see {RULES_DIR}/rules-handoff.md, Fold-in).")
    if report["boards_missing"]:
        print(f"\n{DOCMAP} boards entries that name no tracked page:")
        for f in report["boards_missing"]:
            print(f"  {f}")
    if report["boards_unpaged"]:
        print("\nBoard-build files no board page covers: jig gate refuses a branch that changes one:")
        for e in report["boards_unpaged"]:
            print(f"  {e['path']}: {unpaged_fix(e['path'], e['page'])}")
    if report["boards_unmapped"]:
        print("\nBoard pages no docmap entry names: no handoff will ask whether they still"
              "\nmatch the code. Map each to the code that targets its board:")
        for f in report["boards_unmapped"]:
            print(f"  {f}")
    if report["readme_glossary"]:
        print(f"\nREADME.md has a {README_GLOSSARY} section: the glossary's home is {GLOSSARY}, since "
              f"pages cite its terms and docs point only at docs ({RULES_DIR}/rules-docs.md, Documentation). "
              f"`jig update` lists the move, and `jig update --apply --glossary` makes it.")
    if report["glossary_unheaded"]:
        terms = report["glossary_unheaded"]
        print(f"\nTerms in {GLOSSARY} written as bold words, not headings: {len(terms)} "
              f"({', '.join(terms[:5])}{' …' if len(terms) > 5 else ''}).\nMake each a `### <term>` "
              f"heading, so `{GLOSSARY} § <term>` names it ({RULES_DIR}/rules-docs.md, Documentation).")
    if report["root_docs_named"]:
        print(f"\nPages and decision entries that name a root document ({RULES_DIR}/rules-docs.md, Documentation): "
              f"docs point only at docs; a root document may point into docs/, never the reverse:")
        for e in report["root_docs_named"]:
            for n, line in e["lines"]:
                print(f"  {e['path']}:{n}: {clip(line.strip())}")
    if report["contract_holders"]:
        print(f"\nChecks, counters and lines that hold the old page contract ({RULES_DIR}/rules-docs.md, Documentation):")
        for h in report["contract_holders"]:
            print(f"  {h['label']}: {h['fix']}")
    if report["page_contract"]:
        print(f"\nPages off the page contract ({RULES_DIR}/rules-docs.md, Documentation):")
        for e in report["page_contract"]:
            for p in e["problems"]:
                print(f"  {e['path']}: {p}" + ("" if p.startswith("old contract") else state_tag(e, rec)))
    if report["project_in_product"]:
        print(f"\nThe project in the product's pages and entries ({RULES_DIR}/rules-docs.md, Documentation): a "
              f"page or an entry says\nwhat the product does today; phases, order and parked work "
              f"live in {ROADMAP}:")
        for e in report["project_in_product"]:
            for p in e["problems"]:
                print(f"  {e['path']}: {p}")
    if report["process_in_pages"]:
        print(f"\nHow the repository is worked, in the product's pages ({RULES_DIR}/rules-docs.md, Documentation: "
              f"Product and process):\na page describes the product; this goes to {PROCESS_HOMES}, "
              "unless the product itself reads it:")
        for e in report["process_in_pages"]:
            print(f'  {e["path"]}:{e["line"]}: "{e["names"]}"')
    if report["datasheets_unlinked"]:
        print(f"\nFiles in a page's folder, or in docs/{DATASHEETS}/, that no page links: link each"
              "\nfrom the page that leans on it (a datasheet from its Components table), or drop it:")
        for f in report["datasheets_unlinked"]:
            print(f"  {f}")
    if report["datasheets_orphan"]:
        print(f"\nFiles in a {DATASHEETS}/ folder that is in no page's folder: move each into the "
              f"{DATASHEETS}/\nof the page that uses it, or of the nearest folder two pages share "
              f"(docs/{DATASHEETS}/ at the top):")
        for f in report["datasheets_orphan"]:
            print(f"  {f}")
    if report["datasheets_missing"]:
        print(f"\nPages linking a file under {DATASHEETS}/ that doesn't exist: fetch it again from"
              "\nthe source URL the page records, and check its hash:")
        for page, target in report["datasheets_missing"]:
            print(f"  {page:<40} -> {target}")
    if report["datasheets_misplaced"]:
        print(f"\nPages linking a datasheet in another page's {DATASHEETS}/: a datasheet two pages "
              "use lives in\nthe nearest folder both share. Move it there, and relink both pages:")
        for page, target, home in report["datasheets_misplaced"]:
            print(f"  {page} -> {target}: move it to {home}")
    if report["findings_not_counted"]:
        print(f"\n{CONFIG} findings entries that count as no answer ({RULES_DIR}/rules-docs.md, Documentation):")
        for e in report["findings_not_counted"]:
            print(f"  {e['id']}: {e['why']}")
    if report["exceptions_unused"]:
        print(f"\n{CONFIG} findings exceptions that answer no finding now ({RULES_DIR}/rules-docs.md, "
              "Documentation): drop each on trunk, or record it at the page's new path:")
        for e in report["exceptions_unused"]:
            print(f"  {e['id']}: {e['outcome']}")
    if report["remap_contradictions"]:
        print(f"\nRemap rows that keep a page where survey moves it, with no exception recorded "
              f"({RULES_DIR}/rules-docs.md, Documentation):")
        for c in report["remap_contradictions"]:
            print(f"  {c['path']}: survey moves it to {c['to']}; move it in the remap, or record "
                  f"\"{c['id']}\": \"exception: <the owner's reason>\" in findings")
    co = report["coordination"]
    print("\nHow parallel work is coordinated today (and what each maps to in jig):")
    for f in co["found"]:
        print(f"  {f['what']:<42} -> {f['maps_to']:<32} {', '.join(f['at'])}")
    if co["git_hooks"]:
        print(f"  {'git hooks installed':<42} -> {'the hooks':<32} {', '.join(co['git_hooks'])}")
    if co["homebrew_boards"]:
        print(f"  {'a homebrew board (owns/shares/jobs)':<42} -> {'the board':<32} "
              f"{', '.join(co['homebrew_boards'])}")
    if co["worktrees"]:
        print(f"  {'git worktrees in use':<42} -> {'one per job':<32} {co['worktrees']} linked")
    if co["open_branches"]:
        n = len(co["open_branches"])
        print(f"  {'branches not merged into trunk':<42} -> {'jobs to adopt':<32} "
              f"{n}: {', '.join(co['open_branches'][:6])}{' …' if n > 6 else ''}")
    if not any([co["found"], co["git_hooks"], co["homebrew_boards"], co["worktrees"],
                co["open_branches"]]):
        print("  none found — a single-session repo; jobs need no setup until a second session starts")
    homes_line = dict(DOC_HOMES)
    if GENRES is not None:
        homes_line["docs/"] = (
            "the definitions this metarepo holds: docs/<genre>/<name>.md each page, in a genre folder "
            f"({', '.join(GENRES) if GENRES else f'any folder under docs/, until {META} declares genres'}); "
            f"a genre has no page, its term is a ### heading under # {BASIC_TERMS} in {GLOSSARY}, the one file directly in docs/; a page holding "
            "other files moves into docs/<genre>/<name>/<name>.md; decision registers stay where they are")
    print("\nDoc homes: " + "; ".join(f"{k} = {v}" for k, v in homes_line.items()))
    old = old_board(root)
    # A repo already on jig with old pages has a migration of its own; adopt would replan the repo.
    old_pages = any(p.startswith("old contract") for e in report["page_contract"] for p in e["problems"]) \
        or any(h["kind"] in ("page", "deep") and old_contract((root / h["path"]).read_text(errors="replace"))
               for h in report["homeless"] if (root / h["path"]).is_file())
    outside = (any(h["kind"] in ("page", "genre") for h in report["homeless"])
               or bool(report["not_docs_hiding"]))
    # A repo on jig never adopts again: redocument converts pages, update fixes them in place.
    on_jig = (root / CONFIG).exists()
    # A deep page is folded or approved, not edited where it sits, as update leaves it.
    in_place = [e for e in report["page_contract"] if e["path"] not in homes]
    project = (f", and move the project listed above to {ROADMAP} on the owner's word"
               if report["project_in_product"] else "")
    # A finding unanswered, or approved and not yet carried out, still stands: the last line
    # never says there is nothing to do while one does.
    unanswered = len([e for e in finds.values() if e["outcome"] is None])
    approved = len([e for e in finds.values() if e["outcome"] == "approved"])
    remapped, unused = len(report["remap_contradictions"]), len(report["exceptions_unused"])
    # Each count names who acts on it: update records answers and makes the moves it can; an
    # unused exception and a remap row are the owner's edits on trunk; a metarepo's move is a job's.
    def count(n: int, what: str, route: str) -> list[str]:
        return [f"{n} {what.format(s='s' if n != 1 else '')}: {route}"] if n else []
    counts = (count(unanswered, "finding{s} not answered", "run /jig:update to record an answer to each")
              + count(approved, "finding{s} approved and not done", "move each in a job (M4)"
                      if (root / META).exists()
                      else "run /jig:update to carry out the moves, and make the edits by hand")
              + count(unused, "exception{s} answering no finding",
                      "drop each on trunk, or record it at the page's new path")
              + count(remapped, "remap row{s} keeping a page survey moves",
                      "move each page in the remap, or record the owner's exception"))
    standing = "; ".join(counts) if counts and on_jig else ""
    verdict = (f"An older jig's board is at {old}: run /jig:update first, not /jig:adopt or /jig:init."
          if old else "Pages in the old Now / Rules / Checks shape: run /jig:redocument to convert them."
          if old_pages else f"Board pages in the old {OLD_BOARDS} layout: run /jig:redocument to move them."
          if report["old_boards"] else "Pages outside the docs tree: run /jig:redocument to convert them."
          if outside and on_jig else "Checks, counters or lines that hold the old page contract, with no "
          "old page left: run /jig:update to edit each where it sits." if report["contract_holders"] and on_jig
          else "Pages off the page contract where they sit: run /jig:update "
          "to review each in place." if in_place and on_jig
          else "On jig already, no page to convert: give each file above its home" + project + "."
          if report["homeless"] and on_jig else f"On jig already{project or ': nothing to do'}."
          if on_jig else "Run /jig:adopt to turn this into a migration plan.")
    # Pages off the contract in place are among the findings not answered: one route says both.
    if standing and verdict.startswith("Pages off the page contract where they sit") and unanswered:
        verdict = "On jig already: nothing to do."
        standing = standing.replace("run /jig:update to record an answer to each",
                                    "run /jig:update to review each in place and record an answer to each", 1)
    if standing:
        verdict = (f"On jig already: {standing}." if verdict.endswith(": nothing to do.")
                   else f"{verdict} {standing[0].upper()}{standing[1:]}.")
    print(verdict)
    return 0

# ------------------------------------------------------------------- metarepo

# A metarepo holds a set of repos' shared definitions, decisions and conventions: docs only.
# Pararepos cite it at a released tag. Everything here is off unless .jig/meta.json exists.
META = f"{DIR}/meta.json"
META_DEFAULTS = {
    "name": "",
    "entry_files": [f"{DIR}/decisions.md", GLOSSARY],
    "tag_pattern": r"^v\d+\.\d+(\.\d+)?$",
    "decision_prefix": "D-",
    "pararepos": [],
}
# A metarepo's pages, in any genre, at any depth: entry_files' glob for them.
META_GENRE_ENTRY = "docs/**/*.md"
DECISION_STATUSES = ("open", "proposed", "accepted", "superseded", "rejected")
# Before the log, a register row's Status cell, whole: a word alone, with a note in
# parentheses, or "superseded by D-12". Whole-cell, because a Decision cell often starts with a
# status word ("Open question: …").
# A register row may also be struck: project scope, not a decision, which --merge-log leaves out.
ROW_STATUSES = (*DECISION_STATUSES, "struck")
STATUS_CELL = re.compile(rf"(?:{'|'.join(ROW_STATUSES)})(?:\s*\(.*\)|\s+by\s+\S+)?")
# A commit's subject starts with the ids it touches (D-022: …, GLOSSARY: …), so git log is
# the decision index. A branch's entry isn't numbered yet: its subject leads with D-?<slug>.
SUBJECT_ID = r"(?:[A-Z][A-Z0-9_-]*|[A-Za-z][\w-]*\?[a-z0-9]+(?:-[a-z0-9]+)*)"
SUBJECT_IDS = re.compile(rf"^{SUBJECT_ID}(?:, ?{SUBJECT_ID})*: \S")
# The release log before .jig/decisions.md: read only for tags made before it, and by update's
# migration.
CHANGELOG = "CHANGELOG.md"


def is_entry(path: str, entry_files: list[str]) -> bool:
    """entry_files are jig's globs, never git pathspecs: git's `**` misses a file directly
    under the folder. jig's own files never count, or a `**/*.md` would make M3 ask the
    hubnode's trunk bookkeeping for a log line that M4 then refuses on trunk. The decision log
    and the ideas file are the exception, always: they are the metarepo's decisions and open
    questions, which pararepos cite."""
    return path in (LOG, IDEAS) or (not path.startswith(f"{DIR}/") and matches(path, entry_files))


def entry_paths(rev: str, cwd: str | None = None) -> list[str]:
    """The tracked files at rev that its meta.json's entry_files name."""
    meta = {**META_DEFAULTS, **json.loads(git("show", f"{rev}:{META}", cwd=cwd) or "{}")}
    # Unquoted, so a non-ASCII name reaches the glob as itself.
    names = git("-c", "core.quotePath=false", "ls-tree", "-r", "--name-only", rev, cwd=cwd)
    return [f for f in names.splitlines() if is_entry(f, meta["entry_files"])]


def load_meta(trunk: str) -> dict | None:
    """The metarepo config from TRUNK, like the board: a branch can't switch its own gates off."""
    raw = git("show", f"{trunk}:{META}")
    if not raw:
        return None
    try:
        return {**META_DEFAULTS, **json.loads(raw)}
    except ValueError:
        return None


def reviewed_commits() -> set[str]:
    """Every commit `jig reviewed` has recorded in this clone, on any branch, review-changes too."""
    return {sha for sha, _ in review_log()}


def counts_reviewed(commit: str, done: set[str], board: "Board") -> bool:
    """A commit is reviewed when `jig reviewed` recorded it, or when a recorded commit is its
    first-parent ancestor and nothing of the job's changed since (`changed_since`): the note, and the deferred.md rows
    beside it, are committed after the review, and a clean sync may be too."""
    for c in git("rev-list", "--first-parent", commit).splitlines():
        if c in done:
            return not changed_since(c, commit, board)
    return False


def merging_commits() -> list[str]:
    """The commits a merge in progress brings in. pre-merge-commit runs before git writes
    MERGE_HEAD, but git names what it merges in GIT_REFLOG_ACTION ("merge <ref>...")."""
    head = git("rev-parse", "-q", "--verify", "MERGE_HEAD")
    if head:
        # An octopus writes one line per head; rev-parse reads only the first.
        f = Path(git("rev-parse", "--git-path", "MERGE_HEAD"))
        heads = [l.split()[0] for l in f.read_text().splitlines() if l.strip()] if f.is_file() else []
        return heads or [head]
    action = os.environ.get("GIT_REFLOG_ACTION", "")
    if AUTO_MERGE and action.startswith("merge "):
        return [c for c in (git("rev-parse", "-q", "--verify", f"{r}^{{commit}}")
                            for r in action.split()[1:] if not r.startswith("-")) if c]
    if AUTO_MERGE and action.startswith("pull"):
        # A pull merges what it just fetched: FETCH_HEAD's lines not marked not-for-merge.
        fetched = git_common() / "FETCH_HEAD"
        lines = fetched.read_text().splitlines() if fetched.exists() else []
        return [l.split()[0] for l in lines if l and "not-for-merge" not in l]
    return []


def meta_rules(root: Path, board: "Board", meta: dict, staged: bool) -> list[str]:
    """M1–M5: what may be committed to a metarepo."""
    out: list[str] = []
    trunk = board.trunk
    branch = git("branch", "--show-current")
    paths = changed_paths(trunk, staged)
    merging = merging_commits()
    # A detached HEAD at trunk (or behind it) is trunk all the same: `git push origin
    # HEAD:main` lands what is committed there.
    trunk_side = on_trunk(trunk, branch)
    # M1 docs only: the checker and its scripts live in .jig/, like any jig repo's
    for p in paths:
        if p.endswith(SRC_EXT) and not p.startswith(f"{DIR}/"):
            out.append(f"M1 a metarepo holds no code: {p}")
    if merging:
        # M5 main takes only merges of reviewed branches. A job's sync of trunk, and the
        # gate's scratch merge, are merges into something else.
        done = reviewed_commits() if trunk_side else set()
        for c in (merging if trunk_side else []):
            if not counts_reviewed(c, done, board):
                out.append(f"M5 {c[:12]} has no review on record: review it on its branch "
                           f"(`jig reviewed`), then merge")
        return out
    entry = meta["entry_files"]
    # The log's rules start once trunk has it, or with the change that merges the old files into
    # it; a branch that only adds a log beside them can't switch the old rules off.
    by_log = has_log(trunk) or migrated_here(trunk, staged, meta)
    # M2, before the log: a decision row carries its status and date
    rx = re.compile(rf"^\+\s*\|\s*{re.escape(meta['decision_prefix'])}\d+\s*\|(.*)$", re.M)
    md = [p for p in paths if p.endswith(".md")] if not by_log else []
    diff = git("diff", "-U0", base(trunk), *(["--cached"] if staged else []), "--", *md) if md else ""
    for m in rx.finditer(diff):
        cells = [c.lower() for c in table_cells(m.group(1))]
        if not (any(STATUS_CELL.fullmatch(c) for c in cells)
                and any(re.fullmatch(r"\d{4}-\d{2}-\d{2}", c) for c in cells)):
            out.append(f"M2 a decision row needs a Status cell that is exactly a status "
                       f"({'/'.join(ROW_STATUSES)}), optionally `(note)` or "
                       f"`by {meta['decision_prefix']}…`, and a date (YYYY-MM-DD): "
                       f"{m.group(0)[1:].strip()}")
    # M3 a change to what pararepos cite is recorded where they will read it. Judged on the
    # branch since it left trunk, not this commit: a release sees whole branches, so a line
    # an earlier commit added covers this one, and a commit dropping the only line is caught.
    # No renames: a cited file deleted, or moved out of the entry set, is a change too.
    # Trunk's upstream counts as trunk: a pull of it into the branch moves the base, though
    # the local trunk is stale. A deleted log is a change to it, but no line.
    since = (git("merge-base", "HEAD", trunk, f"{trunk}@{{u}}") or git("merge-base", trunk, "HEAD")
             or "HEAD")
    branch_paths = git("-c", "core.quotePath=false", "diff", "--name-only", "--no-renames", since,
                       *(["--cached"] if staged else [])).splitlines()
    record = LOG if by_log else CHANGELOG
    # An idea is recorded by itself, as an entry is: no change line for it.
    cited = [p for p in branch_paths if p and p not in (record, IDEAS) and is_entry(p, entry)]
    # A metarepo that hasn't moved its glossary yet still names README.md in entry_files, and
    # pararepos cite only that section of it: its other prose changes with no log line. The
    # move takes README.md out of entry_files, and this with it.
    if "README.md" in cited and old_glossary(at_rev(since, "README.md")) == old_glossary(
            in_index("README.md", staged)):
        cited.remove("README.md")
    if cited and (record not in branch_paths or not in_index(record, staged)):
        out.append(f"M3 {', '.join(cited)} changed: add a line{' or an entry' if by_log else ''} "
                   f"to {record} under ## Unreleased")
    # M4 nothing lands on main except merges; jig's own bookkeeping (the board, handoffs) is
    # the exception, since the hubnode keeps it on trunk. The decision log isn't bookkeeping:
    # a decision is reviewed work, so it comes in by a merge like the pages that cite it.
    # The view jig generated beside an old roadmap.md was that bookkeeping too: the update
    # converting the roadmap removes it on trunk.
    keeps = (OLD_ROADMAP_VIEW,) if at_rev(trunk, OLD_ROADMAP) else ()
    if trunk_side and paths and not all((p.startswith(f"{DIR}/") and p not in (LOG, IDEAS)) or p in keeps
                                      for p in paths):
        out.append(f"M4 {trunk} takes only merges of reviewed branches: commit on a branch")
    return out


def check_subject(msg_file: str, meta: dict) -> list[str]:
    """M6, from the commit-msg hook. Merge commits are exempt: their branches carry the ids."""
    if merging_commits() or os.environ.get("GIT_REFLOG_ACTION", "").startswith("merge"):
        return []
    lines = [l for l in Path(msg_file).read_text(errors="replace").splitlines() if l and not l.startswith("#")]
    subject = lines[0] if lines else ""
    if SUBJECT_IDS.match(subject):
        return []
    return [f"M6 a subject starts with the ids it touches ({meta['decision_prefix']}022: …, "
            f"GLOSSARY: …): {subject!r}"]


def meta_problems(root: Path, meta: dict, trunk: str, rev: str = "") -> list[str]:
    """What makes the metarepo's history unreleasable. Shared by release and pre-push,
    because a fast-forward runs no hook and a hand-made tag skips the release. REV is the
    commit to judge as trunk, when it isn't trunk's ref: what a push sends to it."""
    out: list[str] = []
    pat = re.compile(meta["tag_pattern"])
    tags = [t for t in git("tag", "--list").splitlines() if pat.match(t)]
    released = []
    for t in tags:
        if made_by_release(t):
            released.append(t)
        else:
            out.append(f"tag {t} was not made by jig release: its {LOG} has no "
                       f"`## {t} - <date>` heading. Delete it (`git tag -d {t}`)")
    last = latest_tag(released)
    rng = f"{last}..{rev or trunk}" if last else rev or trunk
    done = reviewed_commits()
    board = Board.load(root)
    for line in git("rev-list", "--first-parent", "--parents", rng).splitlines():
        commit, *parents = line.split()
        if len(parents) > 1:
            if not counts_reviewed(parents[1], done, board):
                out.append(f"{commit[:12]} merges {parents[1][:12]}, which has no review on record")
            continue
        if not parents:
            continue                      # the root commit predates the gates
        files = git("diff", "--name-only", parents[0], commit).splitlines()
        # M4's bookkeeping, judged as M4 judged it then: the roadmap's view counts where the
        # commit or trunk before it kept a roadmap, so dropping both passes too. Keep in step.
        keeps = (OLD_ROADMAP_VIEW,) if any(git("show", f"{c}:{OLD_ROADMAP}")
                                           for c in (commit, parents[0])) else ()
        if all((f.startswith(f"{DIR}/") and f != LOG) or f in keeps for f in files):
            continue
        if not git("show", f"{parents[0]}:{META}"):
            continue                      # init --meta's own commit: nothing was gated yet
        out.append(f"{commit[:12]} is on {trunk} without a reviewed merge "
                   f"({git('log', '-1', '--format=%s', commit)}): a fast-forward, or a commit "
                   f"made with the hooks off")
    return out


def yanked_pin(loc: Path, pin: str, name: str) -> list[str]:
    """A warning when the pinned release was yanked, with its line saying why and what to pin."""
    text = git("show", f"{pin}:{LOG}", cwd=str(loc))
    head = re.search(rf"^## {re.escape(pin)} - \S+ \[YANKED\][ \t]*\n+(.*)", text, re.M)
    if not head:
        # A yank is added later, on the metarepo's trunk: the pin's own copy can't carry it.
        text = git("show", f"HEAD:{LOG}", cwd=str(loc))
        head = re.search(rf"^## {re.escape(pin)} - \S+ \[YANKED\][ \t]*\n+(.*)", text, re.M)
    return [f"{name} {pin}, the pin, is yanked: {head.group(1).strip()}"] if head else []


def made_by_release(tag: str, cwd: str | None = None) -> bool:
    """Whether TAG carries the heading `jig release` writes: in the log at the tag, or, for a
    tag made before the log, in that tag's CHANGELOG.md, so an old pin still validates."""
    log = re.compile(rf"^## {re.escape(tag)} - \d{{4}}-\d{{2}}-\d{{2}}( \[YANKED\])?[ \t]*$", re.M)
    old = re.compile(rf"^## {re.escape(tag)} — \d{{4}}-\d{{2}}-\d{{2}}\s*$", re.M)
    return bool(log.search(git("show", f"{tag}:{LOG}", cwd=cwd))
                or old.search(git("show", f"{tag}:{CHANGELOG}", cwd=cwd)))


def version_key(tag: str) -> tuple[int, ...]:
    return tuple(int(n) for n in re.findall(r"\d+", tag))


def latest_tag(tags: list[str]) -> str:
    return max(tags, key=version_key) if tags else ""


def cmd_meta_init(root: Path, args) -> int:
    """`jig init --meta`."""
    # One generated block per AGENTS.md: a pararepo's header would be overwritten, and P1 refuses that later.
    if (root / PARA).exists():
        die(f"{PARA} exists: this is a pararepo, and a repo is a metarepo or a pararepo, not both", 2)
    path = root / META
    wrote = []
    if path.exists():
        print(f"{META} already exists")
    else:
        data = json.loads(json.dumps(META_DEFAULTS))
        data["name"] = getattr(args, "name", None) or root.name
        if getattr(args, "prefix", None):
            data["decision_prefix"] = args.prefix
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(data, indent=2) + "\n")
        print(f"wrote {META}")
        wrote.append(META)
    genres = None
    if getattr(args, "genres", None):
        genres = list(GENRE_TEMPLATES.get(args.genres) or
                      dict.fromkeys(g.strip() for g in args.genres.split(",") if g.strip()))
        if not genres or any("/" in g for g in genres):
            die(f"--genres: a template ({', '.join(GENRE_TEMPLATES)}) or folder names, a,b,c", 2)
        data = json.loads(path.read_text())
        data["genres"] = genres
        # The pages in the genre folders are what pararepos cite, and what M3 asks a line for.
        entry = data.setdefault("entry_files", list(META_DEFAULTS["entry_files"]))
        if not matches("docs/a/b.md", entry):
            entry.append(META_GENRE_ENTRY)
        path.write_text(json.dumps(data, indent=2) + "\n")
        print(f"genres in {META}: {', '.join(genres)}")
        wrote.append(META)
    meta = {**META_DEFAULTS, **json.loads(path.read_text())}
    # The decision log is every repo's, written by init before this. The terms pararepos cite
    # are the glossary's, a docs file: the README is for outsiders, and no entry file.
    gloss = root / GLOSSARY
    if not gloss.exists():
        gloss.parent.mkdir(parents=True, exist_ok=True)
        gloss.write_text(glossary_seed())
        print(f"wrote {GLOSSARY}")
        wrote.append(GLOSSARY)
    # Each genre is a term of the ecosystem's definition, defined once there: it has no page.
    have = {label_fold(t) for t in glossary_terms(gloss.read_text())}
    new = [g for g in genres or [] if label_fold(g) not in have]
    if new and in_form(glossary_entries(gloss.read_text())):
        text = gloss.read_text()
        for g in new:
            text = glossary_add(text, g, "TODO: what its pages define, and what they are not.")
        gloss.write_text(text)
        print(f"added a ### heading per genre under # {BASIC_TERMS} in {GLOSSARY}")
        wrote.append(GLOSSARY)
    elif new:
        print(f"{GLOSSARY} isn't in the one form (# {GLOSSARY_TITLE}, then # {BASIC_TERMS}), so no genre term was "
              f"added: add {', '.join(new)} as ### terms under # {BASIC_TERMS} once it is")
    release_script(root, meta=True)
    trunk = Board.trunk_name(root)
    agents = root / "AGENTS.md"
    # Once meta.json is on trunk, M4 refuses an AGENTS.md commit there: a refresh is a job's.
    if git("show", f"{trunk}:{META}", cwd=str(root)) and on_trunk(
            trunk, git("branch", "--show-current", cwd=str(root))):
        print(f"AGENTS.md not written: {trunk} takes only reviewed merges (M4). Run `jig init "
              "--meta` in a job's worktree to write its metarepo block, and commit AGENTS.md on "
              "the job's branch"
              + (f", with {', '.join(dict.fromkeys(wrote))}, written here: move them there." if wrote else "."))
        return 0
    before = agents.read_text() if agents.exists() else "# AGENTS.md\n"
    after = with_header(before, meta_header(meta, trunk))
    current = after == before and agents.exists()
    if not current:
        agents.write_text(after)
    if git("show", f"{trunk}:{META}", cwd=str(root)):
        print("AGENTS.md's metarepo block is current: nothing to commit for it" if current else
              "wrote AGENTS.md's metarepo block. Commit AGENTS.md on this job's branch.")
    else:
        print("AGENTS.md's metarepo block is current" if current else "wrote AGENTS.md's metarepo block")
        print(f"Commit these on {trunk}, AGENTS.md among them. From then on {trunk} "
              "takes only reviewed merges, and only `jig release` tags.")
    return 0


# ---------------------------------------------------------------- decision log

# Every repo keeps one log: decision entries and Keep a Changelog lines, grouped by release.
# An open question is an idea, in the ideas file, where it changes in place. An entry says what holds now, so a reversed one is
# removed by the commit adding the entry that supersedes it, and git keeps its text. A release's
# change lines are what that version told its readers, so they are frozen.
LOG = f"{DIR}/decisions.md"
# The log header's two lines on versions. The old pair made every Breaking line a major
# release, so the version counted dependents' bookkeeping rather than how much the product
# changed; `jig update` swaps it for the new pair where it stands word for word.
OLD_LOG_HEAD = (
    "This log follows Keep a Changelog (https://keepachangelog.com/en/1.1.0/) plus decision entries, "
    "and versions follow Semantic Versioning (https://semver.org/).\n"
    "A breaking change is one that a reader taking the release must act on, and it is released "
    "as a major version.\n")
LOG_HEAD = (
    "This log follows Keep a Changelog (https://keepachangelog.com/en/1.1.0/) plus decision entries, "
    "and versions are MILESTONE.FEATURE.PATCH, set by how much the product changed "
    "(`.jig/rules/rules-release.md`, Versioning).\n"
    "A breaking change is one that a reader taking the release must act on: a `**Breaking:**` line "
    "says what to change, and it doesn't set the version's level.\n")
LOG_SEED = "# Decisions and changes\n\n" + LOG_HEAD + "\n## Unreleased\n"
# Logs that are still a seed, and read as an empty one: the two earlier jigs wrote, with ## Open
# (today's header and the old one), and the old-header seed once `--fold-ideas` has run before
# `jig update` swapped its header.
# The header before the rulebook became rulesets: a seed holding it is still a seed.
RULES_MD_LOG_HEAD = LOG_HEAD.replace("`.jig/rules/rules-release.md`", "`.jig/RULES.md`")
OLD_LOG_SEEDS = ("# Decisions and changes\n\n" + LOG_HEAD + "\n## Open\n\n## Unreleased\n",
                 "# Decisions and changes\n\n" + RULES_MD_LOG_HEAD + "\n## Open\n\n## Unreleased\n",
                 "# Decisions and changes\n\n" + RULES_MD_LOG_HEAD + "\n## Unreleased\n",
                 "# Decisions and changes\n\n" + OLD_LOG_HEAD + "\n## Open\n\n## Unreleased\n",
                 "# Decisions and changes\n\n" + OLD_LOG_HEAD + "\n## Unreleased\n")
# The log holds decisions only. What is still to be researched before it can be decided, scoped,
# built and documented is an idea, in an entry of the log's form with an id from the log's
# counter: released entries and pararepos cite ids an Open entry had, so an idea keeps its id,
# and deciding it moves its block into the log.
IDEAS = f"{DIR}/ideas.md"
IDEAS_SEED = ("# Ideas\n\nQuestions and ideas to research before they can be decided, scoped, built "
              "and documented: one entry each, as the decision log's, `Open` or `Proposed`.\n")
IDEA_STATUSES = ("Open", "Proposed")
LOG_STATUSES = ("Accepted", "Open", "Proposed")
CHANGE_GROUPS = ("Added", "Changed", "Deprecated", "Removed", "Fixed", "Security")
RELEASE_HEADING = re.compile(r"^## (v\d+\.\d+(?:\.\d+)?) - (\d{4}-\d{2}-\d{2})( \[YANKED\])?[ \t]*$")
# A status belongs on the line under the heading, where it can change without renaming the entry.
HEADING_STATUS = re.compile(rf"(?i)(?:^(?:{'|'.join(DECISION_STATUSES)})\s*[:—–-]|[(\[]\s*(?:"
                            rf"{'|'.join(DECISION_STATUSES)})\b|(?:\s[—–-]|:)\s*(?:{'|'.join(DECISION_STATUSES)})"
                            rf"\s*$)")


def log_prefix(trunk: str) -> str:
    """The repo's decision id prefix: a metarepo's decision_prefix, D- anywhere else."""
    meta = load_meta(trunk)
    return meta["decision_prefix"] if meta else META_DEFAULTS["decision_prefix"]


def placeholder_re(prefix: str) -> str:
    """A branch's id for an entry not numbered yet, `D-?store-ro`: numbered by `jig merge`."""
    return rf"{re.escape(prefix)}\?[a-z0-9]+(?:-[a-z0-9]+)*"


def released_lines(text: str) -> set[int]:
    """The 0-based numbers of the lines inside a release section of a log, its heading included."""
    out, inside = set(), False
    for n, line in enumerate(text.splitlines()):
        if line.startswith("## "):
            inside = bool(RELEASE_HEADING.match(line))
        if inside:
            out.add(n)
    return out


def log_prefix_of(text: str) -> str:
    """The id prefix a log's own entry headings use, where no config says it: a cached copy."""
    m = re.search(r"^### ([A-Za-z][\w]*-)(?:\d|\?)", text, re.M)
    return m.group(1) if m else META_DEFAULTS["decision_prefix"]


def log_id_re(prefix: str) -> str:
    return rf"(?:{re.escape(prefix)}\d+|{placeholder_re(prefix)})"


def log_entries(text: str, prefix: str) -> list[dict]:
    """The log's decision entries in file order: id, title, section (Open, Unreleased, a
    version, or '' above them all), the status line, the line number and the block's text."""
    head = re.compile(rf"^### ({log_id_re(prefix)})(?![\w?-])[ \t]*(.*?)[ \t]*$")
    out: list[dict] = []
    section = ""
    lines = text.splitlines()
    # In with_ideas' text, what follows its ideas heading is the ideas file, its lines counted from there.
    base = None
    for n, line in enumerate(lines):
        if line == IDEAS_JOIN and base is None:
            # The log's last entry ends here: the ideas file's header is none of its text.
            if out and out[-1]["end"] is None:
                out[-1]["end"] = n
            base, section = n, IDEAS
            continue
        if line.startswith("## ") and base is None:
            m = RELEASE_HEADING.match(line)
            section = m.group(1) if m else line[3:].strip()
        if line.startswith(("## ", "### ")) and out and out[-1]["end"] is None:
            out[-1]["end"] = n
        m = head.match(line)
        if m:
            status = next((l.strip() for l in lines[n + 1:] if l.strip()), "")
            if status.startswith("#"):
                status = ""
            out.append({"id": m.group(1), "title": m.group(2), "section": section,
                        "status": status, "line": n + 1 - (base + 1 if base is not None else 0),
                        "file": IDEAS if base is not None else LOG, "start": n, "end": None})
    for e in out:
        e["block"] = "\n".join(lines[e["start"]:e["end"] if e["end"] is not None else len(lines)]).rstrip()
    return out


# One text for the readers of an entry by id: the log, then this line, then the ideas file. An
# entry after it reads as section IDEAS, its line and file the ideas file's own.
IDEAS_JOIN = f"## {IDEAS}"


def with_ideas(log: str, ideas: str) -> str:
    """The log's text and the ideas file's as one, for a reader that looks an id up in both."""
    return f"{log.rstrip(chr(10))}\n\n{IDEAS_JOIN}\n{ideas}" if ideas.strip() else log


def idea_entries(text: str, prefix: str) -> list[dict]:
    """The ideas file's entries, as log_entries gives a log's, in section IDEAS."""
    return log_entries(with_ideas("", text), prefix)


def read_entries_text(root: Path) -> str:
    """This checkout's log and ideas file, as with_ideas joins them."""
    read = lambda f: (root / f).read_text(errors="replace") if (root / f).is_file() else ""
    return with_ideas(read(LOG), read(IDEAS))


def entries_at(rev: str, cwd: str | None = None) -> str:
    """The log and ideas file at REV, as with_ideas joins them."""
    return with_ideas(git("show", f"{rev}:{LOG}", cwd=cwd), git("show", f"{rev}:{IDEAS}", cwd=cwd))


def status_parts(status: str, prefix: str) -> tuple[str, str, str, list[str]] | None:
    """(status, who, date, superseded ids) from `Accepted (the owner, 2026-11-10). Supersedes D-007.`
    Who is any text before the last date, as a register row's note was: `Proposed (runtime team,
    from the 2026-10-27 research, 2026-10-27).` So every row the old M2 took converts to a line
    this one takes."""
    ids = log_id_re(prefix)
    m = re.fullmatch(rf"({'|'.join(LOG_STATUSES)}) \((?:(.+), )?(\d{{4}}-\d{{2}}-\d{{2}})\)\."
                     rf"(?: Supersedes ({ids}(?:,? (?:and )?{ids})*)\.)?", status)
    if not m:
        return None
    return m.group(1), (m.group(2) or "").strip(), m.group(3), re.findall(ids, m.group(4) or "")


def release_sections(text: str) -> dict[str, tuple[str, bool, list[str]]]:
    """Each release section: version → (date, yanked, its lines up to the next section)."""
    out: dict[str, tuple[str, bool, list[str]]] = {}
    cur = None
    for line in text.splitlines():
        if line.startswith("## "):
            m = RELEASE_HEADING.match(line)
            cur = m.group(1) if m else None
            if m:
                out[cur] = (m.group(2), bool(m.group(3)), [])
            continue
        if cur:
            out[cur][2].append(line)
    return out


def trimmed(lines: list[str]) -> list[str]:
    while lines and not lines[0].strip():
        lines = lines[1:]
    while lines and not lines[-1].strip():
        lines = lines[:-1]
    return lines


def log_problems(text: str, prefix: str, trunk: str = "") -> list[str]:
    """M2 for the log: every entry's heading, status line and supersedes links, and which
    section may hold which status. With TRUNK, a link to an entry the log removed resolves
    through trunk's history of the log."""
    out: list[str] = []
    entries = log_entries(text, prefix)
    known = {e["id"] for e in entries}
    seen: set[str] = set()
    for e in entries:
        at = f"{LOG}:{e['line']} {e['id']}"
        if e["id"] in seen:
            out.append(f"M2 {at} is a second entry with that id: an id names one decision")
        seen.add(e["id"])
        if HEADING_STATUS.search(e["title"]):
            out.append(f"M2 {at}: the heading is the id and title only; the status goes on the "
                       f"line under it")
        parts = status_parts(e["status"], prefix)
        if parts is None:
            out.append(f"M2 {at} needs a status line under its heading: `Accepted (who, "
                       f"YYYY-MM-DD).`, optionally ending `Supersedes {prefix}007.`; an open question "
                       f"is an idea, in {IDEAS}")
            continue
        status, who, _, sup = parts
        if status == "Accepted" and not who:
            out.append(f"M2 {at}: an accepted entry says who decided: `Accepted (who, YYYY-MM-DD).`")
        if e["section"] == "Open" and status == "Accepted":
            out.append(f"M2 {at} is accepted: move it to ## Unreleased")
        elif e["section"] not in ("Open", "") and status != "Accepted":
            where = "## Unreleased" if e["section"] == "Unreleased" else f"release {e['section']}"
            out.append(f"M2 {at} is {status.lower()}: {where} holds accepted entries only; an "
                       f"idea goes in {IDEAS}")
        elif e["section"] == "":
            out.append(f"M2 {at} sits above the log's sections: an entry belongs under ## Unreleased "
                       f"or a release")
        for s in sup:
            if s not in known and not (trunk and in_log_history(s, trunk)):
                out.append(f"M2 {at} supersedes {s}, which has no entry in {LOG}"
                           + (f" or in {trunk}'s history of it" if trunk else ""))
            elif s == e["id"]:
                out.append(f"M2 {at} supersedes itself")
    return out


def open_problems(old: str, new: str, prefix: str) -> list[str]:
    """The log keeps only decisions: a `## Open` heading it didn't have, and an Open or
    Proposed entry added under one, are refused by line. A log not folded yet keeps what it
    has, so its entries can still change in place until `jig update` folds them."""
    out = [f"M2 {LOG}:{n} `{IDEAS_JOIN}` is the heading jig joins the ideas file under when it reads "
           f"both: the log can't hold it" for n, l in enumerate(new.splitlines(), 1) if l == IDEAS_JOIN]
    if not any(OPEN_HEADING.match(l) for l in old.splitlines()):
        out += [f"M2 {LOG}:{n} `## Open`: the log holds decisions only; an open question is an "
                f"idea in {IDEAS}" for n, l in enumerate(new.splitlines(), 1) if OPEN_HEADING.match(l)]
    was = {e["id"] for e in log_entries(old, prefix)}
    out += [f"M2 {LOG}:{e['line']} {e['id']} is {e['status'].split(' ')[0].lower()}: an idea goes in {IDEAS}"
            for e in log_entries(new, prefix)
            if e["section"] == "Open" and e["id"] not in was and e["status"].startswith(IDEA_STATUSES)]
    return out


def ideas_problems(text: str, log: str, prefix: str, trunk: str = "", trunk_side: bool = False,
                   glossary: tuple[str | None, str] | None = None,
                   kept: set[tuple[str, tuple[str, ...]]] = frozenset()) -> list[str]:
    """M2 for the ideas file: each idea's heading and status line, one block per id across it
    and the log, its supersedes links, and on trunk numbered ids only. With GLOSSARY (its text
    and name), each `(labels …)` line too, by label_problems: a scope's check, word for word."""
    out: list[str] = []
    for n, line in enumerate(text.splitlines(), 1):
        if line.startswith("## "):
            out.append(f"M2 {IDEAS}:{n} `{line.strip()}`: the ideas file has no sections, only its "
                       f"entries, one after another")
    ideas = idea_entries(text, prefix)
    in_log = {e["id"] for e in log_entries(log, prefix)}
    known = in_log | {e["id"] for e in ideas}
    seen: set[str] = set()
    for e in ideas:
        at = f"{IDEAS}:{e['line']} {e['id']}"
        if e["id"] in seen:
            out.append(f"M2 {at} is a second idea with that id: an id names one thing")
        seen.add(e["id"])
        if e["id"] in in_log:
            out.append(f"M2 {at} is also an entry in {LOG}: an id names one thing across both "
                       f"files, so a decided idea leaves {IDEAS}")
        if HEADING_STATUS.search(e["title"]):
            out.append(f"M2 {at}: the heading is the id and title only; the status goes on the "
                       f"line under it")
        parts = status_parts(e["status"], prefix)
        if parts is None:
            out.append(f"M2 {at} needs a status line under its heading: `Open (YYYY-MM-DD).` or "
                       f"`Proposed (YYYY-MM-DD).`, optionally ending `Supersedes {prefix}007.`")
            continue
        if parts[0] not in IDEA_STATUSES:
            out.append(f"M2 {at} is decided: move it to {LOG} `## Unreleased`, its id and block "
                       f"kept, with its `Accepted (who, YYYY-MM-DD).` line")
        for sup in parts[3]:
            if sup == e["id"]:
                out.append(f"M2 {at} supersedes itself")
            elif sup not in known and not (trunk and in_log_history(sup, trunk)):
                out.append(f"M2 {at} supersedes {sup}, which has no entry in {LOG} or {IDEAS}"
                           + (f" or in {trunk}'s history of them" if trunk else ""))
        if trunk_side and "?" in e["id"]:
            out.append(f"M2 {at} isn't numbered, and {trunk} takes numbers only: `jig merge "
                       f"--number` numbers what a merge in progress brings in")
        if glossary is not None:
            for n, labels in idea_labels(e):
                if (e["id"], tuple(labels)) not in kept:
                    out += [f"M2 {x}" for x in label_problems(labels, glossary[0], f"{IDEAS}:{n} {e['id']}", glossary[1])]
    return out


def idea_labels(e: dict) -> list[tuple[int, list[str]]]:
    """Each `(labels …)` line of idea E, a line of its own after its status line, with its line
    number in the ideas file. Read by split_labels, as a scope's labels are: one reader for both."""
    out, lines = [], e["block"].splitlines()
    status = next((k for k in range(1, len(lines)) if lines[k].strip()), len(lines))
    for k in range(status + 1, len(lines)):
        rest, labels = split_labels(lines[k].strip())
        if labels is not None and not rest:
            out.append((e["line"] + k, labels))
    return out


def idea_glossary(staged: bool | None = None) -> tuple[str | None, str]:
    """The glossary an idea's labels name terms of, and its name as a refusal says it: the one a
    scope's labels are checked against here, the metarepo's in a family that plans from its
    roadmap, this repo's own otherwise, as the change being committed has it (STAGED), or as
    trunk has it when None."""
    fam = family()
    if fam.reads_meta:
        return fam.glossary, fam.glossary_name
    if staged is None:
        return fam.glossary, GLOSSARY
    return in_index(GLOSSARY, staged) or None, GLOSSARY


def cmd_ideas(root: Path, args) -> int:
    """`jig ideas [--label L]…`: the research list. Each idea with its id, title, status, labels
    and the pages it touches; in a metarepo each registered pararepo's too, read on its trunk as
    peers are, named by repo. --label keeps those carrying it, matched as `jig roadmap --label` is."""
    trunk = Board.load(root).trunk
    prefix = log_prefix(trunk)
    glossary, _ = idea_glossary()
    want = None
    fam = family()
    if args.label and fam.reads_meta and fam.meta_loc is None:
        die(f"--label: {fam.meta_name or 'the metarepo'} isn't reachable here (`jig repos`), so the glossary "
            "labels name terms of can't be read")
    if args.label:
        if bad := sorted(v for v in args.label if label_problems([v], glossary, "")):
            terms = glossary_terms(glossary or "")
            die(f"--label {', '.join(bad)}: no glossary term" + (f"; known: {', '.join(terms)}" if terms else
                                                                 ": this repo's labels have no glossary"))
        want = {label_fold(v) for v in args.label}
    # A log not folded yet still holds its ideas under ## Open: they are listed too.
    pending = lambda text, p: [e for e in log_entries(text, p) if e["section"] in (IDEAS, "Open")]
    sources = [("", pending(read_entries_text(root), prefix))]
    unread: list[str] = []
    if load_meta(trunk):
        logs, unread = peer_logs(root, trunk)
        sources += [(f"{w}/", pending(text, log_prefix_of(text))) for w, _, text in logs if w != META_KEY]
    shown = 0
    for repo, ideas in sources:
        for e in ideas:
            labels = [l for _, ls in idea_labels(e) for l in ls]
            if want is not None and not {label_fold(l) for l in labels} & want:
                continue
            shown += 1
            touches = entry_touches(e["block"])
            print(f"{repo}{e['id']} {e['title']}")
            print(f"    {e['status']}"
                  + (f"  labels: {', '.join(labels)}" if labels else "")
                  + (f"  touches: {', '.join(touches)}" if touches else ""))
    if not shown:
        print("no ideas" + (f" labelled {', '.join(args.label)}" if args.label else ""))
    for u in unread:
        print(f"not read: {u}")
    return 0


def ideas_rules(trunk: str, staged: bool, trunk_side: bool = False) -> list[str]:
    """M2 for the ideas file, whenever a change touches it or the log beside it."""
    since = since_trunk(trunk)
    new = in_index(IDEAS, staged)
    old = at_rev(since, IDEAS)
    if not new:
        return [f"{IDEAS} is the repo's ideas log: it is never deleted"] if old else []
    prefix = log_prefix(trunk)
    # An entry the fold brings from the log's ## Open is as trunk had it, not new: its Touches
    # line is judged when it changes, as it would have been in the log, and so are its labels.
    base = with_ideas(at_rev(since, LOG), old)
    glossary, kept = idea_label_check(idea_entries(new, prefix), base, prefix, staged, IDEAS)
    return (ideas_problems(new, in_index(LOG, staged), prefix, trunk, trunk_side, glossary, kept)
            + touches_problems(base, new, prefix, trunk, staged, home=IDEAS))


def open_label_problems(trunk: str, staged: bool) -> list[str]:
    """A log not folded yet keeps its ideas under ## Open, which `jig ideas` lists: their
    `(labels …)` lines are judged as the ideas file's are."""
    prefix = log_prefix(trunk)
    since = since_trunk(trunk)
    pending = [e for e in log_entries(in_index(LOG, staged), prefix) if e["section"] == "Open"]
    if not any(idea_labels(e) for e in pending):
        return []
    base = with_ideas(at_rev(since, LOG), at_rev(since, IDEAS))
    glossary, kept = idea_label_check(pending, base, prefix, staged, LOG)
    if glossary is None:
        return []
    return [f"M2 {x}" for e in pending for n, labels in idea_labels(e) if (e["id"], tuple(labels)) not in kept
            for x in label_problems(labels, glossary[0], f"{LOG}:{n} {e['id']}", glossary[1])]


def idea_label_check(ideas: list[dict], base: str, prefix: str, staged: bool, home: str
                     ) -> tuple[tuple[str | None, str] | None, set[tuple[str, tuple[str, ...]]]]:
    """How the hook judges the labels of IDEAS, in file HOME: the glossary, or None to pass them
    unchecked, and the label lines it leaves alone. This repo's own glossary changes in the
    commits it judges, so every label line is checked. The metarepo's changes elsewhere, so
    only the label lines this commit adds or changes are: those of BASE, the ideas file and the
    log's ## Open as trunk has them, are left alone (a dropped term is the metarepo's commit, not
    this one's, and the fold moves a block unchanged). With the metarepo out of reach they pass
    unchecked, as a roadmap's Scope: lines do."""
    fam = family()
    if not fam.reads_meta:
        return idea_glossary(staged), set()
    if fam.meta_loc is None:
        if any(idea_labels(e) for e in ideas):
            print(f"jig: warning: {fam.meta_name or 'the metarepo'} isn't reachable here (`jig repos`), so "
                  f"the (labels …) lines in {home} pass unchecked", file=sys.stderr)
        return None, set()
    return (fam.glossary, fam.glossary_name), {(e["id"], tuple(ls)) for e in log_entries(base, prefix)
                                               if e["section"] in (IDEAS, "Open") for _, ls in idea_labels(e)}


def replaced(e: dict, prefix: str) -> list[str]:
    """The ids entry E supersedes once it is accepted: a proposal names what it would replace,
    and retires nothing until it is accepted."""
    parts = status_parts(e["status"], prefix)
    return parts[3] if parts and parts[0] == "Accepted" else []


def shallow(cwd: str | None = None) -> bool:
    return git("rev-parse", "--is-shallow-repository", cwd=cwd) == "true"


def history_re(want: str) -> str:
    """An ERE for git's -G: the heading of entry WANT, whole, so D-001 is not D-0010. A
    number id only: a D-?slug is no history, and its `?` would be a quantifier."""
    return rf"^### {want}($|[^0-9A-Za-z_?-])"


def in_log_history(want: str, rev: str) -> bool:
    """Whether the log at some commit in REV's history had an entry WANT. A shallow clone
    can't say, so the link passes there: refusing every log commit in it would be worse."""
    if "?" in want:
        return False
    if shallow():
        return True
    # Merges diffed too: `jig merge` numbers a job's D-?slug in the merge commit alone.
    return bool(git("log", "-m", "-E", f"-G{history_re(want)}", "--format=%h", "-1", rev, "--", LOG, IDEAS))


def removed_entries(old: str, new: str) -> tuple[str, list[dict]]:
    """OLD with each entry block NEW no longer has taken out, and those of them that were
    decided (outside a not-yet-folded log's open section) and that no accepted entry in NEW
    supersedes: only that removes one."""
    prefix = log_prefix_of(old)
    now = log_entries(new, prefix)
    gone = [e for e in log_entries(old, prefix) if e["id"] not in {n["id"] for n in now}]
    named = {s for e in now for s in replaced(e, prefix)}
    struck = struck_ids(old, new, prefix)
    lines = old.splitlines()
    for e in reversed(gone):
        del lines[e["start"]:e["start"] + e["block"].count("\n") + 1]
    return "\n".join(lines), [e for e in gone if e["id"] not in named and e["section"] != "Open"
                              and id_number(e["id"], prefix) not in struck]


def removed_lines(text: str) -> set[str]:
    """The change lines under ## Unreleased, ### Removed."""
    out, section, group = set(), "", ""
    for line in text.splitlines():
        if line.startswith("## "):
            section, group = line[3:].strip(), ""
        elif line.startswith("### "):
            group = line[4:].strip()
        elif section == "Unreleased" and group == "Removed" and line.startswith("- "):
            out.add(line.rstrip())
    return out


STRIKE_WHY = "project scope, not a product decision."
# A metarepo's forwarding address for a claim it handed down to the pararepo that owns it:
# `- D-040: moved to <repo>/.jig/decisions.md § D-016.`, a page or `<page> § <heading>` in
# place of the id. The target is a pointer, as the pararepo cites with, so one form covers all three.
MOVE_LINE = re.compile(r"^- `?(?P<what>[^`\s][^`]*?)`?: moved to `?(?P<to>[\w.-]+/[^`]+?)`?\.?$")
# The receiving end of a move: `- D-016: moved from <repo>/.jig/decisions.md § E-085.` under
# ## Unreleased ### Added, a page or `<page> § <heading>` in place of the id. It mirrors the move
# line, one form for all three, and is frozen once released as any change line is.
MOVED_FROM = re.compile(r"^- `?(?P<what>[^`\s][^`]*?)`?: moved from `?(?P<frm>[\w.-]+/[^`]+?)`?\.?$")


def move_key(what: str) -> str:
    """How a moved thing is looked up: an id by its number, as R6 counts it (D-7 is D-007), a
    path as written, a section by its plain heading."""
    path, _, section = what.partition(" § ")
    if section:
        return f"{path.strip()} § {plain(section)}"
    m = re.fullmatch(r"([A-Za-z][\w]*-)0*(\d+)", path.strip())
    return f"{m.group(1)}{int(m.group(2))}" if m else path.strip()


class Moves(dict):
    """moves_in's map, looked up by move_key, so D-007 finds the line written `- D-7: …`."""
    def __getitem__(self, k): return super().__getitem__(move_key(k))
    def __contains__(self, k): return super().__contains__(move_key(k))
    def get(self, k, default=None): return super().get(move_key(k), default)


def log_move_lines(text: str, removed_only: bool = True) -> list[tuple[str, str, str, re.Match]]:
    """(section, group, line, match) for each move-shaped line in log TEXT: under a ### Removed
    group, or with REMOVED_ONLY false under any."""
    out, section, group = [], "", ""
    for line in text.splitlines():
        if line.startswith("## "):
            section, group = line[3:].strip(), ""
        elif line.startswith("### "):
            group = line[4:].strip()
        elif (group == "Removed" or not removed_only) and (m := MOVE_LINE.match(line.rstrip())):
            out.append((section, group, line.rstrip(), m))
    return out


def move_held(section: str) -> bool:
    """Whether a move line under ## SECTION is one: ## Unreleased, or a release it went out in."""
    return section == "Unreleased" or bool(RELEASE_HEADING.match(f"## {section}"))


def moves_in(text: str) -> Moves:
    """Every move line in log TEXT under ## Unreleased or a release, as {moved id, path or path
    § heading: pointer}: where the hook checks one. A released section's change lines are
    frozen, so the map needs no history."""
    out = Moves()
    for section, _, _, m in log_move_lines(text):
        if move_held(section):
            out[move_key(m.group("what"))] = m.group("to").strip()
    return out


def moved_from_lines(text: str) -> list[tuple[str, str, str, re.Match]]:
    """(section, group, line, match) for each moved-from line in log TEXT under a ### Added group."""
    out, section, group = [], "", ""
    for line in text.splitlines():
        if line.startswith("## "):
            section, group = line[3:].strip(), ""
        elif line.startswith("### "):
            group = line[4:].strip()
        elif group == "Added" and (m := MOVED_FROM.match(line.rstrip())):
            out.append((section, group, line.rstrip(), m))
    return out


def moved_from_in(text: str) -> Moves:
    """Every moved-from line in log TEXT under ## Unreleased or a release, as {id, path or path §
    heading here: the pointer it came from}, read as moves_in reads move lines."""
    out = Moves()
    for section, _, _, m in moved_from_lines(text):
        if move_held(section):
            out[move_key(m.group("what"))] = m.group("frm").strip()
    return out


def is_here(repo: str) -> bool:
    """Whether a repo name in a pointer is this repo, by any name `jig repos` knows it by."""
    p = repo_path(repo)
    return p is not None and p.resolve() == main_root().resolve()


def thing_of(what: str) -> tuple[str, str | None]:
    """A moved thing as (path, section): an id is its log's section, a page its path alone."""
    path, _, section = what.partition(" § ")
    if not section and re.fullmatch(r"[A-Za-z][\w]*-(?:\d+|\?[a-z0-9-]+)", path.strip()):
        return LOG, path.strip()
    return path.strip(), section.strip() or None


def thing_key(t: tuple[str, str | None]) -> str:
    """How a (path, section) thing is compared: an id by its number (E-2 is E-002), a section by
    its plain heading, a page by its path."""
    path, section = t
    if path == LOG and section:
        return f"{LOG} § {move_key(section)}"
    return move_key(f"{path} § {section}") if section else path


def same_thing(a: tuple[str, str | None], b: tuple[str, str | None]) -> bool:
    return thing_key(a) == thing_key(b)


def family_names(trunk: str, meta: dict | None) -> tuple[set[str], str]:
    """The repos a claim of this one may move to or come from, and the metarepo that couldn't
    be reached to read them ("" when none): a metarepo's pararepos; for a pararepo, its
    metarepo and the metarepo's other pararepos, read on the metarepo's trunk; nothing for a
    repo with no family."""
    if meta is not None:
        return set(meta.get("pararepos") or []), ""
    para = load_para(trunk)
    if para is None:
        return set(), ""
    out = {para.get("meta", "")} - {""}
    loc = meta_checkout(main_root(), para)
    if loc is None:
        return out, para.get("meta", "")
    try:
        paras = json.loads(trunk_show(loc, META) or "{}").get("pararepos") or []
    except ValueError:
        paras = []
    return out | {n for n in paras if not is_here(n)}, ""


def maybe_family(repo: str, names: set[str], unread: str) -> bool:
    """Whether a misplaced move record names a repo that is, or may be, of the family: with the
    metarepo unread, any repo `jig repos` knows may be one, and the misplacement is refused all the same."""
    return in_family(repo, names) or (bool(unread) and repo_path(repo) is not None)


def in_family(repo: str, names: set[str]) -> bool:
    """Whether REPO is one of NAMES: by name, or by folder, as `Family` reads its members, so an
    alias or a checkout's own name is no stranger."""
    if name_in(repo, names):
        return True
    p = repo_path(repo)
    return p is not None and any((q := repo_path(n)) is not None and q.resolve() == p.resolve() for n in names)


def pointer_parts(ptr: str) -> tuple[str, str, str | None]:
    """A move's pointer as (repo, path, section or None)."""
    repo, _, rest = ptr.partition("/")
    path, _, section = rest.partition(" § ")
    return repo, path.strip(), section.strip() or None


def shown_pointer(ptr: str, here: set[str]) -> str:
    """PTR as a repo named in HERE reads it: its own path, `docs/battery.md, this repo`."""
    repo, path, section = pointer_parts(ptr)
    return f"{path}{f' § {section}' if section else ''}, this repo" if name_in(repo, here) else ptr


def moved_to(moves: dict[str, str], path: str, section: str | None) -> str | None:
    """Where a citation of PATH (§ SECTION) went: the section's own move, or its page's, the
    cited heading carried over when the page's pointer names none."""
    if section and (ptr := moves.get(move_key(f"{path} § {section}"))):
        return ptr
    # A log's section is an entry: its move line names it by its id alone (D-5 is D-005).
    if path in (LOG, IDEAS) and section and (ptr := moves.get(section)):
        return ptr
    if ptr := moves.get(path):
        return ptr if not section or " § " in ptr else f"{ptr} § {plain(section)}"
    return None


def struck_ids(old: str, new: str, prefix: str) -> set[int]:
    """The numbers of the ids NEW's added `- D-040: …` lines under ## Unreleased ### Removed
    open with, when the line gives one of the two reasons that let an entry go, even from a
    release: struck as project scope, which has no product successor, or moved to the
    pararepo that owns it. Only the line's own id: one it mentions later in a sentence is a
    change line about something else, and any other reason lets nothing go."""
    rx = re.compile(rf"- {re.escape(prefix)}(\d+): (.*)$")
    return {int(m.group(1)) for line in removed_lines(new) - removed_lines(old)
            if (m := rx.match(line)) and (m.group(2) == STRIKE_WHY or MOVE_LINE.match(line))}


def trunk_show(loc: Path, path: str) -> str | None:
    """PATH on the trunk of the repo checked out at LOC, None where it has no such file: the
    one live read of another repo's text, for what no pin holds."""
    return git("show", f"{Board.trunk_name(loc)}:{path}", cwd=str(loc)) or None


def move_rules(trunk: str, staged: bool, meta: dict | None) -> list[str]:
    """Each move line the change adds names a repo of this one's family (down, up or sideways),
    a thing this repo no longer has, and a target on that repo's trunk whose moved-from line
    names this repo's thing: both ends say where the claim went. Each moved-from line it adds
    names a family repo whose trunk still has the thing, the move pending, or moves it here.
    Where the other repo can't be reached the line passes with a warning."""
    new, old = in_index(LOG, staged), at_rev(since_trunk(trunk), LOG)
    paras, unread = family_names(trunk, meta)
    prefix = log_prefix(trunk)
    out = []
    # A move line anywhere else is read by nothing and checked by nothing: only one place holds
    # them. Outside ### Removed, only a line naming a pararepo is taken for a misplaced move: a
    # change line saying a page moved inside this repo has the same shape.
    was = {(sec, grp, line) for sec, grp, line, _ in log_move_lines(old, False)}
    out += [f"{LOG}: `{line}` is under ## {sec}{f' ### {grp}' if grp else ''}: a move line goes "
            f"under ## Unreleased ### Removed"
            for sec, grp, line, m in log_move_lines(new, False) if (sec, grp, line) not in was
            and (grp == "Removed" and not move_held(sec)
                 or grp != "Removed" and maybe_family(pointer_parts(m.group("to"))[0], paras, unread))]
    # One address per moved thing: a second line would leave readers to pick between two homes.
    # A line this change rewrites in place is no longer the log's, so a corrected target passes.
    kept = set(new.splitlines())
    had, seen = Moves(), Counter()
    for sec, _, line, m in log_move_lines(old):
        if move_held(sec) and line in kept:
            had[move_key(m.group("what"))] = m.group("to").strip()
    rewritten = {k for k in moves_in(old) if k not in had}
    # A moved id's home is the pararepo now: superseding it here would give it two.
    gone_down = moves_in(new)
    named_before = {i for e in log_entries(old, prefix) for i in replaced(e, prefix)}
    out += [f"{LOG}: {e['id']} supersedes {i}, which the log moved to {gone_down[i]}: its home "
            f"is there now, so a change to it is that repo's"
            for e in log_entries(new, prefix) for i in replaced(e, prefix)
            if i in gone_down and i not in named_before]
    added = [(line, m) for line in sorted(removed_lines(new) - removed_lines(old)) if (m := MOVE_LINE.match(line))]
    for _, m in added:
        seen[move_key(m.group("what"))] += 1
    # An idea moves as an entry does, in any direction: it leaves the ideas file in the commit
    # writing its line.
    since = since_trunk(trunk)
    old_all = with_ideas(old, at_rev(since, IDEAS))
    new_ideas = {id_number(e["id"], prefix) for e in idea_entries(in_index(IDEAS, staged), prefix)}
    old_ids = {id_number(e["id"], prefix) for e in log_entries(old_all, prefix)}
    new_ids = {id_number(e["id"], prefix) for e in log_entries(new, prefix)}
    superseded = {id_number(i, prefix) for e in log_entries(new, prefix) for i in replaced(e, prefix)}
    for line, m in added:
        what, ptr = m.group("what"), m.group("to").strip()
        key = move_key(what)
        if key in had:
            out.append(f"{LOG}: `{line}` moves {what}, which the log already moves to {had[key]}: "
                       f"one move line per thing")
            continue
        if seen[key] > 1:
            out.append(f"{LOG}: `{line}`: this change adds {seen[key]} move lines for {what}: "
                       f"one move line per thing")
            continue
        num = id_number(what, prefix)
        if num is not None and num in superseded:
            out.append(f"{LOG}: `{line}` moves {what}, which an accepted entry supersedes: what "
                       f"holds is its successor, so move that one")
            continue
        # One the log still has is the strike check's refusal (struck_ids reads move lines too).
        if num is not None and num in new_ideas:
            out.append(f"{LOG}: `{line}` moves {what}, which this change doesn't remove from {IDEAS}: "
                       f"a moved idea leaves in the commit that writes its line")
            continue
        if num is not None and num not in old_ids and num not in new_ids and key not in rewritten:
            out.append(f"{LOG}: `{line}` moves {what}, which this change doesn't remove from the log: "
                       f"a moved entry leaves in the commit that writes its line")
            continue
        repo, path, section = pointer_parts(ptr)
        # The family unread, membership can't be judged; what this commit itself holds still is.
        unknown = bool(unread) and not in_family(repo, paras)
        if not unknown and not paras:
            out.append(f"{LOG}: `{line}` moves to {repo}, but this repo has no family (no {META} with "
                       f"pararepos, no {PARA}): a claim moves only between a metarepo and its pararepos")
            continue
        if not unknown and not in_family(repo, paras):
            out.append(f"{LOG}: `{line}` moves to {repo}, which isn't of this repo's family "
                       f"({', '.join(sorted(paras))}): a claim moves within its family only")
            continue
        wpath, _, wsec = what.partition(" § ")
        if num is None and (body := in_index(wpath.strip(), staged)):
            if not wsec:
                out.append(f"{LOG}: `{line}` moves {wpath}, which this repo still has: delete it in "
                           f"the same commit, or drop the line")
            elif pointer_gap(wpath.strip(), wsec, True, body)[0] == RESOLVES:
                out.append(f"{LOG}: `{line}` moves {what}, which {wpath.strip()} still has: remove "
                           f"the section in the same commit, or drop the line")
        if unknown:
            print(f"jig: warning: `{line}`: {unread} isn't reachable here (`jig repos`), so this repo's "
                  f"family wasn't read and {repo} wasn't checked", file=sys.stderr)
            continue
        loc = repo_path(repo)
        if not loc or not loc.is_dir():
            print(f"jig: warning: `{line}`: {repo} isn't in `jig repos` here, so its target "
                  f"wasn't checked", file=sys.stderr)
            continue
        t = Board.trunk_name(loc)
        body = trunk_show(loc, path)
        if body is None:
            out.append(f"{LOG}: `{line}`: {repo}'s {t} has no {path} (read {loc}/{path} on {t}): "
                       f"land it there first")
        # An id names an entry or an idea there: one decided since keeps it in the other file.
        elif section and path in (LOG, IDEAS) and move_key(section) not in entry_keys(entries_at(t, str(loc))):
            out.append(f"{LOG}: `{line}`: {repo}'s {path} on {t} has no entry {section}: "
                       f"land it there first")
        elif section and path not in (LOG, IDEAS) and pointer_gap(path, section, True, body)[0] != RESOLVES:
            out.append(f"{LOG}: `{line}`: {repo}'s {path} on {t} has no heading {section}: "
                       f"land it there first")
        else:
            there = section if path in (LOG, IDEAS) and section else (f"{path} § {section}" if section else path)
            frm = moved_from_in(trunk_show(loc, LOG) or "").get(there)
            if not frm or not is_here(pointer_parts(frm)[0]) or \
                    not same_thing(pointer_parts(frm)[1:], thing_of(what)):
                out.append(f"{LOG}: `{line}`: {repo}'s {LOG} on {t} has no moved-from line for {there} naming "
                           f"this repo's {what} (read {loc}/{LOG}): land it there first, with its moved-from line")
    out += moved_from_rules(new, old, paras, unread)
    return out


def entry_keys(text: str) -> set[str]:
    """The ids TEXT's entries have, as move_key compares them."""
    return {move_key(e["id"]) for e in log_entries(text, log_prefix_of(text))}


def moved_from_rules(new: str, old: str, paras: set[str], unread: str = "") -> list[str]:
    """Both ends of a move stay tied from the receiving side. A moved-from line the change adds
    goes under ## Unreleased ### Added, names a repo of the family whose trunk still has the thing
    (the move pending) or moves it here, and one that can't be reached passes with a warning.
    One the change removes or rewrites while that repo's trunk moves the thing here stays: the
    move line there would point at a home with no record of it."""
    out = []
    was = {line for _, _, line, _ in moved_from_lines(old)}
    now = {line for _, _, line, _ in moved_from_lines(new)}
    # A moved-from line anywhere else is read by nothing and checked by nothing, as a move line.
    placed = {(sec, grp, line) for sec, grp, line, _ in any_moved_from(old)}
    out += [f"{LOG}: `{line}` is under ## {sec}{f' ### {grp}' if grp else ''}: a moved-from line goes "
            "under ## Unreleased ### Added"
            for sec, grp, line, _m in any_moved_from(new)
            if (sec, grp, line) not in placed and (grp == "Added" and not move_held(sec)
                                                   or grp != "Added" and maybe_family(pointer_parts(_m.group("frm"))[0], paras, unread))]

    def source(m: re.Match) -> tuple[str, Path | None, str, str, str | None]:
        repo, path, section = pointer_parts(m.group("frm"))
        loc = repo_path(repo)
        return repo, (loc if loc and loc.is_dir() else None), path, \
            (section if path == LOG and section else (f"{path} § {section}" if section else path)), section

    def points_here(loc: Path, key: str, what: str) -> bool:
        ptr = moves_in(trunk_show(loc, LOG) or "").get(key)
        return bool(ptr) and is_here(pointer_parts(ptr)[0]) and same_thing(pointer_parts(ptr)[1:], thing_of(what))
    for sec, _, line, m in moved_from_lines(old):
        if line in now or not move_held(sec):
            continue
        repo, loc, path, key, _ = source(m)
        if loc is None:
            print(f"jig: warning: `{line}` leaves the log, and {repo} isn't in `jig repos` here, so "
                  "whether its move line still points here wasn't checked", file=sys.stderr)
        elif points_here(loc, key, m.group("what")):
            out.append(f"{LOG}: `{line}` is the receiving end of {repo}'s move line on its "
                       f"{Board.trunk_name(loc)} (read {loc}/{LOG}): it stays as written")
    for sec, _, line, m in moved_from_lines(new):
        if line in was or not move_held(sec):
            continue
        repo, loc, path, key, section = source(m)
        if unread and not in_family(repo, paras):
            print(f"jig: warning: `{line}`: {unread} isn't reachable here (`jig repos`), so this repo's "
                  f"family wasn't read and {repo} wasn't checked", file=sys.stderr)
            continue
        if not in_family(repo, paras):
            out.append(f"{LOG}: `{line}` names {repo}, which isn't of this repo's family"
                       + (f" ({', '.join(sorted(paras))})" if paras else " (it has none)")
                       + ": a claim comes only from a repo of its family")
            continue
        if loc is None:
            print(f"jig: warning: `{line}`: {repo} isn't in `jig repos` here, so its source wasn't "
                  "checked", file=sys.stderr)
            continue
        t = Board.trunk_name(loc)
        their_log = trunk_show(loc, LOG) or ""
        body = their_log if path == LOG else trunk_show(loc, path)
        if path == LOG and section:
            # The thing may be an idea there, in the ideas file beside the log.
            both = with_ideas(their_log, trunk_show(loc, IDEAS) or "")
            pending = move_key(section) in {move_key(e["id"]) for e in log_entries(both, log_prefix_of(both))}
        elif section:
            pending = body is not None and pointer_gap(path, section, True, body)[0] == RESOLVES
        else:
            pending = body is not None
        if not pending and not points_here(loc, key, m.group("what")):
            out.append(f"{LOG}: `{line}`: {repo}'s {path} on {t} (read {loc}/{path}) neither has "
                       f"{section or path} nor moves it here: name what it moved, as its move line does")
    return out


def any_moved_from(text: str) -> list[tuple[str, str, str, re.Match]]:
    """(section, group, line, match) for each moved-from-shaped line in log TEXT, wherever it sits."""
    out, section, group = [], "", ""
    for line in text.splitlines():
        if line.startswith("## "):
            section, group = line[3:].strip(), ""
        elif line.startswith("### "):
            group = line[4:].strip()
        elif m := MOVED_FROM.match(line.rstrip()):
            out.append((section, group, line.rstrip(), m))
    return out


def id_number(eid: str, prefix: str) -> int | None:
    m = re.fullmatch(rf"{re.escape(prefix)}(\d+)", eid)
    return int(m.group(1)) if m else None


def touches_dropped(lines: list[str], keep: bool = False) -> list[str]:
    """LINES without each entry's Touches line, the one right under its status line (KEEP: the
    line stays, its pages emptied). Touches says what an entry is about, not what it decided,
    so a released entry may gain or change it: that is how the backfill reaches a release."""
    out = []
    for i, l in enumerate(lines):
        if (l.startswith("Touches:") and i > 1 and lines[i - 2].startswith("### ")
                and re.match(rf"(?:{'|'.join(LOG_STATUSES)}) \(", lines[i - 1])):
            if keep:
                out.append("Touches:")
            continue
        out.append(l)
    return out


def frozen_problems(old: str, new: str, trunk: str, only: set[str] | None = None) -> list[str]:
    """A commit may remove a superseded entry from a released section, in the commit adding the
    entry superseding it, or a struck one, in the commit adding a ### Removed line naming it; add or change an entry's Touches line (M2 checks its pages); and add
    ` [YANKED]` to a release heading with one line under it saying why. Anything else in a
    released section, its change lines above all, is frozen. ONLY: judge those releases alone."""
    out: list[str] = []
    old, bare = removed_entries(old, new)
    if only is not None:
        bare = [e for e in bare if e["section"] in only]
    out += [f"{LOG}: {e['id']} is removed from release {e['section']}, and no entry in the log "
            f"supersedes it: an entry is removed only by the commit adding the accepted one "
            f"that says `Supersedes {e['id']}.`, or by the commit adding under ## Unreleased "
            f"### Removed one of two lines: the strike, `- {e['id']}: {STRIKE_WHY}`, or the move, "
            f"`- {e['id']}: moved to <repo of its family>/{LOG} § <its id there>.`: add it in the same commit" for e in bare if e["section"] not in ("Unreleased", "")]
    prefix = log_prefix_of(new)
    have = {id_number(e["id"], prefix) for e in log_entries(new, prefix)}
    out += [f"{LOG}: the ### Removed line for {prefix}{n:03d} strikes an entry the log still has: "
            f"remove the entry in the same commit, or drop the line"
            for n in sorted(struck_ids(old, new, prefix) & have) if only is None]
    after = release_sections(new)
    for version, (day, yanked, body) in release_sections(old).items():
        if only is not None and version not in only:
            continue
        if version not in after:
            out.append(f"{LOG}: release {version} is gone; a released section is never edited or removed")
            continue
        day2, yanked2, body2 = after[version]
        # A removed block leaves its blank lines either side: one blank is as good as two.
        was, now = (trimmed([l for i, l in enumerate(b) if l.strip() or i and b[i - 1].strip()])
                    for b in (touches_dropped(body), touches_dropped(body2)))
        if yanked2 and not yanked and now and not now[0].startswith("#"):
            now = trimmed(now[1:])
        if day2 != day or (yanked and not yanked2) or was != now:
            out.append(f"{LOG}: release {version} is frozen on {trunk}: add a new accepted entry that "
                       f"supersedes what changed and remove the old one; a release's change lines stay, and only "
                       f"` [YANKED]` and its one line, or an entry's Touches line, may be added to a release")
    return out


def outside_open_deleted(old: str, new: str) -> bool:
    """Whether NEW drops or rewrites a line of OLD outside a not-yet-folded log's open section,
    where its open entries change in place: elsewhere the log only grows,
    but for an entry NEW supersedes, which it removes, and an entry's Touches line, which may
    change. The swap of the old versioning header for the new one, word for word, is no rewrite."""
    for was in (OLD_LOG_HEAD, RULES_MD_LOG_HEAD):
        if was in old and was not in new and LOG_HEAD in new:
            old = old.replace(was, LOG_HEAD, 1)
    old, bare = removed_entries(old, new)
    if bare:
        return True
    a, b = touches_dropped(old.splitlines(), keep=True), touches_dropped(new.splitlines(), keep=True)
    section, where = "", []
    for line in a:
        if line.startswith("## "):
            section = line[3:].strip()
        where.append(section)
    ops = difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes()
    return any(where[i] != "Open" and a[i].strip()
               for tag, i1, i2, _, _ in ops if tag in ("replace", "delete") for i in range(i1, i2))


def log_rules(trunk: str, staged: bool, trunk_side: bool = False) -> list[str]:
    """M2 and the released sections, in every repo, whenever a change touches the log. On trunk
    an id is a number: a D-?<slug> that got there would be released as one."""
    new = in_index(LOG, staged)
    since = since_trunk(trunk)
    old = at_rev(since, LOG)
    # A branch can hold trunk commits its local trunk lacks (made from origin's, or pulled):
    # a release HEAD has beyond the merge base is trunk's too. Only the releases `--merge-log`
    # writes from the merge base's CHANGELOG.md, before the base had a log, are the branch's.
    head = at_rev("HEAD", LOG) if since != "HEAD" else old
    converted = set() if old else converted_versions(trunk, since)
    beyond = set(release_sections(head)) - set(release_sections(old)) - converted
    if not new:
        if old or (head and (beyond or not unconverting(trunk, since, staged))):
            return [f"{LOG} is the repo's decision log: it is never deleted"]
        return []
    prefix = log_prefix(trunk)
    out = log_problems(new, prefix, trunk) + open_problems(old, new, prefix) + frozen_problems(old, new, trunk)
    if beyond:
        out += frozen_problems(head, new, trunk, only=beyond)
    out += touches_problems(old, new, prefix, trunk, staged)
    if trunk_side:
        out += [f"M2 {LOG}:{e['line']} {e['id']} isn't numbered, and {trunk} takes numbers only: "
                f"`jig merge --number` numbers what a merge in progress brings in"
                for e in log_entries(new, prefix) if "?" in e["id"]]
    return out


def on_trunk(trunk: str, branch: str) -> bool:
    """On trunk, or a detached HEAD at trunk or behind it: `git push origin HEAD:main` lands
    what is committed there."""
    return branch == trunk or (not branch and subprocess.run(
        ["git", "merge-base", "--is-ancestor", "HEAD", trunk], capture_output=True).returncode == 0)


def number_placeholders(root: Path, trunk: str) -> list[str]:
    """`jig merge`: number each `D-?<slug>` entry the merge brings into the log, after the
    highest number the log has, in every file the merge changes. Only ids with an entry: the
    same text elsewhere (a test, a rule's example) is no decision. Called with the merge
    staged, before its commit; the merge message lists each number, so git log keeps the map."""
    prefix = log_prefix(trunk)
    files = [f for f in git("-c", "core.quotePath=false", "diff", "--cached", "--name-only",
                            "--diff-filter=AMR", "HEAD").splitlines() if f]
    texts = dict(head_texts_at(":", files))
    # One counter over the log and the ideas file: an idea keeps its id when it is decided.
    log = with_ideas(texts.get(LOG) or git("show", f":{LOG}"), texts.get(IDEAS) or git("show", f":{IDEAS}"))
    had = {e["id"] for e in log_entries(entries_at("HEAD"), prefix)}
    # Ideas first, as they stood when ## Open headed the log: a merge numbers as it always did.
    found = [e["id"] for e in sorted(log_entries(log, prefix), key=lambda e: e["section"] != IDEAS)
             if "?" in e["id"] and e["id"] not in had]
    if not found:
        return []
    nums = [m.group(1) for m in re.finditer(rf"^### {re.escape(prefix)}(\d+)", log, re.M)]
    # Above every number the log names now or ever did, so a rejected entry's is never given
    # again, and above every number an open job holds from a counter over the log.
    board = Board.load(root)
    held = [n for k, v in (board.data.get("reserve") or {}).items()
            if isinstance(v, dict) and matches(LOG, v.get("files") or [])
            for j in board.jobs.values() for n in held_numbers(j).get(k, ())]
    top = max([highest_id(log, prefix, history=True), *held])
    width = max([3, *(len(n) for n in nums)])
    given = {p: f"{prefix}{top + i:0{width}d}" for i, p in enumerate(dict.fromkeys(found), 1)}
    ph = re.compile(rf"(?<![\w-])(?:{'|'.join(map(re.escape, given))})(?![\w-])")
    for f, text in texts.items():
        new = ph.sub(lambda m: given[m.group(0)], text)
        if new != text:
            (root / f).write_text(new)
            git("add", "--", str(root / f), check=True)
    lines = [f"{p} → {n}" for p, n in given.items()]
    msg = Path(git("rev-parse", "--path-format=absolute", "--git-path", "MERGE_MSG"))
    if msg.is_file():
        msg.write_text(msg.read_text().rstrip("\n") + "\n\nNumbered: " + ", ".join(lines) + "\n")
    return lines


def numbers_given(trunk: str) -> set[int]:
    """In a merge on trunk, the numbers `jig merge` gave the job's D-?<slug> entries: an index
    entry whose title is a placeholder entry's in what is merged in, numbered where that side
    has no such number. A counter over the log takes them as the job's own (R6)."""
    merging = merging_commits()
    if len(merging) != 1:
        return set()
    prefix = log_prefix(trunk)
    theirs = log_entries(entries_at(merging[0]), prefix)
    titles = {e["title"] for e in theirs if "?" in e["id"]}
    had = {e["id"] for e in theirs}
    return {int(e["id"][len(prefix):]) for e in log_entries(entries_at(""), prefix)
            if e["title"] in titles and e["id"] not in had and e["id"][len(prefix):].isdigit()}


def head_texts_at(rev: str, paths: list[str]) -> list[tuple[str, str]]:
    """PATHS' text at REV (':' the index), binary files left out."""
    out = []
    for p in paths:
        body = subprocess.run(["git", "show", f"{rev}{p}" if rev == ":" else f"{rev}:{p}"],
                              capture_output=True).stdout
        if body and b"\0" not in body:
            out.append((p, body.decode(errors="replace")))
    return out


def removed_entry(want: str, prefix: str, rev: str = "HEAD",
                  cwd: str | None = None) -> tuple[str, dict, dict | None] | None:
    """Entry WANT as it stood in the last commit of REV's history whose log had it, that
    commit, and the accepted entry superseding it in the commit that removed it."""
    if "?" in want:
        return None
    # First parent, merges diffed against it: a job's D-?slug is numbered only in its merge.
    # The ideas file too: an idea dropped or moved away left from there, and one decided moved
    # its block into the log, where this finds it first.
    for c in git("log", "-m", "--first-parent", "-E", f"-G{history_re(want)}", "--format=%H", rev,
                 "--", LOG, IDEAS, cwd=cwd).splitlines():
        here = log_entries(entries_at(c, cwd), prefix)
        if any(e["id"] == want for e in here):
            return c, next(e for e in here if e["id"] == want), None
        had = next((e for e in log_entries(entries_at(f"{c}^", cwd), prefix) if e["id"] == want), None)
        if had:
            by = next((e for e in here if want in replaced(e, prefix)), None)
            return git("rev-parse", f"{c}^", cwd=cwd), had, by
    return None


def holds_now(want: str, text: str, prefix: str, rev: str | None = None,
              cwd: str | None = None) -> str | None:
    """The entry in log TEXT that holds in place of WANT: each accepted supersedes link
    followed forward, and with REV, through git where TEXT no longer has a link's entry. A
    chain that ends at a move gives the move's pointer, `<repo>/<path> § <id>`."""
    chain = hold_chain(want, text, prefix, rev, cwd)
    have = {e["id"] for e in log_entries(text, prefix)}
    return chain[-1] if len(chain) > 1 and (chain[-1] in have or "/" in chain[-1]) else None


def hold_chain(want: str, text: str, prefix: str, rev: str | None = None,
               cwd: str | None = None) -> list[str]:
    """WANT and each id that superseded it in turn, oldest first, as holds_now walks them, and
    last the pointer of the move that took the final one to a pararepo, if one did."""
    entries = log_entries(text, prefix)
    have = {e["id"] for e in entries}
    by = {s: e["id"] for e in entries for s in replaced(e, prefix)}
    moves = moves_in(text)
    chain = [want]
    while True:
        cur = chain[-1]
        if cur not in have and cur in moves:
            chain.append(moves[cur])
            break
        if cur in by:
            nxt = by[cur]
        elif rev and cur not in have and (found := removed_entry(cur, prefix, rev, cwd)) and found[2]:
            nxt = found[2]["id"]
        else:
            break
        if nxt in chain:
            break
        chain.append(nxt)
    return chain


def cmd_decision(root: Path, args) -> int:
    """Print a decision entry and its supersedes chain. A superseded entry is removed from the
    log, so one the log doesn't have is read from git, and its chain walked to what holds now."""
    if args.page:
        return decisions_on_page(root, args.page)
    if not args.id:
        die("usage: jig decision <id> [--peers], or jig decision --page <page>", 2)
    if args.peers:
        return cmd_peers(root, args)
    board = Board.load(root)
    prefix = log_prefix(board.trunk)
    path = root / LOG
    entries = log_entries(read_entries_text(root), prefix)
    by_id = {e["id"]: e for e in entries}
    want = args.id
    if want not in by_id:
        # D-12 and D-012 are one decision, as R6 counts it.
        want = next((i for i in by_id if decision_id(i) == decision_id(want)), want)
    if want not in by_id:
        steps, cur = [], want
        while cur and cur not in by_id and len(steps) < 50 and (found := removed_entry(cur, prefix)):
            steps.append(found)
            cur = found[2]["id"] if found[2] else ""
        if not steps and shallow():
            die(f"no entry {args.id} in {LOG}, and this clone is shallow: its text may be in the "
                f"history it lacks (`git fetch --unshallow`)", 1)
        if not steps:
            die(f"no entry {args.id} in {LOG} or in its history", 1)
        commit, e, by = steps[0]
        print(e["block"])
        where = (e["section"] if e["section"] not in ("Open", "Unreleased", "", IDEAS)
                 else "an idea" if e["section"] == IDEAS else f"## {e['section'] or 'Unreleased'}")
        print(f"\n{want} was removed from {e['file']}; it stood last at {commit[:7]}, in {where}.")
        for _, old, by in steps:
            if by:
                print(f"  {old['id']} is superseded by {by['id']} {by['title']}")
        last = steps[-1][1]["id"]
        if not steps[-1][2] and (ptr := moves_in(path.read_text() if path.exists() else "").get(last)):
            print(f"  {last} moved to {ptr}: `jig decision {pointer_parts(ptr)[2] or last}` in {pointer_parts(ptr)[0]} reads it.")
        if cur in by_id:
            print(f"What holds now is {cur} {by_id[cur]['title']}: `jig decision {cur}` reads it.")
        return 0
    sups = {e["id"]: (status_parts(e["status"], prefix) or ("", "", "", []))[3] for e in entries}
    # Only an accepted entry holds in place of what it names.
    later = {old: e["id"] for e in entries for old in replaced(e, prefix)}
    chain, cur = [], want
    while cur in by_id and cur not in chain:
        chain.insert(0, cur)
        cur = next((s for s in sups.get(cur, []) if s in by_id), None)
    cur = later.get(want)
    while cur and cur not in chain:
        chain.append(cur)
        cur = later.get(cur)

    def where(e: dict) -> str:
        if e["section"] == IDEAS:
            return f"an idea in {IDEAS}"
        return f"## {e['section']}" if e["section"] == "Open" else e["section"] or "above the log's sections"

    print(by_id[want]["block"])
    if by_id[want]["section"] == IDEAS:
        print(f"\n{want} is an idea in {IDEAS}: not decided yet.")
    if frm := moved_from_in(path.read_text() if path.exists() else "").get(want):
        print(f"\n{want} moved from {frm}.")
    if len(chain) > 1:
        print("\nChain, oldest first:")
        for i in chain:
            e = by_id[i]
            mark = "  ← this one" if i == want else ""
            print(f"  {i} {e['title']} ({where(e)}){mark}")
    if want in later:
        last = chain[-1]
        print(f"\n{want} is superseded by {later[want]}; what holds now is {last} {by_id[last]['title']}.")
    for s in sups.get(want, []):
        if s not in by_id:
            print(f"\n{want} supersedes {s}, which is removed from {LOG}: `jig decision {s}` reads it from git.")
    return 0


# ------------------------------------------------------------- what a decision touches
# Two entries that rule on one situation differently contradict each other, and only a reader
# can tell. jig.py picks the pairs a reader must see side by side: entries whose Touches lines
# name the same page, or a page and one below it. It never judges a pair.

SELF = "."     # this repo, in a page key
META_KEY = "meta"   # a pararepo's metarepo, in a page key
# One line per entry, page and peer log, listing every peer there: a busy page asks once, not
# once per entry that ever touched it. The pointer in parentheses is a path with no blank or
# parenthesis, then for a glossary term ` § <term>` with no parenthesis, so an answer may hold both.
PAIR_LINE = re.compile(r"^- \[[ xX]\] (\S+) vs (\S+) § ([^\s,]+(?:, [^\s,]+)*) \(([^()\s]+(?: § [^()]+)?)\): (.*)$")
# Any ticked or open checklist line with ` vs ` tries to be one: a line reshaped anywhere is
# refused by name, never read as missing. A line with no checkbox is the job's own note.
PAIR_SHAPED = re.compile(r"^- \[.\] \S+ vs ")
UNREAD = "not read for peers"


# `Touches: none — <reason>`: an entry that rules on no page or term, such as a rule for the whole
# repo. The whole line, so a reason may hold commas; it peers with nothing. A line that starts
# with the word none in any other shape is an attempt at it, refused with this form.
NONE_ATTEMPT = re.compile(r"`?none\b", re.I)
TOUCHES_NONE = re.compile(r"none (?:—|-) (\S.*)$")
NONE_FORM = "`Touches: none — <reason>`"


def touches_line(block: str) -> str | None:
    """The text after `Touches:` on the line right under an entry's status line; None when it
    has no such line."""
    lines = [l.strip() for l in block.splitlines()[1:] if l.strip()]
    m = re.match(r"Touches:(.*)$", lines[1]) if len(lines) > 1 else None
    return m.group(1).strip() if m else None


def touches_none(block: str) -> str | None:
    """An entry's reason when its Touches line starts with the word none: the reason of
    `none — <reason>`, or empty when the line has any other shape. None for any other line."""
    line = touches_line(block)
    if line is None or not NONE_ATTEMPT.match(line):
        return None
    m = TOUCHES_NONE.match(line)
    return m.group(1).strip().rstrip(".").strip() if m else ""


def pointer_shaped(piece: str) -> bool:
    """Whether a comma-separated piece of a Touches line is a pointer: a path, no blank in it,
    ending .md, then perhaps ` § <term>`."""
    page, _ = pointer_term(piece.strip().strip("`").strip())
    return bool(page) and " " not in page and page.endswith(".md")


def decisions_on_page(root: Path, page: str) -> int:
    """`jig decision --page PAGE`: each entry whose `Touches:` names PAGE, or a term on it
    (`PAGE § <term>`), whole, in the log's order: what rules on the page, asked of jig rather
    than read from the log."""
    page = page.strip().removeprefix("./")
    entries = log_entries(read_entries_text(root), log_prefix(Board.load(root).trunk))
    hits = [e for e in entries if any(pointer_term(t)[0] == page for t in entry_touches(e["block"]) or [])]
    if not hits:
        print(f"no decision entry's Touches: names {page}")
        return 0
    print("\n\n".join(e["block"].rstrip("\n") for e in hits))
    return 0


def entry_touches(block: str) -> list[str] | None:
    """The pointers on an entry's `Touches:` line, the line right under its status line; None
    when it has no such line, and none for a line starting with the word none. A term may hold
    a comma: a piece after a term's that is no pointer joins it. A term's pointer is written
    `<page> § <term>`, the form a pair line names it in."""
    line = touches_line(block)
    if line is None:
        return None
    if touches_none(block) is not None:
        return []
    out: list[str] = []
    for x in line.split(","):
        x = x.strip().strip("`").strip()
        if out and "§" in out[-1] and x and not pointer_shaped(x) and not NONE_ATTEMPT.match(x):
            out[-1] += ", " + x
        else:
            out.append(x)
    out = [p.rstrip(".").strip() for p in out if p]
    return [f"{pg} § {t}" if "§" in p else p for p in out for pg, t in [pointer_term(p)]]


def pointer_term(path: str) -> tuple[str, str]:
    """(page, term) for a pointer's path: `docs/glossary.md § products` names one glossary term,
    the shared vocabulary an entry about naming or a genre rules on. Term empty for a page."""
    page, _, term = path.partition("§")
    return page.strip(), term.strip()


def rule_sentence(block: str) -> str:
    """An entry's first body sentence, after its status and Touches lines: what it rules."""
    lines = [l.strip() for l in block.splitlines()[1:] if l.strip()]
    body = lines[2:] if entry_touches(block) is not None else lines[1:]
    text = " ".join(body)
    m = re.match(r"(.+?[.!?])(?=\s|$)", text)
    return (m.group(1) if m else text)[:240]


def page_key(path: str) -> str:
    """A page by what it stands for, so its flat and folder forms are one: docs/a/b for
    docs/a/b.md and docs/a/b/b.md alike."""
    if path.startswith("docs/") and path.endswith(".md") and not reference_file(path):
        return page_folder(path)
    return path


def split_pointer(ptr: str, names: dict[str, str]) -> tuple[str, str]:
    """(repo key, path) for a pointer, in the forms rules-pararepo.md gives a pointer: `<repo>:<path>`,
    `<repo>/<path>`, or a path of the writer's own (key ''). `docs/…` is always a path: a repo
    named docs is reached as `docs:<path>`. A `<repo>:` NAMES doesn't know keys as `?<repo>`."""
    m = re.match(r"([\w.-]+):(.+)$", ptr)
    if m:
        return names.get(m.group(1).casefold(), f"?{m.group(1)}"), m.group(2)
    head, _, rest = ptr.partition("/")
    if rest and head != "docs" and head.casefold() in names:
        return names[head.casefold()], rest
    return "", ptr


def touch_key(ptr: str, writer: str, names: dict[str, str]) -> tuple[str, str]:
    """(repo, page key) for a pointer written in WRITER's log. A glossary term keys as a page
    below the glossary, so two entries meet on one term, and a pointer to the whole glossary
    meets every term; a term never meets the pages of its genre (owner, bug-touches-abstract)."""
    repo, path = split_pointer(ptr, names)
    page, term = pointer_term(path)
    key = page_key(page)
    if term:
        key += "/§" + " ".join(term.casefold().replace("/", " ").split())
    return repo or writer, key


def keys_meet(a: tuple[str, str], b: tuple[str, str]) -> bool:
    """One page, or one page above the other: a page's folder holds the pages below it, as
    pages_above climbs."""
    return a[0] == b[0] and (a[1] == b[1] or a[1].startswith(b[1] + "/") or b[1].startswith(a[1] + "/"))


def superseded_ids(entry: dict, prefix: str) -> set[str]:
    return set((status_parts(entry["status"], prefix) or ("", "", "", []))[3])


def live_entries(text: str, prefix: str) -> list[dict]:
    """The log's entries no other entry in it supersedes: a superseded one rules nothing now."""
    entries = log_entries(text, prefix)
    gone = {s for e in entries for s in superseded_ids(e, prefix)}
    return [e for e in entries if e["id"] not in gone]


def touch_names(root: Path, trunk: str) -> dict[str, str]:
    """The repo names a pointer may carry, each to its key: this repo's own, a pararepo's
    metarepo, a metarepo's registered pararepos."""
    names = {n.casefold(): SELF for n in this_repo_names(root) - {"this"}}
    para, meta = load_para(trunk), load_meta(trunk)
    if para:
        names[para["meta"].casefold()] = META_KEY
    for p in (meta or {}).get("pararepos", []):
        names.setdefault(p.casefold(), p)
    return names


def meta_cache(root: Path, para: dict) -> tuple[Path | None, str]:
    """The metarepo's cache at the pin, or None and why it can't be read: a cache at another
    pin rules on what the pararepo no longer cites."""
    for cache in (root / CACHE, main_root() / CACHE):
        if (cache / "PIN").is_file():
            at = (cache / "PIN").read_text().split("\n")[0]
            if at == para.get("pin"):
                return cache, ""
            return None, (f"{para['meta']}'s log: {CACHE}/ is at {at}, the pin is {para.get('pin')}: "
                          "run `jig sync`")
    return None, f"{para['meta']}'s log at the pin, which {CACHE}/ doesn't hold: run `jig sync`"


def peer_logs(root: Path, trunk: str) -> tuple[list[tuple[str, str, str]], list[str]]:
    """Every other repo's log whose entries can be peers, as (key of the repo that wrote it, how
    a line names it, its text): a pararepo's metarepo's at the pin, a metarepo's registered
    pararepos' on their trunks. And one line per log that could not be read."""
    logs, unread = [], []
    para, meta = load_para(trunk), load_meta(trunk)
    if para:
        cache, why = meta_cache(root, para)
        if cache and (cache / LOG).is_file():
            ideas = (cache / IDEAS).read_text(errors="replace") if (cache / IDEAS).is_file() else ""
            logs.append((META_KEY, f"{para['meta']}/{LOG}",
                         with_ideas((cache / LOG).read_text(errors="replace"), ideas)))
        else:
            unread.append(why or f"{para['meta']}'s log, which its cache at the pin doesn't hold")
    for p in (meta or {}).get("pararepos", []):
        loc = repo_path(p)
        if loc is None or not loc.is_dir():
            unread.append(f"{p}, which `jig repos` doesn't list here")
            continue
        text = entries_at(Board.trunk_name(loc), str(loc))
        if text:
            logs.append((p, f"{p}/{LOG}", text))
    return logs, unread


def touching_entries(text: str, prefix: str, writer: str, label: str,
                     names: dict[str, str]) -> list[dict]:
    """A log's live entries, each with its pointers and page keys. An idea in with_ideas' text
    is labelled with its ideas file, so a reader sees it is not decided."""
    out = []
    for e in live_entries(text, prefix):
        ptrs = entry_touches(e["block"]) or []
        here = label[:-len(LOG)] + IDEAS if e["file"] == IDEAS and label.endswith(LOG) else label
        out.append({**e, "label": here, "writer": writer, "pointers": ptrs,
                    "keys": [touch_key(p, writer, names) for p in ptrs]})
    return out


def touching(root: Path, trunk: str, own: str) -> tuple[list[dict], list[str]]:
    """Every live entry in this repo's log OWN and in every peer log, and the logs not read."""
    names = touch_names(root, trunk)
    logs, unread = peer_logs(root, trunk)
    out = touching_entries(own, log_prefix(trunk), SELF, LOG, names)  # OWN as with_ideas joins it
    for writer, label, text in logs:
        out += touching_entries(text, log_prefix_of(text), writer, label, names)
    return out, unread


def peers_of(entry: dict, every: list[dict], prefix: str) -> list[tuple[dict, str]]:
    """ENTRY's peers, each with the pointer of ENTRY's they meet on. Not itself, nor what it
    supersedes or what supersedes it: a chain is one decision over time."""
    out = []
    for o in every:
        if o["writer"] == entry["writer"] and (o["id"] == entry["id"] or o["id"] in superseded_ids(entry, prefix)
                                               or entry["id"] in superseded_ids(o, prefix)):
            continue
        hit = next((p for p, k in zip(entry["pointers"], entry["keys"])
                    if any(keys_meet(k, ok) for ok in o["keys"])), None)
        if hit:
            out.append((o, hit))
    return out


def pair_line(entry: str, label: str, ids: list[str], ptr: str, answer: str = "___") -> str:
    return f"- [ ] {entry} vs {label} § {', '.join(ids)} ({ptr}): {answer}"


def pair_lines(root: Path, trunk: str, rng: str) -> list[str]:
    """Fold-in: one line per page each entry the branch adds or changes meets peers on, per peer
    log, answered agrees, narrows or conflicts. Two of the branch's own entries that are peers
    are asked once. Trunk's entries are read from trunk, so a branch can't drop a peer by
    editing it."""
    prefix = log_prefix(trunk)
    right = rng.partition("..")[2].lstrip(".") or "HEAD"
    edited = edited_decisions(root, prefix, rng)
    names = touch_names(root, trunk)
    head = log_entries(git("show", f"{right}:{LOG}", cwd=str(root)), prefix)
    gone = {s for e in head for s in superseded_ids(e, prefix)}
    changed = [e for e in touching_entries(git("show", f"{right}:{LOG}", cwd=str(root)), prefix, SELF, LOG, names)
               if e["id"] in edited and e["id"] not in gone]
    if not changed:
        return []
    every, unread = touching(root, trunk, entries_at(trunk, str(root)))
    every += changed
    groups: dict[tuple[str, str, str], list[str]] = {}
    seen = set()
    for e in changed:
        for o, ptr in peers_of(e, every, prefix):
            pair = frozenset([(SELF, e["id"]), (o["writer"], o["id"])])
            if pair in seen:
                continue
            seen.add(pair)
            groups.setdefault((e["id"], o["label"], ptr), []).append(o["id"])
    # In number order, so a reader finds an id where they'd look for it.
    out = [pair_line(e, label, sorted(ids, key=lambda i: [int(t) if t.isdigit() else t for t in re.split(r"(\d+)", i)]), ptr)
           for (e, label, ptr), ids in groups.items()]
    out += [f"- [ ] {UNREAD}: {u} — read it beside the changed entries, or why not: ___" for u in unread]
    return out


def pair_keys(line: str) -> list[tuple[str, str, str]]:
    """The pairs a pair line covers, one per peer id on it."""
    m = PAIR_LINE.match(line.strip())
    return [(m.group(1), m.group(2), i) for i in m.group(3).split(", ")] if m else []


def pair_problem(line: str) -> str:
    """Why a fold-in line shaped like a pair line isn't answered as one, or ''."""
    l = line.strip()
    if not PAIR_SHAPED.match(l):
        return ""
    m = PAIR_LINE.match(l)
    if not m:
        return "keep a pair line's shape: `<id> vs <log> § <id>, … (<page>): <answer>`"
    a = m.group(5).strip()
    if re.match(r"agrees\b", a, re.I):
        return ""
    w = re.match(r"(narrows|conflicts)\b[ \t]*:?[ \t]*(.*)$", a, re.I)
    if w:
        word, rest = w.group(1).lower(), w.group(2)
        what = "how" if word == "narrows" else "resolution"
        if not re.search(r"\w", rest):
            return f"{word} needs its {what}: `{word}: …`"
        ids = m.group(3).split(", ")
        # One answer for several peers: a narrows or conflicts says which of them it is about.
        if len(ids) > 1 and not any(re.search(rf"(?<![\w?-]){re.escape(i)}(?![\w-])", rest) for i in ids):
            return f"{word} on a line of several ids names at least one of them: `{word}: <id>, <{what}>`"
        return ""
    return "answer agrees, narrows: <how>, or conflicts: <resolution>"


def gate_pairs(where: Path, trunk: str, fold: str, base: str,
               commit: str) -> tuple[list[str], list[str], list[str]]:
    """The pairs the job's entries make with trunk as the gate merged it, that the note's
    fold-in doesn't answer, each line holding only the ids left uncovered. Split by cause where
    jig can know it: a pair with this repo's log that jig also finds at the note's commit against
    its base was listed at the handoff and left out of the note; the rest are new on trunk since
    the base. Another repo's log is read as it stands now, not as it stood at the base, so a pair
    with it gets no cause."""
    have = {k for l in fold.splitlines() for k in pair_keys(l)}
    then = {k for l in pair_lines(where, base, f"{base}...{commit}") for k in pair_keys(l)}
    left, new, other = [], [], []
    for l in pair_lines(where, trunk, f"{trunk}...HEAD"):
        m = PAIR_LINE.match(l)
        if not m:
            continue
        e, label, ptr = m.group(1), m.group(2), m.group(4)
        open_ids = [i for i in m.group(3).split(", ") if (e, label, i) not in have]
        if label != LOG:
            if open_ids:
                other.append(pair_line(e, label, open_ids, ptr))
            continue
        was = [i for i in open_ids if (e, label, i) in then]
        if was:
            left.append(pair_line(e, label, was, ptr))
        if now := [i for i in open_ids if i not in was]:
            new.append(pair_line(e, label, now, ptr))
    return left, new, other


def migrating_log(trunk: str, staged: bool) -> bool:
    """This change is `jig update --merge-log`: a register's rows or CHANGELOG.md's sections
    were there before it, and are gone after it."""
    meta = load_meta(trunk)
    prefix = (meta or {}).get("decision_prefix")
    return bool(olds := merged_files_at(since_trunk(trunk), meta)) and not any(
        holds_old_log(in_index(f, staged), f, prefix) for f in olds)


def merged_files_at(at: str, meta: dict | None) -> list[str]:
    """The files at AT `--merge-log` merges: CHANGELOG.md with its sections, and a register with
    rows (an entry file, or one named decisions.md). Not every table in a page is a register."""
    entry, prefix = (meta or {}).get("entry_files", []), (meta or {}).get("decision_prefix")
    return [f for f in git("ls-tree", "-r", "--name-only", at).splitlines()
            if (f == CHANGELOG or (f.endswith(".md") and not f.startswith(f"{DIR}/")
                                   and (f in entry or Path(f).name.lower() == "decisions.md")))
            and holds_old_log(at_rev(at, f), f, prefix)]


def converted_versions(trunk: str, since: str) -> set[str]:
    """The releases this branch's `--merge-log` wrote: in SINCE's CHANGELOG.md, and in the log as
    the commit adding it wrote it. A release trunk made later, under a version it reused, isn't;
    nor is anything when a remote's trunk has that commit, since then trunk converted."""
    added = git("log", "--diff-filter=A", "--format=%H", "--reverse", f"{since}..HEAD", "--", LOG).split()
    if not added:
        return set()
    remotes = [r for r in git("for-each-ref", "--format=%(refname)", "refs/remotes").split()
               if r.endswith(f"/{trunk}")]
    if any(subprocess.run(["git", "merge-base", "--is-ancestor", added[0], r],
                          capture_output=True).returncode == 0 for r in remotes):
        return set()
    was = {f"v{m.group(1)}" for l in at_rev(since, CHANGELOG).splitlines() if (m := OLD_RELEASE.match(l))}
    return was & set(release_sections(at_rev(added[0], LOG)))


def unconverting(trunk: str, since: str, staged: bool) -> bool:
    """Removing the log undoes the branch's `--merge-log`: every file it merged is back as it was."""
    olds = merged_files_at(since, load_meta(trunk))
    return bool(olds) and all(in_index(f, staged).strip() == at_rev(since, f).strip() for f in olds)


def migrated_ids(trunk: str, prefix: str | None) -> set[str]:
    """The ids of the register rows where the branch left trunk: the entries `--merge-log`
    writes from them, which may lack Touches."""
    was = since_trunk(trunk)
    rx = re.compile(r"^\s*\|\s*([A-Z][A-Z0-9]*-\d+)\s*\|")
    return {m.group(1) for f in merged_files_at(was, load_meta(trunk))
            for row in rows_in(at_rev(was, f), prefix) if (m := rx.match(row))}


def records_converted(old: str, new: str, prefix: str, trunk: str, staged: bool) -> set[str]:
    """The entries `--merge-log` converts from decision records that this change removes, in an
    empty log or one in use: each ends naming its record (`Record 0001 before this log.`), and
    were decided before Touches. An entry whose record is still there is no conversion."""
    added = [e for e in log_entries(new, prefix) if e["id"] not in {x["id"] for x in log_entries(old, prefix)}]
    marked = {e["id"]: int(m.group(1)) for e in added if (m := RECORD_MARK.search(e["block"]))}
    if not marked:
        return set()
    was = since_trunk(trunk)
    gone = set(git("-c", "core.quotePath=false", "diff", "--name-only", "--no-renames", "--diff-filter=D",
                   was, *(["--cached"] if staged else [])).splitlines())
    # A record there: in a folder of records where the branch left trunk, not any numbered file.
    names = git("-c", "core.quotePath=false", "ls-tree", "-r", "--name-only", was).splitlines()
    folders = record_folders(Path.cwd(), [f for f in names if os.path.dirname(f) in {os.path.dirname(g) for g in gone}],
                             lambda f: at_rev(was, f))
    removed = Counter(n for info in folders.values() for n, f in info["records"] if f in gone)
    # Each removed record converts once: a second entry naming the same one is no conversion.
    claims = Counter(marked.values())
    return {i for i, n in marked.items() if removed[n] and claims[n] <= removed[n]}


def touched_term(path: str, term: str, repo: str, cache: Path | None, staged: bool) -> str:
    """Why a `§` pointer on a Touches line isn't one glossary term, or ''. Only the glossary:
    a § on another page would break when an ordinary heading is renamed. The term is matched
    whole, so two entries spelling it alike meet as peers."""
    if repo.startswith("?"):
        return f"names {repo[1:]}, which is no repo jig knows here"
    if path != GLOSSARY or not term:
        return f"is no glossary term: § names a term of {GLOSSARY}, `{GLOSSARY} § <term>`"
    if "(" in term or ")" in term:
        # A pair line names the pointer in parentheses: a term holding one can't be read back.
        return "is a term with a parenthesis, which a pointer can't name: name the page"
    if repo == META_KEY:
        if cache is None:
            return ""
        text = (cache / GLOSSARY).read_text(errors="replace") if (cache / GLOSSARY).is_file() else ""
        where = "the metarepo's glossary at the pin"
    elif repo not in ("", SELF):
        return "is a pararepo's page: a metarepo names only its own"
    else:
        text, where = body_now(GLOSSARY, staged) or "", GLOSSARY
    have = {t.casefold() for t in glossary_terms(text)}
    return "" if term.casefold() in have else f"is no term in {where}: add `### {term}` under `# {BASIC_TERMS}` there, or name a term it has"


def touches_problems(old: str, new: str, prefix: str, trunk: str, staged: bool,
                     home: str = LOG) -> list[str]:
    """M2: an entry added or changed names the pages it touches, and each is a docs page. An
    entry as trunk has it is left alone until it changes. `jig update --merge-log` converting a
    register writes entries decided before Touches; they are backfilled from update's list. Only
    those: an entry a later commit on the branch adds names its pages."""
    root = Path.cwd()
    # A register's open rows and open records convert into the ideas file, decided before
    # Touches as the log's entries were: the log's own text says whether this is that merge.
    log_old = old if home == LOG else at_rev(since_trunk(trunk), LOG)
    migrating = not log_entries(log_old, prefix) and migrating_log(trunk, staged)
    converted = migrated_ids(trunk, (load_meta(trunk) or {}).get("decision_prefix")) if migrating else set()
    converted |= records_converted(old, new, prefix, trunk, staged)
    names = touch_names(root, trunk)
    para, meta = load_para(trunk), load_meta(trunk)
    cache, _ = meta_cache(root, para) if para else (None, "")
    docmap = list((Board.load(root).data.get("docmap") or {})) if not meta else []
    was = {e["id"]: e["block"] for e in log_entries(old, prefix)}
    out = []
    for e in log_entries(new, prefix):
        if was.get(e["id"]) == e["block"] or e["id"] in converted:
            continue
        at = f"{home}:{e['line']} {e['id']}"
        ptrs = entry_touches(e["block"])
        reason = touches_none(e["block"])
        if reason is not None:
            if not re.search(r"\w", reason):
                out.append(f"M2 {at} touches none in no shape jig reads: write it {NONE_FORM}, "
                           f"an em dash or ` - ` before the reason ({RULES_DIR}/rules-decisions.md, Decision log)")
            elif any(pointer_shaped(x) for x in reason.split(",")):
                out.append(f"M2 {at} mixes none with pages: {NONE_FORM} is the whole line, "
                           f"or name only the pages")
            continue
        if not ptrs:
            shared = f"`{para['meta']}/docs/<genre>/<page>.md` for what it shares, " if para else ""
            out.append(f"M2 {at} names no page it touches: under its status line, `Touches: "
                       f"{shared}docs/<page>.md`, a term as `{GLOSSARY} § <term>`, or `Touches: none — <reason>` "
                       f"({RULES_DIR}/rules-decisions.md, Decision log)")
            continue
        for p in ptrs:
            repo, path = split_pointer(p, names)
            path, term = pointer_term(path)
            docs = path.startswith("docs/") and path.endswith(".md")
            if NONE_ATTEMPT.match(p) and not docs:
                why = f"is no docs page: {NONE_FORM} is the whole line, never one of its pointers"
            elif term or "§" in p:
                why = touched_term(path, term, repo, cache, staged)
            elif repo.startswith("?"):
                why = f"names {repo[1:]}, which is no repo jig knows here"
            elif repo == META_KEY:
                # With no cache at the pin, only its shape: the gate's checkout reads the cache.
                why = ("" if docs and (cache is None or any((cache / f).is_file() for f in page_forms(path)))
                       else "is no page in the metarepo at the pin")
            elif repo not in ("", SELF):
                why = "is a pararepo's page: a metarepo names only its own"
            elif not (docs or any(same_page(k, path) for k in docmap)):
                why = "is no docs page: a page under docs/" + ("" if meta else " or one docmap names")
            else:
                why = "" if any(body_now(f, staged) for f in page_forms(path)) else "is no page here"
            if why:
                out.append(f"M2 {at} touches {p}, which {why}" if why.startswith("is")
                           else f"M2 {at} touches {p}: it {why}")
    return out


def start_entry(root: Path, want: str, logs: list[tuple[str, str, str]], every: list[dict],
                names: dict[str, str], unread: list[str]) -> tuple[dict, str]:
    """The entry `--peers` starts from, and a line saying it hopped to a successor or ''.
    `<repo>/<id>` reads that repo's log; a plain id this log first, since review asks about the
    diff's own entries, then the one other log that holds it. LOGS are (writer, label, text),
    this repo's first. Two other logs holding it is a refusal naming each `<repo>/<id>`."""
    head, _, rest = want.rpartition("/")
    if head:
        if head.casefold() not in names:
            die(f"no repo {head} here: a `<repo>/<id>` names this repo, its metarepo or a pararepo `jig repos` lists", 1)
        key = names[head.casefold()]
        logs, want = [lg for lg in logs if lg[0] == key], rest
        if not logs:
            die(f"{head}'s log was not read for peers:" + "".join(f"\nnot read: {u}" for u in unread), 1)
        every = [e for e in every if e["writer"] == key]
    searched = [label for _, label, _ in logs]

    def held(writer: str) -> dict | None:
        es = [e for e in every if e["writer"] == writer]
        return next((e for e in es if e["id"] == want), None) or \
            next((e for e in es if decision_id(e["id"]) == decision_id(want)), None)

    if logs[0][0] == SELF:
        if found := held(SELF):
            return found, ""
        # An id this repo superseded or removed is ours: another log's entry with the same number
        # is a different decision, so it is refused here as `jig decision` reads it.
        prefix = log_prefix_of(logs[0][2])
        if (by := holds_now(want, logs[0][2], prefix, "HEAD", str(root))) and "/" in by:
            die(f"{want} moved to {by}: its peers are read there", 1)
        if by:
            die(f"{want} was superseded in {LOG}; what holds now is {by}: `jig decision {by} --peers`", 1)
        if removed_entry(want, prefix, cwd=str(root)):
            die(f"{want} was removed from {LOG}: `jig decision {want}` reads it", 1)
    others = [lg for lg in logs if lg[0] != SELF]
    hits = [(h, "") for w, _, _ in others if (h := held(w))]
    if not hits:
        # A superseded entry is removed from its log: start from the entry holding in its place.
        for w, label, text in others:
            if (by := holds_now(want, text, log_prefix_of(text))) and (h := next((e for e in every if e["writer"] == w and e["id"] == by), None)):
                hits.append((h, f"{label} § {want} is superseded; starting from {by}, which holds now."))
    if len(hits) == 1:
        return hits[0]
    if hits:
        die(f"{want} is in more than one log; name one: "
            + ", ".join(f"{h['label'].removesuffix('/' + LOG)}/{h['id']}" for h, _ in hits), 1)
    die(f"no live entry {want} in " + ", ".join(searched)
        + "".join(f"\nnot read: {u}" for u in unread), 1)


def cmd_peers(root: Path, args) -> int:
    """`jig decision <id> --peers`: the entries a reader should read beside this one."""
    board = Board.load(root)
    prefix = log_prefix(board.trunk)
    names = touch_names(root, board.trunk)
    others, unread = peer_logs(root, board.trunk)
    logs = [(SELF, LOG, read_entries_text(root))] + others
    every = [e for w, label, text in logs
             for e in touching_entries(text, prefix if w == SELF else log_prefix_of(text), w, label, names)]
    entry, hopped = start_entry(root, args.id, logs, every, names, unread)
    print(f"{entry['id']} {entry['title']}" if entry["writer"] == SELF
          else f"{entry['label']} § {entry['id']} {entry['title']}")
    print(f"  {rule_sentence(entry['block'])}")
    if hopped:
        print(hopped)
    if not entry["pointers"]:
        reason = touches_none(entry["block"])
        print(f"\n{entry['id']} touches no page ({reason}), so it has no peers." if reason
              else f"\n{entry['id']} has no Touches line, so no peers can be found.")
        return 0
    found = peers_of(entry, every, prefix)
    print(f"\nPeers ({len(found)}):" if found else "\nNo peers.")
    for o, ptr in found:
        idea = ", an idea" if o["file"] == IDEAS else ""
        print(f"  {o['label']} § {o['id']} {o['title']} ({ptr}{idea})")
        print(f"      {rule_sentence(o['block'])}")
    for u in unread:
        print(f"not read: {u}")
    return 0


def placement_hints(root: Path, trunk: str) -> list[str]:
    """In a metarepo: each of its pages two pararepos' entries touch while none of its own
    does. A ruling two repos share is probably the metarepo's."""
    if not load_meta(trunk):
        return []
    every, _ = touching(root, trunk, read_entries_text(root))
    ours = [k for e in every if e["writer"] == SELF for k in e["keys"]]
    by_page: dict[str, set[str]] = {}
    for e in every:
        for k in e["keys"]:
            if e["writer"] != SELF and k[0] == SELF:
                by_page.setdefault(k[1], set()).add(e["writer"])
    # A term keys as docs/glossary/§<term>: shown as the pointer that names it.
    return [f"{page.replace('/§', '.md § ', 1)}: {', '.join(sorted(ws))} rule on it, and no entry here does"
            for page, ws in sorted(by_page.items())
            if len(ws) > 1 and not any(keys_meet((SELF, page), k) for k in ours)]


def untouched_entries(root: Path, trunk: str) -> list[tuple[str, str]]:
    """`jig update`: each live entry or idea with no Touches line, for the backfill, with the
    file it is in: an idea folded from an old log's ## Open may have none."""
    return [(e["file"], f"{e['id']} {e['title']}") for e in live_entries(read_entries_text(root), log_prefix(trunk))
            if entry_touches(e["block"]) is None]


RELEASE = f"{DIR}/scripts/release.sh"
RELEASE_TODO = "# TODO: release protocol."
PUBLISH = f"{DIR}/scripts/publish.sh"
PUBLISH_TODO = "# TODO: publish steps."
VERSION = re.compile(r"^\d+\.\d+\.\d+$")


def release_script(root: Path, meta: bool = False) -> bool:
    """Add release.sh from the template if it's missing. A metarepo's has no build: jig runs
    its release steps itself, so the protocol is already defined."""
    dest = root / RELEASE
    src = Path(__file__).resolve().parent / "scripts" / "release.sh"
    if dest.exists() and not meta:
        return False
    if not dest.exists() and not src.exists():
        return False
    # init copies the template before `init --meta` runs, so a metarepo's may already be here.
    text = (dest if dest.exists() else src).read_text()
    if meta:
        text = "\n".join(l for l in text.splitlines() if not l.startswith(RELEASE_TODO)) + "\n"
    if dest.exists() and dest.read_text() == text:
        return False
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(text)
    dest.chmod(0o755)
    return True


def publish_script(root: Path) -> bool:
    """Add publish.sh from the template, TODO line included, if it's missing."""
    dest = root / PUBLISH
    src = Path(__file__).resolve().parent / "scripts" / "publish.sh"
    if dest.exists() or not src.exists():
        return False
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(src.read_text())
    dest.chmod(0o755)
    return True


def protocol_missing(root: Path, board: "Board", meta: dict | None, para: dict | None) -> str:
    # A metarepo and a pararepo have a default release: jig's own checks, before the tag.
    if meta or para:
        return ""
    script = root / RELEASE
    if not script.exists():
        return f"no {RELEASE}"
    if any(l.startswith(RELEASE_TODO) for l in script.read_text().splitlines()):
        return f"{RELEASE} still holds the template's TODO"
    if not (board.data.get("release") or {}).get("artifacts"):
        return f"the board's release.artifacts is empty"
    return ""


def next_version(last: str, args, meta: dict | None) -> str:
    if args.version:
        if not VERSION.match(args.version):
            die(f"--version takes X.Y.Z, not {args.version}", 2)
        if last and version_key(args.version) <= version_key(last):
            die(f"--version {args.version} is not after {last}", 2)
        return args.version
    # The level is how much the product changed (rules-release.md, Versioning). Leaving 0.y.z is the
    # owner's call, so a milestone counts from 1.0.0 and never makes it.
    if args.milestone and (not last or version_key(last)[0] == 0):
        die(f"--milestone counts milestones from 1.0.0, and the latest release is {last or 'none'}: "
            "1.0.0 is the owner's call, `--version 1.0.0`", 2)
    if not last:
        # A metarepo starts at 0.1.0; any other repo names its first version.
        if not (meta or args.feature):
            die("no v* tag yet: name the first version with --version X.Y.Z, or --feature for 0.1.0", 2)
        return "0.1.0"
    x, y, z = (version_key(last) + (0, 0, 0))[:3]
    if args.milestone:
        return f"{x + 1}.0.0"
    if args.feature:
        return f"{x}.{y + 1}.0"
    return f"{x}.{y}.{z + 1}"


def released_log(text: str, tag: str) -> str:
    """The log with ## Unreleased named for this release, and an empty one above it for what
    comes next. A repo that never releases just grows Unreleased."""
    heading = f"## {tag} - {date.today().isoformat()}"
    if re.search(r"^## Unreleased[ \t]*$", text, re.M):
        return re.sub(r"^## Unreleased[ \t]*$", f"## Unreleased\n\n{heading}", text, count=1, flags=re.M)
    first = re.search(r"^## v\d", text, re.M)
    if first:
        return text[:first.start()] + f"## Unreleased\n\n{heading}\n\n" + text[first.start():]
    return text.rstrip("\n") + f"\n\n## Unreleased\n\n{heading}\n"


def cmd_release(root: Path, args) -> int:
    os.chdir(root)        # every git path below, `.` and `add -u` included, is the whole repo
    board = Board.load(root)
    trunk = board.trunk
    meta = load_meta(trunk)
    para = None if meta else load_para(trunk)
    kind = "metarepo" if meta else "pararepo" if para else "repo"
    print(f"jig release: {board.data.get('name') or root.name} ({kind})")
    if git("branch", "--show-current") != trunk:
        die(f"release from {trunk}", 2)
    if git("status", "--porcelain", "--untracked-files=no"):
        die("commit or stash first: a release names one commit", 2)
    missing = protocol_missing(root, board, meta, para)
    if missing:
        die(f"the release protocol isn't defined ({missing}): run /jig:release, which asks what "
            f"this repo builds and ships and fills in {RELEASE} and release.artifacts", 2)
    problems, loc = (meta_problems(root, meta, trunk) if meta else []), None
    if para:
        problems, loc = para_problems(root, para, trunk)
    left = [f for f in release_waits_for() if not (para and pin_bump(f))]
    bumps = [f for f in release_waits_for() if para and pin_bump(f)]
    for f in bumps:
        print(f"staged {f.name}: {para['meta']} {read_staged(f)[0].get('release')} waits to be taken "
              f"in a job; it doesn't hold this release")
    if not args.force:
        problems += staged_refusal("the release", pin_bumps_wait=not para)
        # A batch's jobs merged on a check owed by one complete run on the trunk they made.
        owed = batch_merges(trunk)
        if owed:
            problems.append(
                f"{len(owed)} merge{'s' if len(owed) > 1 else ''} since the last complete check on "
                f"{trunk} owe{'' if len(owed) > 1 else 's'} the batch's check ("
                + ", ".join(f"{c[:12]} {s}" for c, s in owed)
                + f"): run `jig queue --full -- ./{DIR}/scripts/check.sh --full` on {trunk}, then `jig checked`")
    # Released, a D-?<slug> would be frozen under its version and never get its number.
    problems += [f"{e['file']}:{e['line']} {e['id']} isn't numbered: a merge numbers it (`jig merge "
                 f"--number` while one is in progress); number it on a branch before releasing"
                 for e in log_entries(read_entries_text(root), log_prefix(trunk)) if "?" in e["id"]]
    if problems:
        for p in problems:
            print(f"refused: {p}", file=sys.stderr)
        return 2
    pat = re.compile(meta["tag_pattern"] if meta else r"^v\d+\.\d+(\.\d+)?$")
    last = latest_tag([t for t in git("tag", "--list").splitlines() if pat.match(t)])
    if meta:
        # No rename detection: a cited file moved out of the set still changed what is cited.
        changed = [f for f in git("-c", "core.quotePath=false", "diff", "--name-only", "--no-renames",
                                  last, "HEAD").splitlines()
                   if is_entry(f, meta["entry_files"])] if last else entry_paths("HEAD")
        if not changed:
            die(f"nothing to release: no entry file changed since {last}", 2)
    version = next_version(last, args, meta)
    tag = f"v{version}"
    # A pararepo's release settles its sync buffer: every Open row but a move-in row, `jig
    # move-in`'s, goes to the metarepo in one proposal, made before the build so a release never
    # ships with drift nobody proposed.
    proposed = None
    if para and unproposed(root)[1]:
        proposed = buffer_proposal(root, para, loc, f"buffer-{tag}")

    def undo(why: str) -> int:
        # The tree was clean, so putting tracked files back loses only what the release wrote.
        git("checkout", "-q", "--", ".")
        if proposed:
            proposed[0].unlink()
            git("branch", "-D", proposed[1], cwd=str(loc))
        print(f"refused: {why}. Tracked files are back as they were; nothing is tagged.",
              file=sys.stderr)
        return 2

    env = {k: v for k, v in os.environ.items()
           if k not in ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_PREFIX")}
    globs = (board.data.get("release") or {}).get("artifacts", [])
    # What the globs match before the build, by mtime: a file counts only if this run wrote it.
    before = {f: f.stat().st_mtime_ns for g in globs for f in root.glob(g) if f.is_file()}
    def run(script: Path, argv: list) -> int:
        # Piped, Python's stdout is block-buffered: flush so jig's lines come before the script's.
        sys.stdout.flush()
        cmd = ([str(script)] if os.access(script, os.X_OK) else ["bash", str(script)]) + argv
        return subprocess.run(cmd, cwd=root, env=env).returncode

    for script, argv in ((root / DIR / "scripts" / "check.sh", []), (root / RELEASE, [version])):
        if not script.exists():
            continue
        rc = run(script, argv)
        if rc:
            return undo(f"{script.relative_to(root)} exited {rc}")
    # Only files this run wrote count: last release's build left in dist/ proves nothing.
    made = {g: [f for f in root.glob(g) if f.is_file() and before.get(f) != f.stat().st_mtime_ns]
            for g in globs}
    empty = [g for g, fs in made.items() if not fs]
    if empty:
        return undo(f"this release made no file matching {', '.join(empty)}")
    log = root / LOG
    if log.exists():
        log.write_text(released_log(log.read_text(), tag))
        git("add", "--", LOG, check=True)
    elif meta:
        # A metarepo `jig update` hasn't moved to the log yet releases as it did.
        old = root / CHANGELOG
        text = old.read_text() if old.exists() else "# Changelog\n"
        heading = f"## {tag} — {date.today().isoformat()}"
        if re.search(r"^## Unreleased[ \t]*$", text, re.M):
            text = re.sub(r"^## Unreleased[ \t]*$", f"## Unreleased\n\n{heading}", text, count=1,
                          flags=re.M)
        else:
            text = text.rstrip("\n") + f"\n\n## Unreleased\n\n{heading}\n"
        old.write_text(text)
        git("add", "--", CHANGELOG, check=True)
    git("add", "-u", check=True)
    msg = f"release {tag}"
    if proposed:
        git("add", "--", str(proposed[0].relative_to(root)), check=True)
        msg += f"\n\nProposed the sync buffer's Open rows to {para['meta']} as {proposed[1]}."
    if left:
        msg += (f"\n\nReleased with {len(left)} staged file{'s' if len(left) > 1 else ''} left "
                f"unresolved: {', '.join(f.name for f in left)}")
    tree = git("write-tree", check=True)
    commit = git("rev-parse", "HEAD")
    if tree != git("rev-parse", "HEAD^{tree}") or left:
        # Written with plumbing, so no hook sees it: in a metarepo this is the one commit on
        # trunk that isn't a merge, and the tag beside it is what marks it.
        commit = git("commit-tree", tree, "-p", "HEAD", "-m", msg, check=True)
        git("update-ref", f"refs/heads/{trunk}", commit, check=True)
        git("reset", "-q")
    git("tag", "-a", tag, "-m", tag, commit, check=True)
    print(f"released {tag} at {commit[:12]}.")
    if meta:
        # After the tag: a request that can't be written doesn't undo the release.
        for line in stage_pin_bumps(root, meta, last, tag):
            print(line)
    if proposed:
        print(f"proposed {', '.join(listed_rows(proposed[0].read_text()))} to {para['meta']} as "
              f"{proposed[1]} ({proposed[0].relative_to(root)}): write the change there; "
              f"`jig sync` closes the rows once {para['meta']} releases it.")
    # Overlapping globs match one file twice; publish.sh gets each file once, in glob order.
    built = list(dict.fromkeys(str(f.relative_to(root)) for fs in made.values() for f in sorted(fs)))
    for f in built:
        print(f"  {f}")
    publish = root / PUBLISH
    # The TODO line means the repo hasn't said what a release publishes yet: it never blocks.
    if not publish.exists() or any(l.startswith(PUBLISH_TODO)
                                   for l in publish.read_text().splitlines()):
        print("Push it: git push --follow-tags")
        return 0
    rc = run(publish, [version, *built])
    if rc:
        # The tag may already be pushed, so it stays: the release happened, the publish didn't.
        again = ([] if os.access(publish, os.X_OK) else ["bash"]) + [PUBLISH, version, *built]
        # The release may have run from a subfolder; the command works from anywhere.
        print(f"released {tag} at {commit[:12]}, but {PUBLISH} exited {rc}. Run it again:\n"
              f"  cd {shlex.quote(str(root))} && {shlex.join(again)}", file=sys.stderr)
        return 1
    return 0

# ------------------------------------------------------------------- pararepo

# A pararepo (code, firmware, hardware) cites a metarepo at a released tag. It reads a cache
# of the pinned docs, never a copy committed here, and writes the metarepo only by branch.
PARA = f"{DIR}/para.json"
CACHE = f"{DIR}/meta-cache"
HEADER_BEGIN = f"<!-- jig:meta — generated from {PARA} by `jig init --para`; edit that, not this -->"
HEADER_END = "<!-- jig:meta end -->"
# How a spec says what its contract change means for the metarepo: a proposal branch it waits
# for, a pointers branch it works ahead of (pointer rewrites only, no claim changes), a row of
# the buffer, or why none.
PROPOSAL = re.compile(r"^\s*-?\s*meta: (?:none — \S.*|buffered (?P<row>\S+)|"
                      r"(?P<meta>\S+) proposal (?P<branch>\S+)|"
                      r"(?P<pmeta>\S+) pointers (?P<pbranch>\S+))\s*$", re.M)
# The sync buffer: each metarepo claim this repo has moved away from, held until a release
# proposes them all at once. Rows are Open until the release that settles them is pinned.
BUFFER = f"{DIR}/ledgers/buffer.md"
BUFFER_STATES = ("Open", "Closed")
# A row the metarepo answered by some change other than the proposal that carried it: closed
# by `jig sync --answered` on the owner's word, naming the release, which the pin must hold, and why.
ANSWERED = re.compile(r"^Closed \(answered in (?P<tag>\S+): (?P<reason>[^|]*\S)\)$")
STATE_FORMS = "Open, Closed, or Closed (answered in <release>: <reason>)"
# A proposal the owner says the metarepo will never release: no longer waited on or reported,
# and the rows it carried are owed again.
WITHDRAWN = re.compile(r"^\s*-?\s*meta: (?P<meta>\S+) withdrawn (?P<branch>\S+) — \S.*$", re.M)
# A buffer proposal's spec lists the rows it carries under this heading, one `- <id>` each.
BUFFER_ROWS = re.compile(r"^## Buffer rows\s*\n((?:- \S+.*\n?)*)", re.M)


def buffer_rows(text: str) -> list[list[str]]:
    """The ledger's rows as cells, header and separator left out."""
    rows = [table_cells(l) for l in text.splitlines() if l.lstrip().startswith("|")]
    return [r for r in rows if r and r[0] != "Id" and not re.fullmatch(r":?-+:?", r[0])]


def row_state(cell: str) -> str | None:
    """Open or Closed, an answered close counting as Closed; None for anything else."""
    return cell if cell in BUFFER_STATES else "Closed" if ANSWERED.match(cell) else None


def listed_rows(spec: str) -> list[str]:
    m = BUFFER_ROWS.search(spec)
    return [l[2:].split()[0] for l in m.group(1).splitlines()] if m else []


def proposed_copy(spec: str) -> dict[str, list[str]]:
    """The rows a buffer proposal's spec carried, as they read when proposed. A row edited
    since went to the metarepo in its old form, so only an unchanged one counts as proposed.
    A withdrawn proposal carries nothing: its rows are owed again."""
    if WITHDRAWN.search(spec):
        return {}
    listed = set(listed_rows(spec))
    return {r[0]: r for r in buffer_rows(spec) if r[0] in listed}


def proposed_rows(texts: list[str]) -> set[tuple[str, ...]]:
    return {tuple(r) for s in texts for r in proposed_copy(s).values()}


def load_para(trunk: str) -> dict | None:
    return json_or_none(git("show", f"{trunk}:{PARA}"))


def json_or_none(raw: str) -> dict | None:
    try:
        return json.loads(raw) if raw else None
    except ValueError:
        return None


def para_header(para: dict) -> str:
    paths = ", ".join(f"`{p}`" for p in para.get("contract_paths", [])) or "none yet"
    return "\n".join([
        HEADER_BEGIN,
        f"- Shared definitions: metarepo `{para['meta']}` at `{para['pin']}`, read from "
        f"`{CACHE}/` (`jig sync` on trunk refreshes it and reports newer releases).",
        f"- Contract paths: {paths}. A change there needs a metarepo proposal "
        "(`jig propose`) or `meta: none — <reason>` in its spec.",
        "- The metarepo is written only by branch, via `jig propose`; nothing of it is copied here.",
        HEADER_END,
    ])


# A metarepo's rules every task meets, always loaded as a pararepo's header is. jig's words,
# so they follow jig's rules as they change and are no repo's procedure.
META_HEADER_BEGIN = (f"<!-- jig:meta — generated from {META} by `jig init --meta`; rerun that in "
                     "a job's worktree, not by hand -->")


def meta_header(meta: dict, trunk: str) -> str:
    """The block names entry_files rather than listing them, so editing the list leaves it current."""
    prefix = meta.get("decision_prefix") or META_DEFAULTS["decision_prefix"]
    return "\n".join([
        META_HEADER_BEGIN,
        f"- This is a metarepo (`{RULES_DIR}/rules-metarepo.md`, Metarepo): docs only, no code (M1); "
        "a claim another repo owns is pointed to (`<repo>/<path> § <section>`), never copied.",
        f"- `{trunk}` takes only reviewed merges, so work on a branch (M4). A commit subject starts "
        f"with the ids it touches (`{prefix}012: …`, `GLOSSARY: …`) (M6).",
        f"- A change to an entry file (`{META}`'s `entry_files`) adds a change line under "
        f"`## Unreleased` in `{LOG}` (M3).",
        "- Only `jig release` tags.",
        HEADER_END,
    ])


def with_header(text: str, header: str) -> str:
    # Any begin line, not just today's: the first one said "by `jig para-init`", and a header
    # still carrying it must be replaced, not left beside a second block.
    block = re.compile(rf"^<!-- jig:meta — .*?^{re.escape(HEADER_END)}\n?", re.M | re.S)
    if block.search(text):
        return block.sub(header + "\n", text, count=1)
    first, _, rest = text.partition("\n")
    return f"{first}\n\n{header}\n{rest}" if first.startswith("#") else f"{header}\n\n{text}"


def repos_file() -> Path:
    """The owner's list of where their repos live. A path is one machine's layout, so it lives
    here, never in a repo; no hook or gate reads it."""
    if os.environ.get("JIG_CONFIG"):
        return Path(os.environ["JIG_CONFIG"]).expanduser()
    base = os.environ.get("XDG_CONFIG_HOME") or Path.home() / ".config"
    return Path(base) / "jig" / "repos.json"


REPO_KINDS = ("repo", "meta", "para")


def load_repos() -> dict:
    """{name: {"path": ..., "kind": repo|meta|para, ...}}. An entry that is a bare path is the
    first format, read as a plain repo. Every other key an entry holds (its `aliases`, its
    `designer` folder) is kept, so a save never drops what another command wrote."""
    f = repos_file()
    try:
        raw = json.loads(f.read_text()) if f.exists() else {}
    except ValueError:
        die(f"{f} is not valid JSON", 2)
    if not isinstance(raw, dict):
        die(f"{f} should map names to repos", 2)
    out = {}
    for n, e in raw.items():
        e = dict(e) if isinstance(e, dict) else {"path": e}
        # The designer's folder was written under its old name; read it as `designer`, which
        # the next save writes, so a folder set before the rename keeps working.
        if "rigger" in e:
            e.setdefault("designer", e.pop("rigger"))
        if isinstance(e.get("path"), str):
            out[n] = {**e, "kind": e.get("kind", "repo")}
    return out


def repo_names(e: dict) -> set[str]:
    """What an entry answers to besides its listed name: the aliases the owner gave it. A
    hand-written string is one alias, not its letters."""
    al = e.get("aliases", [])
    return {a for a in ([al] if isinstance(al, str) else al) if isinstance(a, str) and a}


def name_key(n: str) -> str:
    """A name as a person reads it: `NorthStar`, `north-star` and `north_star` are one."""
    return re.sub(r"[\W_]", "", n.casefold())


def near_miss(name: str) -> str | None:
    """The listed name or alias a typed name only matches once punctuation is dropped: never
    taken for it, since two near-identical names have sent work to the wrong repo, but named
    in the refusal."""
    if not name or repo_matches(name):
        return None
    for n, e in sorted(load_repos().items()):
        for label in sorted({n} | repo_names(e)):
            if name_key(label) == name_key(name):
                return label
    return None


def unknown_repo(name: str) -> str:
    many = repo_matches(name) if name else []
    if len(many) > 1:
        repos = load_repos()
        # A checkout's own name is committed in it: renaming the entry can't change that.
        own = [n for n in many if name_in(name, repo_identity(Path(repos[n]["path"])))]
        configs = ", ".join(f"{repos[n]['path']}/{CONFIG}" for n in own)
        fix = (f"change `name` in one checkout's config ({configs}), or remove one entry from "
               f"{repos_file()}" if own else
               "rename one entry (`jig repos rename`) or drop its alias (`jig repos alias --remove`)")
        return f"{name!r} names more than one repo ({', '.join(many)}): {fix}"
    near = near_miss(name)
    return (f"{name!r} isn't in {repos_file()}" + (f": did you mean {near}? A name that matches "
            "only without its punctuation is refused" if near else " (`jig repos` lists them)"))


def save_repos(repos: dict) -> None:
    repos_file().parent.mkdir(parents=True, exist_ok=True)
    repos_file().write_text(json.dumps(repos, indent=2) + "\n")


def repo_identity(path: Path) -> set[str]:
    """The names a checkout answers to by itself: its board's name, its metarepo name."""
    names = set()
    for f, key in ((path / CONFIG, "name"), (path / LEGACY_BOARD, "name"), (path / META, "name")):
        try:
            names.add(json.loads(f.read_text()).get(key, "")) if f.exists() else None
        except ValueError:
            pass
    return names - {""}


def repo_path(name: str) -> Path | None:
    """Where a repo lives, by the name you gave it or the name it gives itself, so an alias
    never breaks a lookup that uses the real one (a pararepo naming its metarepo)."""
    found = repo_matches(name)
    return Path(load_repos()[found[0]]["path"]) if len(found) == 1 else None


def repo_matches(name: str) -> list[str]:
    """The entries a typed name finds: by its listed name, an alias, or the name the checkout
    gives itself. One rule for every place a repo is typed (a staged target, an inbox
    message's `to`, a designer). A human types it, so case is ignored throughout: `App` finds
    `app`, and a `Frontend` one entry calls itself and a `frontend` another lists are one name.
    More than one entry is no answer: the lookup never picks by order or by case."""
    repos = load_repos()
    return [n for n, e in repos.items()
            if name_in(name, {n} | repo_names(e) | repo_identity(Path(e["path"])))]


def labels(repos: dict) -> list[tuple[str, str]]:
    """(label, entry name) for every name and alias in the list."""
    return sorted({(lb, n) for n, e in repos.items() for lb in {n} | repo_names(e)})


def near_duplicates(repos: dict) -> list[tuple[str, str]]:
    """Pairs of names a person reads as one (`NorthStar`, `north-star`), aliases included,
    from two entries: a file staged for one can land in the other."""
    ls = labels(repos)
    return [(a, b) for i, (a, x) in enumerate(ls) for b, y in ls[i + 1:]
            if x != y and name_key(a) == name_key(b)]


def warn_near_duplicates(repos: dict, only: str | None = None) -> None:
    owner = dict(labels(repos))
    for a, b in near_duplicates(repos):
        if only and only not in (a, b, owner[a], owner[b]):
            continue
        print(f"warning: {a} and {b} differ only in case or punctuation, and are two repos:\n"
              f"  {a:<24} {repos[owner[a]]['path']}\n  {b:<24} {repos[owner[b]]['path']}\n"
              f"  rename one (`jig repos rename {owner[b]} <new>`) if both are meant")


def cmd_repos(root: Path, args) -> int:
    repos = load_repos()
    here = Path(git("rev-parse", "--path-format=absolute", "--git-common-dir") or ".").parent \
        if git("rev-parse", "--git-dir") else Path.cwd()
    here = here.resolve()
    mine = [n for n, e in repos.items() if Path(e["path"]).resolve() == here]
    if args.action == "add":
        kind = args.kind if args.kind in REPO_KINDS else None
        kind_form = kind is not None
        if kind is None and args.kind and args.path:      # the first form: add <name> <path>
            name, path, kind = args.kind, Path(args.path).expanduser().resolve(), "repo"
        elif kind:
            path = Path(args.path).expanduser().resolve() if args.path else here
            name = args.name or (sorted(repo_identity(path)) or [path.name])[0]
        else:
            die("usage: jig repos add repo|meta|para [--name N] [--path P]", 2)
        kept: dict = {}
        for old in [n for n, e in repos.items() if Path(e["path"]).resolve() == path and n != name]:
            kept.update(repos.pop(old))             # one entry per checkout; re-adding replaces
        # add <name> <path> re-points a name on purpose; add repo|meta|para must not take one
        if kind_form and name in repos and Path(repos[name]["path"]).resolve() != path:
            die(f"{name} already names {repos[name]['path']}: pick another --name, or rename that one", 2)
        refuse_taken(repos, name, name)
        refuse_own_names(repos, path, name)
        # Its aliases and designer folder stay with the checkout: a name re-pointed from another
        # checkout brings none of that one's.
        own = repos.get(name) if name in repos and Path(repos[name]["path"]).resolve() == path else {}
        repos[name] = {**kept, **(own or {}), "path": str(path), "kind": kind}
        save_repos(repos)
        print(f"{name} ({kind}) → {path}")
        warn_near_duplicates(repos, name)
        old = old_board(path) if kind in ("meta", "para") else None
        if old:
            print(f"  {old} is an older jig's board: run `jig update` there, commit, then "
                  f"`jig init --{kind}{' <metarepo name>' if kind == 'para' else ''}`")
        elif kind == "meta" and not (path / META).exists():
            print(f"  not a metarepo yet: run `jig init --meta` there")
        elif kind == "para" and not (path / PARA).exists():
            print(f"  not a pararepo yet: run `jig init --para <metarepo name>` there")
        return 0
    if args.action == "rename":
        # rename <new> renames this folder's entry; rename <old> <new> any entry
        if not args.kind:
            die("usage: jig repos rename <new>  (this folder), or rename <old> <new>", 2)
        old, new = (args.kind, args.path) if args.path else (mine[0] if mine else None, args.kind)
        if not new or not old or old not in repos:
            die("this folder isn't registered: jig repos add repo|meta|para" if not old
                else f"no repo named {old}", 2)
        if new in repos and new != old:
            die(f"{new} already names {repos[new]['path']}", 2)
        refuse_taken(repos, new, old)
        refuse_own_names(repos, Path(repos[old]["path"]), old)
        repos[new] = repos.pop(old)
        save_repos(repos)
        print(f"{old} is now {new} → {repos[new]['path']}")
        warn_near_duplicates(repos, new)
        return 0
    if args.action == "alias":
        return repos_alias(repos, args)
    if args.action == "which":
        return repos_which(args.kind)
    for name, e in sorted(repos.items()):
        missing = "" if Path(e["path"]).is_dir() else "   (missing)"
        print(f"  {name:<24} {e['kind']:<5} {e['path']}{missing}{'   ← here' if name in mine else ''}")
        if repo_names(e):
            print(f"  {'':<24} aliases: {', '.join(sorted(repo_names(e)))}")
        if e.get("designer"):
            print(f"  {'':<24} designer: {e['designer']}")
    if not repos:
        print(f"no repos in {repos_file()}: jig repos add repo|meta|para")
    warn_near_duplicates(repos)
    # The same lookup staging and forwarding use, so an alias for the jig repo counts too.
    if repo_path("jig") is None:
        print(f"tool reports wait in {feedback_dir()} while the jig repo isn't registered")
    return 0


def refuse_taken(repos: dict, label: str, mine: str) -> None:
    """One name names one repo: a name or alias any entry but `mine` answers to, case ignored,
    is refused, or a lookup of it would find two."""
    for lb, n in labels(repos):
        if n != mine and lb.casefold() == label.casefold():
            die(f"{label} already names {n}" + (f" (its alias {lb})" if lb != n else "")
                + f", {repos[n]['path']}", 2)
    # A checkout answers to its own board or metarepo name too, so a label equal to one would
    # route there as well.
    for n, e in repos.items():
        if n != mine and name_in(label, repo_identity(Path(e["path"]))):
            die(f"{label} is the name {n}'s checkout gives itself, {e['path']}", 2)


def refuse_own_names(repos: dict, path: Path, mine: str) -> None:
    """The names a checkout gives itself are committed in it, so no listed name, alias or
    other checkout's own name may equal one: a lookup would then find two repos."""
    for own in sorted(repo_identity(path)):
        for n, e in repos.items():
            if n != mine and name_in(own, {n} | repo_names(e) | repo_identity(Path(e["path"]))):
                die(f"{path} calls itself {own}, which already names {n}, {e['path']}: change "
                    f"`name` in one checkout's {CONFIG}, or list only one of them", 2)


def repos_which(name: str | None) -> int:
    """The one lookup a skill runs for a typed repo name: the path, or the refusal."""
    if not name:
        die("usage: jig repos which <name>", 2)
    p = repo_path(name)
    if p is None:
        print(f"refused: {unknown_repo(name)}")
        return 1
    print(p)
    return 0


def repos_alias(repos: dict, args) -> int:
    """`repos alias <repo> <alias>`: a shorthand beside the listed name, which a rename would
    replace. One alias names one repo, so one equal to any other name or alias is refused."""
    target, alias = args.kind, args.path
    if not target or not alias:
        die("usage: jig repos alias <repo> <alias> [--remove]", 2)
    name = next((n for n, e in repos.items() if name_in(target, {n} | repo_names(e))), None)
    if name is None:
        die(f"no repo named {unknown_repo(target)}", 2)
    have = sorted(repo_names(repos[name]))
    if args.remove:
        if alias not in have:
            die(f"{name} has no alias {alias}" + (f" (it has {', '.join(have)})" if have else ""), 2)
        have.remove(alias)
        print(f"{name}: alias {alias} removed")
    else:
        refuse_taken(repos, alias, name)
        refuse_own_names(repos, Path(repos[name]["path"]), name)
        if alias.casefold() in {lb.casefold() for lb in {name} | repo_names(repos[name])}:
            die(f"{alias} already names {name}", 2)
        have.append(alias)
        print(f"{name}: alias {alias}")
    if have:
        repos[name]["aliases"] = sorted(have)
    else:
        repos[name].pop("aliases", None)
    save_repos(repos)
    warn_near_duplicates(repos, name)
    return 0


DESIGNER_PARTS = ("record", "drafts", "staged")


def read_json(f: Path) -> dict:
    try:
        d = json.loads(f.read_text()) if f.is_file() else {}
    except ValueError:
        return {}
    return d if isinstance(d, dict) else {}


def cmd_designer(args) -> int:
    """Make the calling session the designer for one repo: its folder outside every repo, the
    pointer to it on the repo's entry in the owner's list, and the facts the list and folders
    give. How a designer works is its skill's; this prints only what config and files say."""
    repos = load_repos()
    found = repo_matches(args.repo)
    if len(found) != 1:
        die(f"refused: {unknown_repo(args.repo)}", 2)
    name = found[0]
    entry = repos[name]
    warn_near_duplicates(repos, name)
    if entry.get("kind") == "meta":
        die(f"refused: {name} is a metarepo, which has no designer: its pararepos' designers stage to it", 2)
    if args.folder:
        folder = Path(args.folder).expanduser().resolve()
    elif entry.get("designer"):
        folder = Path(entry["designer"])
    else:
        # Beside the others, so the designers' parent folder is named once, by the first --folder.
        others = sorted(Path(e["designer"]).parent for n, e in repos.items()
                        if n != name and isinstance(e.get("designer"), str) and e["designer"])
        if not others:
            die(f"refused: no designer folder is set for any repo yet: pass --folder <path>, outside "
                "every repo", 2)
        folder = others[0] / name
    here = Path(entry["path"]).resolve()
    for n, e in sorted(repos.items()):
        repo = Path(e["path"]).resolve()
        if folder == repo or repo in folder.parents:
            die(f"refused: {folder} is inside {n}'s checkout; a designer's folder lives outside every repo", 2)
    made = []
    for part in DESIGNER_PARTS:
        if not (folder / part).is_dir():
            (folder / part).mkdir(parents=True, exist_ok=True)
            made.append(f"{part}/")
    if not (folder / "handoff.md").exists():
        (folder / "handoff.md").write_text(f"# Handoff: {name}'s designer\n")
        made.append("handoff.md")
    entry["designer"] = str(folder)
    save_repos(repos)
    print(f"designer for {name}: {folder}")
    print(f"  holds: {', '.join(sorted(p.name + ('/' if p.is_dir() else '') for p in folder.iterdir()))}")
    print(f"  created: {', '.join(made) if made else 'nothing (all there already)'}")
    # Which repos it may read: its own; with a metarepo, that metarepo and its other pararepos.
    meta_name = read_json(here / PARA).get("meta") if entry.get("kind") == "para" else None
    meta = repo_matches(meta_name) if meta_name else []
    meta = meta[0] if len(meta) == 1 else None
    paras = set(read_json(Path(repos[meta]["path"]) / META).get("pararepos", [])) if meta else set()
    print("repos:")
    for n, e in sorted(repos.items()):
        if n == name:
            mark = "yours"
        elif n == meta:
            mark = "reads: its metarepo"
        elif meta and (n in paras or name_in(meta_name, {read_json(Path(e["path"]) / PARA).get("meta", "")})):
            mark = f"reads: a pararepo of {meta}"
        else:
            mark = "on request"
        print(f"  {n:<24} {mark}")
    if meta_name and not meta:
        print(f"  ({name}'s metarepo, {meta_name}, isn't a single entry in the list: {unknown_repo(meta_name)})")
    staged = staged_files(here)
    print(f"staged in {name}: " + ("nothing" if not staged else ""))
    for f in staged:
        print(f"  {f.name:<32} source: {read_staged(f)[0].get('source') or '(none)'}")
    print(f"{name} has {STAGING}/: {'yes' if (here / STAGING).is_dir() else 'no (`jig update` there adds it)'}; "
          f"{INBOX}/: {'yes' if (here / INBOX).is_dir() else 'no (`jig update` there adds it)'}")
    return 0


def meta_checkout(root: Path, para: dict) -> Path | None:
    """The metarepo's checkout, found by name in repos.json, or None when it isn't listed or
    can't be reached (offline, moved)."""
    p = repo_path(para.get("meta", ""))
    if p is None:
        return None
    # The clone's own top level: a plain folder inside this repo would answer with ours.
    top = git("rev-parse", "--show-toplevel", cwd=str(p)) if p.is_dir() else ""
    return p if top and Path(top).resolve() == p.resolve() else None


def released_tags(cwd: str) -> list[str]:
    """Tags the metarepo's own gates would accept: matching its pattern, with the heading
    the release writes."""
    meta = {**META_DEFAULTS, **json.loads(git("show", f"HEAD:{META}", cwd=cwd) or "{}")}
    pat = re.compile(meta["tag_pattern"])
    out = []
    for t in git("tag", "--list", cwd=cwd).splitlines():
        if pat.match(t) and made_by_release(t, cwd):
            out.append(t)
    return sorted(out, key=version_key)


def para_problems(root: Path, para: dict, trunk: str) -> tuple[list[str], Path | None]:
    """What makes a pararepo unreleasable: its default release, the checks jig already has.
    Warnings (a newer metarepo release, a cited path outside contract_paths) print as `jig
    sync` prints them and refuse nothing. Returns the refusals and the metarepo's checkout."""
    out: list[str] = []
    name, pin = para["meta"], para.get("pin") or ""
    # Trunk's files, not the hooks' view of a commit: a commit made with --no-verify is checked too.
    if para_header(para) not in git("show", f"{trunk}:AGENTS.md"):
        out.append(f"P1 the AGENTS.md header is generated from {PARA}: edit that, then "
                   "`jig init --para` regenerates it")
    tracked = git("ls-files", "--", f"{CACHE}/").splitlines()
    if tracked:
        out.append(f"P3 {', '.join(tracked)} is the metarepo's: pararepos cite it at a tag, never copy it")
    rows = buffer_rows(git("show", f"{trunk}:{BUFFER}"))
    for r in rows:
        if not row_state(r[-1]):
            out.append(f"P2 {BUFFER} row {r[0]} is {r[-1] or 'empty'}: a row is {STATE_FORMS}")
    for i in sorted({r[0] for r in rows if [x[0] for x in rows].count(r[0]) > 1}):
        out.append(f"P2 {BUFFER} has more than one row {i}: each row has an id of its own")
    loc = meta_checkout(root, para)
    if loc is None:
        return out + [f"can't reach {name} to check the pin against: run `jig repos add meta` in its checkout"], None
    # fill_cache below rewrites the cache: a tracked one would leave the tree dirty after a refusal.
    if tracked:
        return out, loc
    git("fetch", "-q", "--tags", cwd=str(loc))
    tags = released_tags(str(loc))
    # The cache can't vouch for the pin: fill_cache takes any commit-ish, `main` included.
    if pin not in tags:
        return out + [f"the pin {pin or '(none)'} in {PARA} is not a release of {name} "
                      f"({', '.join(tags) or 'none yet'}): a pararepo pins a release, never a branch "
                      "or a hand-made tag"], loc
    fill_cache(root, loc, pin)
    # As `jig sync`: until defer_until, what moved upstream is not reported.
    if date.today().isoformat() >= (para.get("defer_until") or ""):
        uncovered_paths(root, loc, para)
        for line in [*yanked_pin(loc, pin, name), *stale_pointers(root), *meta_citations(root, para, decision_ids(loc, pin), loc)]:
            print(line)
        if version_key(tags[-1]) > version_key(pin):
            print("\n".join(newer_release(root, loc, name, pin, tags[-1])))
    return out, loc


def fill_cache(root: Path, loc: Path, pin: str) -> None:
    if not git("rev-parse", "-q", "--verify", f"{pin}^{{commit}}", cwd=str(loc)):
        die(f"the metarepo has no tag {pin}: check \"pin\" in {PARA}", 2)
    cache = root / CACHE
    if cache.exists():
        shutil.rmtree(cache)
    cache.mkdir(parents=True)
    for f in dict.fromkeys([*entry_paths(pin, str(loc)), CHANGELOG]):
        # A derived, gitignored copy for reading: a byte git() couldn't decode is U+FFFD here,
        # and the metarepo keeps the original.
        body = git("show", f"{pin}:{f}", cwd=str(loc))
        if body:
            (cache / f).parent.mkdir(parents=True, exist_ok=True)
            (cache / f).write_text(body + "\n")
    (cache / "PIN").write_text(f"{pin}\ncached {date.today().isoformat()}\n")


def ignore_line(root: Path, line: str) -> None:
    ignore = root / ".gitignore"
    text = ignore.read_text() if ignore.exists() else ""
    if line not in text.splitlines():
        ignore.write_text(text + ("" if not text or text.endswith("\n") else "\n") + line + "\n")


def job_of_change(board: "Board", branch: str) -> dict | None:
    """The open job a change belongs to. On its branch, that job. A merge that commits on trunk
    (`jig merge`) brings the job in as MERGE_HEAD; the gate's scratch checkout is the job's
    commit, detached, with trunk merged into it. Either way the job is the one whose branch
    holds the side of the merge trunk doesn't already have; trunk's board still lists it. It
    must be one job: the branch tip itself, else the one branch whose own line (first parents)
    holds it. A job stacked on another holds its commits too, but off its own line; anything
    still ambiguous, or an octopus merge, belongs to no job, so no spec but the change's answers."""
    if branch and branch != board.trunk:
        return board.job_for_branch(branch)[1]
    merging = merging_commits()
    if len(merging) > 1:
        return None
    ours = [] if branch else [git("rev-parse", "-q", "--verify", "HEAD")]
    tips = {name: git("rev-parse", "-q", "--verify", f"refs/heads/{board.branch(name)}")
            for name in board.jobs}
    for c in filter(None, [*merging, *ours]):
        if is_ancestor(c, board.trunk):
            continue
        exact = [n for n, t in tips.items() if t == c]
        own = exact or [n for n, t in tips.items() if t and c in
                        git("rev-list", "--first-parent", t, f"^{board.trunk}", "--").split()]
        return board.jobs[own[0]] if len(own) == 1 else None
    return None


def is_ancestor(a: str, b: str, cwd: Path | None = None) -> bool:
    return subprocess.run(["git", "merge-base", "--is-ancestor", a, b],
                          capture_output=True, cwd=str(cwd) if cwd else None).returncode == 0


def para_rules(root: Path, board: "Board", para: dict, staged: bool) -> list[str]:
    """P1–P3: what a pararepo may commit."""
    out: list[str] = []
    trunk = board.trunk
    paths = changed_paths(trunk, staged)
    # Deletes and both sides of a rename: P1, P2's contract test and P4 guard paths.
    diffed = changed_paths(trunk, staged, removed=True)
    # P1 the AGENTS.md header says what para.json says
    if "AGENTS.md" in diffed or PARA in diffed:
        try:
            now = json.loads(in_index(PARA, staged) or "null") or para
        except ValueError:
            return [f"P1 {PARA} is not valid JSON"]
        agents = in_index("AGENTS.md", staged)
        if para_header(now) not in agents:
            out.append(f"P1 the AGENTS.md header is generated from {PARA}: edit that, then "
                       "`jig init --para` regenerates it")
    # P2 a contract change carries its metarepo proposal, its buffer row, or says why it needs none
    touched = [p for p in diffed if matches(p, para.get("contract_paths", []))]
    rows = buffer_rows(in_index(BUFFER, staged))
    if BUFFER in paths:
        for r in rows:
            if not row_state(r[-1]):
                out.append(f"P2 {BUFFER} row {r[0]} is {r[-1] or 'empty'}: a row is {STATE_FORMS}")
        # Parallel jobs each appending "the next id" merge cleanly into two rows of one id.
        for i in sorted({r[0] for r in rows if [x[0] for x in rows].count(r[0]) > 1}):
            out.append(f"P2 {BUFFER} has more than one row {i}: each row has an id of its own")
    # An Open row is drift still owed to the metarepo, and it never disappears. It closes only
    # through jig, its other cells as they were, in a commit that changes no contract path: as
    # `jig sync` closes it, once the pin holds a proposal that carried it as it stands; or as
    # `jig sync --answered` closes it, naming a release the pin holds and why. A deleted ledger
    # isn't in `paths`, so the old rows are read whatever changed.
    now = {r[0]: r for r in rows}
    was = [r for r in buffer_rows(at_rev(base(trunk), BUFFER)) if r[-1] == "Open"]
    closing = [(r, now[r[0]]) for r in was if r[0] in now and row_state(now[r[0]][-1]) == "Closed"]
    for r in was:
        if r[0] not in now:
            out.append(f"P2 {BUFFER} row {r[0]} is Open and is gone: an Open row stays until "
                       "`jig sync` closes it")
    if closing:
        try:
            pin = (json.loads(in_index(PARA, staged) or "null") or para).get("pin", "")
        except ValueError:
            pin = para.get("pin", "")
        specs_then = [at_rev(base(trunk), s) for s in git("ls-tree", "-r", "--name-only", base(trunk),
                                                         "--", f"{DIR}/specs/").splitlines()]
        how = ("`jig sync` closes a row once the pin holds the proposal that carried it as it "
               "stands; `jig sync --answered <id> --in <release> --reason <text>` closes one a "
               "release the pin holds answered some other way")
        loc = None
    for r, n in closing:
        answered = ANSWERED.match(n[-1])
        if touched or n[:-1] != r[:-1]:
            out.append(f"P2 {BUFFER} row {r[0]} closed by hand: {how}")
        elif answered:
            # A tag that isn't a version sorts below every pin, so it must be a real release: the
            # metarepo's own list when its checkout is here, else at least a release's shape.
            tag = answered.group("tag")
            loc = loc or meta_checkout(root, para)
            real = tag in released_tags(str(loc)) if loc else bool(re.match(META_DEFAULTS["tag_pattern"], tag))
            if not real:
                out.append(f"P2 {BUFFER} row {r[0]} is answered in {tag}, which is not a release of "
                           f"{para.get('meta')}: name the release that answered it")
            elif version_key(tag) > version_key(pin):
                out.append(f"P2 {BUFFER} row {r[0]} is answered in {tag}, which "
                           f"the pin {pin} doesn't hold: take that release first")
        else:
            # Only the metarepo knows whether a release holds the branch; sync fetched it first.
            branches = [m.group("branch") for t in specs_then if tuple(r) in proposed_rows([t])
                        for m in PROPOSAL.finditer(t) if m.group("branch") and m.group("meta") == para.get("meta")]
            loc = loc or meta_checkout(root, para)
            if not branches:
                out.append(f"P2 {BUFFER} row {r[0]} closed by hand: no proposal carried it as it stands. {how}")
            elif loc is None:
                out.append(f"P2 {BUFFER} row {r[0]} is closed, and {para.get('meta')} can't be reached "
                           "to check that the pin holds its proposal: `jig repos add meta` in its checkout")
            elif not any(proposal_in(loc, b, pin) for b in branches):
                out.append(f"P2 {BUFFER} row {r[0]} closed by hand: {para.get('meta')} {pin} doesn't "
                           f"hold {', '.join(branches)}. {how}")
    # A pointer this change leaves dangling: the metarepo now points at nothing, so it is owed
    # what a contract change is.
    # The cache lives in the primary checkout: it is ignored, so a job's worktree has none.
    # Worse than at the base counts: a file lost is still news when its heading was already missing.
    moves = moves_in(in_index(LOG, staged))
    broken = [f"{f} points to {moved_gap(gap, path, section, moves)}" for f, path, section, code in pointers(root, main_root())
              if any(d == path or d.startswith(f"{path}/") for d in diffed)
              for level, gap in [pointer_gap(path, section, code, body_now(path, staged))]
              if level > pointer_gap(path, section, code, body_at(base(trunk), path))[0]]
    if touched or broken:
        specs = {p for p in paths if p.startswith(f"{DIR}/specs/") and p.endswith(".md")}
        branch = git("branch", "--show-current")
        if branch and branch != trunk:
            specs |= {p for p in git("diff", "--name-only", f"{trunk}...HEAD", "--",
                                     f"{DIR}/specs/").splitlines() if p.endswith(".md")}
        # A merge commit closes the job's spec (Handoff, gate, merge): its answer is read from
        # the job's side, where the spec still is.
        merging = git("rev-parse", "-q", "--verify", "MERGE_HEAD")
        if merging:
            specs |= {p for p in git("diff", "--name-only", f"{trunk}...{merging}", "--",
                                     f"{DIR}/specs/").splitlines() if p.endswith(".md")}
        ids = {r[0] for r in rows if r[-1] == "Open"}
        texts = [in_index(s, staged) or (at_rev(merging, s) if merging else "") for s in specs]
        # The job's own spec, from trunk's board and trunk's copy: whoever controls trunk put
        # the answer there, so a branch can't forge it. A spec that is one line is its own text.
        job = job_of_change(board, branch)
        if job and job.get("spec"):
            texts.append(at_rev(trunk, job["spec"]) or job["spec"])
        answered = any((not m.group("row") or m.group("row") in ids)
                       for t in texts for m in PROPOSAL.finditer(t))
        # A row added or changed in this commit answers it, the way R7's ledger row does.
        diff = git("diff", "-U0", base(trunk), *(["--cached"] if staged else []), "--", BUFFER) \
            if BUFFER in paths else ""
        rowed = any(r[-1] == "Open" for l in diff.splitlines() if l.startswith("+|")
                    for r in buffer_rows(l[1:]))
        answer = (f"add or edit its row in {BUFFER} in this commit (the first row creates the "
                  "file from jig's ledger template), or a spec in this change, or the job's own "
                  "spec on trunk, needs `meta: buffered <row id>`, `meta: <name> proposal "
                  "<branch>` (`jig propose`), `meta: <name> pointers <branch>` (`jig propose "
                  "--pointers`) or `meta: none — <reason>`")
        if not answered and not rowed and touched:
            out.append(f"P2 {', '.join(touched)} is a contract path: {answer}")
        if not answered and not rowed and broken:
            out.append(f"P2 this change leaves the metarepo pointing at nothing ({'; '.join(broken)}): {answer}")
    # P4 no contract change while a file for the metarepo waits unresolved
    waiting = [f.name for f in staged_files(main_root()) if name_in(read_staged(f)[0].get("target"), {para.get("meta", "")})]
    if touched and waiting:
        out.append(f"P4 {', '.join(touched)} is a contract path, and {', '.join(waiting)} for "
                   f"{para.get('meta')} is still staged: resolve it first")
    # P3 nothing of the metarepo is committed here: not the cache, not a checkout of it.
    # A nested checkout can only be staged as a gitlink, and it says whose it is itself.
    for p in paths:
        nested = root / p / META
        is_meta = (git("ls-files", "-s", "--", p).startswith("160000") and nested.exists()
                   and f'"{para.get("meta")}"' in nested.read_text(errors="replace"))
        if p.startswith(f"{CACHE}/") or is_meta:
            out.append(f"P3 {p} is the metarepo's: pararepos cite it at a tag, never copy it")
    return out


def cmd_para_init(root: Path, args) -> int:
    """`jig init --para <metarepo>`. Run again, it regenerates the header and cache from
    para.json."""
    path = root / PARA
    again = path.exists()
    para = json.loads(path.read_text()) if again else {
        "meta": args.meta, "pin": getattr(args, "pin", None), "defer_until": None,
        "contract_paths": getattr(args, "contract", None) or []}
    para.pop("location", None)          # an older para.json: where it lives is repos.json's
    if not para.get("meta"):
        die("first run needs --para <metarepo name>", 2)
    if getattr(args, "location", None):
        cmd_repos(root, argparse.Namespace(action="add", kind="meta", name=para["meta"],
                                           path=args.location))
    agents = root / "AGENTS.md"
    loc = meta_checkout(root, para)
    # A first run needs the metarepo to check the pin against. A re-run's header comes from
    # para.json alone, so it is written first, and only the cache waits for the metarepo.
    if loc is None and not again:
        die(f"can't find {para['meta']}: run `jig repos add meta` in its checkout", 2)
    if not para.get("pin"):
        if loc is None:
            die(f"can't find {para['meta']} to pick a pin: run `jig repos add meta` in its checkout", 2)
        tags = released_tags(str(loc))
        if not tags:
            die(f"{para['meta']} has no release yet: run `jig release` there first", 2)
        para["pin"] = tags[-1]
    path.write_text(json.dumps(para, indent=2) + "\n")
    agents.write_text(with_header(agents.read_text() if agents.exists() else "# AGENTS.md\n",
                                  para_header(para)))
    ignore_line(root, f"{CACHE}/")
    if loc is not None and loc.resolve().is_relative_to(root.resolve()):
        ignore_line(root, f"{loc.resolve().relative_to(root.resolve()).as_posix()}/")
    pin = para["pin"]
    if loc is None:
        why = f"can't find {para['meta']} (`jig repos add meta` in its checkout)"
    elif not git("rev-parse", "-q", "--verify", f"{pin}^{{commit}}", cwd=str(loc)):
        why = f"{para['meta']} has no tag {pin} here (`git -C {loc} fetch --tags`, or check \"pin\")"
    else:
        why = ""
        fill_cache(root, loc, pin)
    if why:
        print(f"warning: {why}: {CACHE}/ was not refreshed.", file=sys.stderr)
    print(f"wrote {PARA}, the AGENTS.md header{'' if why else f', and {CACHE}/ at {pin}'}.")
    print(f"Commit {PARA}, AGENTS.md and .gitignore on {Board.trunk_name(root)}.")
    return 0


def decision_prefix_at(loc: Path, rev: str) -> str:
    """The metarepo's decision_prefix at REV."""
    try:
        meta = {**META_DEFAULTS, **json.loads(git("show", f"{rev}:{META}", cwd=str(loc)) or "{}")}
    except ValueError:
        meta = META_DEFAULTS
    return meta["decision_prefix"]


def decision_ids(loc: Path, rev: str) -> str:
    """A regex for the metarepo's decision ids at REV, from its decision_prefix."""
    return re.escape(decision_prefix_at(loc, rev)) + r"\d+"


def changed_decisions(root: Path, prefix: str, rng: str) -> set[str]:
    """Each decision id whose entry in the log RNG adds, removes or edits, and each one such an
    entry supersedes. The one place a branch's decisions are read: where they live may move,
    the question doesn't."""
    out = edited_decisions(root, prefix, rng)
    now = {e["id"]: e for e in log_entries(git("show", f"{rng.partition('..')[2].lstrip('.') or 'HEAD'}:{LOG}",
                                                   cwd=str(root)), prefix)}
    # What changes an accepted entry is a new one that supersedes and removes it: the old id is news too.
    return out | {s for i in out if i in now for s in (status_parts(now[i]["status"], prefix) or ("", "", "", []))[3]}


def edited_decisions(root: Path, prefix: str, rng: str) -> set[str]:
    """Each decision id whose entry in the log RNG adds, removes or edits."""
    left, _, right = rng.partition("...") if "..." in rng else rng.partition("..")
    if "..." in rng:
        left = git("merge-base", left, right or "HEAD", cwd=str(root)) or left
    def entries(rev: str) -> dict[str, dict]:
        return {e["id"]: e for e in log_entries(git("show", f"{rev}:{LOG}", cwd=str(root)), prefix)}
    was, now = entries(left), entries(right or "HEAD")
    return {i for i in {*was, *now} if (was.get(i) or {}).get("block") != (now.get(i) or {}).get("block")}


def changed_rows(root: Path, meta: dict, rng: str) -> dict[str, set[str]]:
    """Before the log: each decision id whose register row RNG adds, removes or edits, with the
    files holding that row, read from every changed page as the old M2 read them."""
    md = [f for f in git("-c", "core.quotePath=false", "diff", "--name-only", "--no-renames", rng,
                         cwd=str(root)).splitlines()
          if f.endswith(".md") and f != CHANGELOG and not f.startswith(f"{DIR}/")]
    if not md:
        return {}
    row = re.compile(rf"^[+-]\s*\|\s*({re.escape(meta['decision_prefix'])}\d+)\s*\|")
    out: dict[str, set[str]] = {}
    f = ""
    # Fixed prefixes, whatever diff.noprefix or diff.mnemonicPrefix say: the headers are parsed.
    for line in git("-c", "core.quotePath=false", "--literal-pathspecs", "diff", "--no-renames",
                    "--no-ext-diff", "--no-color", "--src-prefix=a/", "--dst-prefix=b/",
                    rng, "--", *md, cwd=str(root)).splitlines():
        if line.startswith(("--- a/", "+++ b/")):
            f = line[6:]
        elif line.startswith(("--- ", "+++ ")):
            continue
        elif m := row.match(line):
            out.setdefault(m.group(1), set()).add(f)
    return out


def decision_citers(root: Path, trunk: str, rng: str) -> dict[str, list[str]]:
    """Each page whose text cites a decision whose entry RNG changed, with those ids: a
    metarepo's entry pages, or the docmap's pages anywhere else. An entry and the pages citing
    it are one home, and an entry is no file docmap can map. A passing mention is asked too:
    "no change because" answers it. The prefix and pages are trunk's, so a branch can't narrow
    them to escape the question."""
    meta = load_meta(trunk)
    rows: set[str] = {LOG}
    if meta and not has_log(trunk):
        # A metarepo `jig update` hasn't moved to the log yet: its register's rows, as before.
        by_row = changed_rows(root, meta, rng)
        changed, rows = set(by_row), {CHANGELOG, *(set().union(*by_row.values()) if by_row else ())}
    else:
        changed = changed_decisions(root, log_prefix(trunk), rng)
    if not changed:
        return {}
    head = git("-c", "core.quotePath=false", "ls-tree", "-r", "--name-only", "HEAD", cwd=str(root))
    docmap = set((Board.load(root).data.get("docmap") or {})) if not meta else set()
    out: dict[str, list[str]] = {}
    for page in head.splitlines():
        if page in rows or not (is_entry(page, meta["entry_files"]) if meta else page in docmap):
            continue
        text = git("show", f"HEAD:{page}", cwd=str(root))
        # Whole ids only: D-7 is not D-70, nor XD-7.
        hit = [d for d in sorted(changed) if re.search(rf"(?<![\w-]){re.escape(d)}(?![\w?-])", text)]
        if hit:
            out[page] = hit
    return out


def terms_changed(loc: Path, old: str, new: str) -> list[str]:
    """Decision ids and glossary headings that changed between two releases. Ids are matched
    by the metarepo's own decision_prefix, which may be lowercase."""
    # Only what a pararepo can read: the entry set release counts and the cache copies. Literal
    # paths, not entry_files globs, since git's `**` misses a file directly under the folder.
    paths = sorted((set(entry_paths(old, str(loc))) | set(entry_paths(new, str(loc)))) - {CHANGELOG})
    # The glossary is read term by term, in either home, by glossary_changes; the README's
    # other headings (Install, Usage) are prose, not terms.
    gloss = "README.md" in paths or GLOSSARY in paths
    log = LOG in paths or IDEAS in paths
    regs = merged_registers(loc, old, new)
    paths = [f for f in paths if f not in ("README.md", GLOSSARY, LOG, IDEAS, *regs)]
    found = []
    if regs:
        # Across the merge into the log the same decisions changed shape, not meaning: only an
        # entry whose title or status differs from its row is news.
        prefix = decision_prefix_at(loc, new)
        def shape(title: str, status: str) -> tuple[str, str]:
            return title.strip(), re.sub(r" Supersedes .*$", "", status.strip())
        was = {}
        for r in regs:
            # Dated from history as the merge dated them, or every superseded row reads as news.
            rows = parse_register(git("show", f"{old}:{r}", cwd=str(loc)), decision_prefix_at(loc, old))[0]
            date_superseded(loc, r, rows, decision_prefix_at(loc, old), old)
            was |= {decision_id(e["id"]): shape(e["title"], e["status"]) for e in rows if e["word"] != "rejected"}
        entries = log_entries(entries_at(new, str(loc)), prefix)
        now = {decision_id(e["id"]): (e["id"], shape(e["title"], e["status"]), e["status"]) for e in entries}
        for i, (shown, sh, status) in now.items():
            if was.get(i) != sh:
                found.append(shown)
                found += (status_parts(status, prefix) or ("", "", "", []))[3]
        found += [i for i in was if i not in now]
    elif log:
        # An entry added, edited or removed, and what a new entry supersedes: a pararepo cites
        # the old id, and needs to hear that it no longer holds.
        prefix = decision_prefix_at(loc, new)
        was, now = ({e["id"]: e for e in log_entries(entries_at(r, str(loc)), prefix)}
                    for r in (old, new))
        for i in sorted({*was, *now}, key=lambda i: (now.get(i) or was[i])["line"]):
            if (was.get(i) or {}).get("block") != (now.get(i) or {}).get("block"):
                found.append(i)
                found += (status_parts((now.get(i) or {}).get("status", ""), prefix) or ("", "", "", []))[3]
    if paths:
        diff = git("--literal-pathspecs", "diff", old, new, "--", *paths, cwd=str(loc))
        found += re.findall(rf"^[+-]\s*\|\s*({decision_ids(loc, new)})\s*\|", diff, re.M)
        found += re.findall(r"^[+-]#{2,3} (.+?)\s*$", diff, re.M)
    if gloss:
        found += glossary_changes(loc, old, new)[0]
    return list(dict.fromkeys(found))


def term_blocks(lines: list[str], level: int) -> dict[str, list[str]]:
    """Each term in LINES with its text, blank lines dropped: a table row is its own text, a
    heading of LEVEL the lines under it, a bold-paragraph term its paragraph. The heading line
    itself is left out, so a term whose level changed with its home reads the same, and a term
    is matched by name whatever its form."""
    out = {t: [lines[i].strip()] for i, t in table_terms(lines)}
    for i, t in bold_terms(lines):
        end = next((j for j in range(i + 1, len(lines)) if not lines[j].strip()), len(lines))
        out[t] = lines[i:end]
    for i, line in enumerate(lines):
        if m := re.match(rf"#{{{level}}}\s+(.+?)\s*$", line):
            end = next((j for j in range(i + 1, len(lines)) if re.match(rf"#{{1,{level}}}\s", lines[j])), len(lines))
            out[term_text(m.group(1))] = [l for l in lines[i + 1:end] if l.strip()]
    return out


def glossary_blocks(text: str) -> dict[str, list[str]]:
    """Each term of a glossary with its own lines, blank lines dropped: its heading's level left
    out, so a term moved between levels or parents reads the same, and a table row is none."""
    lines = text.splitlines()
    heads = [e for e in glossary_entries(text) if e["level"] <= 3]
    return {e["name"]: [l for l in lines[e["start"] + 1:nxt["start"] if nxt else len(lines)] if l.strip()]
            for e, nxt in zip(heads, heads[1:] + [None]) if not e["title"] and e["name"] != BASIC_TERMS}


def glossary_at(loc: Path, rev: str) -> tuple[str, dict[str, list[str]]]:
    """Where REV keeps its glossary, and its terms: docs/glossary.md, or before the move the
    README's Glossary section, so a release across the move compares the same terms."""
    text = git("show", f"{rev}:{GLOSSARY}", cwd=str(loc))
    if text:
        return GLOSSARY, glossary_blocks(text)
    return "README.md", term_blocks(readme_glossary(git("show", f"{rev}:README.md", cwd=str(loc))) or [], 3)


def glossary_changes(loc: Path, old: str, new: str) -> tuple[list[str], list[str], str, str]:
    """(terms added, removed or reworded; terms that moved home; the old home; the new one)
    between two releases. A term that moved is reported as moved, not as removed and added."""
    was_home, was = glossary_at(loc, old)
    now_home, now = glossary_at(loc, new)
    if was_home != now_home:
        return ([t for t in now if t not in was] + [t for t in was if t not in now],
                [t for t in now if t in was], was_home, now_home)
    return ([t for t in now if was.get(t) != now[t]] + [t for t in was if t not in now],
            [], was_home, now_home)


OPENING = "propose: "


def proposal_empty(loc: Path, branch: str, trunk: str) -> bool:
    """Whether a proposal branch exists with nothing written on it: its tip is the opening commit
    `jig propose` made, or, for a branch made before there was one, sits on trunk's own line."""
    tip = git("rev-parse", "-q", "--verify", f"refs/heads/{branch}^{{commit}}", cwd=str(loc))
    if not tip:
        return False
    return opening_commit(loc, tip) or tip in git("rev-list", "--first-parent", trunk, cwd=str(loc)).split()


def opening_commit(loc: Path, rev: str) -> bool:
    """Whether REV is the commit `jig propose` opens a branch with: nothing written on it."""
    subject = git("log", "-1", "--format=%s", rev, cwd=str(loc))
    return subject.startswith(OPENING) and subject.endswith("nothing written yet")


def proposal_in(loc: Path, branch: str, tag: str) -> bool:
    """Whether a proposal is in a release: its branch is an ancestor of the tag, or, the branch
    deleted after its merge, a merge reachable from the tag names it. M4 makes every change to
    the metarepo's trunk a merge, and git's default subject names the branch."""
    tip = git("rev-parse", "-q", "--verify", f"refs/heads/{branch}^{{commit}}", cwd=str(loc))
    if tip:
        # An empty proposal is an ancestor of every later tag (its opening commit merged, or the
        # trunk commit an old one sits on): nothing of it is released.
        return not proposal_empty(loc, branch, Board.trunk_name(loc)) and subprocess.run(["git", "merge-base", "--is-ancestor", tip, tag],
                                               cwd=loc, capture_output=True).returncode == 0
    # git's own subject names the branch; `jig merge`'s names the job, whose board entry, read
    # just before that merge deleted it, names the branch.
    named = re.compile(rf"^Merge branch '{re.escape(branch)}'( into \S+)?$")
    for line in git("log", "--merges", "--format=%H %s", tag, cwd=str(loc)).splitlines():
        sha, _, subject = line.partition(" ")
        # An empty proposal merged and deleted is still empty: nothing of it is released.
        if named.match(subject) and not opening_commit(loc, f"{sha}^2"):
            return True
        job = re.search(r"(?:^|: )merge (\S+)$", subject)
        if job:
            try:
                jobs = json.loads(git("show", f"{sha}^1:{JOBS}", cwd=str(loc)) or "{}")
            except ValueError:
                continue
            entry = jobs.get(job.group(1)) if isinstance(jobs, dict) else None
            if isinstance(entry, dict) and (entry.get("branch") or job.group(1)) == branch:
                return True
    return False


def unreleased_proposals(root: Path, para: dict, trunk: str, commit: str, named: list[str]) -> list[str]:
    """Why the job at COMMIT can't merge yet: a spec it builds on cites a metarepo proposal that
    isn't in trunk's pinned release, or a pointers branch the metarepo doesn't have. Its specs
    are the ones it changed and the ones the board and its note name, which may sit on trunk
    already (`jig propose` there, then `jig open`); a one-line board spec is its own text. Read
    at the commit, because the hubnode gates from trunk."""
    changed = [p for p in git("diff", "--name-only", f"{trunk}...{commit}", "--",
                              f"{DIR}/specs/").splitlines() if p.endswith(".md")]
    specs = list(dict.fromkeys([*filter(None, named), *changed]))
    found = [(s, m) for s in specs
             for m in PROPOSAL.finditer(git("show", f"{commit}:{s}") or git("show", f"{trunk}:{s}") or s)]
    # A withdrawal is the owner's word on trunk: it wins over a job's copy from before it.
    gone = {w.group("branch") for s in specs for w in WITHDRAWN.finditer(git("show", f"{trunk}:{s}") or "")
            if w.group("meta") == para.get("meta")}
    cited = [(s, m) for s, m in found if m.group("branch") and m.group("branch") not in gone]
    ahead = [(s, m) for s, m in found if m.group("pbranch")]
    if not cited and not ahead:
        return []
    name, pin = para.get("meta", ""), para.get("pin", "")
    loc = meta_checkout(root, para)
    out = []
    # A pointers branch is work ahead, not a dependency: it needn't be released, only real, or
    # the answer is a free-text pass whose only failure signal is a dangling-pointer report.
    for spec, m in ahead:
        what = f"{spec} answers with pointers branch {m.group('pbranch')}"
        if m.group("pmeta") != name:
            out.append(f"{what} on {m.group('pmeta')}, but this repo's metarepo is {name}")
        elif loc is None:
            out.append(f"{what}, and {name} can't be reached to check it (see `jig repos`)")
        # Merged and deleted is real too, released or not: the metarepo's trunk then holds it.
        elif not git("rev-parse", "-q", "--verify", f"refs/heads/{m.group('pbranch')}", cwd=str(loc)) \
                and not proposal_in(loc, m.group("pbranch"), Board.trunk_name(loc)):
            out.append(f"{what}, which {name} has no branch for and hasn't merged: open it "
                       "with `jig propose --pointers`")
    for spec, m in cited:
        what = f"{spec} cites proposal {m.group('branch')}"
        if m.group("meta") != name:
            out.append(f"{what} on {m.group('meta')}, but this repo's metarepo is {name}")
        elif loc is None:
            out.append(f"{what}, and {name} can't be reached to check it (see `jig repos`)")
        elif not proposal_in(loc, m.group("branch"), pin):
            later = [t for t in released_tags(str(loc)) if version_key(t) > version_key(pin)
                     and proposal_in(loc, m.group("branch"), t)]
            out.append(f"{what}, released in {name} {later[0]} but this repo pins {pin}: bump the pin "
                       "(`jig sync` on trunk says how), then `jig sync` the job" if later else
                       f"{what}, which is not in {name} {pin}, the pin, nor in any release: "
                       "it merges once it's released and pinned")
    return out


def sync_meta(root: Path) -> int:
    """`jig sync` on a pararepo's trunk: refresh the cache, report what moved upstream."""
    os.chdir(root)        # its git paths, and the pin commit's, are the whole repo's
    para = json.loads((root / PARA).read_text())
    agents = root / "AGENTS.md"
    if para_header(para) not in (agents.read_text() if agents.exists() else ""):
        print("the AGENTS.md header is out of date: run `jig init --para`, and commit only what "
              "it changed")
    until = para.get("defer_until")
    if until and date.today().isoformat() < until:
        return 0
    loc = meta_checkout(root, para)
    name, pin = para["meta"], para["pin"]
    if loc is None:
        cached = (root / CACHE / "PIN").read_text().split("\n") if (root / CACHE / "PIN").exists() else []
        print(f"can't reach {name} (see `jig repos`): reading the cache "
              f"({' '.join(cached).strip() or 'empty'}). Newer releases are unknown until it's reachable.")
        return 0
    git("fetch", "-q", "--tags", cwd=str(loc))
    fill_cache(root, loc, pin)
    tags = released_tags(str(loc))
    latest = tags[-1] if tags else pin
    buffered = []          # (spec, branch, the rows it carried that are still Open, unchanged)
    still = {tuple(r) for r in buffer_rows((root / BUFFER).read_text() if (root / BUFFER).exists() else "")
             if r[-1] == "Open"}
    open_ids = {r[0] for r in still}
    for spec in sorted((root / DIR / "specs").glob("*.md")):
        text = spec.read_text()
        # Withdrawn, then released anyway: its rows still Open are answered, by --answered.
        for w in WITHDRAWN.finditer(text):
            owed = [i for i in listed_rows(text) if i in open_ids]
            if w.group("meta") == name and owed:
                first = next((t for t in tags if proposal_in(loc, w.group("branch"), t)), None)
                if first:
                    print(f"proposal {w.group('branch')} ({spec.relative_to(root)}): withdrawn, but "
                          f"released by {first}: once the pin holds it, `jig sync --answered "
                          f"{','.join(owed)} --in {first} --reason <text>`")
        for m in PROPOSAL.finditer(text):
            if m.group("branch") and m.group("meta") == name:
                first = next((t for t in sorted(set(tags) | {pin}, key=version_key)
                              if proposal_in(loc, m.group("branch"), t)), None)
                # A buffer proposal whose rows all left Open some other way waits on nothing.
                idle = not first and listed_rows(text) and not set(listed_rows(text)) & open_ids
                b = m.group("branch")
                if first:
                    state = f"released by {first}"
                elif proposal_empty(loc, b, Board.trunk_name(loc)):
                    # The opening commit is the proposal's date; a branch from before it has
                    # only the spec here that cites it.
                    tip = f"refs/heads/{b}"
                    since = (git("log", "-1", "--format=%cs", tip, cwd=str(loc)) if opening_commit(loc, tip)
                             else git("log", "--diff-filter=A", "-1", "--format=%cs", "--",
                                      str(spec.relative_to(root))) or "uncommitted")
                    state = (f"empty: nothing written on it in {name} since {since}; write the change "
                             f"there (git -C {loc} worktree add <dir> {b}), or {withdraw_line(b)}"
                             + ("; it carries no Open row" if idle else ""))
                    idle = False
                else:
                    state = "not released"
                print(f"proposal {b} ({spec.relative_to(root)}): {state}"
                      + (f", and carries no Open row: {withdraw_line(m.group('branch'))} if it won't be"
                         if idle else ""))
                rows = [i for i, r in proposed_copy(text).items() if tuple(r) in still]
                if rows:
                    buffered.append((spec, m.group("branch"), rows))
            elif m.group("pbranch") and m.group("pmeta") == name:
                b = m.group("pbranch")
                first = next((t for t in sorted(set(tags) | {pin}, key=version_key)
                              if proposal_in(loc, b, t)), None)
                state = (f"released by {first}" if first else "merged, not released"
                         if proposal_in(loc, b, Board.trunk_name(loc)) else "open"
                         if git("rev-parse", "-q", "--verify", f"refs/heads/{b}", cwd=str(loc))
                         else "missing")
                print(f"pointers {b} ({spec.relative_to(root)}): {state}")
    uncovered_paths(root, loc, para)
    # The buffer settles when the metarepo releases its proposal: the pin moves to the first
    # release that holds one, and its rows close in that same commit. A pin already holding it
    # (bumped by hand) closes them where it stands.
    held = [pin] + [t for t in tags if version_key(t) > version_key(pin)]
    settles = next((t for t in held if any(proposal_in(loc, b, t) for _, b, _ in buffered)), None)
    if settles:
        closing = [(s, b, rows) for s, b, rows in buffered if proposal_in(loc, b, settles)]
        if busy := in_progress(root):
            print(f"{name} {settles} releases {', '.join(b for _, b, _ in closing)}: {busy} is in progress "
                  f"here: finish it first, so jig sync can close its rows in a commit of their own")
        elif git("status", "--porcelain", "--", PARA, "AGENTS.md", BUFFER) or git("diff", "--cached", "--name-only"):
            print(f"{name} {settles} releases {', '.join(b for _, b, _ in closing)}: commit or stash first, "
                  f"so jig sync can close its rows in a commit of their own")
        else:
            moved = settles != pin
            body = changes_report(root, loc, pin, settles) if moved else []
            ids = [i for _, _, rows in closing for i in rows]
            para["pin"] = settles
            (root / PARA).write_text(json.dumps(para, indent=2) + "\n")
            agents.write_text(with_header(agents.read_text() if agents.exists() else "# AGENTS.md\n",
                                          para_header(para)))
            ledger = (root / BUFFER).read_text().splitlines(keepends=True)
            for n, l in enumerate(ledger):
                r = buffer_rows(l)
                if r and r[0][0] in ids and r[0][-1] == "Open":
                    ledger[n] = re.sub(r"\bOpen(\s*\|?\s*)$", r"Closed\1", l.rstrip("\n")) + "\n"
            (root / BUFFER).write_text("".join(ledger))
            fill_cache(root, loc, settles)
            git("add", "--", PARA, "AGENTS.md", BUFFER, check=True)
            subject = f"meta: {name} {pin} → {settles}" if moved else f"meta: {name} {pin}: close {', '.join(ids)}"
            done = subprocess.run(["git", "commit", "-q", "-m", subject, "-m",
                                   "\n".join(body + ["", f"Closed {', '.join(ids)}: "
                                                      f"{', '.join(b for _, b, _ in closing)} released "
                                                      f"in {settles}."]).strip()],
                                  cwd=root)
            if done.returncode:
                die(f"the commit was refused: {PARA}, AGENTS.md and {BUFFER} are staged as jig wrote them", 1)
            print(f"{subject}: committed, closing {', '.join(ids)}.")
            pin = settles
    for line in [*yanked_pin(loc, pin, name), *stale_pointers(root), *meta_citations(root, para, decision_ids(loc, pin), loc)]:
        print(line)
    if version_key(latest) <= version_key(pin):
        print(f"{name} {pin} is the latest release")
        return 0
    print("\n".join(newer_release(root, loc, name, pin, latest)))
    return 0


def withdraw_line(branch: str) -> str:
    return f"`jig propose --withdraw {branch} --reason <text>`"


def sync_answered(root: Path, ids: str, release: str | None, reason: str | None) -> int:
    """`jig sync --answered`: close Open rows the metarepo answered by a change other than the
    proposal that carried them, on the owner's word. The row keeps its claim and records the
    release and the reason, in a commit of its own that P2 checks against the pin."""
    os.chdir(root)
    para = json.loads((root / PARA).read_text())
    name, pin = para["meta"], para["pin"]
    reason = (reason or "").strip()
    if not release or not reason:
        die("usage: jig sync --answered <id>[,<id>…] --in <release> --reason <text>", 2)
    if "|" in reason or "\n" in reason:
        die("the reason goes in a table cell: one line, no `|`", 2)
    loc = meta_checkout(root, para)
    if loc is None:
        die(f"can't find {name}: run `jig repos add meta` in its checkout", 2)
    git("fetch", "-q", "--tags", cwd=str(loc))
    if release not in released_tags(str(loc)):
        die(f"{release} is not a release of {name}", 2)
    if version_key(release) > version_key(pin):
        die(f"{name} {release} is above the pin, {pin}: take it first (`jig sync` says how)", 2)
    if git("status", "--porcelain"):
        die("commit or stash first: the answered rows close in a commit of their own", 2)
    if busy := in_progress(root):
        die(f"{busy} is in progress here: finish it first, so the answered rows close in a commit of their own", 2)
    want = [i for i in re.split(r"[,\s]+", ids) if i]
    ledger = (root / BUFFER).read_text().splitlines(keepends=True) if (root / BUFFER).exists() else []
    state = {r[0]: r[-1] for l in ledger for r in buffer_rows(l)}
    bad = [i for i in want if state.get(i) != "Open"]
    if bad:
        die(f"not an Open row of {BUFFER}: {', '.join(bad)}", 2)
    cell = f"Closed (answered in {release}: {reason})"
    for n, l in enumerate(ledger):
        r = buffer_rows(l)
        if r and r[0][0] in want:
            ledger[n] = re.sub(r"\bOpen(\s*\|?\s*)$", lambda m: cell + m.group(1), l.rstrip("\n")) + "\n"
    (root / BUFFER).write_text("".join(ledger))
    git("add", "--", BUFFER, check=True)
    subject = f"meta: {name} {pin}: {', '.join(want)} answered in {release}"
    if subprocess.run(["git", "commit", "-q", "-m", subject, "-m", reason], cwd=root).returncode:
        die(f"the commit was refused: {BUFFER} is staged as jig wrote it", 1)
    print(f"{subject}: committed.")
    # A buffer proposal left carrying no Open row waits on nothing; withdrawing it is the owner's.
    still = {r[0] for l in ledger for r in buffer_rows(l) if r[-1] == "Open"}
    for spec in sorted((root / DIR / "specs").glob("*.md")):
        text = spec.read_text()
        listed = set(listed_rows(text))
        if listed & set(want) and not listed & still:
            for m in PROPOSAL.finditer(text):
                if m.group("branch") and m.group("meta") == name and not proposal_in(loc, m.group("branch"), pin):
                    print(f"{m.group('branch')} ({spec.relative_to(root)}) carries no Open row now: "
                          f"{withdraw_line(m.group('branch'))} if {name} won't release it")
    return 0


BULLET = re.compile(r"^[-*+][ \t]+")


def breaking_lines(loc: Path, pin: str, latest: str) -> list[str]:
    """Each `**Breaking:**` line released after PIN up to LATEST, oldest release first, with its
    release: what a reader taking them must act on, which the version's level doesn't say."""
    text = git("show", f"{latest}:{LOG}", cwd=str(loc))
    out = []
    for version, (_, _, lines) in sorted(release_sections(text).items(), key=lambda v: version_key(v[0])):
        if version_key(pin) < version_key(version) <= version_key(latest):
            out += [f"  {version}: {BULLET.sub('', l.strip())}" for l in lines if "**Breaking:**" in l]
    return out


def newer_release(root: Path, loc: Path, name: str, pin: str, latest: str) -> list[str]:
    breaking = breaking_lines(loc, pin, latest)
    return [f"{name} {latest} is out; this repo pins {pin}.",
            *(["Breaking, to act on:", *breaking] if breaking else []), "",
            *changes_report(root, loc, pin, latest),
            f"\nTo take it: set \"pin\" to \"{latest}\" in {PARA}, run `jig init --para {name}`, and commit "
            f"those alone as `meta: {name} {pin} → {latest}` with this report as the body."]


PIN_BUMP_KIND = "pin-bump"


def stage_pin_bumps(root: Path, meta: dict, prev: str, tag: str) -> list[str]:
    """A metarepo release asks each pararepo whose citations it broke to move its pin: a staged
    request in that pararepo, carrying the releases' Breaking lines and what to rewrite, from its
    pin to TAG. Broke means a citation that resolved at PREV and dangles at TAG, or a decision id
    TAG removed or superseded, cited as `<meta>/<path> § <id>` (or bare where the pararepo's own
    prefix differs). A request still open from here (its release above the pin) is rewritten
    when something from the pin to TAG breaks what it cites, and left as it is otherwise (a
    Breaking line alone breaks nothing it cites); an answered one (the pin holds it) only when
    this release breaks something; a same-named file that isn't this metarepo's request is never touched. A
    pararepo on an older jig layout is skipped. A line per pararepo. Writes nothing but that file."""
    name = meta.get("name") or root.name
    out: list[str] = []
    if not prev:
        return out
    prefix = decision_prefix_at(root, tag)
    now_log = entries_at(tag)
    key = lambda line: line.split(", which ")[0]

    def broken(there: Path, para: dict, trunk: str, since: str, here: set[str]) -> tuple[list[str], list[str]]:
        """What the releases after SINCE up to TAG broke there: its citations that resolve at
        SINCE and dangle at TAG, each with the new home a move gives it, and the decision ids
        SINCE had and TAG doesn't, each with the files citing it."""
        moved = {}
        for l in git("-c", "core.quotePath=false", "diff", "-M", "--name-status", since, tag).splitlines():
            parts = l.split("\t")
            if parts[0].startswith("R") and len(parts) == 3:
                moved[parts[1]] = parts[2]
        # A row citation's loss is the id list's; this list is the paths and headings.
        was = {key(l) for l in meta_citations(there, para, decision_ids(root, since), root, (trunk, since), here)}
        rewrites, rows = [], {}
        for l in meta_citations(there, para, decision_ids(root, tag), root, (trunk, tag), here):
            if key(l) in was or " bare: " in l:
                continue
            # A citation of a row the release took away: the ids' list, with where it is cited.
            if " has no row for" in l and (m := re.match(r"(.+?:\d+) cites .*? § (\S+), which ", l)):
                rows.setdefault(m.group(2), []).append(m.group(1))
                continue
            cited = re.search(rf"cites {re.escape(name)}/(\S+?)(?:[ ,]|$)", l)
            if cited and cited.group(1) in moved and ": now " not in l:
                l += f": now `{name}/{moved[cited.group(1)]}`"
            rewrites.append(l)
        then = log_entries(entries_at(since), prefix)
        gone = sorted({e["id"] for e in then} - {e["id"] for e in log_entries(now_log, prefix)})
        # An id a gone entry had superseded hopped to it; once that one moves down, the old id's
        # new home is the move's too, so a bare citation of it is news.
        hopped = {o for e in then if e["id"] in gone for o in replaced(e, prefix)
                  if "/" in (holds_now(o, now_log, prefix, tag, str(root)) or "")}
        own = log_prefix_of(git("show", f"{trunk}:{LOG}", cwd=str(there)))
        ids = []
        for i in sorted(set(gone) | hopped | set(rows)):
            files = list(rows.get(i, []))
            # A bare id is this metarepo's only where the pararepo numbers its own decisions with
            # another prefix; with the same one, only a qualified citation (above) is its.
            if own != prefix and (i in gone or i in hopped):
                cited = {f.split(":", 1)[0] for f in files}
                # jig's own files are no citation: its specs, ledgers, log and process are the repo's.
                files += [g for f in git("grep", "-l", "-w", "-F", i, trunk, "--", ".", f":!{HANDOFFS}",
                                         cwd=str(there)).splitlines()
                          if (g := f.split(":", 1)[1]) not in cited
                          and (not g.startswith(f"{DIR}/") or g.startswith((f"{DIR}/specs/", f"{DIR}/ledgers/", LOG, IDEAS, PROCESS)))]
            if files:
                by = holds_now(i, now_log, prefix, tag, str(root))
                state = f" (moved: {shown_pointer(by, here)})" if by and "/" in by else f" (now {by})" if by else " (removed)"
                ids.append(f"{i}{state}: cited in " + ", ".join(files))
        return rewrites, ids

    for para_name in meta.get("pararepos", []):
        where = repo_path(para_name)
        if not where:
            out.append(f"{para_name}: skipped, it isn't in `jig repos`")
            continue
        there = Path(where)
        if old := old_board(there):
            out.append(f"{para_name}: skipped, it is on an older jig layout ({old}): `jig update` there")
            continue
        try:
            trunk = json.loads((there / CONFIG).read_text()).get("trunk") or "main"
            para = json.loads(git("show", f"{trunk}:{PARA}", cwd=str(there)) or "{}")
        except (OSError, ValueError):
            para = {}
        if para.get("meta") != name:
            out.append(f"{para_name}: skipped, its {PARA} doesn't cite {name}")
            continue
        until = para.get("defer_until")
        if until and date.today().isoformat() < until:
            out.append(f"{para_name}: skipped, it defers {name} until {until}")
            continue
        pin = para.get("pin") or ""
        if pin and version_key(pin) >= version_key(tag):
            out.append(f"{para_name}: skipped, it already pins {pin}")
            continue
        dest = there / STAGING / f"pin-bump-{name}.md"
        h = read_staged(dest)[0] if dest.exists() else {}
        # Ours is this metarepo's request; open is ours with a release above the pin. An answered
        # one (the pin holds it) is rewritten only when this release breaks something, as a new
        # request would be; a file of that name that isn't ours is never touched.
        ours = h.get("kind") == PIN_BUMP_KIND and h.get("from") == name
        open_ = ours and bool(h.get("release")) and (not pin or version_key(h["release"]) > version_key(pin))
        here = {para_name}
        if not open_ and not any(broken(there, para, trunk, prev, here)):
            out.append(f"{para_name}: skipped, it cites nothing {tag} broke")
            continue
        if dest.exists() and not ours:
            out.append(f"{para_name}: not staged, {STAGING}/{dest.name} there isn't {name}'s pin bump: "
                       "left as it is")
            continue
        # The request covers the whole gap from the pin, so one file serves every release since.
        since = pin if pin and git("rev-parse", "-q", "--verify", f"{pin}^{{commit}}") else prev
        rewrites, ids = broken(there, para, trunk, since, here)
        breaking = breaking_lines(root, since, tag)
        # Only what it broke (the owner, 2026-11-18): a gap from the pin that breaks nothing it
        # cites asks for nothing, so an open request is left as it stands.
        if not rewrites and not ids:
            out.append(f"{para_name}: skipped, nothing from {since} to {tag} breaks what it cites"
                       + (f"; {STAGING}/{dest.name} left as it is" if dest.exists() else ""))
            continue
        body = [f"# {name}: move the pin from {pin} to {tag}", "",
                f"{name} {tag} broke what this repo cites. Take it in a job: rewrite the uses below, "
                f"set \"pin\" to \"{tag}\" in {PARA}, run `jig init --para {name}`, and commit the pin "
                f"as `meta: {name} {pin} → {tag}` with this request as the body.", ""]
        if breaking:
            body += ["## Breaking", "", *[f"-{l[1:]}" for l in breaking], ""]
        if rewrites:
            body += ["## Rewrites", "", *[f"- {l}" for l in rewrites], ""]
        if ids:
            body += ["## Removed or superseded", "", *[f"- {l}" for l in ids], ""]
        head = {"staged": "true", "target": para_name, "kind": PIN_BUMP_KIND, "change": "update",
                "destination": PARA, "source": f"{name} release {tag} / {date.today().isoformat()}",
                "from": name, "pin": pin, "release": tag, "status": "staged"}
        try:
            dest.parent.mkdir(parents=True, exist_ok=True)
            dest.write_text("---\n" + "".join(f"{k}: {v}\n" for k, v in head.items()) + "---\n" + "\n".join(body))
        except OSError as e:
            out.append(f"{para_name}: not staged, {e}")
            continue
        plural = lambda n, what: f"{n} {what}{'s' if n != 1 else ''}"
        sup = sum(" (now " in i for i in ids)
        went = sum(" (moved: " in i for i in ids) + sum(" moved: now " in r for r in rewrites)
        plain_rewrites = sum(" moved: now " not in r for r in rewrites)
        gone_ids = len(ids) - sup - sum(" (moved: " in i for i in ids)
        counts = ([plural(plain_rewrites, "rewrite")] if plain_rewrites else []) \
            + ([plural(sup, "superseded id")] if sup else []) \
            + ([f"{went} moved"] if went else []) \
            + ([plural(gone_ids, "removed id")] if gone_ids else [])
        out.append(f"{para_name}: staged {STAGING}/{dest.name} ({', '.join(counts) or 'nothing to rewrite'})")
    return out


def merged_registers(loc: Path, old: str, new: str) -> list[str]:
    """The registers OLD held rows in that the merge into the log, between OLD and NEW, took."""
    if git("ls-tree", "--name-only", old, "--", LOG, cwd=str(loc)) or \
            not git("ls-tree", "--name-only", new, "--", LOG, cwd=str(loc)):
        return []
    prefix = decision_prefix_at(loc, old)
    return [f for f in entry_paths(old, str(loc)) if f != LOG and f.endswith(".md")
            and rows_in(git("show", f"{old}:{f}", cwd=str(loc)), prefix)]


def entries_moved(loc: Path, old: str, new: str) -> list[tuple[str, str | None]]:
    """Each entry file at OLD that NEW lacks, with where it went (None: removed). git's rename
    detection names the new path, so no changelog line has to be read for it. A register the
    merge into the log took went there."""
    paths = sorted((set(entry_paths(old, str(loc))) | set(entry_paths(new, str(loc)))) - {CHANGELOG})
    if not paths:
        return []
    regs = merged_registers(loc, old, new)
    out = []
    for line in git("-c", "core.quotePath=false", "--literal-pathspecs", "diff", "-M", "--name-status",
                    old, new, "--", *paths, cwd=str(loc)).splitlines():
        f = line.split("\t")
        if f[0].startswith("R"):
            out.append((f[1], f[2]))
        elif f[0] == "D":
            out.append((f[1], LOG if f[1] in regs else None))
    return out


def closed_row(path: str, line: str) -> bool:
    """A Closed BUFFER row cites the pin it was written at: history, not a use."""
    return path == BUFFER and line.lstrip().startswith("|") and row_state((table_cells(line) or [""])[-1]) == "Closed"


def buffer_copy(listed: set[str], line: str) -> bool:
    """A buffer proposal spec's copy of a row it lists under `## Buffer rows`: history, as a
    Closed row is. The BUFFER row itself is still checked while it is Open."""
    return bool(listed) and line.lstrip().startswith("|") and (table_cells(line) or [""])[0] in listed


def used_in(text: str, whole: bool = False) -> list[str]:
    """This repo's files that use TEXT. Of jig's own files only specs and ledgers count: the
    rulebook's examples and the cache aren't the repo's use, but a spec or an Open BUFFER row is."""
    keep = (f"{DIR}/specs/", f"{DIR}/ledgers/", LOG, IDEAS, PROCESS)
    return list(dict.fromkeys(f for f, _, line in grep_hits("-I", "-F", *(["-w"] if whole else []), "--", text)
                              if (not f.startswith(f"{DIR}/") or f.startswith(keep)) and not closed_row(f, line)))


def changes_report(root: Path, loc: Path, old: str, new: str) -> list[str]:
    out = ["Changed, in this repo's terms:"]
    # What the metarepo moved down reads as moved, with its new home, never as removed.
    moves = moves_in(git("show", f"{new}:{LOG}", cwd=str(loc)))
    here = this_repo_names(root)
    prefix = decision_prefix_at(loc, new)
    # An idea decided in place keeps its id: it reads as accepted, never as removed.
    was_idea = {e["id"] for e in log_entries(entries_at(old, str(loc)), prefix) if e["section"] in (IDEAS, "Open")}
    decided = {e["id"] for e in log_entries(entries_at(new, str(loc)), prefix)
               if e["id"] in was_idea and e["section"] != IDEAS}
    for was, now in entries_moved(loc, old, new):
        users = used_in(was)
        state = (f"moved: {shown_pointer(moves[was], here)}" if not now and was in moves
                 else 'now ' + now if now else 'removed')
        out.append(f"  {was} ({state}): "
                   + (f"used in {', '.join(users)}" if users else "not used here"))
    for term in terms_changed(loc, old, new):
        # An id as a whole word: D-1 is not a use of D-12. A heading's term may be inflected.
        users = used_in(term, bool(re.fullmatch(decision_ids(loc, new), term)))
        # A heading moves as `<page> § <heading>`, and its term is the heading alone.
        ptr = moves.get(term) or next((p for k, p in moves.items() if k.endswith(f" § {term}")), None)
        state = f" (moved: {shown_pointer(ptr, here)})" if ptr else " (accepted)" if term in decided else ""
        out.append(f"  {term}{state}: " + (f"used in {', '.join(users)}" if users else "not used here"))
    _, moved, was, now = glossary_changes(loc, old, new)
    for term in moved:
        users = used_in(term)
        out.append(f"  {term} (moved: {was} § {term} → {now} § {term}): "
                   + (f"used in {', '.join(users)}" if users else "not used here"))
    return out


def head_texts(paths: list[str], rev: str = "HEAD", cwd: str | None = None) -> list[tuple[str, str]]:
    """PATHS' text at REV (HEAD), read in one git call; binary files (a NUL byte) left out."""
    raw = subprocess.run(["git", "cat-file", "--batch"], capture_output=True, cwd=cwd,
                         input="".join(f"{rev}:{p}\n" for p in paths).encode()).stdout
    out, at = [], 0
    for p in paths:
        head_end = raw.index(b"\n", at)
        head = raw[at:head_end].split()
        if head[-1] == b"missing":
            at = head_end + 1
            continue
        size = int(head[2])
        body = raw[head_end + 1:head_end + 1 + size]
        at = head_end + 1 + size + 1
        if b"\0" not in body:
            out.append((p, body.decode(errors="replace")))
    return out


def meta_citations(root: Path, para: dict, ids: str, loc: Path | None = None,
                   at: tuple[str, str] | None = None, ours: set[str] | None = None) -> list[str]:
    """This repo's citations of the metarepo checked against the cache: the mirror of
    stale_pointers. A citation is `<meta>/<path> § <section>`; a section that is a decision id
    (IDS, the metarepo's prefix) names a row, any other a heading. A bare path that names an
    entry file at the pin and nothing here is named too, since it can't be told from this repo's
    own. Handoffs, Closed BUFFER rows and a buffer proposal's copies of its rows cite the pin
    they were written at, so they are left out. A cite of the metarepo's roadmap is read on its
    trunk, not at the pin.
    Reported, never refused. Read at HEAD against the cache, as stale_pointers reads it; with AT,
    (this repo's revision, the metarepo's tag in LOC), read there instead: a metarepo's release
    compares its pararepos' citations against two of its tags. A citation of what the metarepo
    moved down ends with its new home, read as OURS (this repo's names) calls it."""
    cache, name, pin = root / CACHE, para["meta"], para["pin"]
    # The metarepo's roadmap is project data, not a contract: no pin holds it, so a cite of it
    # is read on the metarepo's trunk, and a pin bump never changes what it finds.
    mtrunk = Board.trunk_name(loc) if loc else None
    if ours is None:
        ours = this_repo_names(root)
    if at:
        rev, pin = at
        mfiles = git("-c", "core.quotePath=false", "ls-tree", "-r", "--name-only", pin, cwd=str(loc)).splitlines()
        have = set(mfiles)
        mdirs = {"/".join(f.split("/")[:k]) for f in mfiles for k in range(1, f.count("/") + 1)}
        entries = [f for f in mfiles if f != CHANGELOG]

        def meta_text(path: str) -> str | None:
            return git("show", f"{pin}:{path}", cwd=str(loc)) if path in have else "" if path.rstrip("/") in mdirs else None
    else:
        if not cache.is_dir():
            return []
        rev = "HEAD"
        entries = [f.relative_to(cache).as_posix() for f in sorted(cache.rglob("*"))
                   if f.is_file() and f.name != "PIN" and f != cache / CHANGELOG]

        def meta_text(path: str) -> str | None:
            target = cache / path
            return target.read_text(errors="replace") if target.is_file() else "" if target.is_dir() else None
    sized = [l.split("\t", 1) for l in git("-c", "core.quotePath=false", "ls-tree", "-r", "-l", rev,
                                           cwd=str(root)).splitlines()]
    here = [p for _, p in sized]
    tracked = set(here)
    # A citation lives in prose: a blob over a megabyte (an image, a firmware build) isn't read.
    small = [p for meta, p in sized if meta.split()[1] == "blob" and meta.split()[3] != "-"
             and int(meta.split()[3]) <= 1 << 20]
    folders = {"/".join(p.split("/")[:k]) + "/" for p in here for k in range(1, p.count("/") + 1)}
    bare = sorted((e for e in entries if e not in tracked), key=len, reverse=True)
    # One plain alternation finds the candidates and the boundaries are checked after: a regex
    # per entry, or one with a lookbehind, over every line of a big repo is too slow for a sync.
    one = re.compile("|".join(map(re.escape, bare))) if bare else None
    rows = re.compile(rf"(?<!\w)({ids})(?!\w)")
    named = (f"{name.casefold()}/", f"{name.casefold()}:")
    gloss = glossary_terms(meta_text(GLOSSARY) or "")
    moves = moves_in(meta_text(LOG) or "")
    out = []
    for f, text in head_texts([p for p in small if not p.startswith(f"{DIR}/")
                               or p.startswith((f"{DIR}/specs/", f"{DIR}/ledgers/", LOG, IDEAS, PROCESS))],
                              rev, str(root)):
        folded = text.casefold()
        if not any(t in folded for t in named) and not (one and one.search(text)):
            continue
        # A released section's change lines are frozen, and its entries change only by being
        # superseded: a citation there isn't fixed in place, so isn't named.
        frozen = released_lines(text) if f == LOG else set()
        copies = set(listed_rows(text)) if f.startswith(f"{DIR}/specs/") else set()
        for n, line in enumerate(text.splitlines(), 1):
            if closed_row(f, line) or buffer_copy(copies, line) or n - 1 in frozen:
                continue
            # A move's two records, its move line and its moved-from line, say where a claim went
            # and came from: history, frozen once released, never a citation to rewrite.
            if f == LOG and (MOVE_LINE.match(line.rstrip()) or MOVED_FROM.match(line.rstrip())):
                continue
            for m in POINTER.finditer(line) if any(t in line.casefold() for t in named) else ():
                if not name_in(m.group("name"), {name}):
                    continue
                path = m.group("path").rstrip(".")
                # docs/ui.md is this repo's own page, whatever its metarepo is called.
                written = f"{m.group('name')}/{path}"
                if written in tracked or f"{written}/" in folders:
                    continue
                code = m.start() > 0 and line[m.start() - 1] == "`" and not m.group("shut")
                rest = m.group("rest")
                section = (rest.split("`")[0].strip() if code else rest) if rest else None
                roadmap = path == ROADMAP
                if roadmap and not mtrunk:
                    continue
                body = trunk_show(loc, path) if roadmap else meta_text(path)
                if path in (LOG, IDEAS) and body is not None:
                    # One id names an entry or an idea: one decided or folded keeps it, in the other file.
                    body = with_ideas(meta_text(LOG) or "", meta_text(IDEAS) or "")
                at_ = mtrunk if roadmap else pin
                row = rows.match(plain(section)) if section and body else None
                if row and (not code or row.group(1) == plain(section)):
                    # A decision is a log entry's heading, or a row in a register from before the log.
                    if not re.search(rf"^(?:\s*\|\s*{re.escape(row.group(1))}\s*\||### {re.escape(row.group(1))}(?!\w))",
                                     body, re.M):
                        # A superseded entry is removed from the log: the citation moves to its successor.
                        by = holds_now(row.group(1), body, log_prefix_of(body), pin if loc else None,
                                       str(loc) if loc else None)
                        now = shown_pointer(by, ours) if by and "/" in by else f"{name}/{path} § {by}"
                        out.append(f"{f}:{n} cites {name}/{path} § {row.group(1)}, which {name} {pin} has no row for"
                                   + (f": now {now}" if by else ""))
                    continue
                level, _ = pointer_gap(path, section or None, code, body)
                # A term the README's glossary held is in the glossary file now.
                moved = (f": now `{name}/{GLOSSARY} § {term}`"
                         if level and path == "README.md" and section
                         and (term := glossary_term_in(plain(section), gloss)) else "")
                gone_to = moved_to(moves, path, section) if level and not roadmap else None
                if gone_to:
                    # Moved down: not missing, but somewhere else, which the reader rewrites to.
                    out.append(f"{f}:{n} cites {name}/{path}{f' § {shown_section(plain(section), code)}' if section else ''}, "
                               f"which {name} {at_} moved: now {shown_pointer(gone_to, ours)}")
                elif level == NO_FILE:
                    out.append(f"{f}:{n} cites {name}/{path}{f' § {shown_section(plain(section), code)}' if moved else ''}, "
                               f"which {name} {at_} doesn't have{moved}")
                elif level == NO_HEADING:
                    out.append(f"{f}:{n} cites {name}/{path} § {shown_section(plain(section), code)}, "
                               f"which {name} {at_} has no heading for{moved}")
            for m in one.finditer(line) if one else ():
                before, after = line[m.start() - 1:m.start()], line[m.end():m.end() + 1]
                if not re.match(r"[\w./:-]", before) and not re.match(r"[\w/-]", after):
                    out.append(f"{f}:{n} cites {m.group(0)} bare: write it as `{name}/{m.group(0)}`")
    return list(dict.fromkeys(out))


def uncovered_paths(root: Path, loc: Path, para: dict) -> None:
    """Report this repo's files that a metarepo decision at the pin cites but contract_paths
    doesn't cover: the decision then describes behavior that can change with no P2 asking.
    A root file in ROOT_DOCS counts only after this repo's name. Only reported: the rule reads trunk's para.json, and adding a path is the owner's choice."""
    ids = decision_ids(loc, para['pin'])
    row = re.compile(rf"^\s*\|\s*({ids})\s*\|.*$", re.M)
    cited = [(m.group(1), m.group(0)) for f in sorted((root / CACHE).rglob("*.md"))
             for m in row.finditer(f.read_text(errors="replace"))]
    # The log's entries, each its whole block: a decision's text runs past its heading.
    log, ideas = root / CACHE / LOG, root / CACHE / IDEAS
    prefix = decision_prefix_at(loc, para["pin"])
    read = lambda f: f.read_text(errors="replace") if f.is_file() else ""
    cited += [(e["id"], e["block"]) for e in log_entries(with_ideas(read(log), read(ideas)), prefix)]
    if not cited:
        return
    # "this" names this repo only in a pararepo's own pointers to the metarepo; in a metarepo
    # decision, this/AGENTS.md is the metarepo's own file.
    names = this_repo_names(root) - {"this"}
    for path in git("-c", "core.quotePath=false", "ls-files").splitlines():
        if path.startswith(f"{DIR}/") or matches(path, para.get("contract_paths", [])):
            continue
        # The path whole, alone or after this repo's name: another pararepo's docs/ui.md is not
        # this one's. A root file every repo has (AGENTS.md) named bare is about every repo, so
        # only this repo's name in front of it points here.
        cite = named_path(rf"{re.escape(path)}(?![\w/-])", bare=path not in ROOT_DOCS)
        ids = [i for i, line in cited
               if any(not m.group("name") or name_in(m.group("name"), names) for m in cite.finditer(line))]
        if ids:
            print(f"{path} is not a contract path, and {', '.join(dict.fromkeys(ids))} name it. "
                  f"If the decision describes something this repo can change there, add the path to "
                  f"\"contract_paths\" in {PARA}; if not, nothing is needed.")


def named_path(path: str, *, bare: bool = False) -> re.Pattern[str]:
    """PATH (a regex) after a repo's name, `app/docs/ui.md` or `app:docs/ui.md`, or alone when
    BARE. Whose name it is is name_in's call, so a name's case folds one way; a path's never does."""
    return re.compile(rf"(?<![\w./:-])(?:(?P<name>[\w.-]+)[/:]){'?' if bare else ''}{path}")


# A metarepo's pointer to a claim this repo owns: `<repo>/<path> § <section>`, the section
# optional. In a code span the section runs to the closing backtick; in prose, where it ends is
# unknown, so REST is the line's remainder and a heading that begins it is the section. REST is
# only looked at, so a later pointer on the line is still found.
POINTER = named_path(r"(?P<path>[\w.-]+(?:/[\w.-]+)*)(?:(?P<shut>`)?[ \t]*§[ \t]*(?=(?P<rest>[^\n]*)))?")
HEADING = re.compile(r"^ {0,3}#{1,6}[ \t]+(.*?)(?:[ \t]+#+)?[ \t]*$", re.M)
# A row no longer in force points at what was, not at what must still be there.
DEAD_ROW = re.compile(r"^(?:superseded|rejected)\b")


def plain(text: str) -> str:
    """Heading text as read: code backticks and emphasis marks dropped, `_` inside a word kept."""
    return re.sub(r"`|\*+|(?<!\w)_+|_+(?!\w)", "", text).strip()


def pointers(root: Path, home: Path | None = None) -> list[tuple[str, str, str | None, bool]]:
    """Every pointer to this repo in HOME's cache (ROOT's by default), decision rows and pages
    alike, as (cache file, path, section, whether the section is a code span's whole text). The
    changelog is history: a path it names was true when written. `this/that` is prose, not a
    repo called this."""
    cache, names, out = (home or root) / CACHE, this_repo_names(root) - {"this"}, []
    for f in sorted(cache.rglob("*.md")):
        if f == cache / CHANGELOG:
            continue
        text = f.read_text(errors="replace")
        # In the log, a superseded entry is history, as a superseded row is: its lines are skipped.
        dead: set[int] = set()
        if f == cache / LOG:
            prefix = log_prefix_of(text)
            entries = log_entries(text, prefix)
            gone = {s for e in entries for s in (status_parts(e["status"], prefix) or ("", "", "", []))[3]}
            dead = {n for e in entries if e["id"] in gone
                    for n in range(e["start"], e["start"] + e["block"].count("\n") + 1)}
            # A released section's change lines are history too: a path one names was true then.
            live = {n for e in entries for n in range(e["start"], e["start"] + e["block"].count("\n") + 1)}
            dead |= {n for n in released_lines(text) if n not in live}
        for n, line in enumerate(text.splitlines()):
            if n in dead:
                continue
            if line.lstrip().startswith("|") and any(DEAD_ROW.match(c) for c in table_cells(line)):
                continue
            for m in POINTER.finditer(line):
                if not name_in(m.group("name"), names):
                    continue
                code = m.start() > 0 and line[m.start() - 1] == "`" and not m.group("shut")
                rest = m.group("rest")
                section = (rest.split("`")[0].strip() if code else rest) if rest else None
                out.append((f"{CACHE}/{f.relative_to(cache).as_posix()}", m.group("path").rstrip("."),
                            section or None, code))
    return list(dict.fromkeys(out))


def body_at(rev: str, path: str) -> str | None:
    """PATH's text at REV ('' the index); '' for a folder; None when neither is there."""
    if git("cat-file", "-t", f"{rev}:{path}") == "blob":
        return at_rev(rev, path)
    listed = git("ls-tree", "-r", "--name-only", rev, "--", path) if rev else git("ls-files", "--", path)
    return "" if listed else None


def body_now(path: str, staged: bool) -> str | None:
    if staged:
        return body_at("", path)
    return Path(path).read_text(errors="replace") if Path(path).is_file() else "" if Path(path).is_dir() else None


# A section's leading number, `2` or `2.1`: the Documentation rule makes it the rule's heading
# and its citation. Whole, so `2` is neither `2.1` nor `20`.
SECTION_NUMBER = re.compile(r"\d+(?:\.\d+)*")
# How badly a pointer misses, in order: P2 asks only when a change makes it worse.
RESOLVES, NO_HEADING, NO_FILE = 0, 1, 2


def section_number(text: str) -> str | None:
    """TEXT's leading number when it is one: it ends the text, or at a blank, or at a `.`, `,`,
    `;`, `:` or `)` that no word follows. `2-factor` and `2.a` are words."""
    m = SECTION_NUMBER.match(text)
    if not m:
        return None
    rest = text[m.end():]
    if not rest or rest[0].isspace() or rest[0] in ".,;:)" and not re.match(r"\w", rest[1:2]):
        return m.group(0)
    return None


def shown_section(want: str, code: bool) -> str:
    """A section as a report prints it: a number whole; prose words up to where the sentence or
    clause ends, a `.` inside a token never cutting."""
    if (number := section_number(want)) is not None:
        return number
    return want if code else re.split(r"[(,;:)|]|\.(?!\S)", want)[0].strip()


def pointer_gap(path: str, section: str | None, code: bool, body: str | None) -> tuple[int, str]:
    """How a pointer misses BODY, the file as it stands (None: no file), and what it lacks;
    (RESOLVES, '') if nothing. A numbered section names the heading with that number; any other
    prose section resolves when some heading begins it, a whole word or more."""
    if body is None:
        return NO_FILE, f"{path}, which this repo doesn't have"
    if not section:
        return RESOLVES, ""
    # The roadmap's sections are its records' keys: it has no headings of its own.
    want = plain(section)
    heads = [plain(h) for h in (roadmap_headings(body) if path.endswith(ROADMAP) else HEADING.findall(body))]
    number = section_number(want)
    if number is not None:
        if number in {section_number(h) for h in heads}:
            return RESOLVES, ""
    elif want in heads or not code and any(h and re.match(rf"{re.escape(h)}(?!\w)", want) for h in heads):
        return RESOLVES, ""
    return NO_HEADING, f"{path} § {shown_section(want, code)}, which {path} has no heading for"


def moved_gap(gap: str, path: str, section: str | None, moves: dict[str, str]) -> str:
    """A pointer's gap as a report says it: one this repo's move line sends elsewhere reads
    `(moved: <pointer>)`, never as missing."""
    ptr = moved_to(moves, path, section)
    return f"{path}{f' § {section}' if section else ''} (moved: {ptr})" if ptr else gap


def dangling(root: Path) -> list[tuple[str, str, str | None, bool, int, str]]:
    """Each cached pointer that misses this repo's HEAD, as (cache file, path, section, code,
    level, gap), one per line a report prints: pointers into a missing file read the same. A
    page or section this repo moved away reads where it went."""
    seen, out = set(), []
    moves = moves_in(body_at("HEAD", LOG) or "")
    for f, path, section, code in pointers(root):
        level, gap = pointer_gap(path, section, code, body_at("HEAD", path))
        gap = moved_gap(gap, path, section, moves) if level else gap
        if level and (f, gap) not in seen:
            seen.add((f, gap))
            out.append((f, path, section, code, level, gap))
    return out


def stale_pointers(root: Path) -> list[str]:
    """Reported, never refused: the fix is the metarepo's, through the buffer."""
    return [f"{f} points to {gap}" for f, _, _, _, _, gap in dangling(root)]


def removed_by(commit: str) -> list[tuple[str, str | None]]:
    """What COMMIT took away: each deleted path with None, each renamed one with where it went."""
    out = []
    for line in git("-c", "core.quotePath=false", "show", "-M", "--name-status", "--format=",
                    commit).splitlines():
        cells = line.split("\t")
        if cells[0] == "D":
            out.append((cells[1], None))
        elif cells[0].startswith("R") and len(cells) == 3:
            out.append((cells[1], cells[2]))
    return out


def removal(path: str, section: str | None, code: bool, level: int) -> tuple[str, str] | None:
    """The newest commit in this repo's history before which the pointer missed less than it
    does now and after which it missed as much, and what the repo has instead ('deleted', or
    the new path); None when it never had it. The resolver decides both sides, so what counts
    as removed is what P2 would have asked about."""
    def misses(rev: str) -> int:
        return pointer_gap(path, section, code, body_at(rev, path))[0]
    for commit in git("log", "--format=%h", "--", path).splitlines():
        if misses(commit) >= level > misses(f"{commit}^"):
            if level == NO_HEADING:
                return commit, path
            new = next((n for o, n in removed_by(commit) if o == path or o.startswith(f"{path}/")), None)
            return commit, new or "deleted"
    return None


def naming_row(rows: list[list[str]], path: str, section: str | None = None,
               states: tuple[str, ...] = ("Open",)) -> list[str] | None:
    """The first row in one of STATES whose cells name PATH (and SECTION, for a heading)."""
    where = re.escape(path) + (rf"[ \t]*§[ \t]*{re.escape(section)}(?!\.?\w)" if section else r"(?![\w/-])")
    named = re.compile(rf"(?<![\w./-]){where}")
    return next((r for r in rows if row_state(r[-1]) in states and any(named.search(c) for c in r[1:-1])), None)


def row_offer(claim: str, now: str) -> str:
    return f"offer a row for {BUFFER}: claim \"{claim}\", this repo now \"{now}\""


def buffer_offer(root: Path, claim: str, path: str, now: str, section: str | None = None) -> str:
    """What to do about a claim this repo moved away from: the Open row that already names PATH
    (and SECTION, for a heading), or the row to add to buffer.md, the owner's to accept. Never
    written here."""
    ledger = root / BUFFER
    row = naming_row(buffer_rows(ledger.read_text()) if ledger.exists() else [], path, section)
    if row:
        return f"Open row {row[0]} in {BUFFER} already names it"
    return row_offer(claim, now)


_BROUGHT: dict[str, dict[str, str]] = {}


def brought_by(trunk: str) -> dict[str, str]:
    """Which first-parent merge on TRUNK brought each commit in."""
    if trunk not in _BROUGHT:
        out: dict[str, str] = {}
        for m in reversed(git("rev-list", "--first-parent", "--merges", trunk, "--").splitlines()):
            for c in git("rev-list", f"{m}^1..{m}^2").splitlines():
                out.setdefault(c, m)
        _BROUGHT[trunk] = out
    return _BROUGHT[trunk]


def trunk_answers(commit: str, trunk: str, spec_dirs: list[str]) -> list["re.Match"]:
    """The P2 answers that covered COMMIT on trunk, read the way P2 read them: the specs it
    touched; and, for a commit a merge brought in, the specs its branch changed and the spec of
    the job whose entry that merge deleted (`jig merge` deletes it there), as trunk held it then
    (a one-line spec is its own text). Update reads these so it never offers a BUFFER row for
    what an answer already covered."""
    def specs_of(*rng: str) -> list[str]:
        return [p for p in git("-c", "core.quotePath=false", *rng, "--name-only", "--diff-filter=ACMRT",
                               "--", *spec_dirs).splitlines() if p.endswith(".md")]
    full = git("rev-parse", "-q", "--verify", f"{commit}^{{commit}}") or commit
    texts = [at_rev(full, s) for s in specs_of("show", "--format=", full)]
    m = brought_by(trunk).get(full)
    if m:
        texts += [at_rev(f"{m}^2", s) for s in specs_of("diff", f"{m}^1...{m}^2")]
        try:
            before = json.loads(at_rev(f"{m}^1", JOBS) or "{}")
            after = json.loads(at_rev(m, JOBS) or "{}")
        except ValueError:
            before, after = {}, {}
        for name in [n for n in before if n not in after]:
            spec = (before[name] or {}).get("spec") or ""
            if spec:
                texts.append(at_rev(f"{m}^1", spec) or spec)
    return [x for t in texts for x in PROPOSAL.finditer(t)]


def pointer_cleanup(root: Path) -> list[str]:
    """Update's Metarepo pointers block: each cached pointer that dangles, and its fix. An older
    P2 let some of these through; the update that brings the fix is where the repo hears of them."""
    if not (root / CACHE).is_dir():
        return [f"no metarepo cache ({CACHE}): run `jig sync`, then update again"]
    out = []
    try:
        para = json.loads((root / PARA).read_text()) if (root / PARA).exists() else {}
    except ValueError:
        para = {}
    meta, pin = para.get("meta", ""), para.get("pin", "")
    loc = meta_checkout(root, para) if para else None
    olds = dict(LAYOUT)
    for f, path, section, code, level, gap in dangling(root):
        line = f"{f} points to {gap}: "
        # Moved by this repo's move line, the pointer still dangles in the metarepo: the same
        # answer as any removal, a pointers proposal or a row, with where it went named.
        moved = "; the metarepo's rewrite is a pointers proposal (`jig propose --pointers`)" if "(moved: " in gap else ""
        found = removal(path, section, code, level)
        if found is None:
            out.append(line + "this repo never had it, so the metarepo's pointer is what's wrong; "
                       "fix it there with `jig propose`")
            continue
        commit, now = found
        what = (f"renamed to {now} in {commit}" if level == NO_FILE and now != "deleted"
                else f"removed in {commit}")
        # A branch answer from this repo's metarepo: its rewrite is pending until the pin holds
        # the branch. Once the pin holds it and the pointer still dangles, the rewrite missed it,
        # and nothing else will fix it. A metarepo out of reach can't say, so it stays pending.
        branches = [x.group("pbranch") or x.group("branch") for x in
                    trunk_answers(commit, Board.trunk_name(root), [f"{DIR}/specs/", *olds[f"{DIR}/specs/"]])
                    if (x.group("pbranch") or x.group("branch")) and (x.group("pmeta") or x.group("meta")) == meta]
        pinned = [b for b in branches if loc is not None and pin and proposal_in(loc, b, pin)]
        pending = [b for b in branches if b not in pinned]
        if pending:
            out.append(line + f"this repo {what}, and the metarepo's rewrite is pending on "
                       f"{pending[0]}: it resolves when the pin holds that branch")
            continue
        shown = shown_section(plain(section), code) if level == NO_HEADING else None
        where = f"{path} § {shown}" if shown else path
        missed = f"the metarepo's rewrite in {pinned[0]} missed it; " if pinned else ""
        out.append(line + f"this repo {what}; " + missed
                   + buffer_offer(root, f"{f}: the pointer to {where}", path, f"{now}, {commit}", shown) + moved)
    return out


def contract_removals(root: Path, trunk: str) -> list[str]:
    """Update's Contract removals block: each trunk commit that took a contract path away while
    nothing answered it, which an older P2 let through, and the one buffer.md row to offer for
    it. Each commit is judged by the contract_paths its parent's para.json held, which is what P2
    read then. Writes nothing."""
    olds = dict(LAYOUT)
    para_at = [PARA, *olds[PARA]]
    spec_dirs = [f"{DIR}/specs/", *olds[f"{DIR}/specs/"]]
    ledgers = [BUFFER, f"{DIR}/ledgers/BUFFER.md"] + [f"{d}BUFFER.md" for d in olds[f"{DIR}/ledgers/"]]
    rows = buffer_rows(at_rev(trunk, BUFFER))
    # The Metarepo pointers block already speaks for a path a cached pointer names.
    pointed = {p for _, p, _, _, _, _ in dangling(root)}
    # A path trunk has again, restored or re-added, was put back: nothing is owed.
    back = set(git("-c", "core.quotePath=false", "ls-tree", "-r", "--name-only", trunk).splitlines())
    try:
        today = json.loads(at_rev(trunk, PARA) or "{}").get("contract_paths") or []
    except ValueError:
        today = []
    out = []
    for line in git("log", "--no-merges", "-M", "--diff-filter=DR", "--format=%H %h %s", trunk, "--").splitlines():
        commit, short, subject = (line.split(" ", 2) + [""])[:3]
        raw = next((b for p in para_at if (b := at_rev(f"{commit}^", p))), "")
        try:
            globs = (json.loads(raw) if raw else {}).get("contract_paths") or []
        except ValueError:
            continue
        gone = [(o, n) for o, n in removed_by(commit) if matches(o, globs) and o not in back
                and not any(o == p or o.startswith(f"{p}/") for p in pointed) and not naming_row(rows, o, states=BUFFER_STATES)]
        if not gone:
            continue
        writes = git("-c", "core.quotePath=false", "show", "-M", "--name-only", "--diff-filter=ACMRT",
                     "--format=", commit).splitlines()
        if any(matches(w, globs) for w in writes):
            continue                    # P2 asked then, and its answer covers the commit
        if trunk_answers(commit, trunk, spec_dirs):
            continue
        added = git("show", "--format=", "-U0", commit, "--", *ledgers)
        if any(r[-1] == "Open" for l in added.splitlines() if l.startswith("+|") for r in buffer_rows(l[1:])):
            continue
        what = "; ".join(f"{o} → {n}" if n else f"{o} deleted" for o, n in gone)
        pin = json.loads(raw).get("pin") or "the pin"
        now = "; ".join(f"moved to {n}" if n else "deleted" for _, n in gone)
        text = (f"{short} {subject}: {what}: "
                + row_offer(f"the contract at {pin}: {', '.join(o for o, _ in gone)}", f"{now}, {short}"))
        for n in [n for _, n in gone if n and not matches(n, today)]:
            text += f"; {n} isn't a contract path: add it to contract_paths if it still holds the contract"
        out.append(text)
    return out


def removal_blocks(root: Path, trunk: str, always: bool) -> list[str]:
    """A pararepo update's Metarepo pointers and Contract removals blocks. ALWAYS, as a planned
    update's report shows them; otherwise only a block with something in it, so a repo that is
    up to date still hears of what an older P2 let through until it answers it."""
    out = []
    pointed = pointer_cleanup(root) if always or (root / CACHE).is_dir() else []
    if pointed:
        out += ["\nMetarepo pointers (from the cache as the last `jig sync` left it; update "
                "changes none of them):", *(f"  {l}" for l in pointed)]
    removed = contract_removals(root, trunk)
    if removed or always:
        out += ["\nContract removals (trunk commits an older P2 let take a contract path away "
                "unanswered; update changes none of them):", *(f"  {l}" for l in removed or ["none"])]
    return out


def cmd_propose(root: Path, args) -> int:
    para = json.loads((root / PARA).read_text()) if (root / PARA).exists() else None
    if para is None and (old := old_board(root)):
        # init refuses an older layout too, so naming it here would send someone in a circle.
        die(f"this repo is on an older jig layout ({old}): run `jig update` first; then, if it "
            "isn't a pararepo yet, `jig init --para <metarepo name>`", 2)
    if para is None:
        die(f"not a pararepo (no {PARA}): a proposal is a pararepo's branch on its metarepo. "
            "`jig init --para <metarepo name>` makes this one", 2)
    loc = meta_checkout(root, para)
    if loc is None:
        die(f"can't find {para['meta']}: run `jig repos add meta` in its checkout", 2)
    if args.withdraw:
        return withdraw_proposal(root, para, loc, args.withdraw, args.reason)
    if args.buffer:
        slug = args.slug or args.spec or f"buffer-{date.today().isoformat()}"
        made = buffer_proposal(root, para, loc, slug)
        moving = move_in_left(root, para["meta"])
        if made is None:
            print(f"nothing to propose: {BUFFER} has no Open row that a proposal doesn't already carry as it stands"
                  + (f"; {moving}." if moving else "."))
            return 0
        spec, branch = made
        print(f"made {branch} in {para['meta']} for every Open row of {BUFFER} but a move-in row, listed in "
              f"{spec.relative_to(root)}. Commit that spec." + (f" {moving[0].upper()}{moving[1:]}." if moving else ""))
        print(f"Write the change there on that branch (git -C {loc} worktree add <dir> {branch}); "
              f"the rows close when `jig sync` takes the release that holds it.")
        return 0
    if not (args.spec and args.slug):
        die("usage: jig propose <spec> <slug> [--pointers], or jig propose --buffer [slug]", 2)
    spec = root / args.spec
    if not spec.exists():
        die(f"no spec at {args.spec}", 2)
    branch = open_proposal(para, loc, args.slug)
    line = f"- meta: {para['meta']} {'pointers' if args.pointers else 'proposal'} {branch}"
    text = spec.read_text()
    if re.search(r"^## Decisions\s*$", text, re.M):
        text = re.sub(r"^(## Decisions\s*\n)", rf"\1{line}\n", text, count=1, flags=re.M)
    else:
        text = text.rstrip("\n") + f"\n\n## Decisions\n{line}\n"
    spec.write_text(text)
    print(f"made {branch} in {para['meta']} and recorded it in {args.spec}.")
    print(f"Write the change there on that branch (git -C {loc} worktree add "
          f"<dir> {branch}); it lands by the metarepo's own review and release.")
    return 0


def withdraw_proposal(root: Path, para: dict, loc: Path, branch: str, reason: str | None) -> int:
    """Mark a proposal the metarepo will never release as withdrawn, in the spec that names it.
    The metarepo's branch is the metarepo's to delete: a pararepo writes there only by proposing."""
    reason = (reason or "").strip()
    if not reason or "\n" in reason:
        die("usage: jig propose --withdraw <branch> --reason <text>", 2)
    name, pin = para["meta"], para["pin"]
    hits = [(spec, m) for spec in sorted((root / DIR / "specs").glob("*.md"))
            for m in PROPOSAL.finditer(spec.read_text())
            if m.group("branch") == branch and m.group("meta") == name]
    if not hits:
        die(f"no spec here says `meta: {name} proposal {branch}`", 2)
    git("fetch", "-q", "--tags", cwd=str(loc))
    if proposal_in(loc, branch, pin):
        die(f"{name} {pin}, the pin, already holds {branch}: a released proposal can't be withdrawn", 2)
    # Released above the pin, it isn't moot: the pin moves, and sync closes its rows.
    later = next((t for t in released_tags(str(loc)) if version_key(t) > version_key(pin)
                  and proposal_in(loc, branch, t)), None)
    if later:
        die(f"{name} {later} released {branch}: bump the pin instead (`jig sync` on trunk says how), "
            "and sync closes its rows", 2)
    for spec, m in hits:
        text = spec.read_text()
        line = re.sub(r"meta: \S+ proposal \S+", lambda _: f"meta: {name} withdrawn {branch} — {reason}",
                      m.group(0), count=1)
        spec.write_text(text[:m.start()] + line + text[m.end():])
        open_rows = {r[0]: r for r in buffer_rows((root / BUFFER).read_text() if (root / BUFFER).exists() else "")
                     if r[-1] == "Open"}
        rows = [i for i in listed_rows(text) if i in open_rows]
        # A move-in row is `jig move-in`'s alone: no release or buffer proposal carries it.
        moving = [i for i in rows if open_rows[i][2:3] == [MOVE_IN_NOW]]
        rest = [i for i in rows if i not in moving]
        print(f"withdrew {branch} in {spec.relative_to(root)}. Commit that spec."
              + (f" Its Open rows ({', '.join(rest)}) go again in the next proposal." if rest else "")
              + (f" Its move-in row ({', '.join(moving)}) goes again by `jig move-in`." if moving else ""))
    print(f"The branch stays in {name}; its owner deletes it there: git -C {loc} branch -D {branch}")
    return 0


def open_proposal(para: dict, loc: Path, slug: str) -> str:
    branch = f"propose/{main_root().name}-{slug}"   # the repo's name, not a job's folder
    if git("rev-parse", "-q", "--verify", f"refs/heads/{branch}", cwd=str(loc)):
        die(f"{branch} already exists in {para['meta']}", 2)
    # A branch from the metarepo's trunk, made without checking anything out: main is untouched.
    # Its opening commit is its own, so the metarepo's list of unmerged branches shows it before
    # anything is written on it; a branch at trunk's tip is merged already and listed nowhere.
    trunk = Board.trunk_name(loc)
    opening = git("commit-tree", f"{trunk}^{{tree}}", "-p", trunk, "-m",
                  f"{OPENING}{main_root().name}: nothing written yet", cwd=str(loc), check=True)
    git("branch", branch, opening, cwd=str(loc), check=True)
    return branch


def unproposed(root: Path, moving_in: bool = False) -> tuple[list[str], list[str]]:
    """The buffer's table header and its Open rows not yet proposed as they stand. A row a
    proposal already carries unchanged waits for that one; an edited row goes again. A move-in
    row (`jig move-in`'s) is that command's alone: only MOVING_IN lists it, so a release or
    `jig propose --buffer` never carries one into a proposal step 2 would take for its own."""
    text = (root / BUFFER).read_text() if (root / BUFFER).exists() else ""
    lines = [l for l in text.splitlines() if l.lstrip().startswith("|")]
    sent = proposed_rows([s.read_text() for s in sorted((root / DIR / "specs").glob("*.md"))])
    return ([l for l in lines if not buffer_rows(l)],
            [l for l in lines if buffer_rows(l) and buffer_rows(l)[0][-1] == "Open"
             and tuple(buffer_rows(l)[0]) not in sent
             and (moving_in or (buffer_rows(l)[0][2:3] or [""])[0] != MOVE_IN_NOW)])


def buffer_proposal(root: Path, para: dict, loc: Path, slug: str,
                    only: set[str] | None = None) -> tuple[Path, str] | None:
    """Every Open row of the buffer not yet proposed, in one proposal: a metarepo branch, and a
    spec here that lists the rows by id, which is the record of what went. None when no row
    is left to propose. ONLY: just those rows, as `jig move-in` proposes its own."""
    head, open_ = unproposed(root, moving_in=only is not None)
    open_ = [l for l in open_ if only is None or buffer_rows(l)[0][0] in only]
    if not open_:
        return None
    spec = root / DIR / "specs" / f"{slug}.md"
    if spec.exists():
        die(f"{spec.relative_to(root)} already exists: name the proposal (`jig propose --buffer <slug>`)", 2)
    branch = open_proposal(para, loc, slug)
    ids = "".join(f"- {buffer_rows(l)[0][0]}\n" for l in open_)
    table = "\n".join([*head, *open_])
    spec.parent.mkdir(parents=True, exist_ok=True)
    spec.write_text(
        f"# Buffer proposal: {slug}\n\n"
        f"Each row is a claim of {para['meta']} at {para['pin']} that this repo has moved away from. "
        f"For each row, {para['meta']} decides where the claim lives (rules-metarepo.md: What the metarepo holds). "
        f"A contract gets the new text with its source; a claim this repo owns gets a pointer to "
        f"the \"This repo now\" source wherever {para['meta']} states it, never a copy "
        f"(rules-metarepo.md: Newer wins, Every copy).\n\n"
        f"## Buffer rows\n{ids}\n{table}\n\n## Decisions\n- meta: {para['meta']} proposal {branch}\n")
    return spec, branch


# -------------------------------------------------------------------- staging

# Where a chat drops a file meant for this repo, or another. Untracked: nothing in it is
# authoritative, and it can reach a contract only through `jig staging resolve`.
STAGING = f"{DIR}/staging"
KINDS = ("spec", "doc", "decisions", "user-story", "feature-request", "feedback", "roadmap", "pin-bump")
HEADER_KEYS = ("staged", "target", "kind", "change", "destination", "source", "status")


def feedback_dir() -> Path:
    """Where a tool report waits when the jig repo isn't in repos.json: beside that list, so
    it survives a cleared temp folder and the same `jig staging` finds it from any repo."""
    return repos_file().parent / "feedback"


def staged_files(root: Path) -> list[Path]:
    d = root / STAGING
    # Markdown only: a .DS_Store or an editor's swap file is not a staged file.
    return sorted(f for f in d.iterdir() if f.is_file() and f.suffix == ".md") if d.exists() else []


def read_staged(path: Path) -> tuple[dict, str, list[str]]:
    """The header (a `key: value` block between --- lines), the body, and what's wrong."""
    text = path.read_text(errors="replace").replace("\r\n", "\n")
    m = re.match(r"---\n(.*?)\n---\n?(.*)", text, re.S)
    if not m:
        return {}, text, ["no header"]
    head = {}
    for line in m.group(1).splitlines():
        k, sep, v = line.partition(":")
        if sep:
            head[k.strip()] = v.strip()
    bad = [f"no {k}" for k in HEADER_KEYS if not head.get(k)]
    if head.get("kind") and head["kind"] not in KINDS:
        bad.append(f"kind {head['kind']!r} is not one of {', '.join(KINDS)}")
    if head.get("kind") == "feedback" and not head.get("from"):
        bad.append("no from: a report names the repo it came from")
    if head.get("change") and head["change"] not in ("new", "update"):
        bad.append(f"change {head['change']!r} is not new or update")
    if head.get("staged") and head["staged"] != "true":
        bad.append("staged is not true")
    # A file staged before the roadmap was JSON names its old path: the same roadmap.
    if head.get("kind") == "roadmap" and head.get("destination") and head["destination"] not in (ROADMAP, OLD_ROADMAP):
        bad.append(f"destination {head['destination']!r}: a roadmap change lands in {ROADMAP} only")
    if head.get("kind") == "pin-bump" and (head.get("destination") != PARA or head.get("change") != "update"):
        bad.append(f"a pin bump is `change: update` to {PARA} only")
    if head.get("moved-from") and not re.fullmatch(r"[\w.-]+/\S.*", head["moved-from"]):
        bad.append(f"moved-from {head['moved-from']!r} is not a pointer, <repo>/<path>[ § <heading or id>]")
    if head.get("moved-from") and head.get("kind") not in ("decisions", "doc"):
        bad.append("moved-from: only a decision entry, a page or a section moves between repos")
    if head.get("kind") == "pin-bump" and not head.get("release"):
        bad.append("no release: a pin bump names the release it moves the pin to")
    if head.get("kind") == "roadmap" and head.get("change") == "new":
        bad.append(f"change new: a roadmap change is `change: update` to {ROADMAP}")
    return head, m.group(2), bad


def provenance(head: dict, path: Path) -> str:
    """What a landed file carries to say where it came from. The staged file's name makes it
    one file's mark: two files from the same session can't stand in for each other."""
    return f"Source: {head.get('source', '')} (staged as {path.name})"


def staged_summary(root: Path) -> str:
    files = staged_files(root)
    if not files:
        return ""
    kinds = [read_staged(f)[0].get("kind", "?") for f in files]
    return f"{len(files)} staged in {STAGING}: " + ", ".join(
        f"{kinds.count(k)} {k}" for k in dict.fromkeys(kinds))


def fallback_files() -> list[Path]:
    d = feedback_dir()
    return sorted(d.glob("*.md")) if d.is_dir() else []


def release_waits_for() -> list[Path]:
    """The main checkout's staging, since staged files are never committed, and any report in
    the fallback folder aimed at this repo: it is staged here in all but location."""
    return staged_files(main_root()) + [f for f in fallback_files()
                                        if addressed_here(read_staged(f)[0].get("target", ""), main_root())]


def pin_bump(f: Path) -> bool:
    return read_staged(f)[0].get("kind") == "pin-bump"


def staged_refusal(what: str, pin_bumps_wait: bool = True) -> list[str]:
    """Release waits while anything is staged. Reading it only refuses more, so a branch can't
    weaken it. A pararepo's staged pin bump doesn't hold its release: the pin is its buffer."""
    files = [f for f in release_waits_for() if pin_bumps_wait or not pin_bump(f)]
    return [f"{what} waits while {len(files)} file{'s' if len(files) > 1 else ''} sit in "
            f"{STAGING} or {feedback_dir()}: {', '.join(f.name for f in files)}. Resolve or "
            f"drop each (`jig staging resolve` / `drop`), or force it"] if files else []


def this_repo_names(root: Path) -> set[str]:
    # The name from the trunk checkout's config alone: its jobs.json may be mid-edit, and a
    # handoff reading this must not fail on it.
    try:
        name = json.loads((main_root() / CONFIG).read_text()).get("name")
    except (OSError, ValueError, AttributeError):
        name = None
    names = {"this", name or main_root().name}
    # and any alias you gave this checkout in repos.json
    names |= {lb for n, e in load_repos().items() if Path(e["path"]).resolve() == main_root().resolve()
              for lb in {n} | repo_names(e)}
    meta = root / META
    if meta.exists():
        names.add(json.loads(meta.read_text() or "{}").get("name", ""))
    return names - {""}


def name_in(name: str | None, names: set[str]) -> bool:
    """A human types a repo's name, so `App` and `app` are one repo."""
    return (name or "").casefold() in {n.casefold() for n in names - {""}}


def names_this_repo(name: str | None, root: Path) -> bool:
    return name_in(name, this_repo_names(root))


def bare_path(dest: str) -> bool:
    """A header's destination is a path and nothing else: prose around it is never guessed at.
    A space counts as prose: "see docs/x.md" would otherwise land as a file of that name."""
    return dest.endswith(".md") and not re.search(r"[\s:,;]", dest)


def decision_id(cell: str) -> str:
    """D-2 and D-002 are one decision: the number counts, as R6 counts it."""
    return re.sub(r"\d+", lambda m: str(int(m.group())), cell.strip())


def after_names(head: dict) -> list[str]:
    """The staged files this one waits for: names, comma- or space-separated, a YAML list's
    brackets and quotes tolerated, `a` read as `a.md` since staged files are Markdown."""
    names = [Path(n).name for n in re.split(r"[,\s\[\]'\"]+", head.get("after", "")) if n]
    return [n if n.endswith(".md") else f"{n}.md" for n in names]


def batch_order(files: list[Path]) -> tuple[list[Path], dict[str, set[str]], set[str]]:
    """Files in an order where each comes after those its `after:` names, name order within a
    level; then, last since no order gets them through, each file in an `after` cycle with the
    cycle's members, and the files that only wait on one."""
    names = {f.name: f for f in files}
    edges = {f.name: {n for n in after_names(read_staged(f)[0]) if n in names and n != f.name}
             for f in files}
    waits = {n: set(w) for n, w in edges.items()}
    out: list[Path] = []
    while waits:
        ready = sorted(n for n, w in waits.items() if not w)
        if not ready:
            break
        for n in ready:
            out.append(names[n])
            del waits[n]
        for w in waits.values():
            w.difference_update(ready)

    def reach(n: str) -> set[str]:
        seen, todo = set(), list(waits.get(n, ()))
        while todo:
            m = todo.pop()
            if m not in seen:
                seen.add(m)
                todo += waits.get(m, ())
        return seen
    reaches = {n: reach(n) for n in waits}
    cycles = {n: {m for m in r if n in reaches[m]} for n, r in reaches.items() if n in r}
    return out + [names[n] for n in sorted(waits)], cycles, set(waits) - set(cycles)


def stuck_note(name: str, cycles: dict[str, set[str]], blocked: set[str]) -> str:
    if name in cycles:
        return f"after: in a cycle with {', '.join(sorted(cycles[name] - {name}))}"
    return "after: waits on a cycle" if name in blocked else ""


def escapes(dest: str) -> bool:
    """A destination is relative to the target's root and stays under it: no absolute path,
    no home folder, no drive, no `..` climbing out. `resolve` and `check` judge it alike."""
    return (dest.startswith(("/", "~", "\\")) or bool(re.match(r"[A-Za-z]:", dest))
            or os.path.normpath(dest).split(os.sep)[0] == "..")


def fill_roles(root: Path, text: str) -> tuple[str, str]:
    """A spec staged from a chat can't run `jig roles` against this repo's config, so its
    `## Roles` arrives empty: resolve writes the lines /jig:spec would, or refuses as it does.
    A section that holds anything but comments is the author's, and stays. A spec staged from
    an older template says `## Workflow`, filled alike."""
    head = re.search(r"^##[ \t]+(?:roles|workflow)\b.*$", text, re.I | re.M)
    nxt = re.search(r"^## ", text[head.end():], re.M) if head else None
    body = text[head.end():head.end() + nxt.start()] if nxt else text[head.end():] if head else ""
    if head and re.sub(r"<!--.*?-->", "", body, flags=re.S).strip():
        return text, ""
    roles, bad = role_settings(Board.load(root, working_tree=True).data)
    if bad:
        die("\n  ".join(["the spec's ## Roles is empty, and `jig roles` refuses:", *bad,
                         f"fix {CONFIG}, then resolve again"]), 1)
    lines = role_lines(roles)
    if not head:
        return text.rstrip("\n") + f"\n\n## Roles\n{lines}\n", "; ## Roles added"
    kept = body.strip("\n")
    rest = text[head.end() + nxt.start():] if nxt else ""
    return (text[:head.end()] + "\n" + (f"{kept}\n" if kept else "") + f"{lines}\n"
            + (f"\n{rest}" if rest else "")), "; ## Roles filled"


def cmd_staging_check(args) -> int:
    """Headers only, from the plugin's copy outside any repo: a chat writes a batch from
    outside the target and can't run `jig staging` there."""
    files = [Path(f).expanduser() for f in args.file]
    if not files:
        die("which files? jig staging check <file>…", 2)
    batch = {f.name for f in files}
    _, cycles, blocked = batch_order([f for f in files if f.is_file()])
    bad = False
    for f in files:
        if not f.is_file():
            print(f"{f}: no such file")
            bad = True
            continue
        head, body, problems = read_staged(f)
        notes = []
        if head.get("kind") == "decisions":
            # A warning only: resolve logs an Accepted entry as decided, and a chat can write
            # Accepted for what was only discussed; the owner says which. Outside any repo no
            # config names the prefix, so the entries' own headings do.
            prefix = log_prefix_of(body)
            for e in log_entries(body, prefix):
                parts = status_parts(e["status"], prefix)
                if parts and parts[0] == "Accepted":
                    said = f"{parts[1]}, {parts[2]}" if parts[1] else parts[2]
                    notes.append(f"{e['id']} says Accepted ({said}): resolve logs it as decided; "
                                 f"confirm {parts[1] or 'who'} accepted it, else write Proposed")
        dest = head.get("destination", "")
        if dest and escapes(dest):
            problems.append(f"destination {dest!r} is outside the target: give a path relative "
                            "to its root")
        target = head.get("target", "")
        there = repo_path(target) if target and target != "this" else None
        if target and target != "this" and not there:
            problems.append(f"target {unknown_repo(target)}")
        # A warning only: the owner may keep both names on purpose.
        for a, b in near_duplicates(load_repos()):
            if name_in(target, {a, b}):
                notes.append(f"target {target!r}: {a} and {b} are both in the repos list; "
                             "make sure it is the one you mean")
        have = batch | ({p.name for p in staged_files(there)} if there else set())
        problems += [f"after {n}: not in this batch or the target's staging"
                     for n in after_names(head) if n not in have]
        if stuck := stuck_note(f.name, cycles, blocked):
            problems.append(f"{stuck}: no order resolves it; fix one header's after:")
        print(f"{f.name}: {'ok' if not problems else ''}".rstrip())
        for p in problems:
            print(f"    {p}")
        for n in notes:
            print(f"    warning: {n}")
        bad |= bool(problems)
    return 1 if bad else 0


def cmd_staging(root: Path, args) -> int:
    ensure_roadmap(root)
    if args.action not in ("resolve", "drop"):
        # Staged files are never committed, so a detached worktree (a spec or bug session's)
        # lists the primary checkout's, as resolve and drop already read them.
        root = main_root()
        files, cycles, blocked = batch_order(staged_files(root))
        waiting = fallback_files()
        if not files and not waiting:
            print(f"nothing staged in {STAGING}")
            return 0
        if files:
            print(staged_summary(root))
        if waiting:
            why = "" if repo_path("jig") else " (the jig repo isn't in repos.json)"
            print(f"{len(waiting)} waiting in {feedback_dir()}{why}:")
        bad = False
        for f in files + waiting:
            head, _, problems = read_staged(f)
            origin = f", from {head['from']}" if head.get("from") else ""
            waits = f", after {', '.join(after_names(head))}" if after_names(head) else ""
            print(f"  {f.name}: {head.get('change', '?')} {head.get('kind', '?')} for "
                  f"{head.get('target', '?')} → {head.get('destination', '?')}{origin}{waits}")
            for p in problems:
                print(f"      {p}")
                bad = True
            # A waited-for file that isn't staged is gone: resolved, dropped or forwarded.
            # `check`, which sees the batch before it is staged, catches a misspelt name.
            if stuck := stuck_note(f.name, cycles, blocked):
                print(f"      {stuck}")
                bad = True
        return 1 if bad else 0

    if not args.file:
        die(f"which file? jig staging {args.action} <file>", 2)
    # Staged files live in the main checkout only: they are never committed into a job. A
    # report whose jig repo wasn't registered waits in the fallback folder instead.
    name = Path(args.file).name
    path = main_root() / STAGING / name
    if not path.exists():
        path = feedback_dir() / name
    if not path.exists():
        die(f"no {args.file} in {STAGING} or {feedback_dir()}", 2)
    if args.action == "drop":
        # A staged file was never committed, so a record of dropping it would point at nothing.
        path.unlink()
        print(f"dropped {path.name}")
        return 0
    head, body, problems = read_staged(path)
    if problems:
        die(f"{path.name}: {'; '.join(problems)}", 2)
    still = [n for n in after_names(head)
             if n != path.name and ((main_root() / STAGING / n).exists() or (feedback_dir() / n).exists())]
    if still:
        _, cycles, blocked = batch_order(staged_files(main_root()) + fallback_files())
        stuck = stuck_note(path.name, cycles, blocked)
        die(f"{path.name} waits for {', '.join(still)}, still staged: "
            + (f"{stuck}, so no order resolves it; fix one header's after:" if stuck else
               f"resolve or drop {'it' if len(still) == 1 else 'them'} first"), 1)
    kind, change, dest = (head.get(k, "") for k in ("kind", "change", "destination"))
    mark = provenance(head, path)

    target = head["target"]
    # The one lookup `staging check` and `jig inbox` use, so resolve never lands a file the
    # check read as another repo's.
    if not addressed_here(target, root):
        return forward(root, path, head)

    def done(msg: str) -> int:
        path.unlink()
        print(f"resolved {path.name}: {msg}")
        return 0

    came = head.get("moved-from", "")

    def moved_here(text: str, what: str) -> str:
        """The log TEXT with the moved-from line for WHAT, landed from `moved-from:`, in this job."""
        line = f"- {what}: moved from {came}."
        return text if line in text.splitlines() else log_with_line(text or LOG_SEED, "Added", line)

    def landed_as(where: str) -> str:
        """What the moved-from line names for a page landed at WHERE: the section, when one moved."""
        section = pointer_parts(came)[2]
        return f"{where} § {section}" if section else where

    def inside(rel: str) -> Path:
        """A destination stays inside the repo: no absolute path, no climbing out with .."""
        out = (root / rel).resolve()
        if escapes(rel) or not out.is_relative_to(root.resolve()):
            die(f"destination {rel!r} is outside this repo: give a path relative to its root", 2)
        return out

    def unanswered(spec: str) -> None:
        """A report resolves once its spec has its overlap answered: resolving is where the
        hubnode moves on, so an overlap left here would reach `jig open` unread."""
        if group := group_of(root, Board.load(root, working_tree=True), spec):
            die(group_refusal(group, f"{spec}, which carries `{mark}`,"), 1)

    def landed(rel: str, carrier: bool = False) -> bool:
        """The mark is in REL. A spec carrying a request holds it as a whole `Source:` line, as rig
        reads a carrier; a doc or spec update may hold it anywhere: a comment, a sentence, a list."""
        f = inside(rel)
        text = f.read_text(errors="replace") if f.exists() else None
        return text is not None and (carries(text, mark) if carrier else mark in text)

    if kind == "pin-bump":
        # The pin is this repo's buffer: it moves in a reviewed job that rewrites the uses the
        # request lists, never by resolving the request.
        trunk = Board.load(root, working_tree=True).trunk
        pin = json.loads(git("show", f"{trunk}:{PARA}") or "{}").get("pin") or ""
        if not pin or version_key(pin) < version_key(head["release"]):
            die(f"{path.name} waits for {trunk}'s {PARA} to pin {head['release']} (it pins "
                f"{pin or 'nothing'}): land it as a job (`/jig:spec` from it), whose pin commit carries "
                "the request as its body, with the uses it lists rewritten; then resolve again", 1)
        return done(f"{trunk} pins {pin}")
    if kind == "roadmap":
        # The roadmap carries no provenance lines, so the owner reads it as the plan; the
        # commit that applied the change on trunk carries the mark in its message instead.
        trunk = Board.load(root, working_tree=True).trunk
        if not git("log", trunk, "-F", f"--grep={mark}", "--format=%h", "--", ROADMAP):
            die(f"a roadmap change lands on {trunk}: write it with `jig roadmap --draft`, show the owner "
                f"the diff, `jig roadmap --edit` on a yes, and commit {ROADMAP} with `{mark}` in the "
                "message, then resolve again", 1)
        return done(f"applied to {ROADMAP} on {trunk}")
    if kind == "feature-request" and change == "update" and bare_path(dest):
        # The header names the spec the request changes; another spec carrying the mark would
        # resolve it while the named one is never amended.
        if not landed(dest, carrier=True) and (note := note_carrying(root, mark)):
            return done(f"carried by {note}")
        if not landed(dest, carrier=True):
            die(f"a request resolves into a spec: amend {dest}, the spec it names, from it, "
                f"carrying `{mark}`, then resolve again", 1)
        unanswered(dest)
        return done(f"carried by {dest}")
    if kind in ("user-story", "feature-request", "feedback"):
        specs = [s for s in (root / DIR / "specs").glob("*.md") if carries(s.read_text(), mark)]
        # Its spec has closed: the note that kept the spec's marks says what built it.
        if not specs and (note := note_carrying(root, mark)):
            return done(f"carried by {note}")
        if not specs:
            how = "write a new spec" if change == "new" else "amend the spec it extends"
            what = {"user-story": "a story", "feature-request": "a request"}.get(kind, "a report")
            die(f"{what} resolves into a spec: {how} under {DIR}/specs/ from it, carrying "
                f"`{mark}`, then resolve again", 1)
        for s in specs:
            unanswered(s.relative_to(root).as_posix())
        return done(f"carried by {specs[0].relative_to(root)}")
    if kind in ("spec", "doc") and not bare_path(dest):
        die(f"destination {dest!r} isn't a path yet: find the page, put its path in the header, "
            "then resolve again", 1)
    if kind == "decisions" and not (root / LOG).exists():
        # A repo `jig update` hasn't moved to the log yet keeps its register of rows until it does.
        return resolve_register(root, path, dest, change, body, mark, inside, done)
    if kind == "decisions" and not bare_path(dest):
        die(f"destination {dest!r} in the header isn't a path: put {LOG} in `destination:`, "
            "then resolve again", 1)
    if kind == "decisions" and dest != LOG:
        # One log per repo: a second register would hold decisions nobody reads or cites.
        die(f"`destination:` is {dest}, not {LOG}: decisions land in the repo's one log; fix "
            "the header, then resolve again", 1)
    if kind == "spec" and not dest.startswith(f"{DIR}/specs/"):
        dest = f"{DIR}/specs/{Path(dest).name}"
    if dest in RULES_NAMES:
        # A root rules file is loaded on every agent turn, so a provenance line there costs
        # every load: like the roadmap, the trunk commit that changed it carries the mark.
        # --full-history sees a mark on a job's merge commit, the usual way the file arrives.
        trunk = Board.load(root, working_tree=True).trunk
        if git("log", trunk, "--full-history", "-F", f"--grep={mark}", "--format=%h", "--", dest):
            return done(f"applied to {dest} on {trunk}")
        if change == "new" and not inside(dest).exists():
            inside(dest).write_text(body.lstrip("\n"))
            step = f"wrote {dest} with no mark in it: commit it"
        else:
            step = f"needs judgment: edit {dest} with this file's content and commit the edit"
        die(f"{step}, on {trunk} or in a job merged to {trunk}, with `{mark}` in the commit "
            "message, never in the file, then resolve again", 1)
    prefix = log_prefix(Board.trunk_name(root))
    if change == "update":
        if kind == "decisions":
            # An accepted entry is never edited, so an update is an Open entry edited in place or
            # a new accepted entry that supersedes and removes it: the log shows it once it's done.
            text = inside(dest).read_text() if inside(dest).exists() else ""
            have = {e["id"]: e["block"] for e in log_entries(text, prefix)}
            missing = [e["id"] for e in log_entries(body, prefix) if have.get(e["id"]) != e["block"]]
            if missing:
                die(f"edit {dest} so it shows {', '.join(missing)} as staged (a released entry is "
                    f"superseded by a new accepted entry that removes it in the same commit, never edited), "
                    f"then resolve again", 1)
            return done(f"entries confirmed in {dest}")
        if not landed(dest):
            die(f"needs judgment: edit {dest} with this file's content, keeping `{mark}` in it "
                "as provenance, then resolve again", 1)
        if came:
            inside(LOG).write_text(moved_here(inside(LOG).read_text() if inside(LOG).exists() else "", landed_as(dest)))
            return done(f"{dest} carries it; its moved-from line is in {LOG}")
        return done(f"{dest} carries it")
    if kind == "decisions":
        log = inside(dest)
        entries = log_entries(body, prefix)
        first = next((i for i, l in enumerate(body.splitlines()) if l.startswith("### ")), None)
        rest = [l for l in body.splitlines()[:first] if l.strip() and not l.lstrip().startswith(("#", "<!--"))]
        if rest or not entries:
            die(f"{path.name} holds {'no decision entries' if not entries else 'lines before its first entry'}: "
                f"each decision is `### {prefix}?<slug> <title>` with its status line under it", 1)
        decided = [e for e in entries if e["status"].startswith("Accepted")]
        ideas = [e for e in entries if not e["status"].startswith("Accepted")]
        problems = log_problems("## Unreleased\n\n" + "\n\n".join(e["block"] for e in decided), prefix)
        problems += ideas_problems("\n\n".join(e["block"] for e in ideas), "", prefix)
        problems = [p for p in problems if "supersedes" not in p]
        if problems:
            die("\n  ".join([f"{path.name} isn't ready for the log:", *problems]), 1)
        # An open question is an idea, appended to the ideas file beside the log; an accepted
        # entry is this release's.
        ideas_file = log.with_name(Path(IDEAS).name)
        text = log.read_text() if log.exists() else LOG_SEED
        ideas_text = ideas_file.read_text() if ideas_file.exists() else IDEAS_SEED
        have = {decision_id(e["id"]) for e in log_entries(with_ideas(text, ideas_text), prefix)}
        dupes = [e["id"] for e in entries if decision_id(e["id"]) in have]
        if dupes:
            die(f"{', '.join(dupes)} already in {dest} or its ideas file: stage it as `change: update`", 1)
        if came and len(entries) != 1:
            die(f"{path.name} moves one claim (`moved-from: {came}`) but holds {len(entries)} entries: "
                "stage one entry per moved claim", 1)
        for e in decided:
            if not re.search(r"^## Unreleased[ \t]*$", text, re.M):
                text = text.rstrip("\n") + "\n\n## Unreleased\n"
            text = re.sub(r"^## Unreleased[ \t]*\n", lambda m: f"{m.group(0)}\n{e['block']}\n", text,
                          count=1, flags=re.M)
        for e in ideas:
            ideas_text = ideas_text.rstrip("\n") + f"\n\n{e['block']}\n"
        if came:
            # Numbered with its entry or idea at the merge: number_placeholders renames the id
            # everywhere. Its moved-from line is the log's either way.
            text = moved_here(text, entries[0]["id"])
        log.parent.mkdir(parents=True, exist_ok=True)
        said = []
        if decided or came:
            log.write_text(text)
        if decided:
            said.append(f"{len(decided)} entr{'ies' if len(decided) > 1 else 'y'} added to {dest}")
        if ideas:
            ideas_file.write_text(ideas_text)
            idea_at = str(Path(dest).with_name(Path(IDEAS).name))
            said.append(f"{len(ideas)} idea{'s' if len(ideas) > 1 else ''} added to {idea_at}")
        return done(", ".join(said) + (", with its moved-from line" if came else ""))
    out = inside(dest)
    if out.exists():
        die(f"{dest} exists: stage it as `change: update`, or pick another path", 1)
    out.parent.mkdir(parents=True, exist_ok=True)
    filled = ""
    if kind == "spec":
        first, _, rest = body.lstrip("\n").partition("\n")
        text, filled = fill_roles(root, f"{first}\n\n{mark}\n{rest}" if first.startswith("#")
                                     else f"{mark}\n\n{body}")
        out.write_text(text)
    else:
        out.write_text(body.rstrip("\n") + f"\n\n---\n{mark}\n")
    if came:
        inside(LOG).write_text(moved_here(inside(LOG).read_text() if inside(LOG).exists() else "", landed_as(dest)))
        filled += f", with its moved-from line in {LOG}"
    return done(f"written to {dest}{filled}")


def resolve_register(root: Path, path: Path, dest: str, change: str, body: str, mark: str,
                     inside, done) -> int:
    """Staged decisions in a repo with no log yet: rows appended to the register, as before it."""
    if not bare_path(dest):
        die(f"destination {dest!r} in the header isn't a path: put only the register's "
            "path in `destination:`, then resolve again", 1)
    if (root / META).exists():
        # A misspelt register (DECISION.md) would start a second one nobody cites.
        entry = {**META_DEFAULTS, **json.loads((root / META).read_text() or "{}")}["entry_files"]
        if not is_entry(dest, entry):
            die(f"destination {dest} isn't a register {META}'s entry_files name "
                f"({', '.join(entry)}): fix the header, or add it there first", 1)
    reg = inside(dest)
    rows = decision_rows(body, root)
    if change == "update":
        text = reg.read_text() if reg.exists() else ""
        missing = [r for r in rows if r not in text]
        if missing or mark not in text:
            die(f"edit {reg.relative_to(root.resolve())} so it shows these rows and carries "
                f"`{mark}`, then resolve again", 1)
        return done(f"rows confirmed in {reg.relative_to(root)}")
    rest = [l for l in body.splitlines() if l.strip() and l.rstrip() not in rows
            and not l.lstrip().startswith(("|---", "| Id", "#", "<!--"))]
    if rest:
        die(f"{len(rest)} line{'s' if len(rest) > 1 else ''} in {path.name} aren't decision "
            "rows: apply them with the owner, delete them from the staged file, then resolve "
            "again", 1)
    if not rows:
        die(f"no decision rows in {path.name}", 1)
    text = reg.read_text() if reg.exists() else "| Id | Decision | Status | Date |\n|---|---|---|---|\n"
    have = {decision_id(l.split("|")[1]) for l in text.splitlines() if l.startswith("|") and l.count("|") > 2}
    dupes = [r.split("|")[1].strip() for r in rows if decision_id(r.split("|")[1]) in have]
    if dupes:
        die(f"{', '.join(dupes)} already in {reg.name}: stage it as `change: update`", 1)
    reg.parent.mkdir(parents=True, exist_ok=True)
    reg.write_text(text.rstrip("\n") + "\n" + "\n".join(rows) + "\n")
    ids = ", ".join(r.split("|")[1].strip() for r in rows)
    # In a metarepo, M3 refuses the commit on a branch with no line yet: that's its rule
    # to enforce, not staging's line to write.
    also = f"; add `- {ids}. {mark}` to {CHANGELOG} (M3)" if (root / META).exists() else ""
    return done(f"{len(rows)} row{'s' if len(rows) > 1 else ''} appended to {reg.name}{also}")


def decision_rows(body: str, root: Path) -> list[str]:
    meta = root / META
    # A metarepo's ids are its decision_prefix, defaulted like everywhere else; a plain repo's
    # register has no configured prefix, so any uppercase one is taken.
    known = ({**META_DEFAULTS, **json.loads(meta.read_text() or "{}")}["decision_prefix"]
             if meta.exists() else None)
    prefix = re.escape(known) if known else r"[A-Z][A-Z0-9]*-"
    rx = re.compile(rf"^\s*\|\s*{prefix}\d+\s*\|")
    return [l.rstrip() for l in body.splitlines() if rx.match(l)]


def forward(root: Path, path: Path, head: dict) -> int:
    """A staged file is resolved in its target. From here it moves into the target's own
    staging, the one place jig writes in another repo, after checking both sides agree."""
    target = head["target"]
    there = repo_path(target)
    if not there and len(repo_matches(target)) > 1:
        die(f"refused: {unknown_repo(target)}", 2)
    if not there:
        die(f"{target} isn't this repo and isn't in {repos_file()}: "
            f"jig repos add {target} <path>", 2)
    there = Path(there)
    if old := old_board(there):
        die(f"{target} at {there} is on an older jig layout ({old}): run `jig update` there "
            "first, then resolve again", 2)
    if not (there / DIR).is_dir():
        die(f"{target} is listed at {there}, but that isn't a jig repo (no {DIR}/): fix it "
            f"with `jig repos add {target} <path>`", 2)
    me = Board.load(root, working_tree=True).data.get("name") or main_root().name
    para = json.loads((root / PARA).read_text()) if (root / PARA).exists() else None
    meta = json.loads((root / META).read_text()) if (root / META).exists() else None
    if para and target == para.get("meta"):
        theirs = json.loads(git("show", f"HEAD:{META}", cwd=str(there)) or "{}")
        if me not in theirs.get("pararepos", []):
            die(f"{target}'s {META} doesn't list {me} as a pararepo: add it there "
                "first", 2)
    if meta and target in meta.get("pararepos", []):
        theirs = json.loads((there / PARA).read_text()) if (there / PARA).exists() else {}
        if theirs.get("meta") != meta.get("name"):
            die(f"{target}'s {PARA} doesn't cite {meta.get('name')}: run `jig init --para` there "
                "first", 2)
    dest = there / STAGING / path.name
    if dest.exists():
        die(f"{target} already has {STAGING}/{path.name}", 2)
    dest.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(path), dest)
    print(f"forwarded {path.name} to {target}'s {STAGING}/; resolve it in a session there.")
    if para and target == para.get("meta"):
        print(f"If a spec here depends on it: jig propose <spec> <slug>.")
    return 0


# -------------------------------------------------------------------- roadmap

# Every stand-alone repo and metarepo keeps a roadmap, its structure there even when empty, so
# work left for later always has a home; a pararepo plans from its metarepo's. Phases and scopes are the owner's decisions; their states are derived from specs and the
# handoffs that landed them, so the file never takes a progress edit.
ROADMAP = f"{DIR}/roadmap.json"
SPECS = f"{DIR}/specs/"
HANDOFFS = f"{DIR}/handoffs/"


class Snapshot:
    """Where the roadmap's inputs are read from: a commit (trunk), the index (a merge being
    committed, which the view must describe), or the trunk checkout's files (`--write`, which
    a roadmap edit regenerates before it is committed)."""
    def __init__(self, rev: str = "", where: str = "rev", cwd: Path | None = None):
        # CWD: another repo's checkout, read at REV (its trunk), for the one roadmap's states.
        self.rev, self.where, self.cwd = rev, where, cwd

    def ls(self, folder: str) -> list[str]:
        # Tracked files only, in both checkout modes: an untracked spec draft or note isn't
        # work merge or `jig roadmap` would see. An unmerged path is listed once per stage.
        args = (["ls-tree", "-r", "--name-only", self.rev, "--", folder] if self.where == "rev"
                else ["ls-files", "--", folder])
        out = git("-c", "core.quotePath=false", *args, cwd=str(self.cwd or main_root())).splitlines()
        return list(dict.fromkeys(p for p in out if p))

    def show(self, path: str) -> str:
        if self.where == "files":
            p = main_root() / path
            return p.read_text(errors="replace") if p.is_file() else ""
        return git("show", f"{':' if self.where == 'index' else self.rev + ':'}{path}",
                   **({"cwd": str(self.cwd)} if self.cwd else {}))

    def landed(self, commit: str) -> bool:
        """The note's commit is in this tree's history. Mid-merge that history is both parents."""
        if self.where == "rev":
            return is_ancestor(commit, self.rev, self.cwd)
        merge = git("rev-parse", "-q", "--verify", "MERGE_HEAD", cwd=str(main_root()))
        return any(is_ancestor(commit, t) for t in ["HEAD"] + ([merge] if merge else []))


# Unindented, so a nested note under a scope is never a scope; no space or `/` in the name,
# since the id is <phase>/<scope> and is written on one line in specs.
SCOPE_LINE = re.compile(r"- `?([A-Za-z0-9][\w.-]*)`?(?::\s*(.*))?")
SCOPE_ID = re.compile(r"[A-Za-z0-9][\w.-]*")


# The one roadmap section that isn't a phase: work with no phase, in no order, parked mid-build
# or not started, one place for both. Its ids are `No phase/<id>`, so a spec takes one as it
# takes a scope, and its states are derived the same way; it is never current, since a last
# phase would be ordered and made current. An item naming pages is one rig offers; the pages
# alone decide that. Reserved by name, so no phase can be called it.
NO_PHASE = "No phase"
# The section the one list replaced: `jig update --apply` folds it into No phase, and the hook
# then refuses its heading, so parked work never has two homes again.
UP_NEXT = "Up next"
# `(touches docs/a.md, docs/b.md)` at the end of a list item or a scope: the pages the work
# will change, which reading-list and fold-in look items up by.
TOUCHES = re.compile(r"\s*\(touches\s+([^()]*)\)\s*$")
RESERVED = (UP_NEXT.lower(), NO_PHASE.lower())


def split_touches(what: str) -> tuple[str, list[str]]:
    """An item's text without its `(touches …)`, and the pages it names."""
    m = TOUCHES.search(what)
    if not m:
        return what, []
    pages = [p.strip().strip("`") for p in m.group(1).split(",") if p.strip()]
    return what[:m.start()].rstrip(), pages


# `(after alpha/host, beta)` at the end of a scope, before any `(touches …)` so TOUCHES stays
# anchored at the line's end: what the scope waits on. A line of its own in a phase's note is
# the phase's, and applies to each of its scopes. A ref is `<phase>/<scope>` or `<phase>`.
AFTER = re.compile(r"\s*\(after(?:\s+([^()]*))?\)\s*$")


# `(needed by App alpha/pairing)` on a scope, or a line of its own in a phase: the waits on
# it this section confirms. Another product's `(after …)` it doesn't confirm is flagged for the
# owner, never blocking: the owner, 2026-11-21, asked jig to flag them for the owner to rule on.
NEEDED = re.compile(r"\s*\(needed by(?:\s+([^()]*))?\)\s*$")


def split_after(what: str) -> tuple[str, list[str] | None]:
    """A scope's text without its `(after …)` and `(needed by …)`, `(touches …)` kept, and the
    refs its `(after …)` names: None when it names no wait, [] when the parentheses hold
    nothing."""
    body, after, _, _ = split_waits(what)
    return body, after


# `(labels teleport, wallet-compatibility)` on a scope or a `No phase` item: the features it
# touches, each a glossary term (R1–R3, R7). Never a ref: a label orders nothing. Read only by
# split_labels and checked only by label_problems, so every reader of labels (the roadmap, the
# ideas log) reads and checks them one way.
LABELS = re.compile(r"\s*\(labels(?:\s+([^()]*))?\)\s*$")


def split_labels(what: str) -> tuple[str, list[str] | None]:
    """WHAT without the `(labels …)` that ends it, and the labels it names: None when it ends in
    none, [] when the parentheses hold nothing."""
    m = LABELS.search(what)
    if not m:
        return what, None
    return what[:m.start()].rstrip(), refs_of(m.group(1))


def label_fold(name: str) -> str:
    """A label or a term as it is compared: case folded, each run of spaces, `-` and `_` one
    `-`, so the scope-style `wallet-compatibility` names the heading `Wallet compatibility`."""
    return re.sub(r"[\s_-]+", "-", name.casefold()).strip("-")


def label_problems(labels: list[str] | None, glossary_text: str | None, where: str,
                   glossary: str = GLOSSARY) -> list[str]:
    """Each way LABELS, written at WHERE (`line <n>: scope <id>`), fails the glossary
    GLOSSARY_TEXT (None when there is none): a label naming no term, after label_fold, or a
    `(labels)` naming nothing. GLOSSARY is the file as a refusal names it."""
    if labels is None:
        return []
    if not labels:
        return [f"{where} has (labels) naming nothing"]
    if glossary_text is None:
        return [f"{where} labels {', '.join(labels)}, but there is no {glossary}: a label is a term "
                "of it, so it goes in first"]
    terms = {label_fold(t) for t in glossary_terms(glossary_text)}
    return [f"{where} labels {l}, which {glossary} has no term for: a label is a term of it, any "
            "case and spacing" for l in labels if label_fold(l) not in terms]


def split_waits(what: str) -> tuple[str, list[str] | None, list[str] | None, list[str] | None]:
    """(text, after refs, needed-by refs, labels): the trailing `(after …)`, `(needed by …)`,
    `(labels …)` and `(touches …)`, in any order, split off, the `(touches …)` written back at
    the end of the text, where its readers look; None for one not written. Peeled in a loop, so
    no order of the four can hide a wait or a label as plain text; one written twice is read
    whole, refs, labels and pages joined, and repeated_waits names it for the hook to refuse."""
    head, after, needed, touches, lists, labels = what, None, None, None, 0, None
    while True:
        if (lb := split_labels(head))[1] is not None:
            head, labels = lb[0], lb[1] + (labels or [])
        elif t := TOUCHES.search(head):
            touches, head = (t.group(1) if touches is None else f"{t.group(1)}, {touches}"), head[:t.start()]
            lists += 1
        elif a := AFTER.search(head):
            after, head = refs_of(a.group(1)) + (after or []), head[:a.start()]
        elif n := NEEDED.search(head):
            needed, head = refs_of(n.group(1)) + (needed or []), head[:n.start()]
        else:
            break
    # Unchanged unless something was split off or joined: one `(touches …)` stays as written.
    if after is None and needed is None and labels is None and lists < 2:
        return what, None, None, None
    return head.rstrip() + (f" (touches {touches})" if touches is not None else ""), after, needed, labels


def phase_waits(line: str) -> tuple[list[str] | None, list[str] | None] | None:
    """(after refs, needed-by refs) when LINE is nothing but `(after …)` and `(needed by …)`, in
    either order, as a phase writes its own: None for any other line, which is note prose."""
    head, after, needed, _ = split_waits(line.strip())
    return (after, needed) if not head.strip() and (after is not None or needed is not None) else None


def phase_labels(line: str) -> bool:
    """Whether LINE is nothing but trailing parentheses, one of them `(labels …)`: a phase's
    own labels, which R6 doesn't have (labels sit on scopes), so the hook refuses it rather
    than keep it as note prose."""
    head, _, _, labels = split_waits(line.strip())
    return not head.strip() and labels is not None


def repeated_waits(what: str) -> list[str]:
    """Each of `(after …)`, `(needed by …)`, `(labels …)` and `(touches …)` that WHAT's tail
    writes twice: one names all it holds, so a second is refused rather than half-read."""
    head, seen, out = what, set(), []
    while True:
        kind = ""
        if (lb := split_labels(head))[1] is not None:
            kind, head = "labels", lb[0]
        else:
            for k, rx in (("touches", TOUCHES), ("after", AFTER), ("needed by", NEEDED)):
                if m := rx.search(head):
                    kind, head = k, head[:m.start()]
                    break
        if not kind:
            return out
        if kind in seen and kind not in out:
            out.append(kind)
        seen.add(kind)


def refs_of(text: str | None) -> list[str]:
    return [r.strip().strip("`").strip() for r in (text or "").split(",") if r.strip().strip("`").strip()]


def parse_no_phase(text: str, problems: list[str] | None = None) -> list[dict]:
    """The one list's items, each {id, sid, what, text, touches, after, line}, in file order:
    WHAT without its `(after …)` and `(touches …)`, TEXT without its `(after …)` only, as a
    scope's text is kept, and SID its id as a `Scope:` line names it."""
    return parse_section(text, NO_PHASE, problems)


def is_list_heading(name: str, section: str = NO_PHASE) -> bool:
    """`## No phase`, or a product's `## <Product> No phase`: a list, never a phase."""
    n = name.strip().lower()
    return n == section.lower() or (section == NO_PHASE and n.endswith(" " + NO_PHASE.lower()))


def parse_section(text: str, section: str, problems: list[str] | None = None) -> list[dict]:
    """An old roadmap.md's reserved section's items, `(after …)` and `(touches …)` split off,
    each with the heading of its LIST, which is its id's first part. The conversion's alone."""
    problems = [] if problems is None else problems
    shape = "<what it is>"
    items: list[dict] = []
    inside, fence, at = False, False, section
    last = None     # the item an indented line hangs under: one of this list, or none yet
    for n, raw in enumerate(text.split("\n"), 1):
        line = raw.rstrip()
        if line.lstrip().startswith("```"):
            fence = not fence
            continue
        if fence:
            continue
        if m := re.match(r"##\s+(.+?)$", line):
            inside = is_list_heading(m.group(1), section)
            at = m.group(1).strip()
            last = None
            continue
        if inside and line.strip() and line[0] in " \t":
            # Lines nested under an item (fold_up_next kept them) are its text. One before its
            # list's first item hangs under nothing: the conversion's check names it.
            if last is not None:
                last["more"].append(line)
            continue
        if not inside or not line.strip() or line[0] in " \t":
            continue
        m = SCOPE_LINE.fullmatch(line)
        if not m and re.fullmatch(r"(?i)(exit when|scopes):", line.strip()):
            # A phase already called this reads as the reserved section, so say why it changed.
            problems.append(f"line {n}: ## {at} is a reserved section, not a phase: rename "
                            f"the phase to keep its {line.strip()}")
            continue
        if not m:
            problems.append(f"line {n}: not a {at} item (- `<id>`: {shape}, "
                            f"unindented): {line.strip()}")
            continue
        body, refs, needed, labels = split_waits((m.group(2) or "").strip())
        for kind in repeated_waits((m.group(2) or "").strip()):
            problems.append(f"line {n}: {at} item {m.group(1)} has a second ({kind} …): one names all it holds")
        what, pages = split_touches(body)
        if any(i["sid"] == f"{at}/{m.group(1)}" for i in items):
            problems.append(f"line {n}: {at} item {m.group(1)} appears twice")
        if refs == []:
            problems.append(f"line {n}: {at} item {m.group(1)} has (after …) naming nothing")
        items.append({"id": m.group(1), "sid": f"{at}/{m.group(1)}", "what": what, "text": body,
                      "touches": pages, "after": refs or [], "needed": needed or [], "line": n, "list": at,
                      "labels": labels, "more": []})
        last = items[-1]
    return items


def list_phase(items: list[dict]) -> dict:
    """The one list in a phase's shape, so its items are read, checked and given states as
    scopes are. It is never a phase: no phase line, no current, and no ref names it."""
    return {"name": NO_PHASE, "exit": [], "line": 0, "headed": True, "note": [], "after": [],
            "after_line": 0, "scopes": [(i["sid"], i["text"]) for i in items],
            "after_of": {i["sid"]: (i["after"], i["line"]) for i in items if i["after"]}}


def renames(rev: str, staged: bool = True) -> dict[str, str]:
    """Every file the change renames from REV, old path to new, across the whole tree: a page
    moved into docs/ from outside is a rename too, and git sees one only with both sides in view."""
    out = {}
    for line in git("-c", "core.quotePath=false", "diff", *(["--cached"] if staged else []), "-M",
                    "--name-status", rev).splitlines():
        parts = line.split("\t")
        if parts[0].startswith("R") and len(parts) == 3:
            out[parts[1]] = parts[2]
    return out


def page_moves(rev: str) -> dict[str, str]:
    """The docs pages the index renames from REV, old path to new. A move between a page's two
    forms is no move: both name the page."""
    return {a: b for a, b in renames(rev).items()
            if a.startswith("docs/") and b.startswith("docs/") and not same_page(a, b)}


def records_in(data: dict, keep=lambda heading: True):
    """Each (heading key, record) of DATA's phases' scopes and its items, in sections KEEP accepts."""
    for p in data.get("phases") or []:
        if isinstance(p, dict) and keep(phase_key(p)):
            for s in p.get("scopes") or []:
                if isinstance(s, dict):
                    yield phase_key(p), s
    for i in data.get("no_phase") or []:
        if isinstance(i, dict) and keep(list_key(str(i.get("product") or ""))):
            yield list_key(str(i.get("product") or "")), i


def retarget_touches(raw: str, moves: dict[str, str], keep=lambda heading: True) -> str:
    """The roadmap file RAW with each `touches` page MOVES renames written at its new path, in the
    sections whose key KEEP accepts: a section another repo owns names that repo's pages, which
    this repo's move never renames."""
    data = roadmap_load(raw)
    if not moves or data is None:
        return raw
    for _, r in records_in(data, keep):
        if r.get("touches"):
            r["touches"] = [next((to for old, to in moves.items() if same_page(str(p).strip("`"), old)), p)
                            for p in r["touches"]]
    return roadmap_dumps(data)


def parse_roadmap(text: str, problems: list[str] | None = None) -> list[dict]:
    """An old roadmap.md's phases in file order, each {name, exit: [(ticked, text)], scopes:
    [(id, what)]}, for the conversion alone: roadmap.json is read by roadmap_phases.
    Anything it can't read is added to PROBLEMS by line, never dropped quietly: a scope lost
    to a typo would read as a phase with less work in it. Fenced code is skipped, so a roadmap
    that quotes an example doesn't grow phases. `## No phase` is no phase: parse_no_phase
    reads it; an old `## Up next` is reported, for `jig update` to fold. A phase's note is the
    prose before its first list or box, fences kept: a box there stays unparsed, as before notes, so it never shows under a done phase.
    PRE holds every line above `Exit when:` and `Scopes:`, each with whether a fence holds it:
    the note the conversion carries whole."""
    problems = [] if problems is None else problems
    phases: list[dict] = []
    part, fence, ids, skip = "", False, set(), False
    for n, raw in enumerate(text.split("\n"), 1):
        line = raw.rstrip()
        in_pre = phases and not skip and not part
        in_note = in_pre and phases[-1]["noting"]
        if line.lstrip().startswith("```"):
            fence = not fence
            if in_note:
                phases[-1]["note"].append(line)
            if in_pre:
                phases[-1]["pre"].append((line, True))
            continue
        if fence:
            if in_note:
                phases[-1]["note"].append(line)
            if in_pre:
                phases[-1]["pre"].append((line, True))
            continue
        if in_pre and not re.match(r"##\s+", line) and not re.fullmatch(r"(?i)(exit when|scopes):", line.strip()):
            # Every line above Exit when: and Scopes:, list or not: an old roadmap.md's note whole.
            phases[-1]["pre"].append((line, False))
        if m := re.match(r"##\s+(.+?)$", line):
            skip = m.group(1).strip().lower() in RESERVED or is_list_heading(m.group(1))
            if m.group(1).strip().lower() == UP_NEXT.lower():
                problems.append(f"line {n}: ## {UP_NEXT} is folded into ## {NO_PHASE}, the one list "
                                f"for work with no phase: move its items there (`jig update --apply` "
                                "folds them, ids and text kept)")
            if skip:
                continue
            if any(p["name"] == m.group(1) for p in phases):
                problems.append(f"line {n}: phase {m.group(1)} appears twice")
            phases.append({"name": m.group(1), "exit": [], "scopes": [], "line": n, "headed": False,
                           "note": [], "noting": True, "pre": [], "after": [], "after_line": 0, "after_of": {},
                           "needed": [], "needed_of": {}, "labels_of": {}})
            part = ""
        elif skip or not phases:
            continue
        elif phase_labels(line):
            # R6: a phase has scopes, and the scopes have labels. Kept as prose, a label would
            # name a feature nothing reads.
            problems.append(f"line {n}: phase {phases[-1]['name']} has a (labels …) line of its own: "
                            "labels sit on its scopes, each scope naming its own")
            if in_note:
                phases[-1]["note"].append(line)
        elif part != "scopes" and (w := phase_waits(line)):
            # The phase's waits, read wherever they sit outside Scopes:, `(after …)` and
            # `(needed by …)` on one line or two, so none is ever dropped as note prose and its
            # scopes offered as free work.
            after, needed = w
            name = phases[-1]["name"]
            if in_note:
                phases[-1]["note"].append(line)
            for kind in repeated_waits(line.strip()):
                problems.append(f"line {n}: phase {name} has a second ({kind} …): one names all it holds")
            if after is not None:
                if phases[-1]["after_line"]:
                    problems.append(f"line {n}: phase {name} has a second (after …) line: one line names "
                                    "all it waits on")
                phases[-1]["after"], phases[-1]["after_line"] = after, n
                if not after:
                    problems.append(f"line {n}: phase {name} has (after …) naming nothing")
            if needed is not None:
                if phases[-1].get("needed_line"):
                    problems.append(f"line {n}: phase {name} has a second (needed by …) line: one line "
                                    "names all that waits on it")
                phases[-1]["needed"], phases[-1]["needed_line"] = needed, n
        elif not part and re.match(r"\s*[-*+] ", line):
            phases[-1]["noting"] = False
        elif not part and phases[-1]["noting"] and not re.fullmatch(r"(?i)(exit when|scopes):", line.strip()):
            phases[-1]["note"].append(line)
        elif re.fullmatch(r"(?i)exit when:", line.strip()):
            part, phases[-1]["headed"], phases[-1]["has_exit"] = "exit", True, True
        elif re.fullmatch(r"(?i)scopes:", line.strip()):
            part, phases[-1]["headed"] = "scopes", True
        elif part == "exit" and (m := re.match(r"\s*- \[([ xX])\]\s*(.*)", line)):
            phases[-1]["exit"].append((m.group(1) != " ", m.group(2).strip()))
        elif part == "scopes" and line.strip():
            m = SCOPE_LINE.fullmatch(line)
            if not m:
                problems.append(f"line {n}: not a scope (- `<scope>`: <what it is>, unindented, "
                                f"its name with no space or /): {line.strip()}")
                continue
            sid = f"{phases[-1]['name']}/{m.group(1)}"
            if sid in ids:
                problems.append(f"line {n}: scope {sid} appears twice")
            ids.add(sid)
            what, refs, needed, labels = split_waits((m.group(2) or "").strip())
            for kind in repeated_waits((m.group(2) or "").strip()):
                problems.append(f"line {n}: scope {sid} has a second ({kind} …): one names all it holds")
            if labels is not None:
                phases[-1]["labels_of"][sid] = (labels, n)
            if refs is not None:
                phases[-1]["after_of"][sid] = (refs, n)
                if not refs:
                    problems.append(f"line {n}: scope {sid} has (after …) naming nothing")
            if needed:
                phases[-1]["needed_of"][sid] = needed
            phases[-1]["scopes"].append((sid, what))
    for p in phases:
        del p["noting"]
        p["note"] = "\n".join(p["note"]).strip("\n").splitlines()
        if not p["headed"]:
            problems.append(f"line {p['line']}: phase {p['name']} has neither `Exit when:` nor "
                            f"`Scopes:` (every `## ` heading but ## {NO_PHASE} is a phase)")
    return phases


# The one example of each roadmap record: its fields and their types, said once. `jig update`
# writes each as the repo's template, and the commit check compares every record with it, so a
# field the example lacks, or one of another type, is refused (the owner: "once in jig.py, the
# template a copy").
ROADMAP_RECORDS = {
    "phase": {"product": "Product", "name": "alpha", "note": "What the phase is for, in prose.",
              "exit": [{"text": "What is true when the phase is done", "done": False}],
              "after": ["Product beta/scope"], "needed_by": ["Other alpha/scope"], "scopes": []},
    "scope": {"id": "scope", "text": "What the scope builds", "labels": ["feature"],
              "touches": ["docs/page.md"], "after": ["alpha/other"], "needed_by": ["Other alpha/scope"]},
    "no_phase": {"id": "item", "text": "What the work is", "labels": ["feature"],
                 "touches": ["docs/page.md"], "after": ["alpha/scope"], "needed_by": ["Other alpha/scope"],
                 "product": "Product", "stopped_at": "Where the work stopped", "parked": "2026-01-31"},
}
ROADMAP_SEED_DATA = {"products": [], "phases": [], "no_phase": []}
# What each record must carry: the rest are left out when empty.
ROADMAP_REQUIRED = {"phase": ("name",), "scope": ("id",), "no_phase": ("id",)}
PARKED = re.compile(r"\d{4}-\d{2}-\d{2}")


def roadmap_dumps(data: dict) -> str:
    """The roadmap file as jig writes it: one form, so two writes of one plan are one text."""
    return json.dumps(data, indent=2, ensure_ascii=False) + "\n"


def one_of_each(pairs: list) -> dict:
    """A JSON object's pairs as a dict, refusing a key written twice: json.loads would keep the
    last quietly, and the edit that wrote the first would be lost unseen."""
    out = {}
    for k, v in pairs:
        if k in out:
            raise ValueError(f"key {json.dumps(k, ensure_ascii=False)} appears twice in one object")
        out[k] = v
    return out


def roadmap_parse(raw: str) -> dict | None:
    """RAW's roadmap, parsed: None where it isn't a JSON object (or one repeats a key)."""
    try:
        data = json.loads(raw, object_pairs_hook=one_of_each)
    except ValueError:
        return None
    return data if isinstance(data, dict) else None


# Each roadmap file's records, parsed once per command and shared by every reader: keyed by the
# file's text, so the trunk's, the index's and a metarepo's are each read once, and a writer's
# new text is a new key.
_RECORDS: dict[str, dict | None] = {}


def roadmap_records(raw: str) -> dict | None:
    """RAW's records, shared: readers never change them (a writer takes roadmap_load's copy)."""
    if raw not in _RECORDS:
        _RECORDS[raw] = roadmap_parse(raw)
    return _RECORDS[raw]


def roadmap_load(raw: str) -> dict | None:
    """RAW's records as a writer's own copy, or None where it isn't a JSON object."""
    data = roadmap_records(raw)
    return copy.deepcopy(data) if data is not None else None


def phase_key(p: dict) -> str:
    """A phase's name as a ref and a heading say it: `<product> <name>`, or its name alone."""
    return " ".join(x for x in (str(p.get("product") or ""), str(p.get("name") or "")) if x)


def list_key(product: str) -> str:
    """A product's No phase list as an id's first part says it: `<product> No phase`."""
    return f"{product} {NO_PHASE}" if product else NO_PHASE


def touches_said(pages: list[str]) -> str:
    return f" (touches {', '.join(pages)})" if pages else ""


def item_said(i: dict) -> str:
    """An item's text with where it stopped and when, as rig, the reading list and a person read it."""
    return "; ".join([str(i.get("text") or "")] + [x for x in (
        f"stops at {i['stopped_at']}" if i.get("stopped_at") else "",
        f"parked {i['parked']}" if i.get("parked") else "") if x])


def strs(v) -> list[str]:
    return [str(x) for x in v] if isinstance(v, list) else []


def roadmap_phases(raw: str, problems: list[str] | None = None) -> list[dict]:
    """The roadmap file RAW's phases, read from its records, in the shape every reader takes:
    {name (the phase's key), product, exit: [(ticked, text)], scopes: [(id, what)], note: [lines],
    after, needed, after_of, needed_of, labels_of, touches_of, plain_of}. A scope's WHAT is its
    text with its touches said after it, for a person; PLAIN_OF and TOUCHES_OF hold each apart.
    Each duplicate or reserved name is added to PROBLEMS by the phase, scope or item it names."""
    problems = [] if problems is None else problems
    data = roadmap_records(raw) or {}
    phases: list[dict] = []
    ids: set[str] = set()
    for p in data.get("phases") or []:
        if not isinstance(p, dict):
            continue
        key = phase_key(p)
        if key.lower() in RESERVED or is_list_heading(key):
            problems.append(f"## {key} is a reserved section, not a phase: rename the phase")
            continue
        if any(q["name"] == key for q in phases):
            problems.append(f"phase {key} appears twice")
        after, needed = strs(p.get("after")), strs(p.get("needed_by"))
        ph = {"name": key, "product": str(p.get("product") or ""), "line": 0, "headed": True,
              "exit": [(bool(e.get("done")), str(e.get("text") or "")) for e in p.get("exit") or []
                       if isinstance(e, dict)],
              "note": str(p.get("note") or "").split("\n") if p.get("note") else [],
              "after": after, "after_line": 1 if after else 0, "needed": needed,
              "scopes": [], "after_of": {}, "needed_of": {}, "labels_of": {}, "touches_of": {}, "plain_of": {}}
        for s in p.get("scopes") or []:
            if not isinstance(s, dict) or not s.get("id"):
                continue
            sid = f"{key}/{s['id']}"
            if sid in ids:
                problems.append(f"scope {sid} appears twice")
            ids.add(sid)
            text, pages = str(s.get("text") or ""), strs(s.get("touches"))
            ph["scopes"].append((sid, (text + touches_said(pages)).strip()))
            ph["plain_of"][sid], ph["touches_of"][sid] = text, pages
            if s.get("after"):
                ph["after_of"][sid] = (strs(s["after"]), 1)
            if s.get("needed_by"):
                ph["needed_of"][sid] = strs(s["needed_by"])
            if s.get("labels"):
                ph["labels_of"][sid] = (strs(s["labels"]), 1)
        phases.append(ph)
    return phases


def roadmap_list_items(raw: str, problems: list[str] | None = None) -> list[dict]:
    """The roadmap file RAW's No phase items, read from its records, each {id, sid, list (its
    list's key), what (its text, with where it stopped and when), text (that with its touches
    said, for a person), touches, after, needed, labels, line}. No phase has no order: the
    items come as the file lists them."""
    problems = [] if problems is None else problems
    data = roadmap_records(raw) or {}
    items: list[dict] = []
    for i in data.get("no_phase") or []:
        if not isinstance(i, dict) or not i.get("id"):
            continue
        at = list_key(str(i.get("product") or ""))
        sid = f"{at}/{i['id']}"
        if any(x["sid"] == sid for x in items):
            problems.append(f"{at} item {i['id']} appears twice")
        what, pages = item_said(i), strs(i.get("touches"))
        items.append({"id": str(i["id"]), "sid": sid, "list": at, "what": what,
                      "text": (what + touches_said(pages)).strip(), "touches": pages,
                      "after": strs(i.get("after")), "needed": strs(i.get("needed_by")),
                      "labels": strs(i.get("labels")) or None, "line": 0})
    return items


def roadmap_sections(raw: str) -> list[tuple[str, int, str]]:
    """(key, 0, rows) for each section of the roadmap file RAW, the units an edit is judged and
    written in: "" for `products`, each phase by its key, each No phase list by its key. ROWS
    are its records as JSON, one per line, a phase's own fields first and then each scope, a
    list's items sorted by id (No phase has no order), so two sections compare by their text."""
    return [(h, 0, "\n".join(rows)) for h, rows in section_rows(raw)]


def row(kind: str, rec) -> str:
    return json.dumps({"kind": kind, "record": rec}, sort_keys=True, ensure_ascii=False)


def section_rows(raw: str) -> list[tuple[str, list[str]]]:
    out = []
    for h, recs in section_records(raw):
        if not h:
            out.append((h, [row("products", recs[0])]))
        elif is_list_heading(h):
            out.append((h, sorted(row("item", r) for r in recs)))
        else:
            p = recs[0]
            out.append((h, [row("phase", {k: v for k, v in p.items() if k != "scopes"})]
                        + [row("scope", s) for s in p.get("scopes") or []]))
    return out


def section_records(raw: str) -> list[tuple[str, list]]:
    """(key, records) for each section of RAW, in order: "" holding `products`, each phase (one
    record, its scopes in it), each No phase list (its items)."""
    data = roadmap_records(raw) or {}
    out: list[tuple[str, list]] = [("", [list(data.get("products") or [])])]
    out += [(phase_key(p), [p]) for p in data.get("phases") or [] if isinstance(p, dict)]
    lists: dict[str, list] = {}
    for i in data.get("no_phase") or []:
        if isinstance(i, dict):
            lists.setdefault(list_key(str(i.get("product") or "")), []).append(i)
    return out + list(lists.items())


def from_sections(sections: list[tuple[str, list]]) -> str:
    """The roadmap file holding SECTIONS, as section_records gives them."""
    data = {"products": [], "phases": [], "no_phase": []}
    for h, recs in sections:
        if not h:
            data["products"] = list(recs[0]) if recs else []
        elif is_list_heading(h):
            data["no_phase"] += recs
        else:
            data["phases"] += recs
    return roadmap_dumps(data)


def same_roadmap(a: str, b: str) -> bool:
    """Whether two roadmap files hold the same records, however each is spaced."""
    return roadmap_records(a) == roadmap_records(b)


def waits_said(rec: dict) -> str:
    return " ".join(f"({kind} {', '.join(rec[key])})" for kind, key in
                    (("labels", "labels"), ("after", "after"), ("needed by", "needed_by"))
                    if rec.get(key))


def record_line(rec: dict, text: str) -> str:
    tail = " ".join(x for x in (waits_said(rec), f"(touches {', '.join(rec['touches'])})"
                                if rec.get("touches") else "") if x)
    body = " ".join(x for x in (text, tail) if x)
    return f"- `{rec.get('id', '')}`" + (f": {body}" if body else "")


def roadmap_md(data: dict) -> str:
    """DATA in the old roadmap.md's form, for the conversion's own check alone: a phase per
    heading, `<product> <name>` where it has a product, its note, its waits, `Exit when:` and
    `Scopes:`, then each list. A text's lines after its first follow its line, as an old item's
    nested lines did. Never read back: the file is JSON."""
    out = ["# Roadmap"]

    def lines_of(rec: dict, first: str, text: str) -> list[str]:
        rest = text.split("\n")[1:]
        return [record_line(rec, first)] + rest
    for p in data.get("phases") or []:
        if not isinstance(p, dict):
            continue
        out += ["", f"## {phase_key(p)}"]
        if p.get("note"):
            out += ["", *str(p["note"]).split("\n")]
        out += [f"({k} {', '.join(p[key])})" for k, key in (("after", "after"), ("needed by", "needed_by"))
                if p.get(key)]
        if "exit" in p:
            out += ["", "Exit when:"] + [f"- [{'x' if e.get('done') else ' '}] {e.get('text', '')}"
                                         for e in p["exit"] if isinstance(e, dict)]
        if "scopes" in p:
            out += ["", "Scopes:"]
            for s in p.get("scopes") or []:
                if isinstance(s, dict):
                    text = str(s.get("text") or "")
                    out += lines_of(s, text.split("\n")[0], text)
    lists: dict[str, list[str]] = {"": []}
    for i in data.get("no_phase") or []:
        if not isinstance(i, dict):
            continue
        text = str(i.get("text") or "")
        lists.setdefault(str(i.get("product") or ""), []).extend(
            lines_of(i, item_said({**i, "text": text.split("\n")[0]}), text))
    for prod, lines in lists.items():
        out += ["", f"## {list_key(prod)}", *([""] + lines if lines else [])]
    return "\n".join(out) + "\n"


def roadmap_data(md: str, owners: dict[str, str]) -> dict:
    """The old roadmap MD as roadmap.json's records: every phase, scope, item, suffix, note and
    exit check with its text unchanged, each phase under the product of OWNERS its leading words
    name, as the glossary's products placed it (Family's owners: a metarepo's glossary, none elsewhere).
    What it can't carry, uncarried names; the conversion waits on it."""
    md = fold_up_next(md) if up_next_heading(md) else md
    out: dict = {"products": [], "phases": [], "no_phase": []}

    def add(prod: str) -> None:
        if prod and prod not in out["products"]:
            out["products"].append(prod)

    def rec(base: dict, text: str, labels, after, needed, touches) -> dict:
        for key, v in (("text", text), ("labels", labels), ("touches", touches), ("after", after),
                       ("needed_by", needed)):
            if v:
                base[key] = v
        return base
    for p in parse_roadmap(md):
        prod = product_of(p["name"], owners)
        add(prod)
        phase = {"product": prod} if prod else {}
        phase["name"] = p["name"][len(prod):].strip() if prod else p["name"]
        # Every line above Exit when: and Scopes: is the note, fences whole: only an unfenced
        # wait line is the phase's wait, as old jig read it.
        note = "\n".join(l for l, fenced in p["pre"] if fenced or (phase_waits(l) is None and not phase_labels(l)))
        if note.strip("\n"):
            phase["note"] = note.strip("\n")
        if p["exit"] or p.get("has_exit"):
            phase["exit"] = [{"text": t, "done": d} for d, t in p["exit"]]
        if p["after"]:
            phase["after"] = p["after"]
        if p.get("needed"):
            phase["needed_by"] = p["needed"]
        phase["scopes"] = []
        for sid, what in p["scopes"]:
            text, pages = split_touches(what)
            phase["scopes"].append(rec({"id": sid.split("/", 1)[1]}, text, p["labels_of"].get(sid, (None,))[0],
                                       p["after_of"].get(sid, ([],))[0], p["needed_of"].get(sid), pages))
        out["phases"].append(phase)
    for i in parse_no_phase(md):
        prod = "" if i["list"] == NO_PHASE else i["list"][:-len(NO_PHASE)].strip()
        add(prod)
        item = {"id": i["id"]}
        what, stopped, parked = i["what"], "", ""
        # rules-roadmap.md's parked form, `<what>; stops at <where>; parked <YYYY-MM-DD>`: anything else is text.
        if m := re.fullmatch(r"(.*?); stops at (.+?)(?:; parked (\d{4}-\d{2}-\d{2}))?", what):
            what, stopped, parked = m.group(1), m.group(2), m.group(3) or ""
        elif m := re.fullmatch(r"(.*?); parked (\d{4}-\d{2}-\d{2})", what):
            what, parked = m.group(1), m.group(2)
        # Nested lines join the item's text after its touches are split from its own line.
        what += "".join("\n" + l for l in i["more"])
        rec(item, what, i["labels"], i["after"], i["needed"], i["touches"])
        if prod:
            item["product"] = prod
        if stopped:
            item["stopped_at"] = stopped
        if parked:
            item["parked"] = parked
        out["no_phase"].append(item)
    return out


def roadmap_shape(data, where: str = ROADMAP) -> list[str]:
    """Each field of DATA the example records don't have, or of another type, and each product
    a record names that `products` doesn't include."""
    if not isinstance(data, dict):
        return [f"{where} is not a JSON object"]
    out = [f"{where}: `{k}` is not a roadmap field; it holds only {', '.join(ROADMAP_SEED_DATA)}"
           for k in data if k not in ROADMAP_SEED_DATA]
    for k in ROADMAP_SEED_DATA:
        if k in data and not isinstance(data[k], list):
            out.append(f"{where}: `{k}` must be a list")
    products = data.get("products") if isinstance(data.get("products"), list) else []
    if any(not isinstance(p, str) for p in products):
        out.append(f"{where}: `products` holds the glossary's product terms, each a string")

    def check(r, kind: str, at: str) -> None:
        if not isinstance(r, dict):
            out.append(f"{where}: {at} is not a {kind.replace('_', ' ')} record")
            return
        example = ROADMAP_RECORDS[kind]
        for k, v in r.items():
            if k not in example:
                out.append(f"{where}: {at} has `{k}`, which a {kind.replace('_', ' ')} record doesn't: "
                           f"it holds {', '.join(example)}")
            elif not same_type(v, example[k]):
                out.append(f"{where}: {at}'s `{k}` must be {type_said(example[k])}")
        for k in ROADMAP_REQUIRED[kind]:
            if not r.get(k):
                out.append(f"{where}: {at} has no `{k}`")
        if kind == "phase" and "exit" not in r and "scopes" not in r:
            out.append(f"{where}: {at} has neither `exit` nor `scopes`: a phase carries one or both, "
                       "either an empty list")
        if kind == "phase" and isinstance(r.get("exit"), list):
            check_box = ROADMAP_RECORDS["phase"]["exit"][0]
            for c, e in enumerate(r["exit"], 1):
                if not isinstance(e, dict):
                    continue
                said = f"{at}'s `exit` check {json.dumps(e['text'], ensure_ascii=False) if 'text' in e else c}"
                out.extend(f"{where}: {said} has `{k}`, which an exit check doesn't: it holds text and done"
                           for k in e if k not in check_box)
                out.extend(f"{where}: {said} has no `{k}`" for k in check_box if k not in e)
                out.extend(f"{where}: {said}'s `{k}` must be {type_said(check_box[k])}"
                           for k in check_box if k in e and not same_type(e[k], check_box[k]))
        # An id is written `<phase>/<id>` on one line in specs: no space and no `/` in it.
        if kind != "phase" and isinstance(r.get("id"), str) and r["id"] and not SCOPE_ID.fullmatch(r["id"]):
            out.append(f"{where}: {at}'s `id` holds a space or a /: an id is one word")
        if kind == "no_phase" and isinstance(r.get("parked"), str) and r["parked"] and not PARKED.fullmatch(r["parked"]):
            out.append(f"{where}: {at}'s `parked` is a date, YYYY-MM-DD")
        prod = r.get("product")
        if isinstance(prod, str) and prod and prod not in products:
            out.append(f"{where}: {at} names product {prod}, which `products` doesn't include")
    for n, p in enumerate(data.get("phases") or [] if isinstance(data.get("phases"), list) else [], 1):
        at = f"phase {p.get('name') if isinstance(p, dict) and p.get('name') else n}"
        check(p, "phase", at)
        if isinstance(p, dict) and isinstance(p.get("scopes"), list):
            for s in p["scopes"]:
                check(s, "scope", f"{at} scope {s.get('id') if isinstance(s, dict) else '?'}")
    for n, i in enumerate(data.get("no_phase") or [] if isinstance(data.get("no_phase"), list) else [], 1):
        check(i, "no_phase", f"{NO_PHASE} item {i.get('id') if isinstance(i, dict) and i.get('id') else n}")
    return out


def roadmap_file_problems(raw: str, owners: dict[str, str], glossary: str = GLOSSARY) -> list[str]:
    """What the roadmap file RAW holds that jig refuses before reading it: not JSON, a field or a
    type the example records don't have, or a product that isn't one of the glossary's product
    terms (OWNERS), or that `products` doesn't include."""
    data = roadmap_load(raw)
    if data is None:
        return [f"{ROADMAP} is not a JSON object" + (": " + json_error(raw) if raw.strip() else "")]
    out = roadmap_shape(data)
    out += [f"{ROADMAP}: product {p} is no product of {glossary}: a product there carries its repo"
            for p in data.get("products") or [] if isinstance(p, str) and p not in owners]
    return out


def json_error(raw: str) -> str:
    try:
        json.loads(raw, object_pairs_hook=one_of_each)
    except ValueError as e:
        return str(e)
    return "not an object"


def unline(problem: str) -> str:
    """PROBLEM without a `line <n>: ` put first: roadmap.json's readers name the phase, scope or
    item, and a check shared with the old parser may still give a line."""
    return re.sub(r"^line \d+: ", "", problem)


def same_type(v, example) -> bool:
    if isinstance(example, bool):
        return isinstance(v, bool)
    if isinstance(example, list):
        if not isinstance(v, list):
            return False
        inner = example[0] if example else None
        return all(same_type(x, inner) for x in v) if inner is not None and not isinstance(inner, dict) \
            else all(isinstance(x, dict) for x in v)
    if isinstance(example, dict):
        return isinstance(v, dict)
    return isinstance(v, type(example))


def type_said(example) -> str:
    if isinstance(example, bool):
        return "true or false"
    if isinstance(example, list):
        return "a list of records" if example and isinstance(example[0], dict) or not example else "a list of strings"
    return "a string"


# `jig roadmap show`: one width per entry, so a column is a step in the order and nothing else.
SHOW_CELL = 24
SHOW_WIDTH = 100


def show_columns(phases: list[dict], items: list[dict]) -> dict[str, int]:
    """Each scope's and item's column: one past the furthest column of anything it waits on, a
    phase standing for all its scopes. Waits on what the chart doesn't hold count nothing."""
    entries = {s["id"]: s for p in phases for s in p["scopes"]} | {i["id"]: i for i in items}
    phase_of = {s["id"]: p for p in phases for s in p["scopes"]}
    by_phase = {p["name"]: [s["id"] for s in p["scopes"]] for p in phases}
    col: dict[str, int] = {}

    def waits(sid: str) -> list[str]:
        own = entries[sid].get("after") or []
        p = phase_of.get(sid)
        return list(own) + list(p["after"] if p else [])

    def place(sid: str, seen: frozenset = frozenset()) -> int:
        if sid in col:
            return col[sid]
        if sid in seen:                       # a ring: the hook refuses it, the chart still draws
            return 0
        deps = []
        for r in waits(sid):
            for d in (by_phase.get(r) or ([r] if r in entries else [])):
                deps.append(place(d, seen | {sid}))
        col[sid] = 1 + max(deps) if deps else 0
        return col[sid]
    for sid in entries:
        place(sid)
    return col


def show_cell(s: dict) -> str:
    name = s["id"].rsplit("/", 1)[1]
    state = "blocked" if s["state"] == "open" and s.get("waits") else s["state"]
    room = SHOW_CELL - 3 - len(state)          # the brackets, and one space before the state
    name = name if len(name) <= room else name[:room - 1] + "…"
    return f"[{name}{' ' * (SHOW_CELL - 2 - len(name) - len(state))}{state}]"


def show_box(title: str, scopes: list[dict], col: dict[str, int], lo: int, hi: int) -> list[str]:
    """A box over columns LO..HI holding SCOPES, each in its column; within a column, scopes
    sharing a first label sit together, in the order the first of each appears."""
    cols: dict[int, list[dict]] = {}
    for s in scopes:
        cols.setdefault(col[s["id"]], []).append(s)
    for c, ss in cols.items():
        firsts = list(dict.fromkeys((x.get("labels") or [""])[0] for x in ss))
        ss.sort(key=lambda x: firsts.index((x.get("labels") or [""])[0]))
    inner = max((hi - lo + 1) * (SHOW_CELL + 1) - 1, len(title) + 2)
    out = ["+" + f"- {title} ".ljust(inner + 2, "-") + "+"]
    for row in range(max((len(v) for v in cols.values()), default=0)):
        cells = [show_cell(cols[c][row]) if row < len(cols.get(c, [])) else " " * SHOW_CELL
                 for c in range(lo, hi + 1)]
        out.append("| " + " ".join(cells).ljust(inner) + " |")
    if not scopes:
        out.append("| " + "(no scopes)".ljust(inner) + " |")
    out.append("+" + "-" * (inner + 2) + "+")
    return out


def render_show(phases: list[dict], items: list[dict], width: int = SHOW_WIDTH) -> str:
    """The roadmap as a text chart, no dates: a box per phase, as wide as its scopes, at the
    columns its scopes' waits put them in; a box per product around its phases where the chart
    holds more than one; each product's No phase items last. Wider than WIDTH, each phase is its
    own band, its first column at the left."""
    col = show_columns(phases, items)
    groups: list[tuple[str, list[dict]]] = []
    for p in phases:
        if not groups or groups[-1][0] != p.get("product", ""):
            groups.append((p.get("product", ""), []))
        groups[-1][1].append(p)
    lists: dict[str, list[dict]] = {}
    for i in items:
        lists.setdefault(i.get("product", ""), []).append(i)
    products = list(dict.fromkeys([g for g, _ in groups] + list(lists)))
    boxed = len(products) > 1
    span = lambda ss: (min((col[s["id"]] for s in ss), default=0), max((col[s["id"]] for s in ss), default=0))

    def draw(banded: bool) -> list[str]:
        def band(title: str, ss: list[dict]) -> list[str]:
            lo, hi = span(ss)
            box = show_box(title, ss, col, lo, hi)
            pad = 0 if banded else lo * (SHOW_CELL + 1)
            return [" " * pad + l for l in box]
        out: list[str] = []
        for prod in products:
            lines: list[str] = []
            for p in next((ps for g, ps in groups if g == prod), []):
                kind = f"{p['type']}, {p['state']}"
                lines += band(f"{p['name']} ({kind})", p["scopes"])
            if prod in lists:
                lines += band(f"{prod + ' ' if prod else ''}{NO_PHASE}", lists[prod])
            if boxed:
                w = max(len(l) for l in lines)
                lines = (["+" + f"= {prod or 'this repo'} ".ljust(w + 2, "=") + "+"]
                         + ["| " + l.ljust(w) + " |" for l in lines] + ["+" + "=" * (w + 2) + "+"])
            out += lines
        return out
    # Measured as drawn, borders and all: the chart bands only when a line would pass WIDTH.
    out = draw(False)
    if max((len(l) for l in out), default=0) > width:
        out = draw(True)
    return "\n".join(out) + "\n" if out else "The roadmap is empty.\n"


# The first STAMP whose checker reads roadmap.json: an older one on trunk refuses a commit
# removing .jig/roadmap.md, so the conversion waits for the commit that installs this checker.
ROADMAP_JSON_STAMP = 13
OLD_ROADMAP = f"{DIR}/roadmap.md"
OLD_ROADMAP_VIEW = "ROADMAP.md"


def roadmap_home(show) -> str:
    """Where a pararepo plans from, by what SHOW (path -> its text at a checkout and rev, "" or
    None for none) finds: "own" for a roadmap.json of its own, "unconverted" for its own old
    roadmap.md waiting to convert, "meta" for neither, its metarepo's roadmap. The one test of
    it: a reader, the merge, a move, the sweep and move-in each ask this, never the files."""
    if show(ROADMAP):
        return "own"
    return "unconverted" if show(OLD_ROADMAP) else "meta"
# The line every view jig generated carried, so update removes jig's and leaves a repo's own.
OLD_VIEW_MARK = "_Generated by `jig roadmap --write`"


# The comment jig's seed wrote above the first heading (3c7905c to aa9e2b8): jig's words, so the
# conversion drops it. A comment holding anything else is the owner's, and is named.
SEED_COMMENT = [
    f"<!-- The owner's plan, changed on trunk only and on the owner's word ({DIR}/RULES.md, Roadmap).",
    "Phases are level-two headings, in order, each with an `Exit when:` checklist, a `Scopes:` list",
    "of backticked scope names with what each is, or both. Work with no phase is an item under",
    "No phase below, a backticked id and what it is. A spec takes an id on its `Scope:` line, and",
    "names one it leaves for later work on its `Later:` line. -->",
]


def old_lines(md: str, exempt: bool) -> Counter:
    """Each non-blank line of roadmap MD in the old form, keyed by the section it sits in and,
    for an indented line, the line it hangs under, written one way: trailing space dropped,
    `[X]` as `[x]`, `Exit when:` and `Scopes:` in one case, a list line's suffixes in
    split_waits' order, a phase's waits one to a line. EXEMPT: the first line's `# ` title,
    jig's seed comment and an `## Up next` heading (the fold's own) go uncounted."""
    lines = md.split("\n")
    skip: set[int] = set()
    if exempt:
        first = next((n for n, l in enumerate(lines) if l.strip()), None)
        if first is not None and re.match(r"#\s+", lines[first]):
            skip.add(first)
        for n in range(len(lines)):
            if [l.rstrip() for l in lines[n:n + len(SEED_COMMENT)]] == SEED_COMMENT:
                skip.update(range(n, n + len(SEED_COMMENT)))
    out: Counter = Counter()
    under, parent, fence = "", None, False
    for n, raw in enumerate(lines):
        line = raw.rstrip()
        if n in skip or not line.strip():
            continue
        if line.lstrip().startswith("```"):
            fence = not fence
            out[(under, parent, line)] += 1
            continue
        if not fence and (m := re.match(r"##\s+(.+?)\s*$", line)):
            title = m.group(1).strip()
            if title.lower() == UP_NEXT.lower():
                title = NO_PHASE
                if exempt:
                    under, parent = title, None
                    continue
            # A heading keys the lines under it: what it holds is counted, the heading isn't, so
            # a list's heading written twice reads as one list.
            under, parent = title, None
            continue
        indented = line[0] in " \t"
        for said in [line] if fence else said_old(line):
            out[(under, parent if indented else None, said)] += 1
        if not indented and not fence:
            parent = said_old(line)[0]
    return out


def said_old(line: str) -> list[str]:
    """LINE, unfenced, as old_lines compares it: a phase's waits a line each."""
    s = line.rstrip()
    if re.fullmatch(r"(?i)\s*(exit when|scopes):", s):
        return [s.strip().lower()]
    if m := re.match(r"\s*- \[([ xX])\]\s*(.*)", s):
        return [f"- [{' ' if m.group(1) == ' ' else 'x'}] {m.group(2).strip()}"]
    if (w := phase_waits(s)) is not None:
        return [f"({k} {', '.join(r)})" for k, r in (("after", w[0]), ("needed by", w[1])) if r is not None]
    if not s[:1].isspace() and (m := SCOPE_LINE.fullmatch(s)):
        body, after, needed, labels = split_waits((m.group(2) or "").strip())
        what, pages = split_touches(body)
        return [record_line({"id": m.group(1), "labels": labels, "after": after, "needed_by": needed,
                             "touches": pages}, what)]
    return [s]


def uncarried(md: str, owners: dict[str, str], check=None) -> list[str]:
    """What of the old roadmap MD the conversion would lose or change, so it waits until the
    owner moves, fixes or deletes it. Judged by the output: the records the conversion writes
    (products placed by OWNERS) are drawn in the old form again, and each old line that doesn't
    come back under its heading, and under the line it hung from, is named. So are the
    parsers' problems, a line the `## Up next` fold loses, and what CHECK (the hook's checks)
    finds in the file it would write. The first line's title and jig's seed comment alone are
    dropped unnamed."""
    folded = fold_up_next(md) if up_next_heading(md) else md
    out = []
    # The fold moves lines and drops only its own heading: anything else it lost is named.
    count = lambda t: Counter(l.rstrip() for l in t.split("\n") if l.strip()
                              and not re.fullmatch(rf"##\s+({UP_NEXT}|{NO_PHASE})", l.strip(), re.I))
    out += [f"a line the fold of ## {UP_NEXT} loses: {l.strip()}" for l in (count(md) - count(folded))]
    problems: list[str] = []
    parse_roadmap(folded, problems)
    parse_section(folded, NO_PHASE, problems)
    # In the old file's own words: these lines are Markdown, not roadmap.json's fields.
    out += [re.sub(r"^line \d+: ", "", x) for x in problems]
    data = roadmap_data(md, owners)
    # The drawing's own title is exempt as the old file's is, so an old file's second `# `
    # line never matches it.
    back = old_lines(roadmap_md(data), True)
    for (under, parent, said), n in (old_lines(md, True) - back).items():
        out += [f"{'under ## ' + under if under else 'above the first heading'}: {said.strip()}"] * n
    if not out and check is not None:
        out += [unline(x) for x in check(roadmap_dumps(data))]
    return out


def roadmap_owners(fam: "Family", glossary: str | None = None) -> dict[str, str]:
    """The owners a roadmap file's products are placed and judged by: a metarepo's glossary
    (GLOSSARY's text where given, else Family's), and none in any other repo, a pararepo keeping
    its own roadmap included. The hook and the conversion both ask it, so they can't differ."""
    if fam.kind != "meta":
        return {}
    return term_owners(glossary) if glossary is not None else fam.owners


def convert_roadmap(root: Path, here: Path) -> None:
    """`jig update --apply`: .jig/roadmap.md as roadmap.json, then the old file and a ROADMAP.md
    jig generated removed. Products are placed as Family places them: by the glossary in a
    metarepo, nowhere else, as the hook and every reader read them."""
    md = read_raw(root / OLD_ROADMAP)
    (root / ROADMAP).write_text(roadmap_dumps(roadmap_data(md, roadmap_owners(family(root)))))
    git("rm", "-q", "-f", "--", OLD_ROADMAP, check=True)
    git("add", "--", ROADMAP, check=True)
    view = root / OLD_ROADMAP_VIEW
    if view.is_file() and OLD_VIEW_MARK in view.read_text(errors="replace"):
        git("rm", "-q", "-f", "--", OLD_ROADMAP_VIEW, check=True)


def conversion_waits(root: Path) -> list[str]:
    """uncarried for ROOT's old roadmap, with Family's owners and the hook's own checks."""
    trunk = Board.trunk_name(root)
    fam = family(root, trunk)
    owners = roadmap_owners(fam)
    have = set(Snapshot(trunk).ls("docs/"))
    return uncarried(read_raw(root / OLD_ROADMAP), owners,
                     lambda raw: roadmap_file_problems(raw, owners, fam.glossary_name)
                     + roadmap_problems(raw, fam, have, trunk))


def roadmap_label_problems(text: str, glossary_text: str | None, glossary: str = GLOSSARY) -> list[str]:
    """Each label of TEXT's scopes and items that label_problems refuses, by line."""
    out = []
    for p in roadmap_phases(text):
        for sid, (labels, n) in p["labels_of"].items():
            out += label_problems(labels, glossary_text, f"line {n}: scope {sid}", glossary)
    for i in roadmap_list_items(text):
        out += label_problems(i["labels"], glossary_text, f"line {i['line']}: {i['sid']}", glossary)
    return out


def waits_of(p: dict, sid: str) -> list[str]:
    """What scope SID of phase P waits on: its own refs, then its phase's."""
    own = p["after_of"].get(sid, ([], 0))[0]
    return own + [r for r in p["after"] if r not in own]


def ref_problems(phases: list[dict], items: list[dict] = ()) -> list[str]:
    """Each `(after …)` ref the roadmap can't honour, by line: one naming nothing it has, one
    naming itself (a scope its own phase, too, which waits on it), and each ring once, with all
    its members. A ring never opens on its own: every member waits on another forever. The one
    list's ITEMS wait and are waited on as scopes are; no ref names the list itself."""
    names = {p["name"] for p in phases}
    phases = phases + [list_phase(list(items))]
    scopes = {sid: p for p in phases for sid, _ in p["scopes"]}
    out: list[str] = []
    edges: dict[str, list[str]] = {}
    lines: dict[str, int] = {}
    for p in phases:
        waits = [(p["name"], p["after"], p["after_line"])] if p["after_line"] else []
        waits += [(sid, refs, n) for sid, (refs, n) in p["after_of"].items()]
        if p["after_line"]:
            lines[p["name"]] = p["after_line"]
        # A phase is done when its scopes are, so it waits on each of them.
        edges[p["name"]] = [sid for sid, _ in p["scopes"]]
        for who, refs, n in waits:
            lines.setdefault(who, n)
            for r in refs:
                if r not in scopes and r not in names:
                    out.append(f"line {n}: {who} waits on {r}, which the roadmap has no phase or "
                               f"scope for: a ref is <phase>/<scope>, <phase> or {NO_PHASE}/<id>")
                elif r == who or (who in scopes and r == scopes[who]["name"]):
                    out.append(f"line {n}: {who} waits on {r}, "
                               + ("itself" if r == who else "its own phase, which waits on it"))
                else:
                    edges.setdefault(who, []).append(r)
    for p in phases:
        for sid, _ in p["scopes"]:
            # A phase's wait is each of its scopes' wait.
            for r in p["after"]:
                if r == sid:
                    out.append(f"line {p['after_line']}: phase {p['name']} waits on {r}, one of its "
                               "own scopes, which then waits on itself")
                elif (r in scopes or r in names) and r != p["name"]:
                    edges.setdefault(sid, []).append(r)
                    lines.setdefault(sid, p["after_line"])
    for ring in rings(edges):
        # Every ring holds a wait, so it is reported at the first line that writes one.
        first = min((x for x in ring if x in lines), key=lambda x: (lines[x], x))
        out.append(f"line {lines[first]}: a ring: {', '.join(sorted(ring))} wait on each "
                   "other, so none can start: drop one `after` ref")
    return out


def unconfirmed(text: str, owners: dict[str, str]) -> list[tuple[str, str]]:
    """(waiter, ref) for each `(after …)` naming another product's scope or phase whose section
    doesn't confirm it with `(needed by <waiter>)`, on the scope, its phase, or the phase named:
    a wait one product's plan makes on another's, for the owner to rule on. It blocks nothing."""
    phases, items = roadmap_phases(text), roadmap_list_items(text)
    product: dict[str, str] = {}
    needs: dict[str, list[str]] = {}
    for p in phases:
        product[p["name"]] = product_of(p["name"], owners)
        needs[p["name"]] = p["needed"]
        for sid, _ in p["scopes"]:
            product[sid] = product[p["name"]]
            needs[sid] = p["needed_of"].get(sid, []) + p["needed"]
    for i in items:
        product[i["sid"]] = product_of(i["list"].removesuffix(" " + NO_PHASE), owners)
        needs[i["sid"]] = i["needed"]
    waits = [(p["name"], r) for p in phases for r in p["after"]]
    waits += [(sid, r) for p in phases for sid, (refs, _) in p["after_of"].items() for r in refs]
    waits += [(i["sid"], r) for i in items for r in i["after"]]
    out = []
    for who, ref in waits:
        if ref not in product or not product[ref] or product[ref] == product.get(who):
            continue
        phase_of = who.rsplit("/", 1)[0] if "/" in who else who
        if not ({who, phase_of} & set(needs.get(ref, []))):
            out.append((who, ref))
    return out


def rings(edges: dict[str, list[str]]) -> list[set[str]]:
    """Each strongly connected set of more than one node in EDGES (Tarjan's): a ring, once.
    Iterative, so a long chain of waits can't exhaust the stack and crash the hook."""
    index: dict[str, int] = {}
    low: dict[str, int] = {}
    stack: list[str] = []
    on: set[str] = set()
    out: list[set[str]] = []
    for root in sorted(edges):
        if root in index:
            continue
        work = [(root, 0)]
        while work:
            v, i = work.pop()
            if i == 0:
                index[v] = low[v] = len(index)
                stack.append(v)
                on.add(v)
            nexts = edges.get(v, [])
            if i > 0:
                low[v] = min(low[v], low[nexts[i - 1]])
            while i < len(nexts) and (nexts[i] in index):
                if nexts[i] in on:
                    low[v] = min(low[v], index[nexts[i]])
                i += 1
            if i < len(nexts):
                work += [(v, i + 1), (nexts[i], 0)]
                continue
            if low[v] == index[v]:
                comp = set()
                while True:
                    w = stack.pop()
                    on.discard(w)
                    comp.add(w)
                    if w == v:
                        break
                if len(comp) > 1:
                    out.append(comp)
    return out


def roadmap_scopes(text: str) -> set[str]:
    """Every id a `Scope:` line may name: each phase's scopes and each item of the one list."""
    return set(scope_ids(text))


def spec_scopes(text: str) -> list[str]:
    """The scopes a spec's `Scope:` line takes, in its order."""
    m = re.search(r"^Scope:[ \t]*(.*)$", text, re.M)
    return [s.strip().strip("`") for s in m.group(1).split(",") if s.strip()] if m else []


# A spec's `Later:` line, retired: work not built stays on the roadmap, unspecced, and a spec
# takes only what it builds. Read only to refuse one and to remove it (`jig update --apply`).
LATER_LINE = re.compile(r"^Later:[ \t]*.*\n?", re.M)


def later_line(text: str) -> "re.Match | None":
    """A spec's `Later:` line in its header, above its first `## ` section: a line in its body,
    an example in a fence say, is no record."""
    end = m.start() if (m := re.search(r"^## ", text, re.M)) else len(text)
    return LATER_LINE.search(text, 0, end)


def cited(path: str, text: str, bad) -> str:
    """What PATH's `Scope:` line names that BAD holds, as a refusal says it: "takes a, b"; ""
    when none."""
    took = [s for s in scopes_in(path, text) if bad(s)]
    return f"takes {', '.join(took)}" if took else ""


def takes_scopes(path: str) -> bool:
    """A spec, or a handoff note, which keeps the scopes of a spec that has closed."""
    return is_spec(path) or path.startswith(HANDOFFS) and path.endswith(".md")


def scopes_in(path: str, text: str) -> list[str]:
    return spec_scopes(note_head(text) if path.startswith(HANDOFFS) else text)


def is_spec(path: str) -> bool:
    # _template.md is the shape a spec starts from, not a task: its placeholder takes nothing.
    return path.startswith(SPECS) and path.endswith(".md") and not Path(path).name.startswith("_")


def partial_specs(snap: Snapshot) -> set[str]:
    """Specs a landed `Partial: yes` note names: work under way, whatever else names them."""
    out = set()
    for n in snap.ls(HANDOFFS):
        body = snap.show(n)
        spec = re.search(r"^Spec: (\S+)", body, re.M)
        commit = re.search(r"^Commit: (\w+)", body, re.M)
        if spec and commit and re.search(r"^Partial: yes", body, re.M) and snap.landed(commit.group(1)):
            out.add(os.path.normpath(spec.group(1)))
    return out


def completing_notes(snap: Snapshot) -> dict[str, str]:
    """Each spec with a landed handoff that isn't partial, to the newest such note: its work is
    in this tree's history. A note may name its spec by file name alone."""
    done: dict[str, tuple[str, str]] = {}
    for n in snap.ls(HANDOFFS):
        body = snap.show(n)
        spec = re.search(r"^Spec: (\S+)", body, re.M)
        commit = re.search(r"^Commit: (\w+)", body, re.M)
        if not spec or not commit or re.search(r"^Partial: yes", body, re.M):
            continue
        s = os.path.normpath(spec.group(1))
        date = re.search(r"^Date: (\S+)", body, re.M)
        key = (date.group(1) if date else "", n)
        if (s not in done or key > done[s]) and snap.landed(commit.group(1)):
            done[s] = key
    return {s: k[1] for s, k in done.items()}


def complete_specs(snap: Snapshot) -> set[str]:
    return set(completing_notes(snap))


def note_for(spec: str, notes: dict[str, str]) -> str:
    return notes.get(spec) or notes.get(Path(spec).name) or ""


def finished_specs(snap: Snapshot, board: "Board", job: str = "", named: set[str] | None = None) -> list[dict]:
    """The specs whose work is done and that nothing still holds: complete and named by no open
    job, or a `Bug-for:` spec whose job has left the board (a bug spec reaches trunk only with
    its job's merge). Each with its completing note ("" for a bug spec). With JOB, only that
    job's: the specs its notes name (NAMED) and its `Bug-for:` specs. A spec a cached metarepo
    pointer names is kept, with why: removing it would leave that pointer dangling."""
    notes = completing_notes(snap)
    held = {os.path.normpath(j["spec"]) for j in board.jobs.values() if is_spec(j.get("spec", ""))}
    named = {os.path.normpath(x) for x in named or ()}
    root = main_root()
    pointed = {p for _, p, _, _ in pointers(root)} if (root / CACHE).is_dir() else set()
    para = bool(snap.show(PARA))
    out = []
    for f in snap.ls(SPECS):
        if not is_spec(f):
            continue
        bug = bug_for(snap.show(f))
        carry = ""
        if bug:
            if bug in board.jobs or job and bug != job:
                continue
            note = ""
            # Its Scope: and staged marks outlive it on its job's note, as its job's spec's do.
            carry = job_note(snap, bug)
        else:
            note = note_for(f, notes)
            if not note or f in held or Path(f).name in {Path(h).name for h in held}:
                continue
            if job and f not in named and Path(f).name not in named:
                continue
        # In a pararepo `jig sync` follows a proposal through the spec naming it, and closes the
        # buffer rows it carried from there: that spec stays while the link is in it.
        text = snap.show(f)
        follows = para and (any(m.group("branch") or m.group("pbranch") for m in PROPOSAL.finditer(text))
                            or bool(WITHDRAWN.search(text)))
        out.append({"spec": f, "note": note, "carry": carry or note,
                    "kept": "a cached metarepo pointer names it" if f in pointed else
                    "it names a metarepo proposal or pointers branch `jig sync` follows" if follows else ""})
    return out


def job_note(snap: Snapshot, job: str) -> str:
    """JOB's newest landed handoff note that isn't partial, by its `# Handoff:` title, or ""."""
    best = ("", "")
    for n in snap.ls(HANDOFFS):
        body = snap.show(n)
        commit = re.search(r"^Commit: (\w+)", body, re.M)
        # The title on the first line, as handoff_notes reads it: a quoted one in the prose isn't.
        if (body.split("\n", 1)[0] == f"# Handoff: {job}" and commit
                and not re.search(r"^Partial: yes", body, re.M) and snap.landed(commit.group(1))):
            date = re.search(r"^Date: (\S+)", body, re.M)
            best = max(best, ((date.group(1) if date else ""), n))
    return best[1]


def note_head(text: str) -> str:
    """A handoff note's header, above its first section: where its `Spec:` and `Scope:` lines
    are. A line in its prose that happens to start `Scope:` is no scope."""
    return text.split("\n## ", 1)[0]


# A staged file's mark in a spec, as `provenance` writes it, with a request's quote after it.
MARK_LINE = re.compile(r"^Source: .*\(staged as [^)\n]+\).*$", re.M)


def close_specs(finished: list[dict], snap: Snapshot) -> list[str]:
    """Remove each finished spec, its note keeping what outlives it, in the note's header after
    its `Spec:` line: the spec's `Scope:`, read now so a scope re-pointed after the handoff is
    carried right, and each staged file's mark it carried, which `resolve` then finds there.
    Staging itself is untouched: a staged file leaves only by `resolve` or `drop`. Stages the
    changes in the trunk checkout; returns what it did, a line each."""
    root, out = main_root(), []
    for x in finished:
        f, note = x["spec"], x["note"]
        if x["kept"]:
            out.append(f"kept {f}: {x['kept']}")
            continue
        text = snap.show(f)
        carry = x.get("carry", note)
        if carry:
            body = read_raw(root / carry)
            head = note_head(body)
            add = [l for l in MARK_LINE.findall(text) if l not in head.splitlines()]
            # A job's bug spec closes onto the same note, so a Scope: line already there gains its ids.
            if ids := spec_scopes(text):
                have = re.search(r"^Scope:[ \t]*(.*)$", head, re.M)
                if not have:
                    add.insert(0, f"Scope: {', '.join(ids)}")
                else:
                    old = [i.strip().strip("`") for i in have.group(1).split(",") if i.strip()]
                    if new := [i for i in ids if i not in old]:
                        body = body.replace(have.group(0), f"Scope: {', '.join(old + new)}", 1)
            if add:
                body = re.sub(r"^(Spec: .*\n)", lambda m: m.group(1) + "".join(f"{l}\n" for l in add),
                              body, count=1, flags=re.M)
            if body != read_raw(root / carry):
                write_raw(root / carry, body)
                git("add", "--", carry, check=True, cwd=str(root))
        # -f: mid-merge the spec is staged from the job, as a new file.
        git("rm", "-q", "-f", "--", f, check=True, cwd=str(root))
        out.append(f"closed {f}")
    return out


def carries(text: str, mark: str) -> bool:
    """TEXT holds MARK as a whole `Source: … (staged as …)` line, a request's quote after it or
    not: the mark, not a substring of some longer one."""
    return any(l == mark or l.startswith(mark + ":") for l in (x.rstrip() for x in MARK_LINE.findall(text)))


def note_carrying(root: Path, mark: str, trunk: str = "") -> str:
    """The landed, non-partial handoff note whose header carries MARK: a closed spec's record of
    what its job built. A partial note's spec is still in flight, so its header counts for nothing."""
    trunk = trunk or Board.trunk_name(root)
    for n in sorted((root / HANDOFFS).glob("*.md")):
        body = n.read_text(errors="replace")
        commit = re.search(r"^Commit: (\w+)", body, re.M)
        if (carries(note_head(body), mark) and commit and not re.search(r"^Partial: yes", body, re.M)
                and is_ancestor(commit.group(1), trunk)):
            return n.relative_to(root).as_posix()
    return ""


def built_by(root: Path, board: "Board", mark: str, finished: list[dict] | None = None) -> str:
    """What built a staged file, by what the tree holds now: a finished spec still in it (its close
    pending, or kept) carrying the mark, or a closed spec's note. "" for anything else."""
    for x in finished if finished is not None else finished_specs(Snapshot(board.trunk), board):
        if carries((root / x["spec"]).read_text(errors="replace") if (root / x["spec"]).is_file() else "", mark):
            return x["spec"]
    return note_carrying(root, mark, board.trunk)


def quiet_resolve(root: Path, f: Path, carrier: str) -> bool:
    """Whether `resolve` lands a staged file CARRIER built writing nothing: a story, request or
    report, which its spec carried, or a pin-bump whose release trunk's pin holds. A decisions
    file never is: whether its job logged its entries
    is the hubnode's to read (the owner, 2026-11-18), so it stays, noted, for the hubnode."""
    head, _, problems = read_staged(f)
    if not carrier or problems or not addressed_here(head.get("target", ""), root):
        return False
    if head.get("kind") == "pin-bump":
        # Its landing is the pin itself, read from trunk now, as resolve reads it: no content is
        # matched. A job that didn't move the pin leaves it noted, the hubnode's step.
        trunk = Board.trunk_name(root)
        pin = json.loads(git("show", f"{trunk}:{PARA}", cwd=str(root)) or "{}").get("pin") or ""
        return bool(pin) and bool(head.get("release")) and version_key(pin) >= version_key(head["release"])
    return head.get("kind") in ("user-story", "feature-request", "feedback")


def term_owners(glossary: str, holder: set[str] | None = None) -> dict[str, str]:
    """{product: the repo its `Repo:` names} for each product of GLOSSARY (glossary_products),
    or "" where the repo whose glossary it is controls it: `Repo: none`, no `Repo:` yet, or a
    name of HOLDER, that repo's names (this repo's by default). Backticks and a closing period
    are read past, as a hand writes them."""
    names = this_repo_names(main_root()) if holder is None else holder
    out = {}
    for product, fields in glossary_products(glossary).items():
        repo = fields.get("Repo", "").strip().strip("`").rstrip(".").strip("`").strip()
        out[product] = "" if repo.casefold() in ("", "none") or name_in(repo, names) else repo
    return out


def meta_names(loc: Path | None, name: str = "") -> set[str]:
    """The names the metarepo checked out at LOC goes by, NAME and its META's `name`: whose
    glossary a pararepo reads, so its products controlled there read "" in term_owners."""
    try:
        own = json.loads(trunk_show(loc, META) or "{}").get("name", "") if loc is not None else ""
    except ValueError:
        own = ""
    return {name, own} - {""}


def product_of(heading: str, owners: dict[str, str]) -> str:
    """The product a roadmap heading belongs to: the longest term of OWNERS its leading words
    are, case folded; "" for one of the repo's own phases or its own list."""
    h = heading.casefold()
    hits = [t for t in owners if h == t.casefold() or h.startswith(t.casefold() + " ")]
    return max(hits, key=len) if hits else ""


# A phase's type is read from its name, as the owner named the types, so no marker can
# disagree with the name: Greek letters are Prototype, `Pilot <letter>` is Pilot, and any other
# name is Production, its name the owner's choice. Types run in this order within a product.
PHASE_TYPES = ("Prototype", "Pilot", "Production")
GREEK = {"alpha", "beta", "gamma", "delta", "epsilon", "zeta", "eta", "theta", "iota", "kappa",
         "lambda", "mu", "nu", "xi", "omicron", "pi", "rho", "sigma", "tau", "upsilon", "phi",
         "chi", "psi", "omega"}


def phase_type(heading: str, product: str = "") -> str:
    """The type of phase HEADING, read from its name after PRODUCT's term, case folded."""
    name = heading[len(product):].strip() if product else heading.strip()
    if name.casefold() in GREEK:
        return "Prototype"
    if re.fullmatch(r"(?i)pilot\s+[a-z]", name):
        return "Pilot"
    return "Production"


def type_problems(phases: list[dict], owners: dict[str, str]) -> list[str]:
    """Each phase, by line, whose type comes before the type of a phase above it in its
    product (the repo's own phases are one product): a pilot after launch reads as going back."""
    out, top = [], {}
    for p in phases:
        product = product_of(p["name"], owners)
        kind = phase_type(p["name"], product)
        rank = PHASE_TYPES.index(kind)
        if product in top and rank < top[product][0]:
            out.append(f"line {p['line']}: phase {p['name']} ({kind}) comes after {top[product][1]} "
                       f"({PHASE_TYPES[top[product][0]]}): within a product, types run "
                       f"{', then '.join(PHASE_TYPES)}")
        if product not in top or rank > top[product][0]:
            top[product] = (rank, p["name"])
    return out


class Family:
    """A metarepo and its pararepos planning from one roadmap, the metarepo's, read live from
    its checkout's trunk and never at the pin (R6: "read it live"). A pararepo that keeps a
    roadmap of its own, or a repo with no metarepo, is its own family of one. Built once per
    command; every roadmap reader takes it, so no site reads the roadmap its own way."""

    def __init__(self, root: Path, trunk: str):
        self.root, self.trunk = root, trunk
        self.kind, self.meta_loc, self.meta_name = "own", None, ""
        self.text = at_rev(trunk, ROADMAP)
        # The glossary labels name terms of: the metarepo's in a family, read where the roadmap
        # is; a repo's own otherwise. None when there is none, or it can't be reached.
        self.glossary: str | None = at_rev(trunk, GLOSSARY) or None
        self.owners: dict[str, str] = {}
        self.others: list[tuple[str, Snapshot]] = []   # the other reachable repos' trunks
        self.unreachable: list[str] = []
        self._trees: dict[str, set[str]] = {}
        meta, para = load_meta(trunk), load_para(trunk)
        paras: list[str] = []
        if meta is not None:
            self.kind, self.meta_loc = "meta", root
            self.owners = term_owners(at_rev(trunk, GLOSSARY))
            paras = list(meta.get("pararepos") or [])
        elif para is not None and roadmap_home(lambda p: at_rev(trunk, p)) == "meta":
            # A pararepo whose trunk holds its own roadmap, as JSON or in the old Markdown form
            # waiting to convert, plans from it: its pages and glossary judge it, before the
            # conversion and after.
            self.kind, self.meta_name = "para", para.get("meta", "")
            self.meta_loc = meta_checkout(root, para)
            if self.meta_loc is None:
                self.unreachable.append(self.meta_name)
                self.glossary = None
                return
            self.text = trunk_show(self.meta_loc, ROADMAP) or ""
            self.glossary = trunk_show(self.meta_loc, GLOSSARY) or None
            self.owners = term_owners(self.glossary or "", meta_names(self.meta_loc, self.meta_name))
            self.others.append((self.meta_name, Snapshot(Board.trunk_name(self.meta_loc), cwd=self.meta_loc)))
            try:
                paras = list(json.loads(trunk_show(self.meta_loc, META) or "{}").get("pararepos") or [])
            except ValueError:
                paras = []
        else:
            return
        for name in paras:
            loc = repo_path(name)
            if loc is not None and loc.is_dir() and loc.resolve() == root.resolve():
                continue
            if loc is None or not loc.is_dir():
                self.unreachable.append(name)
                continue
            # One that keeps a roadmap of its own is its own family of one: its ids are its
            # roadmap's, and the same `alpha/x` here is another scope.
            if roadmap_home(lambda p: trunk_show(loc, p)) != "meta":
                continue
            self.others.append((name, Snapshot(Board.trunk_name(loc), cwd=loc)))

    @property
    def glossary_name(self) -> str:
        """The glossary as a refusal names it: the metarepo's, prefixed, when read from there."""
        return f"{self.meta_name}'s {GLOSSARY}" if self.kind == "para" else GLOSSARY

    @property
    def reads_meta(self) -> bool:
        """The roadmap is the metarepo's, read from another checkout."""
        return self.kind == "para"

    def owner_loc(self, product: str) -> Path | None:
        """Where a product's controlling repo is checked out; the metarepo for one it controls."""
        owner = self.owners.get(product, "")
        if not owner:
            return self.meta_loc
        loc = repo_path(owner) if owner else None
        return loc if loc is not None and loc.is_dir() else None

    def owner_gone(self, product: str) -> str:
        """The repo a product's owner names when it can't be reached here, else ""."""
        owner = self.owners.get(product, "")
        return owner if product and owner and self.owner_loc(product) is None else ""

    def ours(self, product: str) -> bool:
        """Whether this repo builds the work under a heading of PRODUCT ("" for the
        metarepo's own sections): rig offers only that."""
        if self.kind == "own":
            return True
        if self.kind == "meta":
            return not product or self.owners.get(product) == ""
        loc = self.owner_loc(product) if product else None
        return loc is not None and loc.resolve() == self.root.resolve()

    def pages_of(self, product: str, here: set[str]) -> set[str] | None:
        """The files a `(touches …)` under PRODUCT's heading is looked up in: the metarepo's for
        its own sections and a product it controls, the controlling repo's for a
        pararepo's, each on its trunk; HERE where that is this repo. None when it can't be
        reached."""
        loc = self.meta_loc if not product or self.owners.get(product) == "" else self.owner_loc(product)
        if loc is None:
            return None if product or self.kind == "para" else here
        if loc.resolve() == self.root.resolve():
            return here
        key = str(loc.resolve())
        if key not in self._trees:
            self._trees[key] = set(git("-c", "core.quotePath=false", "ls-tree", "-r", "--name-only",
                                       Board.trunk_name(loc), cwd=str(loc)).splitlines())
        return self._trees[key]

    def page_home(self, sid: str, trunk: str) -> str:
        """Whose trunk a `(touches …)` of SID names a page of, as a refusal says it."""
        product = product_of(sid.rsplit("/", 1)[0].removesuffix(" " + NO_PHASE), self.owners)
        owner = self.owners.get(product, "")
        if product and owner:
            return f"{owner}'s trunk"
        return f"{self.meta_name}'s trunk" if self.kind == "para" else trunk

    def section_of(self, repo: str) -> str:
        """The product a pararepo REPO owns in this metarepo's roadmap, when that repo plans
        from it (has no roadmap of its own); "" otherwise."""
        loc = repo_path(repo)
        if self.kind != "meta" or loc is None or not loc.is_dir() or roadmap_home(lambda p: trunk_show(loc, p)) != "meta":
            return ""
        return next((t for t in sorted(self.owners) if self.owner_loc(t) is not None
                     and self.owner_loc(t).resolve() == loc.resolve()), "")

    def products_in(self) -> list[str]:
        """The products the roadmap's headings belong to."""
        heads = [p["name"] for p in roadmap_phases(self.text)] + [i["list"].removesuffix(" " + NO_PHASE)
                                                                 for i in roadmap_list_items(self.text)]
        return sorted({product_of(h, self.owners) for h in heads} - {""})

    def unknown_owners(self) -> list[tuple[str, str]]:
        """(product, repo) for each product heading whose `Repo:` names no repo jig knows."""
        heads = {p["name"] for p in roadmap_phases(self.text)} | {i["list"] for i in roadmap_list_items(self.text)}
        prods = {product_of(h, self.owners) for h in heads} - {""}
        return sorted((pr, self.owners[pr]) for pr in prods
                      if self.owners[pr] and repo_path(self.owners[pr]) is None)


_FAMILIES: dict[tuple[str, str], "Family"] = {}


def family(root: Path | None = None, trunk: str = "") -> "Family":
    """This repo's family, built once per command: every roadmap reader asks for it. Keyed on
    the trunk checkout, whatever worktree asks, so a job's worktree never sees its own repo
    as another one."""
    root = main_root()
    trunk = trunk or Board.trunk_name(root)
    key = (str(root.resolve()), trunk)
    if key not in _FAMILIES:
        _FAMILIES[key] = Family(root, trunk)
    return _FAMILIES[key]


def roadmap_list(snap: Snapshot, fam: "Family | None" = None) -> list[dict]:
    """The one list's items, each with its specs, state and waits as a scope has them, plus
    its touches, its short `item` id and `plain` text without the pages."""
    full = roadmap_full(snap, fam)
    return full[1] if full else []


_TAKERS: dict[tuple, tuple] = {}


def scope_takers(snap: Snapshot, label: str = "") -> tuple[dict[str, list[tuple[str, bool]]], dict[str, str]]:
    """({scope id: [(spec, complete)]}, {closed spec: its note}) from SNAP's specs and notes,
    each spec named as LABEL's (`<repo>:<path>`) when it is another repo's. A commit's answer
    never changes, so it is read once per command."""
    key = (snap.rev, str(snap.cwd), label) if snap.where == "rev" else None
    if key and key in _TAKERS:
        return _TAKERS[key]
    out = _scope_takers(snap, label)
    if key:
        _TAKERS[key] = out
    return out


def _scope_takers(snap: Snapshot, label: str) -> tuple[dict[str, list[tuple[str, bool]]], dict[str, str]]:
    takes: dict[str, list[tuple[str, bool]]] = {}
    tree = [f for f in snap.ls(SPECS) if is_spec(f)]
    notes = completing_notes(snap)
    name = lambda f: f"{label}:{f}" if label else f
    for f in tree:
        for sc in spec_scopes(snap.show(f)):
            # A note may name its spec by file name alone; the spec's path or its name both count.
            takes.setdefault(sc, []).append((name(f), bool(note_for(f, notes))))
    # A closed spec's scopes live on its note's `Scope:` line; a spec still in the tree wins.
    names = {Path(f).name for f in tree}
    closed: dict[str, str] = {}
    for spec, note in sorted(notes.items()):
        if spec not in tree and Path(spec).name not in names:
            for sc in spec_scopes(note_head(snap.show(note))):
                takes.setdefault(sc, []).append((name(spec), True))
                closed[name(spec)] = name(note)
    return takes, closed


_FULL: dict[tuple, object] = {}


def roadmap_full(snap: Snapshot, fam: "Family | None" = None) -> tuple[list[dict], list[dict]] | None:
    """roadmap_state's reading, once per commit and family for the command: rig and the hooks
    ask for it several times, and each read pulls every repo the family reaches. Callers get
    their own copy, since some annotate what they read."""
    key = (snap.rev, str(snap.cwd), id(fam)) if snap.where == "rev" else None
    if key is None:
        return _roadmap_full(snap, fam)
    if key not in _FULL:
        _FULL[key] = _roadmap_full(snap, fam)
    return copy.deepcopy(_FULL[key])


def _roadmap_full(snap: Snapshot, fam: "Family | None" = None) -> tuple[list[dict], list[dict]] | None:
    """(phases, the one list's items), every scope and item with its specs and state, every
    phase with its state; None when there is no roadmap. The list is given states as a
    phase's scopes are, and is never a phase: it has no state, and is never current. With a
    family FAM, the roadmap is the metarepo's, its states pulled from every repo FAM reaches,
    each product with a current phase of its own; a product whose owner can't be reached
    reads `unknown`."""
    text = fam.text if fam is not None and fam.reads_meta else snap.show(ROADMAP)
    if not text:
        return None
    owners = fam.owners if fam is not None else {}
    phases = roadmap_phases(text)
    items = roadmap_list_items(text)
    lp = list_phase(items)
    takes: dict[str, list[tuple[str, bool]]] = {}
    closed: dict[str, str] = {}
    for label, sn in [("", snap)] + (fam.others if fam is not None else []):
        t, c = scope_takers(sn, label)
        for sc, specs in t.items():
            takes.setdefault(sc, []).extend(specs)
        closed.update(c)
    for p in phases:
        p["product"] = product_of(p["name"], owners)
        p["type"] = phase_type(p["name"], p["product"])
    for p in phases + [lp]:
        p["scopes"] = [{"id": sid, "what": what, "bare": p.get("plain_of", {}).get(sid, what),
                        "touches": p.get("touches_of", {}).get(sid, []), "specs": takes.get(sid, []),
                        "notes": {f: closed[f] for f, _ in takes.get(sid, []) if f in closed},
                        "after": waits_of(p, sid), "labels": p.get("labels_of", {}).get(sid, ([], 0))[0]}
                       for sid, what in p["scopes"]]
        for s in p["scopes"]:
            s["product"] = p.get("product", "")
            s["state"] = ("open" if not s["specs"] else
                          "done" if all(ok for _, ok in s["specs"]) else "taken")
        # A phase with nothing in it has nothing to finish, so it is never done: it would
        # otherwise read as finished work.
        p["empty"] = not p["scopes"] and not p["exit"]
        p["done"] = not p["empty"] and all(s["state"] == "done" for s in p["scopes"]) and all(t for t, _ in p["exit"])
    for s, i in zip(lp["scopes"], items):
        s.update(item=i["id"], plain=i["what"], touches=i["touches"], line=i["line"], labels=i["labels"] or [],
                 product=product_of(i["list"].rsplit(" ", 2)[0] if i["list"] != NO_PHASE else "", owners))
    # Specs and notes are read from every repo reached; a product's owner out of reach may hold
    # the one that takes a scope, so its state is unknown rather than open.
    gone = {pr for pr in owners if fam is not None and fam.owner_gone(pr)}
    for x in [sc for p in phases for sc in p["scopes"]] + lp["scopes"]:
        if x["product"] in gone and x["state"] != "done":
            x["state"] = "unknown"
    # Blocked is derived from refs, as states are from specs: a qualifier, never a fourth state.
    done = {p["name"] for p in phases if p["done"]} | {s["id"] for p in phases + [lp] for s in p["scopes"]
                                                       if s["state"] == "done"}
    for s in lp["scopes"]:
        s["waits"] = [r for r in s["after"] if r not in done]
    lp.pop("done", None)
    # Each product's phases are ordered among themselves in file order, and so are the repo's
    # own: nothing orders one product after another but an (after …).
    current: set[str] = set()
    for p in phases:
        p["waits"] = [r for r in p["after"] if r not in done]
        for s in p["scopes"]:
            s["waits"] = [r for r in s["after"] if r not in done]
        # A phase still waiting on another isn't current work: the next one that can be is.
        if p.pop("done"):
            p["state"] = "done"
        elif p["product"] not in current and not p["waits"]:
            p["state"] = "current"
            current.add(p["product"])
        else:
            p["state"] = "next"
    return phases, lp["scopes"]


# What `jig init` writes, `jig update` adds and a command finding none commits.
ROADMAP_SEED = roadmap_dumps(ROADMAP_SEED_DATA)
SEED_SUBJECT = "roadmap: the empty structure jig init writes"


def roadmap_withheld(here: Path, trunk: str = "") -> str:
    """Why no roadmap is written here, or "": a pararepo plans from its metarepo's, an old
    roadmap.md converts instead, and a root ROADMAP.md that is the repo's own is a roadmap for
    the owner to move in first."""
    # Trunk's, as every site asking roadmap_home reads it; the checkout's where no trunk is named.
    home = roadmap_home((lambda p: at_rev(trunk, p)) if trunk else (lambda p: (here / p).exists()))
    if ((here / PARA).is_file() or trunk and load_para(trunk) is not None) and home != "unconverted":
        return "para"
    if home == "unconverted":
        if trunk and (here / ROADMAP).exists() and not (here / OLD_ROADMAP).exists():
            return f"{OLD_ROADMAP} is converted to {ROADMAP} here, and not committed: commit the conversion on {trunk}"
        return f"{OLD_ROADMAP} is the roadmap in jig's old form: `jig update --apply` converts it to {ROADMAP}"
    if not (here / ROADMAP).exists() and ((here / OLD_ROADMAP_VIEW).is_file() or trunk and at_rev(trunk, OLD_ROADMAP_VIEW)):
        return (f"{OLD_ROADMAP_VIEW} is the repo's own: move what it holds into {ROADMAP} first, "
                "with `jig roadmap --draft` and `--edit` (`jig update` lists it)")
    return ""


def empty_roadmap(raw: str) -> bool:
    """A roadmap holding no phase and no item: the seed, or one emptied since."""
    return not roadmap_phases(raw) and not roadmap_list_items(raw)


def write_seed(here: Path) -> None:
    (here / ROADMAP).parent.mkdir(parents=True, exist_ok=True)
    (here / ROADMAP).write_text(ROADMAP_SEED)


def ensure_roadmap(root: Path, trunk: str = "", *, init: bool = False, write: bool = True) -> None:
    """The roadmap's empty structure where a stand-alone repo or metarepo has none. INIT: in
    ROOT's files, left uncommitted like the rest of init. Otherwise trunk's: committed alone
    in the trunk checkout on trunk with nothing staged (R5, and `merge` and `rig --close`
    refuse a dirty tree), and anywhere else, or without WRITE, one line saying where it is
    written. Lines go to stderr, so `--json` stays parseable."""
    if init:
        if (root / PARA).is_file() and (root / ROADMAP).is_file() and empty_roadmap(read_raw(root / ROADMAP)):
            # A plain init before `init --para` wrote the seed: a pararepo plans from its
            # metarepo's, and an empty structure holds nothing to move in.
            if git("ls-files", "--", ROADMAP, cwd=str(root)):
                git("rm", "-q", "-f", "--", ROADMAP, check=True, cwd=str(root))
            else:
                (root / ROADMAP).unlink(missing_ok=True)
            print(f"removed {ROADMAP}, the empty structure: a pararepo plans from its metarepo's roadmap")
            return
        why = "" if (root / ROADMAP).exists() else roadmap_withheld(root)
        if (root / ROADMAP).exists() or why == "para":
            return
        if why:
            print(f"{ROADMAP} not written: {why}")
            return
        write_seed(root)
        print(f"wrote {ROADMAP}, the roadmap's empty structure")
        return
    main = main_root()
    trunk = trunk or Board.trunk_name(main)
    if at_rev(trunk, ROADMAP):
        return
    why = roadmap_withheld(main, trunk)
    if why == "para":
        return
    if why:
        print(f"jig: {trunk} has no {ROADMAP}: {why}", file=sys.stderr)
        return
    held = seed_held(root, main, trunk, write)
    if held:
        print(f"jig: {trunk} has no {ROADMAP}: {held}", file=sys.stderr)
        return
    write_seed(main)
    git("add", "--", ROADMAP, check=True, cwd=str(main))
    # A metarepo's subjects lead with an id (M6), so its seed commit leads with ROADMAP.
    subject = f"ROADMAP: {SEED_SUBJECT.split(': ', 1)[1]}" if (main / META).is_file() else SEED_SUBJECT
    # The pathspec commits this file alone, whatever else the index holds.
    if subprocess.run(["git", "commit", "-q", "-m", subject, "--", ROADMAP],
                      cwd=str(main)).returncode:
        print(f"jig: {ROADMAP} is written and staged but not committed: fix what the hook refused, "
              "then `git commit`", file=sys.stderr)
        return
    _FAMILIES.clear()
    print(f"jig: committed {ROADMAP} on {trunk}: {subject}", file=sys.stderr)


def in_progress(where: Path) -> str:
    """The git operation under way in WHERE's checkout, or "": a commit jig makes there by itself
    would otherwise become that merge's or pick's commit, under jig's subject. A clean tree
    doesn't show it: a clean `git merge --no-commit` stages nothing a status reports."""
    return next((what for ref, what in (("MERGE_HEAD", "a merge"), ("CHERRY_PICK_HEAD", "a cherry-pick"),
                                         ("REVERT_HEAD", "a revert"), ("rebase-apply", "a rebase or `git am`"),
                                         ("rebase-merge", "a rebase"))
                 if Path(git("rev-parse", "--path-format=absolute", "--git-path", ref, cwd=str(where))).exists()),
                "")


def seed_held(root: Path, main: Path, trunk: str, write: bool) -> str:
    """Why the seed isn't committed here, said as what to do, or "" when it may be: its commit
    is the trunk checkout's own, and never lands inside someone's merge or staged work."""
    later = f"`jig roadmap` in the {trunk} checkout writes it"
    if not is_main_worktree(root):
        return f"this is a worktree, not the {trunk} checkout: {later}"
    if not write:
        return later
    if git("branch", "--show-current") != trunk:
        return f"the {trunk} checkout is on another branch: {later} once it is back on {trunk}"
    state = in_progress(main)
    if state:
        return f"{state} is in progress here: finish it, then {later}"
    if (main / ROADMAP).exists():
        return (f"{ROADMAP} is here but not on {trunk}, perhaps left staged by a refused commit: "
                "commit it, or remove it and run `jig roadmap` again")
    if git("diff", "--cached", "--name-only", cwd=str(main)):
        return f"changes are staged here: commit or unstage them, then {later}"
    return ""


# `jig roadmap`'s filters, each repeatable: values of one flag are or'd, different flags and'ed.
# One table, so a new filter (a label, say) is one row here and its test in roadmap_filter,
# which refuses a row it has no test for: a filter it ignored would print the whole roadmap.
ROADMAP_FILTERS = {
    "product": "a product's term, as its glossary section names it",
    "phase": "a phase's name, with or without its product (`alpha`, `Widget alpha`), or `No phase`",
    "type": "prototype, pilot or production",
    "state": "open, taken, done, blocked (open and waiting) or unknown",
    "owner": "the repo that owns the work: a product's Repo:, or this repo for its own phases",
    "label": "a glossary term a scope or item carries as a label, any case and spacing",
}
FILTER_STATES = ("open", "taken", "done", "blocked", "unknown")


def roadmap_filters(args) -> dict[str, set[str]]:
    """The filters ARGS sets, each flag's values case folded; {} for none."""
    return {k: {v.casefold() for v in vals} for k in ROADMAP_FILTERS if (vals := getattr(args, k, None))}


def roadmap_filter(phases: list[dict], items: list[dict], filt: dict[str, set[str]],
                   owners: dict[str, str], me: str, mine: set[str] = frozenset(),
                   self_names: set[str] = frozenset(), ident=str.casefold,
                   glossary: str | None = None) -> tuple[list[dict], list[dict]]:
    """(phases, items) FILT chooses. Product, phase, type and owner choose phases; state chooses
    scopes within them, and a phase it leaves with no scope goes. A list item matches product,
    owner and state; `No phase` among the phases chooses the lists, and a type leaves them out.
    ME is the repo the roadmap's own sections and the products it controls belong to; an owner
    value naming this repo by any name jig knows it by (SELF_NAMES) means the owners in MINE.
    Owners are compared as IDENT reads them, one repo however it is named (an alias, its listed
    name). A value naming nothing jig knows dies, naming the known ones, so a typo never
    reads as an empty roadmap. A label, like a state, chooses scopes within the phases; it
    names a term of GLOSSARY, the glossary's text, as label_problems judges a label."""
    if untested := sorted(set(filt) - {"product", "phase", "type", "state", "owner", "label"}):
        die(f"--{untested[0]} has no test in roadmap_filter: add one there, or the filter would "
            "print the whole roadmap")
    owner_of = lambda pr: ident(owners[pr] if pr and owners.get(pr, "") else me)
    if "owner" in filt:
        repos = {ident(me)} | {owner_of(pr) for pr in owners} | {ident(o) for o in mine}
        named = {v: {ident(o) for o in (mine if name_in(v, self_names) else {v})} for v in filt["owner"]}
        if bad := sorted(v for v, ids in named.items() if not ids <= repos):
            die(f"--owner {', '.join(bad)}: no such owner; known: "
                f"{', '.join(sorted({me} | {owners[pr] or me for pr in owners}))}")
        filt = dict(filt, owner=set().union(*named.values()))
    lists = [i["id"].rsplit("/", 1)[0] for i in items]
    known = {
        "product": sorted(owners),
        "phase": [p["name"] for p in phases] + sorted({NO_PHASE, *lists}),
        "type": [t.casefold() for t in PHASE_TYPES],
        "state": list(FILTER_STATES),
    }
    also = {"phase": {(p["name"][len(p["product"]):].strip() if p["product"] else p["name"]).casefold()
                      for p in phases}}
    if "label" in filt:
        terms = glossary_terms(glossary or "")
        if bad := sorted(v for v in filt["label"] if label_problems([v], glossary, "")):
            die(f"--label {', '.join(bad)}: no glossary term" + (f"; known: {', '.join(terms)}" if terms else
                                                                 ": this repo's labels have no glossary"))
        filt = dict(filt, label={label_fold(v) for v in filt["label"]})
    for k, vals in filt.items():
        if k in ("owner", "label"):
            continue
        if bad := sorted(vals - {x.casefold() for x in known[k]} - also.get(k, set())):
            die(f"--{k} {', '.join(bad)}: {'no such ' + k if known[k] else 'this roadmap has no ' + k + 's'}"
                + (f"; known: {', '.join(known[k])}" if known[k] else ""))

    def chosen(k: str, value: str) -> bool:
        return k not in filt or value.casefold() in filt[k]

    def scope_in(s: dict) -> bool:
        if "label" in filt and not {label_fold(l) for l in s.get("labels") or []} & filt["label"]:
            return False
        if "state" not in filt:
            return True
        states = {s["state"]} | ({"blocked"} if s["state"] == "open" and s.get("waits") else set())
        return bool(states & filt["state"])

    def common(product: str) -> bool:
        return chosen("product", product) and chosen("owner", owner_of(product))

    out = []
    for p in phases:
        own = p["name"][len(p["product"]):].strip() if p["product"] else p["name"]
        if not common(p["product"]) or not chosen("type", p["type"]):
            continue
        if "phase" in filt and not ({p["name"].casefold(), own.casefold()} & filt["phase"]):
            continue
        scopes = [s for s in p["scopes"] if scope_in(s)]
        if ("state" in filt or "label" in filt) and not scopes:
            continue
        out.append(dict(p, scopes=scopes))
    # A list item is in no phase: `--phase "No phase"`, or its product's list by name, chooses it.
    kept = [i for i in items if "type" not in filt and common(i["product"]) and scope_in(i)
            and ("phase" not in filt or {NO_PHASE.casefold(), i["id"].rsplit("/", 1)[0].casefold()} & filt["phase"])]
    return out, kept


def cmd_roadmap(root: Path, args) -> int:
    board = Board.load(root, working_tree=True)
    trunk = board.trunk
    ensure_roadmap(root, trunk)
    fam = family(root, trunk)
    if (args.draft or args.edit is not None) and (roadmap_filters(args) or args.show or args.json or args.id):
        die("--draft and --edit take no filter, no show and no query: the draft is the whole roadmap")
    if args.show and (args.json or args.id):
        die("show draws a chart; --json and --id ask for records: one or the other")
    if args.draft:
        return roadmap_draft(main_root(), fam, trunk)
    if args.edit is not None:
        return roadmap_edit(main_root(), fam, trunk, args.edit)
    filt = roadmap_filters(args)
    snap = Snapshot(trunk)
    if fam.reads_meta and fam.meta_loc is None:
        print(f"the roadmap is {fam.meta_name}'s, which can't be reached here (`jig repos`)")
        return 0
    full = roadmap_full(snap, fam)
    if full is None:
        # ensure_roadmap said above why trunk has none yet, and where it is written.
        return 0
    phases, items = full
    text = fam.text if fam.reads_meta else snap.show(ROADMAP)
    me = fam.meta_name if fam.reads_meta else \
        (load_meta(trunk) or {}).get("name") or board.data.get("name") or main_root().name
    # In a pararepo planning from the metarepo's roadmap, this repo owns the products whose
    # Repo: names it; elsewhere it owns the roadmap's own sections.
    names = this_repo_names(root)
    mine = ({o for o in fam.owners.values() if o and name_in(o, names)} if fam.reads_meta
            else {me})
    def repo_ident(name: str) -> str:
        found = repo_matches(name)
        return (found[0] if len(found) == 1 else name).casefold()
    shown, shown_items = roadmap_filter(phases, items, filt, fam.owners, me, mine, names, repo_ident,
                                        fam.glossary)
    # The chart and the query go to stdout alone, so they can be piped; the problems still
    # print, to stderr.
    say = (lambda *a: print(*a, file=sys.stderr)) if args.show or args.json or args.id else print
    if fam.reads_meta:
        say(f"{ROADMAP} is {fam.meta_name}'s, read from its trunk")
    raw = roadmap_raw(Board.trunk_name(fam.meta_loc), cwd=fam.meta_loc) if fam.reads_meta else roadmap_raw(trunk)
    problems = roadmap_file_problems(raw, fam.owners, fam.glossary_name) + roadmap_problems(
        text, fam, set(snap.ls("docs/")), trunk)
    for x in problems:
        say(x if x.startswith(ROADMAP) else f"{ROADMAP} {x}")
    for name in fam.unreachable:
        say(f"{name} can't be reached here (`jig repos`): its products' scopes read unknown")
    if fam.kind == "meta":
        for who, ref in unconfirmed(text, fam.owners):
            say(f"unconfirmed: {who} waits on {ref}, whose section doesn't say (needed by {who}): "
                "the owner rules on it; it blocks nothing")
    if filt and not shown and not shown_items:
        say("nothing in the roadmap matches these filters")
    for line in label_heads(fam, {label_fold(v) for v in filt.get("label", ())}):
        say(line)
    # Read by label, the work may be any repo's: each line names whose.
    whose = (lambda s: work_owner(fam, s.get("product", ""))) if "label" in filt else (lambda s: "")
    if args.show:
        print(render_show(shown, shown_items, args.width), end="")
        return 1 if problems else 0
    if args.json or args.id:
        print(json.dumps(roadmap_query(raw, shown, shown_items, args.id), indent=2, ensure_ascii=False))
        return 1 if problems else 0
    for p in shown:
        print(f"{p['name']}  {p['type']}, {p['state']}"
              + ("  (empty: no scopes and no exit boxes)" if p["empty"] else ""))
        for n in p["note"]:
            print(f"  {n}".rstrip())
        for t, what in p["exit"]:
            print(f"  [{'x' if t else ' '}] {what}")
        for s in p["scopes"]:
            specs = ", ".join(f"{f} ({'complete' if ok else 'in progress'})" for f, ok in s["specs"])
            after = f"after {', '.join(s['waits'])}" if s["state"] == "open" and s["waits"] else ""
            labels = f"labels {', '.join(s['labels'])}" if s["labels"] else ""
            print(f"  {s['id']:<24} {s['state']:<6} {'  '.join(x for x in (whose(s), labels, after, specs) if x)}".rstrip())
    if shown_items:
        print(NO_PHASE)
        for s in shown_items:
            specs = ", ".join(f"{f} ({'complete' if ok else 'in progress'})" for f, ok in s["specs"])
            after = f"after {', '.join(s['waits'])}" if s["state"] == "open" and s["waits"] else ""
            pages = f"(touches {', '.join(s['touches'])})" if s["touches"] else ""
            labels = f"labels {', '.join(s['labels'])}" if s["labels"] else ""
            print(f"  {s['id']:<24} {s['state']:<6} {'  '.join(x for x in (whose(s), labels, after, pages, specs) if x)}".rstrip())
    return 1 if problems else 0


def roadmap_query(raw: str, phases: list[dict], items: list[dict], ids: list[str]) -> dict:
    """The records the filters chose (PHASES, ITEMS), each with its key and its derived state,
    as `jig roadmap --json` prints them: an agent asks jig for the records it needs rather than
    reading the roadmap file. IDS, when given, keep only those: a phase by its key, a scope or
    an item by its id. An id the roadmap lacks dies, naming it."""
    data = roadmap_records(raw) or {}
    recs = {f"{k}/{r.get('id')}": r for k, r in records_in(data)}
    own = {phase_key(p): {k: v for k, v in p.items() if k != "scopes"}
           for p in data.get("phases") or [] if isinstance(p, dict)}
    if ids:
        known = set(recs) | set(own)
        if missing := [i for i in ids if i not in known]:
            die(f"the roadmap has no {', '.join(missing)}: an id is <phase>/<scope>, <list>/<item> or a "
                "phase's name (`jig roadmap` lists them)")
    want = set(ids)
    out: dict = {"phases": [], "no_phase": []}
    for p in phases:
        whole = not want or p["name"] in want
        scopes = [{"id": s["id"], "state": s["state"], "record": recs.get(s["id"], {})}
                  for s in p["scopes"] if whole or s["id"] in want]
        if whole or scopes:
            out["phases"].append({"key": p["name"], "type": p["type"], "state": p["state"],
                                  "record": own.get(p["name"], {}), "scopes": scopes})
    out["no_phase"] = [{"id": i["id"], "state": i["state"], "record": recs.get(i["id"], {})}
                       for i in items if not want or i["id"] in want]
    return out


def roadmap_problems(text: str, fam: "Family", have: set[str], trunk: str) -> list[str]:
    """Each thing in roadmap TEXT jig refuses or reports, by line: its shape, its refs, its
    labels, a touched page HAVE (or the owning repo's trunk) lacks, an owner jig doesn't know.
    `jig roadmap` prints them; `--edit` refuses a draft holding any."""
    problems: list[str] = []
    parsed = roadmap_phases(text, problems)
    problems += ref_problems(parsed, roadmap_list_items(text, problems))
    problems += type_problems(parsed, fam.owners)
    problems += roadmap_label_problems(text, fam.glossary, fam.glossary_name)
    problems += [f"{iid} touches {page}, which {fam.page_home(iid, trunk)} has no page for: re-point it"
                 for iid, page in sorted(dead_touches(text, have, fam))]
    problems += [f"product {pr}: its Repo: names {o}, which `jig repos` doesn't know"
                 for pr, o in fam.unknown_owners()]
    return [unline(x) for x in problems]


def label_heads(fam: "Family", labels: set[str]) -> list[str]:
    """`<term>: owned by <repo>` for each glossary term LABELS (label_fold'ed) name under a
    product, with its controlling repo (the product's `Repo:`, or this repo for its own): what
    `--label` is headed by, so a repo sees whose feature the work leans on (R2)."""
    if fam.kind == "own":
        return []
    meta = fam.meta_name if fam.kind == "para" else "this repo"
    out = {}
    for e in glossary_entries(fam.glossary or ""):
        # A shared term, under `Basic terms`, belongs to no product: no repo heads it.
        if e["level"] <= 3 and not e["title"] and label_fold(e["name"]) in labels \
                and (e["product"] or e["level"] == 1) \
                and e["product"] != BASIC_TERMS and e["name"] != BASIC_TERMS:
            product = e["name"] if e["level"] == 1 else e["product"]
            out[e["name"]] = fam.owners.get(product, "") or meta
    return [f"{t}: owned by {o}" for t, o in sorted(out.items())]


def work_owner(fam: "Family", product: str) -> str:
    """The repo that builds work under PRODUCT ("" for the roadmap's own sections), as `--label`
    names it; "" in a stand-alone repo, where everything is its own."""
    if fam.kind == "own":
        return ""
    owner = fam.owners.get(product, "") if product else ""
    return owner or (fam.meta_name if fam.kind == "para" else "this repo")


# ------------------------------------------------------------- the edit command

def draft_path() -> Path:
    """The draft `jig roadmap --draft` writes: under the git common dir, outside every tree, so
    no second copy of the roadmap is ever committed."""
    return Path(git("rev-parse", "--path-format=absolute", "--git-common-dir")) / "jig" / "roadmap-draft.json"


def base_raw(fam: "Family", trunk: str) -> str:
    """The roadmap file this repo plans from, as JSON: trunk's, or the metarepo's trunk's."""
    if fam.reads_meta:
        return roadmap_raw(Board.trunk_name(fam.meta_loc), cwd=fam.meta_loc) if fam.meta_loc else ""
    return roadmap_raw(trunk)


def heading_product(heading: str, owners: dict[str, str]) -> str:
    """The product a roadmap heading, a phase's or a list's, belongs to; "" for the repo's own."""
    if not heading or heading.strip().lower() == NO_PHASE.lower():
        return ""
    return product_of(heading.removesuffix(" " + NO_PHASE) if is_list_heading(heading) else heading, owners)


def may_change(fam: "Family", heading: str) -> bool:
    """Whether this repo may change the section under HEADING: a pararepo its products', the
    metarepo its own and the products it owns as this repo, a stand-alone repo all of it."""
    if fam.kind == "own":
        return True
    if fam.kind == "para" and not heading:
        return False
    return fam.ours(heading_product(heading, fam.owners))


def heading_owner(fam: "Family", heading: str) -> str:
    return fam.owners.get(heading_product(heading, fam.owners), "") or fam.meta_name or "this repo"


def roadmap_draft(root: Path, fam: "Family", trunk: str) -> int:
    """`jig roadmap --draft`: the roadmap this repo plans from, live, as a draft to edit."""
    if fam.kind == "para" and fam.meta_loc is None:
        die(f"the roadmap is {fam.meta_name}'s, which can't be reached here (`jig repos`)")
    base = roadmap_base(root, fam, trunk)
    if not base:
        die(f"nothing written: {fam.meta_name}'s {ROADMAP} isn't on its trunk yet" if fam.kind == "para"
            else f"nothing written: {ROADMAP} isn't on {trunk} yet (above)")
    path = draft_path()
    if path.exists() and not same_roadmap(path.read_text(), base):
        die(f"{path} is a draft that differs from the roadmap: `jig roadmap --edit` it, or delete it")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(roadmap_dumps(roadmap_records(base) or ROADMAP_SEED_DATA))
    print(f"wrote {path}")
    # A glossary product the roadmap doesn't include gets no list: the hook refuses its heading.
    included = set((roadmap_records(base) or {}).get("products") or [])
    heads = [h for h, _, _ in roadmap_sections(base) if h and may_change(fam, h)]
    if fam.kind != "own":
        # A product's list may be added though its heading isn't there yet.
        mine = sorted({heading_product(h, fam.owners) for h in heads} - {""})
        if fam.kind == "meta":
            mine += [p for p, o in sorted(fam.owners.items()) if not o and p not in mine]
        if fam.kind == "para":
            mine += [p for p in sorted(fam.owners) if p not in mine and fam.ours(p)]
        heads += [f"{p} {NO_PHASE}" for p in mine if p in included and f"{p} {NO_PHASE}" not in heads]
    print("this repo may change: " + ("all of it" if fam.kind == "own" else ", ".join(f"## {h}" for h in heads)
                                      + (f", and its own phases and ## {NO_PHASE}" if fam.kind == "meta" else "")))
    print(f"edit it, then `jig roadmap --edit`")
    return 0


def roadmap_changes(old: str, new: str, keep) -> tuple[list[str], list[str]]:
    """(the sections KEEP accepts whose records NEW changes from OLD, what changed): `added`,
    `changed` and `removed <id>` for each scope and item whose text, labels, waits or touches
    differ, and `changed § <key>` for a section changed in nothing else (an exit check, a note,
    a phase's own waits). Judged by the records, so no edit is ever taken for none."""
    old_s = {h: t for h, _, t in roadmap_sections(old) if keep(h)}
    new_s = {h: t for h, _, t in roadmap_sections(new) if keep(h)}
    heads = [h for h in list(old_s) + [h for h in new_s if h not in old_s] if old_s.get(h, "") != new_s.get(h, "")]

    def reading(raw: str, h: str) -> dict[str, tuple]:
        return {f"{key}/{r.get('id')}": json.dumps(r, sort_keys=True, ensure_ascii=False)
                for key, r in records_in(roadmap_records(raw) or {}, lambda k: k == h)}
    changes = []
    for h in heads:
        a, b = reading(old, h), reading(new, h)
        ids = ([f"added {i}" for i in b if i not in a] + [f"changed {i}" for i in b if i in a and a[i] != b[i]]
               + [f"removed {i}" for i in a if i not in b])
        changes += ids or [f"changed § {h}" if h else "changed `products`"]
    return heads, changes


def section_refusals(old: str, new: str, may, owner_of, who: str, newcomer: bool) -> list[str]:
    """Each section of roadmap NEW that differs from OLD under a key MAY refuses: another repo's
    (OWNER_OF names it), or, NEWCOMER, a new section naming no product WHO owns. `jig roadmap
    --edit` and the hook on a pararepo's proposal branch both ask it."""
    old_s = {h: t for h, _, t in roadmap_sections(old)}
    new_s = {h: t for h, _, t in roadmap_sections(new)}
    out = []
    for h in list(old_s) + [h for h in new_s if h not in old_s]:
        if old_s.get(h, "") == new_s.get(h, "") or may(h):
            continue
        name = f"## {h}" if h else "`products`"
        if not h:
            out.append(f"`products` adds or drops a product {who} doesn't own: a product's inclusion is "
                       "the metarepo hubnode's, or comes with the items a move carries into it")
            continue
        if h not in old_s and newcomer:
            out.append(f"{name} names no product {who} owns: a new product is the metarepo "
                       "hubnode's, its glossary product with its Repo: line first")
        else:
            out.append(f"{name} is {owner_of(h)}'s: {who} changes only its own sections")
    return out


def unknown_labels(text: str, fam: "Family", keep) -> dict[str, list[str]]:
    """{label: [scope ids]} for each label TEXT's sections KEEP accepts name that the glossary
    lacks, by label_problems' check."""
    out: dict[str, list[str]] = {}
    labelled = [(sid, labels) for p in roadmap_phases(text) if keep(p["name"])
                for sid, (labels, _) in p["labels_of"].items()]
    labelled += [(i["sid"], i["labels"]) for i in roadmap_list_items(text) if i["labels"] and keep(i["list"])]
    for sid, labels in labelled:
        for l in labels or []:
            if label_problems([l], fam.glossary, ""):
                out.setdefault(l, []).append(sid)
    return out


def drop_labels(raw: str, drop: set[str]) -> str:
    """The roadmap file RAW with each label in DROP left off the scopes and items naming it."""
    data = roadmap_load(raw)
    if data is None or not drop:
        return raw
    for _, r in records_in(data):
        if r.get("labels") and set(r["labels"]) & drop:
            kept = [l for l in r["labels"] if l not in drop]
            if kept:
                r["labels"] = kept
            else:
                del r["labels"]
    return roadmap_dumps(data)


def splice_sections(raw: str, new: str, keep) -> str:
    """The roadmap file RAW with every section whose key KEEP accepts replaced, whole, by NEW's:
    removed when NEW lacks it, and NEW's own added after the last of them, or at the end of
    their kind (phases, or lists). Every other section stays as it is."""
    mine = [(h, copy.deepcopy(recs)) for h, recs in section_records(new) if h and keep(h)]
    out: list[tuple[str, list]] = []
    placed, last = set(), {False: -1, True: -1}
    for h, recs in section_records(raw):
        if h and keep(h):
            got = next((r for nh, r in mine if nh == h), None)
            if got is not None:
                out.append((h, got))
                placed.add(h)
            last[is_list_heading(h)] = len(out) - 1
            continue
        out.append((h, copy.deepcopy(recs)))
    for h, recs in mine:
        if h in placed:
            continue
        lst = is_list_heading(h)
        at = last[lst] + 1 if last[lst] >= 0 else (len(out) if lst else
                                                   next((k for k, (oh, _) in enumerate(out) if is_list_heading(oh)), len(out)))
        out.insert(at, (h, recs))
        last[lst] = at
        if not lst and last[True] >= at:
            last[True] += 1
    return from_sections(out)


def plumb_commit(loc: Path, branch: str, path: str, text: str, message: str) -> str:
    """Commit TEXT as PATH on BRANCH in the checkout at LOC without moving any checkout: a
    temporary index, `commit-tree`, and `update-ref` from the old tip, so a tip moved meanwhile
    refuses rather than being lost. Returns why it failed, "" once written."""
    tip = git("rev-parse", "-q", "--verify", f"refs/heads/{branch}", cwd=str(loc))
    if not tip:
        return f"{branch} isn't there"
    with tempfile.TemporaryDirectory() as d:
        env = {**os.environ, "GIT_INDEX_FILE": str(Path(d) / "index")}

        def run(*a: str, stdin: str | None = None) -> str:
            p = subprocess.run(["git", *a], cwd=str(loc), env=env, input=stdin, capture_output=True, text=True)
            if p.returncode:
                raise RuntimeError(p.stderr.strip() or f"git {a[0]} failed")
            return p.stdout.strip()
        try:
            blob = run("hash-object", "-w", "--stdin", stdin=text)
            run("read-tree", tip)
            run("update-index", "--add", "--cacheinfo", f"100644,{blob},{path}")
            new = run("commit-tree", run("write-tree"), "-p", tip, "-m", message)
            run("update-ref", f"refs/heads/{branch}", new, tip)
        except RuntimeError as e:
            return str(e)
    return ""


BUFFER_HEAD = ("# Buffer\n\n| Id | Metarepo claim (`<meta>/<path> § section`, at the pin) | This repo now "
               "(source, commit) | Decided (who, date) | State |\n|---|---|---|---|---|\n")


def open_roadmap_proposal(root: Path, meta: str, loc: Path) -> tuple[Path | None, str]:
    """(spec, branch) of this repo's open roadmap proposal: an unmerged
    `propose/<repo>-roadmap-<date>` branch a `roadmap-<date>.md` spec here cites; (None, "")
    for none. One at a time, so the owner merges a pararepo's roadmap edits in one step."""
    trunk = Board.trunk_name(loc)
    spec, branch = None, ""
    for f in sorted((root / SPECS).glob("roadmap-*.md")) if (root / SPECS).is_dir() else []:
        for m in PROPOSAL.finditer(f.read_text()):
            b = m.group("branch") or ""
            if m.group("meta") == meta and b.startswith(f"propose/{root.name}-roadmap-") and \
                    git("rev-list", "-1", f"{trunk}..{b}", cwd=str(loc)):
                spec, branch = f, b
    return spec, branch


def roadmap_base(root: Path, fam: "Family", trunk: str) -> str:
    """The roadmap a draft starts from and an edit is judged against: trunk's, or in a pararepo
    the metarepo's trunk with this repo's sections as its open roadmap proposal has them, so a
    second edit never drops what the first wrote there."""
    if fam.kind != "para":
        return at_rev(trunk, ROADMAP)
    _, branch = open_roadmap_proposal(root, fam.meta_name, fam.meta_loc)
    on = roadmap_raw(f"refs/heads/{branch}", cwd=fam.meta_loc) if branch else ""
    return splice_sections(fam.text, on, lambda h: bool(h) and may_change(fam, h)) if on else fam.text


def roadmap_spec_path(root: Path, loc: Path) -> Path:
    """The spec a new roadmap proposal is recorded in, `roadmap-<date>.md`, its name free here
    and as a branch in the metarepo at LOC."""
    slug, n = f"roadmap-{time.strftime('%Y-%m-%d')}", 1
    while (root / SPECS / f"{slug}.md").exists() or \
            git("rev-parse", "-q", "--verify", f"refs/heads/propose/{root.name}-{slug}", cwd=str(loc)):
        n += 1
        slug = f"roadmap-{time.strftime('%Y-%m-%d')}-{n}"
    return root / SPECS / f"{slug}.md"


def record_roadmap_row(root: Path, meta: str, spec: Path, branch: str, row: list[str]) -> None:
    """ROW added to the buffer and to SPEC, the record of BRANCH, this repo's open roadmap
    proposal. The spec lists roadmap rows only, so a buffer proposal, which leaves out rows a
    proposal carries, never sweeps them."""
    ledger = root / BUFFER
    text = ledger.read_text() if ledger.exists() else BUFFER_HEAD
    ledger.parent.mkdir(parents=True, exist_ok=True)
    ledger.write_text(text.rstrip("\n") + "\n| " + " | ".join(row) + " |\n")
    rows = {r[0]: r for r in buffer_rows(ledger.read_text())}
    ids = (listed_rows(spec.read_text()) if spec.exists() else []) + [row[0]]
    head = [l for l in ledger.read_text().splitlines() if l.lstrip().startswith("|") and not buffer_rows(l)]
    table = "\n".join(head + ["| " + " | ".join(rows[i]) + " |" for i in ids if i in rows])
    spec.parent.mkdir(parents=True, exist_ok=True)
    spec.write_text(
        f"# Roadmap proposal: {spec.stem}\n\n"
        f"Each row is a change to this repo's sections of {meta}'s {ROADMAP}, written on the branch "
        f"below by `jig roadmap --edit`. {meta} merges it at the next sync its owner calls; this repo's "
        f"sections there are replaced whole, and no other section changes.\n\n"
        f"## Buffer rows\n" + "".join(f"- {i}\n" for i in ids) + f"\n{table}\n\n"
        f"## Decisions\n- meta: {meta} proposal {branch}\n")


def stage_label(fam: "Family", label: str, sids: list[str], repo: str) -> Path:
    """A new label term staged for the metarepo's hubnode, whose glossary it is: the term, the
    scopes it labels, and the repo asking. A second edit naming it adds its scopes."""
    path = fam.meta_loc / STAGING / f"label-{label_fold(label)}.md"
    have = path.read_text().split("\n## Labels\n", 1)[1].split() if path.exists() and "\n## Labels\n" in path.read_text() else []
    named = sorted(set(have) | {f"`{s}`" for s in sids}) if have else [f"`{s}`" for s in sids]
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        f"---\nstaged: true\ntarget: {fam.meta_name}\nkind: doc\nchange: update\ndestination: {GLOSSARY}\n"
        f"source: {repo}'s hubnode, {time.strftime('%Y-%m-%d')}\nstatus: staged\n---\n"
        f"# Label: {label}\n\n{repo} labels its roadmap work `{label}`, a term {GLOSSARY} doesn't have. "
        f"Add it as a term, an `### ` heading under its product or feature, or under `# {BASIC_TERMS}`; {repo}'s next "
        f"`jig roadmap --edit` then puts the label on these.\n\n## Labels\n" + "\n".join(sorted(set(named))) + "\n")
    return path


def roadmap_edit(root: Path, fam: "Family", trunk: str, file: str) -> int:
    """`jig roadmap --edit [<file>]`: check a draft against the roadmap read again, live, and
    write it where this repo's roadmap changes land: trunk's checkout, or a pararepo's open
    roadmap proposal. Nothing is written while anything is refused."""
    draft = Path(file) if file else draft_path()
    if not draft.is_file():
        die(f"no draft at {draft}: `jig roadmap --draft` writes one")
    draft_raw = draft.read_text()
    if fam.kind == "para" and fam.meta_loc is None:
        die(f"the roadmap is {fam.meta_name}'s, which can't be reached here (`jig repos`): nothing written")
    if shape := roadmap_file_problems(draft_raw, fam.owners, fam.glossary_name):
        for x in shape:
            print(f"{draft}: {x}")
        print("nothing written")
        return 1
    new = draft_raw
    trunk_text = fam.text if fam.kind == "para" else at_rev(trunk, ROADMAP)
    base = roadmap_base(root, fam, trunk)
    if not base:
        die(f"nothing written: {fam.meta_name}'s {ROADMAP} isn't on its trunk yet" if fam.kind == "para"
            else f"nothing written: {ROADMAP} isn't on {trunk} yet (above)")
    here = Path(git("rev-parse", "--show-toplevel") or ".")
    if fam.kind != "para" and (git("branch", "--show-current") != trunk or not is_main_worktree(here)):
        die(f"edit the roadmap in the {trunk} checkout: R5 keeps {ROADMAP} on {trunk}")
    if fam.kind != "para" and (root / ROADMAP).exists() and not same_roadmap((root / ROADMAP).read_text(), base):
        die(f"{ROADMAP} in the {trunk} checkout differs from {trunk}'s: commit or discard it first, "
            "so nothing uncommitted is overwritten")
    out = section_refusals(base, new, lambda h: may_change(fam, h), lambda h: heading_owner(fam, h),
                           "this repo", fam.kind == "para")
    keep = lambda h: bool(h) and may_change(fam, h) and fam.kind == "para"
    staged = unknown_labels(new, fam, lambda h: may_change(fam, h)) if fam.kind == "para" else {}
    result = splice_sections(trunk_text, drop_labels(new, set(staged)), keep) if fam.kind == "para" else new
    have = set(Snapshot(trunk).ls("docs/"))
    out += roadmap_problems(result, fam, have, trunk)
    dropped = dropped_scopes(trunk_text, roadmap_scopes(result), Snapshot(trunk), fam)
    out += [f"{ROADMAP} drops {', '.join(gone)}, which {f} still {verb}: re-point its {line} line first"
            for f, gone, line, verb in scope_holders(dropped, [(f, at_rev(trunk, f)) for f in Snapshot(trunk).ls(SPECS)
                                                   + Snapshot(trunk).ls(HANDOFFS)])]
    out += others_holding(dropped, fam)
    if out:
        for x in out:
            print(f"{draft}: {unline(x)}" if not x.startswith(ROADMAP) else x)
        print("nothing written")
        return 1
    if fam.kind != "para":
        (root / ROADMAP).write_text(roadmap_dumps(roadmap_records(result)))
        draft.unlink()
        print(f"wrote {ROADMAP}: commit it on {trunk} on the owner's yes")
        return 0
    para = load_para(trunk)
    # What this edit changes, against what the open proposal already holds.
    heads, ids = roadmap_changes(base, splice_sections(base, drop_labels(new, set(staged)), keep), keep)
    if not ids and not staged:
        draft.unlink()
        print("no change: nothing written")
        return 0
    num = max([int(r[0][1:]) for r in buffer_rows((root / BUFFER).read_text() if (root / BUFFER).exists() else "")
               if re.fullmatch(r"B\d+", r[0])] or [0]) + 1
    if ids:
        row = [f"B{num}", ", ".join(f"{fam.meta_name}/{ROADMAP} § {h}" for h in heads), "; ".join(ids),
               f"hubnode, {time.strftime('%Y-%m-%d')}", "Open"]
        # The branch first, then the row and the spec: a refused commit leaves nothing written.
        spec, branch = open_roadmap_proposal(root, para["meta"], fam.meta_loc)
        opened = not branch
        if opened:
            spec = roadmap_spec_path(root, fam.meta_loc)
            branch = open_proposal(para, fam.meta_loc, spec.stem)
        on = roadmap_raw(f"refs/heads/{branch}", cwd=fam.meta_loc)
        why = plumb_commit(fam.meta_loc, branch, ROADMAP, splice_sections(on, drop_labels(new, set(staged)), keep),
                           f"roadmap: {root.name}: {'; '.join(ids)}")
        if why:
            if opened:
                git("branch", "-D", branch, cwd=str(fam.meta_loc))
            print(f"{branch} in {fam.meta_name} wasn't written ({why}): nothing written; "
                  "`jig roadmap --edit` again")
            return 1
        record_roadmap_row(root, para["meta"], spec, branch, row)
        print(f"wrote {branch} in {fam.meta_name}: {'; '.join(ids)}")
        print(f"added {BUFFER} row B{num} and {spec.relative_to(root)}: commit them here")
    for label, sids in sorted(staged.items()):
        path = stage_label(fam, label, sids, root.name)
        print(f"staged {path} for {fam.meta_name}: the label {label} is added once the term lands")
    draft.unlink()
    return 0


# ----------------------------------------------------------------- family report

# Past a week, a staged file or a proposal nobody has acted on is stale (the pararepos' inputs:
# "staged items over a week old"). The age is printed whatever it is, so nothing needs setting.
STALE_DAYS = 7


def family_members(root: Path, trunk: str) -> tuple[str, Path | None, list[tuple[str, Path]], list[str]] | None:
    """(metarepo's name, its checkout, every member reached as (name, trunk checkout), the
    names not reached) for this repo's family, read the same from the metarepo or any
    pararepo; None outside a family."""
    meta, para = load_meta(trunk), load_para(trunk)
    if meta is not None:
        name, loc, paras = meta.get("name") or root.name, root, list(meta.get("pararepos") or [])
    elif para is not None:
        name, loc = para.get("meta", ""), meta_checkout(root, para)
        if loc is None:
            return name, None, [], [name]
        try:
            paras = list(json.loads(trunk_show(loc, META) or "{}").get("pararepos") or [])
        except ValueError:
            paras = []
    else:
        return None
    members, gone = [(name, loc)], []
    for n in paras:
        at = repo_path(n)
        if at is None or not at.is_dir():
            gone.append(n)
        else:
            members.append((n, root if at.resolve() == root.resolve() else at))
    return name, loc, members, gone


def age_days(when: float) -> int:
    return max(0, int((time.time() - when) // 86400))


def name_pairs(names: list[tuple[str, str]]) -> list[tuple[str, str]]:
    """(a, b) for each two of NAMES, (group, name), in different groups whose names are one
    once label_fold folds them, or where one is the other with whole hyphen-words added at
    its start or end (`teleport`, `teleport-clipboard`): maybe one thing under two names."""
    out = []
    for i, (ga, a) in enumerate(names):
        for gb, b in names[i + 1:]:
            if ga == gb:
                continue
            fa, fb = label_fold(a.rsplit("/", 1)[-1]), label_fold(b.rsplit("/", 1)[-1])
            short, long_ = sorted((fa, fb), key=len)
            if fa == fb or long_.startswith(short + "-") or long_.endswith("-" + short):
                out.append((a, b))
    return out


def family_report(root: Path, trunk: str) -> dict | None:
    """What the family has let sit, read from every member reached: staged files with their
    ages, the metarepo's unmerged `propose/` branches with theirs, pending decision entries
    touching labelled work not done, and two names for one thing. None outside a family. It
    writes nothing: a report, never a refusal."""
    fam_of = family_members(root, trunk)
    if fam_of is None:
        return None
    meta_name, meta_loc, members, gone = fam_of
    out = {"meta": meta_name, "unreachable": gone, "staged": [], "proposals": [], "entries": [], "pairs": []}
    for name, loc in members:
        for f in staged_files(loc):
            head, _, _ = read_staged(f)
            age = age_days(f.stat().st_mtime)
            out["staged"].append({"repo": name, "file": f.name, "target": head.get("target", ""),
                                  "kind": head.get("kind", ""), "age": age, "stale": age > STALE_DAYS})
    if meta_loc is None:
        return out
    mtrunk = Board.trunk_name(meta_loc)
    cites: dict[str, list[str]] = {}
    for name, loc in members[1:]:
        for f in sorted((loc / SPECS).glob("*.md")) if (loc / SPECS).is_dir() else []:
            for m in PROPOSAL.finditer(f.read_text(errors="replace")):
                if m.group("branch") and m.group("meta") == meta_name:
                    cites.setdefault(m.group("branch"), []).append(f"{name}:{SPECS}{f.name}")
    for b in git("for-each-ref", "--format=%(refname:short)", "refs/heads/propose/", cwd=str(meta_loc)).split():
        empty = proposal_empty(meta_loc, b, mtrunk)
        merged = not git("rev-list", "-1", f"{mtrunk}..{b}", cwd=str(meta_loc))
        if merged and not empty:
            continue
        # Its opening commit's date: the first commit past trunk, or the tip of one on trunk's line.
        first = (git("rev-list", "--reverse", f"{mtrunk}..{b}", cwd=str(meta_loc)).split() or [b])[0]
        age = age_days(int(git("log", "-1", "--format=%ct", first, cwd=str(meta_loc)) or time.time()))
        out["proposals"].append({"branch": b, "age": age, "empty": empty, "stale": age > STALE_DAYS,
                                 "cited": cites.get(b, [])})
    gloss = trunk_show(meta_loc, GLOSSARY) or ""
    terms, owners = glossary_terms(gloss), term_owners(gloss, meta_names(meta_loc, meta_name))
    # The states are the family's, read as every roadmap reader reads them; a pararepo keeping
    # a roadmap of its own plans from no labelled scope of the metarepo's.
    fam = family(root, trunk)
    full = roadmap_full(Snapshot(trunk), fam) if fam.kind != "own" else None
    work = ([s for p in full[0] for s in p["scopes"]] + full[1]) if full else []

    def repo_of(product: str) -> str:
        return owners.get(product, "") or meta_name
    # The pending rulings: the metarepo's ideas, a log not folded yet's ## Open, and ## Unreleased.
    log = with_ideas(trunk_show(meta_loc, LOG) or "", trunk_show(meta_loc, IDEAS) or "")
    for e in log_entries(log, log_prefix_of(log)):
        if e["section"] not in ("Open", "Unreleased", IDEAS):
            continue
        for ptr in entry_touches(e["block"]) or []:
            page, term = pointer_term(ptr)
            if page != GLOSSARY or not term:
                continue
            want = label_fold(glossary_term_in(term, terms) or term)
            hit = [(w["id"], repo_of(w["product"])) for w in work
                   if w["state"] != "done" and want in {label_fold(l) for l in w["labels"]}]
            if hit:
                out["entries"].append({"id": e["id"], "title": e["title"], "term": term, "work": hit})
    # The glossary's own pairs: any two terms one once folded.
    out["pairs"] = [(a, b) for i, a in enumerate(terms) for b in terms[i + 1:]
                    if a != b and label_fold(a) == label_fold(b)]
    text = trunk_show(meta_loc, ROADMAP) or ""
    ids = [(product_of(p["name"], owners), sid) for p in roadmap_phases(text) for sid, _ in p["scopes"]]
    ids += [(product_of(i["list"].removesuffix(" " + NO_PHASE) if i["list"] != NO_PHASE else "", owners), i["sid"])
            for i in roadmap_list_items(text)]
    out["pairs"] += name_pairs(ids)
    return out


def family_counts(rep: dict) -> tuple[int, int, int, int]:
    """(stale staged files, stale or empty proposals, entries, pairs): what rig's line counts."""
    return (sum(x["stale"] for x in rep["staged"]), sum(x["stale"] or x["empty"] for x in rep["proposals"]),
            len(rep["entries"]), len(rep["pairs"]))


def cmd_family(root: Path, args) -> int:
    trunk = Board.trunk_name(root)
    rep = family_report(root, trunk)
    if rep is None:
        print("no family: this repo is neither a metarepo nor a pararepo")
        return 0
    for name in rep["unreachable"]:
        print(f"{name} can't be reached here (`jig repos`): not read")
    print("Staged:")
    print("\n".join(f"  {x['repo']}  {STAGING}/{x['file']}  target {x['target']}  kind {x['kind']}  "
                    f"{x['age']}d" + ("  stale" if x["stale"] else "") for x in rep["staged"]) or "  nothing")
    print("Proposals:")
    print("\n".join(f"  {x['branch']}  {x['age']}d" + ("  empty" if x["empty"] else "")
                    + ("  stale" if x["stale"] else "")
                    + (f"  cited by {', '.join(x['cited'])}" if x["cited"] else "  cited by no spec")
                    for x in rep["proposals"]) or "  nothing")
    print("Entries touching labelled work:")
    print("\n".join(f"  {x['id']} {x['title']}  ({GLOSSARY} § {x['term']}): "
                    + ", ".join(f"{sid} ({repo})" for sid, repo in x["work"]) for x in rep["entries"]) or "  nothing")
    print("Two names:")
    print("\n".join(f"  {a} and {b}" for a, b in rep["pairs"]) or "  nothing")
    return 0


# The project's files: a page or a decision entry that names one goes stale whenever the plan
# moves, and is released to pararepos as if it were the product (rules-docs.md, Documentation).
# These are never product text, so the hook refuses them, and survey lists them in old text;
# ROADMAP.md may be a product's own word, so nothing searches for it.
PROJECT_PATHS = re.compile(r"\.jig/(?:specs|handoffs)/|\.jig/roadmap\.(?:json|md)")


# The root documents, which docs never name (rules-docs.md, Documentation): the README is for
# outsiders and may point into docs/, and the rules files are agents', so the arrow runs one
# way. A path, with or without `§`: another repo's (`app/README.md`) or a folder's own README
# is no root document, so nothing may come before the name but `../`.
ROOT_DOC_NAMES = r"(?:README|AGENTS|CLAUDE|GEMINI|CHANGELOG)"
ROOT_DOC_PATH = re.compile(rf"(?<![\w./:-])(?:\.\./)*{ROOT_DOC_NAMES}\.md(?![\w/-])")
# Prose that names one without a path ("listed in the root README"): a hook can't judge it,
# so survey lists it.
ROOT_DOC_WORD = re.compile(rf"(?<![\w/-]){ROOT_DOC_NAMES}\b(?!\.md)")


MD_LINK = re.compile(r"\]\((?P<target>[^)\s]+)")


def root_doc_named(path: str, line: str) -> str:
    """The root document LINE, in file PATH, names as a path, as written; '' for none. A
    Markdown link is relative to its file, so a page's link to its own folder's README.md names
    no root document; any other path is from the repo's root, as jig's pointers are."""
    spans = []
    for m in MD_LINK.finditer(line):
        spans.append(m.span("target"))
        target = m.group("target").split("#")[0]
        if target and "://" not in target and \
                os.path.normpath(os.path.join(os.path.dirname(path), target)) in ROOT_DOCS:
            return m.group("target")
    return next((m.group(0) for m in ROOT_DOC_PATH.finditer(line)
                 if not any(a <= m.start() < b for a, b in spans)), "")


def root_doc_mentions(path: str, text: str, frozen: set[int] = frozenset()) -> list[tuple[int, str]]:
    """(line number, line) for each line of TEXT, file PATH, that names a root document, as a
    path or in prose, but the FROZEN ones (0-based): a released change line can't be edited."""
    return [(n, line) for n, line in enumerate(text.splitlines(), 1)
            if n - 1 not in frozen and (root_doc_named(path, line) or ROOT_DOC_WORD.search(line))]


def product_file(path: str, meta: dict | None = None) -> bool:
    """A file that describes the product only: a docs page, the decision log, or a metarepo's
    entry file."""
    return (path == LOG or (path.startswith("docs/") and path.endswith(".md") and not reference_file(path))
            or (meta is not None and path.endswith(".md") and is_entry(path, meta.get("entry_files", []))))


def scope_ids(text: str) -> list[str]:
    return [sid for p in roadmap_phases(text) for sid, _ in p["scopes"]] + [i["sid"] for i in roadmap_list_items(text)]


def scope_quoted(sids: list[str]) -> list[re.Pattern]:
    """A scope id in code quotes, which no product sentence writes: `alpha/screen`. Bare, the
    words may be the product's ("the v1/api endpoint"), so nothing searches for those."""
    return [re.compile(rf"`{re.escape(sid)}`") for sid in sids]


def added_lines(trunk: str, staged: bool, files: list[str]) -> list[tuple[str, int, str]]:
    """(path, line number, text) for each line the change adds to FILES. Renames are followed,
    so a moved page's old lines aren't new, and a line counts as added only while the file's
    diff adds its text more times than it removes it, so a line moved within a file isn't new
    either: a line diff shows every move as a delete plus an add. The prefixes are fixed,
    whatever the owner's diff settings."""
    # Both sides of every rename are in the pathspec, or git can't see the rename.
    gone = [f for f in changed_paths(trunk, staged, removed=True) if f.endswith(".md") and f not in files]
    diff = git_raw("-c", "core.quotePath=false", "diff", "-M", "-U0", "--no-ext-diff", "--no-color",
                   "--src-prefix=a/", "--dst-prefix=b/", base(trunk), *(["--cached"] if staged else []),
                   "--", *files, *gone)
    return net_added(diff, set(files))


def net_added(diff: str, want: set[str]) -> list[tuple[str, int, str]]:
    """(path, line number, text) for each line a `-U0` diff with a/ and b/ prefixes adds to a
    file in WANT, kept only while that file's diff adds the text more times than it removes it:
    a line diff shows every move as a delete plus an add, so a moved line isn't new. DIFF is
    read raw and split on newlines only, so a form feed or lone CR in a line can't split off a
    line that reads as a header."""
    out, at, n = [], "", 0
    net: dict[str, Counter] = {}
    hunk = False  # the ---/+++ headers sit outside hunks, so they are never counted as text
    for line in diff.split("\n"):
        if line.startswith("diff "):
            hunk = False
        elif not hunk and line.startswith("+++ "):
            # git ends the header with a tab when the name holds a space
            name = line[6:].removesuffix("\t") if " " in line[6:] else line[6:]
            at = name if line.startswith("+++ b/") and name in want else ""
        elif m := re.match(r"@@ -\S+ \+(\d+)", line):
            n, hunk = int(m.group(1)), True
        elif hunk and at and line.startswith("+"):
            out.append((at, n, line[1:]))
            net.setdefault(at, Counter())[line[1:]] += 1
            n += 1
        elif hunk and at and line.startswith("-"):
            net.setdefault(at, Counter())[line[1:]] -= 1
    kept = []
    for f, n, text in out:
        if net[f][text] > 0:
            net[f][text] -= 1
            kept.append((f, n, text))
    return kept


def dead_touches(text: str, have: set[str], fam: "Family | None" = None) -> set[tuple[str, str]]:
    """(item or scope id, page) for each `(touches …)` page HAVE holds in neither form. Under a
    product heading of a family FAM the page is the owning repo's, looked up on its trunk; one
    whose owner can't be reached is not judged here."""
    out = set()
    for heading, sid, pages in touched(text):
        files = have if fam is None else fam.pages_of(product_of(heading, fam.owners), have)
        if files is not None:
            out |= {(sid, t) for t in pages if page_in(t, files) not in files}
    return out


def touched(text: str) -> list[tuple[str, str, list[str]]]:
    """(heading, id, pages) for each list item and scope naming pages with `(touches …)`."""
    out = [(i["list"].rsplit(" ", 2)[0] if i["list"] != NO_PHASE else "", i["sid"], i["touches"])
           for i in roadmap_list_items(text)]
    out += [(p["name"], sid, p["touches_of"].get(sid, [])) for p in roadmap_phases(text) for sid, _ in p["scopes"]]
    return [x for x in out if x[2]]


def root_doc_refusal(at: str, n: int, named: str, text: str) -> str:
    what = "the decision log" if at == LOG else "a page"
    return (f"{at} line {n} names {named}, a root document: {what} points only at docs, and the "
            f"root documents may point into docs/, never the other way"
            + (f"; a term is {GLOSSARY} § <term>" if "README.md" in named else "")
            + f": {clip(text.strip())}")


def boundary_rules(trunk: str, branch: str, staged: bool, paths: list[str],
                   meta: dict | None, not_docs: list[str] = ()) -> list[str]:
    """References run one way: a page or a decision entry never names a spec, a handoff, the
    roadmap, or a scope of it. A roadmap is .jig/roadmap.json's, never a page, and the pages it
    names exist."""
    out = []
    keeps = bool(at_rev(trunk, ROADMAP)) or (branch == trunk and bool(in_index(ROADMAP, staged)))
    for f in paths:
        if f == ROADMAP or Path(f).name.lower() not in ("roadmap.md", "roadmap.json"):
            continue
        if f.startswith("docs/") or (meta and is_entry(f, meta.get("entry_files", []))):
            out.append(f"{f} is a roadmap among the product's pages: phases, scopes and parked work "
                       f"are the project's, and live in {ROADMAP} only")
    moved = ROADMAP in paths or any(f.startswith("docs/") for f in changed_paths(trunk, staged, removed=True))
    if branch == trunk and keeps and moved:
        # A page an item names must still be there: renamed or gone, the item is re-pointed in
        # the same commit. Only what this commit breaks is refused.
        now = set(git("-c", "core.quotePath=false", "ls-files").splitlines())
        before = set(git("-c", "core.quotePath=false", "ls-tree", "-r", "--name-only", "HEAD").splitlines())
        fam = family(main_root(), trunk)
        # A pararepo's commit writing a roadmap of its own plans from it, not the metarepo's.
        own = None if fam.reads_meta and in_index(ROADMAP, staged) else fam
        broke = dead_touches(in_index(ROADMAP, staged), now, own) - dead_touches(at_rev("HEAD", ROADMAP), before, own)
        # A page a metarepo moved down takes its items with it. A pararepo planning from this
        # roadmap takes them in this commit, into its product's section, where its page is the
        # pararepo's; one keeping a roadmap of its own takes them by a staged roadmap change,
        # applied there on its owner's yes (R5).
        moves = moves_in(in_index(LOG, staged))
        for iid, page in sorted(broke):
            if ptr := moves.get(page):
                repo, path, _ = pointer_parts(ptr)
                section = fam.section_of(repo)
                if section:
                    out.append(f"{ROADMAP}: `{iid}` touches {page}, moved to {ptr}: its item follows its "
                               f"page into {repo}'s section (## {section} <phase>, or ## {section} "
                               f"{NO_PHASE}), touching {path} there, in this commit")
                else:
                    out.append(f"{ROADMAP}: `{iid}` touches {page}, moved to {ptr}: stage a roadmap change "
                               f"with `target: {repo}` carrying it, and drop it, or the page from its "
                               f"`touches`, here in this commit")
            else:
                out.append(f"{ROADMAP}: {iid} touches {page}, which this commit leaves with no page: "
                           "re-point its `touches` in this commit")
    fam = family(main_root(), trunk)
    if branch == trunk and fam.reads_meta and fam.text and moved:
        # The metarepo's roadmap names this repo's pages for the products it owns; its hook
        # can't see this commit, so the page's loss is said here, never refused: the item is
        # the metarepo's to re-point, by a proposal.
        now = set(git("-c", "core.quotePath=false", "ls-files").splitlines())
        for heading, iid, pages in touched(fam.text):
            if fam.ours(product_of(heading, fam.owners)):
                for t in pages:
                    if page_in(t, now) not in now:
                        print(f"jig: warning: {fam.meta_name}'s {ROADMAP}: `{iid}` touches {t}, which this "
                              "commit leaves with no page: propose re-pointing it (`jig propose`)", file=sys.stderr)
    files = [f for f in paths if product_file(f, meta)]
    if not files:
        return out
    # On trunk the commit's own roadmap counts too, so a scope added with its page is known.
    fam = family(main_root(), trunk)
    # A pararepo planning from the metarepo's roadmap names its scopes no more than its own.
    sids = (scope_ids(fam.text) if fam.reads_meta else scope_ids(at_rev(trunk, ROADMAP))) \
        + (scope_ids(in_index(ROADMAP, staged)) if branch == trunk else [])
    names = scope_quoted(sids)
    for at, n, text in added_lines(trunk, staged, files):
        hit = PROJECT_PATHS.search(text) or next((m for r in names if (m := r.search(text))), None)
        if hit:
            what = "the decision log" if at == LOG else "a page"
            out.append(f"{at} line {n} names {hit.group(0)}, the project's: {what} describes the "
                       f"product, and a spec, a handoff or the roadmap cites it, never the other "
                       f"way: {clip(text.strip())}")
        elif (at == LOG or (at.startswith("docs/") and not matches(at, not_docs))) \
                and (named := root_doc_named(at, text)):
            out.append(root_doc_refusal(at, n, named, text))
    return out


def heading_lines(text: str) -> dict[str, list[tuple[int, str]]]:
    """Each address `§` can name in TEXT, keyed as `§` compares it (plain, case kept), with the
    (line number, text) of every copy: a heading at any level. Fenced code is skipped: a heading
    quoted in an example is no address. A glossary's terms are its headings: a table row is none."""
    out: dict[str, list[tuple[int, str]]] = {}
    lines = text.splitlines()
    for n, (line, prose) in enumerate(zip(lines, unfenced(lines)), 1):
        if prose and (m := HEADING.match(line)) and (shown := plain(m.group(1))):
            out.setdefault(shown, []).append((n, shown))
    return out


def heading_rules(trunk: str, staged: bool, paths: list[str], not_docs: list[str]) -> list[str]:
    """A heading is the address `<page> § <heading>` cites, as a section number was before the
    page contract, so a page holds each once. Two jobs that each add `## Cache` to a shared page
    merge cleanly into two, and every citation then lands on both. Only a change that raises a
    heading's count past one is refused, so a page that already holds a duplicate stays editable
    and movable."""
    files = [f for f in paths if f.startswith("docs/") and f.endswith(".md") and not reference_file(f)
             and not matches(f, not_docs) and Path(f).name not in ("CHANGELOG.md", "DECISIONS.md")]
    if not files:
        return []
    b = base(trunk)
    came_from = {new: old for old, new in renames(b, staged).items()}
    # A move that rewrites most of a page is a delete and an add to git. What the change deleted
    # is where such a page came from, so its duplicates are no new ones either.
    gone = [f for f in git("-c", "core.quotePath=false", "diff", *(["--cached"] if staged else []),
                           "--name-only", "--diff-filter=D", b).splitlines() if f.endswith(".md")]
    out = []
    for f in files:
        olds = [came_from[f]] if f in came_from else [f, *gone]
        before = [heading_lines(at_rev(b, o)) for o in olds]
        for key, copies in heading_lines(in_index(f, staged)).items():
            if len(copies) > max(1, *(len(h.get(key, [])) for h in before)):
                lines = ", ".join(str(n) for n, _ in copies)
                out.append(f"{f} has `{copies[0][1]}` {len(copies)} times (lines {lines}): a heading "
                           f"is the address `{f} § {copies[0][1]}` cites, so a page "
                           f"holds each once. Rename one or join the sections ({RULES_DIR}/rules-docs.md, Documentation)")
    return out


def form_entries(root: Path, files: list[str], board: dict, read, only: set[str]) -> list[dict]:
    """page_shapes as survey judges FILES, for the pages in ONLY: pages with no home, sections,
    and a shape the owner made an exception of left out."""
    not_docs = board.get("not_docs") or []
    deep = board.get("deep_subsystems") if isinstance(board.get("deep_subsystems"), dict) else {}
    docmap = named_pages(board)
    homeless = {h["path"] for h in doc_homes(root, files, not_docs, read, deep, docmap, only, names=False)}
    sections = frozenset(e["path"] for e in page_levels(root, files, board, read, only=only)
                         if e["level"] == "section")
    rec = findings_record(board)
    return [e for e in page_shapes(root, files, not_docs, docmap, homeless, read, sections, only)
            if not rec.get(finding_id(e), "").startswith("exception:")]


def form_candidates(paths: list[str], files: list[str] = (), born: set[str] = frozenset()) -> set[str]:
    """The pages whose form PATHS can change: each page among them, and both forms of the page
    of each folder above each, whose company it is. A page BORN or gone gives the pages in FILES
    under its folder a home or takes it, which decides whether their form is judged at all."""
    out = {f for p in born for f in files
           if f.startswith(f"{page_folder(p)}/") and f.endswith(".md")}
    for p in paths:
        if not p.startswith("docs/"):
            continue
        if p.endswith(".md"):
            out.add(p)
        parts = p.split("/")
        for i in range(2, len(parts)):
            out |= set(page_forms("/".join(parts[:i]) + ".md"))
    return out


def cat_files(specs: list[str]) -> dict[str, str]:
    """The text of each `<rev>:<path>` in SPECS, in one git call: empty where it is missing."""
    if not specs:
        return {}
    data = subprocess.run(["git", "cat-file", "--batch"], input="\n".join(specs).encode() + b"\n",
                          capture_output=True).stdout
    out, at = {}, 0
    for spec in specs:
        nl = data.index(b"\n", at)
        head, at = data[at:nl].split(), nl + 1
        if len(head) < 3 or head[-1] == b"missing":
            out[spec] = ""
            continue
        n = int(head[2])
        out[spec], at = data[at:at + n].decode(errors="replace"), at + n + 1
    return out


def page_form_rules(root: Path, board: "Board", trunk: str, staged: bool, guarded: list[str]) -> list[str]:
    """A page this change puts in the wrong form, as survey words it. Form's fix is a `git mv`
    any branch can make, unlike depth's, so it is refused. Only what this change does is: an
    entry the base already has is survey's, as an old line in a touched page is never refused.
    Only the pages the change can reform are judged, so a commit costs what it touches."""
    if not any(f.startswith("docs/") for f in guarded):
        return []
    b = base(trunk)
    q = ("-c", "core.quotePath=false")
    # From the root: run in a subfolder, both list only what is under it.
    before = [f for f in git(*q, "ls-tree", "-r", "--name-only", b, cwd=str(root)).splitlines() if f]
    after = [f for f in git(*q, "ls-files", cwd=str(root)).splitlines()
             if f and (staged or (root / f).exists())]
    was, now = set(before), set(after)
    only = form_candidates(guarded, before + after,
                           {p for p in guarded if p.endswith(".md") and (p in was) != (p in now)})

    def reader(files: list[str], rev: str | None):
        # Every docs page's text in one git call: a page outside ONLY is still read for its
        # level, and a call per page would cost a large tree minutes.
        md = [f for f in files if f.startswith("docs/") and f.endswith(".md")]
        if rev is None:
            texts = {f: (root / f).read_text(errors="replace") for f in md if (root / f).is_file()}
        else:
            got = cat_files([f"{rev}:{f}" for f in md])
            texts = {f: got[f"{rev}:{f}"] for f in md}
        return lambda f: texts[f] if f in texts else (at_rev(rev, f) if rev else in_index(f, staged))
    old = {e["path"] for e in form_entries(root, before, board.data, reader(before, b), only)}
    # An unnamed page's fix is a docmap key, trunk's (R5), not a move: survey's alone.
    return [f"{e['path']}: {shape_fix(e)} ({RULES_DIR}/rules-docs.md, Documentation: this change puts the "
            "page in the wrong form; make the move in it)"
            for e in form_entries(root, after, board.data, reader(after, "" if staged else None), only)
            if e["named"] and e["path"] not in old]


def proposed_branch(branch: str, trunk: str) -> bool:
    """A `propose/` branch `jig propose` made: its first commit past trunk is the proposal's
    opening, so a branch merely named so carries no roadmap change."""
    if not branch.startswith("propose/"):
        return False
    first = git("rev-list", "--reverse", "--topo-order", f"{trunk}..HEAD").split("\n", 1)[0]
    return bool(first) and opening_commit(main_root(), first)


def moving_in(para: dict, staged: bool, removed: str | None = None, old_form: bool = False) -> list[str]:
    """The pararepo's commit removing its own roadmap (REMOVED, as JSON: trunk's roadmap.json, or
    OLD_FORM, its old roadmap.md converted), once its phases and lists are the metarepo's: every
    `Scope:` line it keeps names the metarepo's ids, read on its trunk."""
    removed = at_rev(Board.trunk_name(main_root()), ROADMAP) if removed is None else removed
    if empty_roadmap(removed) and not old_form:
        # The empty structure an init wrote before `init --para`: nothing in it moves in. An old
        # roadmap.md's emptiness its caller judged, with what the conversion would name.
        return []
    loc = meta_checkout(main_root(), para)
    if loc is None:
        print(f"jig: warning: {para.get('meta', 'the metarepo')} isn't reachable here (`jig repos`), so "
              f"the Scope: lines this commit keeps pass unchecked", file=sys.stderr)
        return []
    text = trunk_show(loc, ROADMAP) or ""
    owners = term_owners(trunk_show(loc, GLOSSARY) or "", meta_names(loc, para.get("meta", "")))
    here = main_root().resolve()
    heads = [p["name"] for p in roadmap_phases(text)] + [i["list"].removesuffix(" " + NO_PHASE)
                                                       for i in roadmap_list_items(text)]
    mine = {pr for pr in {product_of(h, owners) for h in heads} - {""}
            if (o := owners[pr]) and (l := repo_path(o)) is not None and l.resolve() == here}
    if not mine and old_form:
        return [f"{OLD_ROADMAP} still holds phases or items: `jig update --apply` converts it, or "
                f"`jig move-in` moves them to the metarepo"]
    if not mine:
        return [f"{ROADMAP}: this commit removes it, but {para['meta']}'s roadmap holds none of this repo's "
                f"products yet, so its phases would be on no trunk: name the product in {para['meta']}'s "
                f"glossary with its `Repo:` line, and propose its phases there first ({BUFFER}, `jig propose`)"]
    known = roadmap_scopes(text)
    out = []
    for f in git("-c", "core.quotePath=false", "ls-files", "--", SPECS, HANDOFFS).splitlines():
        if takes_scopes(f) and (what := cited(f, in_index(f, staged), lambda sc: sc not in known)):
            out.append(f"{f} {what}, which {para['meta']}'s {ROADMAP} on its trunk doesn't "
                       f"have: this commit removes {ROADMAP}, so re-point it to {para['meta']}'s ids here")
    return out


def dropped_scopes(old: str, known: set[str], snap: Snapshot, fam: "Family") -> set[str]:
    """The scopes and items roadmap OLD has and KNOWN lacks. A built list item stays, shown
    done, until the owner's roadmap change removes it: its notes keep naming it, so dropping a
    done one is no drop."""
    built = {s["id"] for s in roadmap_list(snap, fam) if s["state"] == "done"}
    return roadmap_scopes(old) - known - built


def scope_holders(dropped: set[str], files: list[tuple[str, str]]) -> list[tuple[str, list[str], str, str]]:
    """(file, the DROPPED ids it names, its line, what the line does) for each spec or note of
    FILES, (path, text): a `Scope:` line that takes them, naming ids the roadmap must keep."""
    out = []
    for f, text in files:
        if not takes_scopes(f):
            continue
        if gone := [s for s in scopes_in(f, text) if s in dropped]:
            out.append((f, gone, "Scope:", "takes"))
    return out


def others_holding(dropped: set[str], fam: "Family") -> list[str]:
    """A refusal for each spec or note of a pararepo planning from this roadmap that takes a
    DROPPED scope: it takes the scopes in its own specs and notes."""
    out = []
    for label, sn in fam.others:
        for f, gone, line, verb in scope_holders(dropped, [(f, sn.show(f)) for f in sn.ls(SPECS) + sn.ls(HANDOFFS)]):
            out.append(f"{ROADMAP} drops {', '.join(gone)}, which {label}:{f} still {verb}: "
                       f"{label} re-points its {line} line first")
    return out


# A move's own lines in the metarepo's log, added by its proposal: the page landing here with its
# moved-from line (up), or the pointers to it renamed (sideways).
MOVE_LANDS = re.compile(r"^- (?P<as>.+?): moved from (?P<src>[\w.-]+)/.+?\.\s*$", re.M)
MOVE_POINTERS = re.compile(r"^- Pointers to (?P<src>[\w.-]+)/.+? name (?P<to>[\w.-]+)/(?P<as>.+?), where it moved\.\s*$", re.M)


def move_follows(fork_log: str, log: str, names: set[str]) -> list[tuple[str, str]]:
    """(receiver, page) for each move a proposal from the repo called NAMES carries, read from the
    lines its LOG adds to FORK_LOG: up, the metarepo itself ("") receives; sideways, the named one."""
    old = set(fork_log.splitlines())
    added = "\n".join(l for l in log.splitlines() if l not in old)
    out = [("", m.group("as").partition(" § ")[0].strip()) for m in MOVE_LANDS.finditer(added)
           if m.group("src") in names]
    out += [(m.group("to"), m.group("as").partition(" § ")[0].strip()) for m in MOVE_POINTERS.finditer(added)
            if m.group("src") in names]
    return out


def only_items_for(old: str, new: str, pages: list[str]) -> bool:
    """Whether section rows NEW (roadmap_sections' form) differ from OLD only by added scopes or
    items, each touching one of PAGES: the items that follow a moved page into its receiver's
    section."""
    left = Counter(l for l in old.split("\n") if l)
    added = []
    for l in (l for l in new.split("\n") if l):
        if left[l] > 0:
            left[l] -= 1
        else:
            added.append(json.loads(l))
    if any(n > 0 for n in left.values()):
        return False
    return bool(added) and all(
        a["kind"] in ("scope", "item") and any(same_page(str(p).strip("`"), page) for p in strs(a["record"].get("touches"))
                                               for page in pages) for a in added)

def proposal_section_refusals(branch: str, fork: str, text: str, fam: "Family", meta: dict,
                              logs: tuple[str, str] | None = None,
                              fork_owners: dict[str, str] | None = None) -> list[str]:
    """section_refusals for a metarepo's `propose/<repo>-<slug>` branch changing the roadmap
    from FORK (trunk's, where the branch left it) to TEXT: the proposing repo changes only the
    products it owns. `jig propose` names the branch for the pararepo's folder, so the repo is
    found by its `jig repos` name or its folder's, the longest that the branch starts with; a
    branch naming no pararepo is refused, never passed unjudged. FORK is the commit being made's
    merge base with trunk, so trunk's own changes merged in are in it, never the branch's. A
    section FORK has is whose FORK_OWNERS (its glossary) says, so a product renamed in the same
    commit loses its old headings as its own and a term taken over doesn't bring its sections;
    a new section is whose the commit's own glossary (FAM's owners) says."""
    def called(r: str) -> set[str]:
        loc = repo_path(r)
        return {r} | ({loc.name} if loc is not None else set())
    names = [(n, r) for r in meta.get("pararepos") or [] for n in called(r) if branch.startswith(f"propose/{n}-")]
    if not names:
        return [f"{branch} names no pararepo of this metarepo (its `pararepos`, by name or folder): "
                "a roadmap change reaches it by `jig roadmap --edit` in the pararepo that owns the sections"]
    repo = max(names, key=lambda x: len(x[0]))[1]
    # Only the proposing repo's own moves: another pararepo's move line lends it nothing.
    moves = move_follows(*logs, called(repo)) if logs else []
    old_s = {h: t for h, _, t in roadmap_sections(fork)}
    new_s = {h: t for h, _, t in roadmap_sections(text)}

    def whose(h: str) -> str:
        owners = fork_owners if fork_owners is not None and h in old_s else fam.owners
        return owners.get(heading_product(h, owners), "")

    def follows(h: str) -> bool:
        # A move's proposal carries the moved page's items into its receiver's section, and
        # nothing else there: the owner's Part C route for items, where no other edit passes.
        owner = whose(h) if h else None
        pages = [p for to, p in moves or [] if owner is not None and
                 (not owner if not to else name_in(owner, {to}))]
        return bool(pages) and only_items_for(old_s.get(h, ""), new_s.get(h, ""), pages)
    def products_owned() -> bool:
        # `products` changes with the sections the proposal may change: a product the proposing
        # repo owns, added or dropped, or one added for the items a move carries into it.
        a = set((roadmap_records(fork) or {}).get("products") or [])
        b = set((roadmap_records(text) or {}).get("products") or [])
        owners = fam.owners if fork_owners is None else {**fork_owners, **fam.owners}
        carried = lambda p: any(heading_product(h, fam.owners) == p and old_s.get(h, "") != t and follows(h)
                                for h, t in new_s.items() if h)
        return all(owners.get(p, "") == repo or (p in b - a and carried(p)) for p in a ^ b)
    owns = lambda h: (whose(h) == repo or follows(h)) if h else products_owned()
    owner = lambda h: whose(h) or "this repo"
    return section_refusals(fork, text, owns, owner, repo, True)


def roadmap_rules(board: "Board", branch: str, staged: bool, paths: list[str],
                  guarded: list[str]) -> list[str]:
    """Scopes a spec cites must be the roadmap's. On trunk the commit's own roadmap counts, so
    one commit can add a scope and the spec taking it, or drop one and re-point its specs."""
    trunk = board.trunk
    on_trunk = branch == trunk
    old = at_rev(trunk, ROADMAP)
    fam = family(main_root(), trunk)
    out, named = [], set()
    adds = on_trunk and bool(in_index(ROADMAP, staged))
    if fam.reads_meta and not old and adds and fam.meta_loc is not None \
            and any(fam.ours(p) for p in fam.products_in()):
        # Moved in, its plan is the metarepo's: a roadmap here would be a second copy to drift.
        return [f"{ROADMAP}: this repo plans from {fam.meta_name}'s roadmap, which holds its products "
                f"({', '.join(p for p in fam.products_in() if fam.ours(p))}): change them there, by a "
                f"{BUFFER} row and `jig propose`, never in a roadmap of its own"]
    removed = on_trunk and old and not in_index(ROADMAP, staged)
    para = (load_para(trunk) or json_or_none(in_index(PARA, staged))) if removed else None
    if para is not None:
        return moving_in(para, staged)
    if removed:
        # A pararepo's removal is moving in, judged above; anywhere else work left for later
        # would have no home again.
        return [f"{ROADMAP}: this commit removes it, but every stand-alone repo and metarepo keeps a "
                f"roadmap ({RULES_DIR}/rules-roadmap.md, Roadmap): change it, don't remove it"]
    if on_trunk and (old_md := at_rev(trunk, OLD_ROADMAP)) and not in_index(OLD_ROADMAP, staged) \
            and not in_index(ROADMAP, staged):
        # The old form removed with no roadmap.json beside it: judged as the roadmap is (the
        # owner, 2026-11-25, "Works for me"). The conversion stages the JSON in the same commit.
        para = load_para(trunk) or json_or_none(in_index(PARA, staged))
        converted = roadmap_dumps(roadmap_data(old_md, {}))
        if para is None:
            return [f"{OLD_ROADMAP}: this commit removes it with no {ROADMAP} in its place, but every "
                    f"stand-alone repo and metarepo keeps a roadmap: `jig update --apply` converts it"]
        # Empty, and nothing the conversion would name: prose or a line it can't read is held.
        if empty_roadmap(converted) and not uncarried(old_md, {}):
            return []
        return moving_in(para, staged, converted, old_form=True)
    if load_meta(trunk) is not None and proposed_branch(branch, trunk) and ROADMAP in paths:
        # A pararepo's proposal: its merge is judged on trunk; what it says is checked here too,
        # as `jig roadmap --edit` checks it: only the proposing repo's sections change.
        if shape := roadmap_file_problems(roadmap_raw(staged=True) if staged else roadmap_raw(cwd=Path(".")),
                                          term_owners(in_index(GLOSSARY, staged) or at_rev(trunk, GLOSSARY))):
            return shape
        text = in_index(ROADMAP, staged)
        # Where the commit being made leaves trunk: a merge of trunk into the branch moves it to
        # trunk's tip, so a resolution keeping the branch's old copy of another repo's section
        # reads as the change it is.
        fork = git("merge-base", trunk, "HEAD", *merging_commits())
        # The branch's own glossary says whose a heading is: a product it proposes is its own.
        if own := in_index(GLOSSARY, staged):
            fam.owners = term_owners(own)
        logs = (at_rev(fork, LOG) if fork else at_rev(trunk, LOG), in_index(LOG, staged))
        problems = proposal_section_refusals(branch, at_rev(fork, ROADMAP) if fork else old, text, fam,
                                             load_meta(trunk), logs,
                                             term_owners(at_rev(fork, GLOSSARY) or "") if fork else None)
        parsed = roadmap_phases(text, problems)
        problems += ref_problems(parsed, roadmap_list_items(text, problems))
        problems += type_problems(parsed, fam.owners)
        problems += roadmap_label_problems(text, in_index(GLOSSARY, staged) or None)
        return [f"{ROADMAP} {unline(x)}" for x in problems]
    if fam.reads_meta and not old and not adds:
        # The roadmap is the metarepo's, read live from its trunk: no release carries it.
        takers = [f for f in paths if takes_scopes(f) and cited(f, in_index(f, staged), lambda s: True)]
        if fam.meta_loc is None:
            if takers:
                print(f"jig: warning: {fam.meta_name or 'the metarepo'} isn't reachable here (`jig repos`), "
                      f"so the Scope: lines in {', '.join(takers)} pass unchecked", file=sys.stderr)
            return []
        known = roadmap_scopes(fam.text)
        for f in takers:
            if what := cited(f, in_index(f, staged), lambda s: s not in known):
                out.append(f"{f} {what}, which {fam.meta_name}'s {ROADMAP} on its trunk "
                           "doesn't have: a scope is <phase>/<scope> or <list>/<id> from it")
        return out
    text = in_index(ROADMAP, staged) if on_trunk else old
    if not text and not old:
        # Every stand-alone repo and metarepo keeps a roadmap, so an id named before trunk has
        # one names nothing: it would read as placed while no list holds it.
        return [f"{f} {what}, but {trunk} has no {ROADMAP}: `jig roadmap` in the {trunk} checkout "
                "writes it, then name ids from it"
                for f in paths if takes_scopes(f) and (what := cited(f, in_index(f, staged), lambda s: True))]
    known = roadmap_scopes(text)
    if on_trunk and (ROADMAP in paths or GLOSSARY in guarded):
        # Products are a metarepo's (Family reads them only there), so elsewhere a product is
        # refused as jig roadmap reports it, never committed for the readers to miss.
        shape = roadmap_file_problems(roadmap_raw(staged=staged) if staged else roadmap_raw(cwd=Path(".")),
                                      roadmap_owners(fam, in_index(GLOSSARY, staged)))
        if shape:
            return shape
    if on_trunk and ROADMAP in paths:
        problems: list[str] = []
        parsed = roadmap_phases(text, problems)
        problems += ref_problems(parsed, roadmap_list_items(text, problems))
        problems += type_problems(parsed, fam.owners)
        out += [f"{ROADMAP} {unline(x)}" for x in problems]
    if on_trunk and (ROADMAP in paths or GLOSSARY in guarded):
        # Checked on either file's change: a glossary commit dropping or renaming a term a
        # label names re-points the label in the same commit, as a dropped scope's specs are.
        hint = (f" ({GLOSSARY} changes in this commit: re-point or drop the label in it)"
                if GLOSSARY in guarded else "")
        out += [f"{ROADMAP} {unline(x)}{hint}" for x in roadmap_label_problems(text, in_index(GLOSSARY, staged) or None)]
    if on_trunk and (ROADMAP in guarded or OLD_ROADMAP in guarded):
        # Before the conversion, trunk's roadmap is its old roadmap.md, read as converted: a
        # conversion commit that loses a phase drops its scopes like any other.
        base = old or (roadmap_dumps(roadmap_data(old_md, {})) if (old_md := at_rev(trunk, OLD_ROADMAP)) else "")
        dropped = dropped_scopes(base, known, Snapshot(trunk), fam)
        here = git("-c", "core.quotePath=false", "ls-files", "--", SPECS, HANDOFFS).splitlines()
        for f, gone, line, verb in scope_holders(dropped, [(f, in_index(f, staged)) for f in here]):
            named.add(f)
            out.append(f"{ROADMAP} drops {', '.join(gone)}, which {f} still {verb}: re-point "
                       f"the {line} line in {f} in this commit")
        out += others_holding(dropped, fam)
        for name in fam.unreachable:
            print(f"jig: warning: {name} isn't reachable here (`jig repos`): a scope its specs take "
                  "may be dropped unseen", file=sys.stderr)
    for f in paths:
        if takes_scopes(f) and f not in named and (what := cited(f, in_index(f, staged),
                                                                 lambda s: s not in known)):
            out.append(f"{f} {what}, which {ROADMAP} on {trunk} doesn't have: "
                       "a scope is <phase>/<scope> or <list>/<id> from it")
    return out


