REVIEW_LEDGER = "docs/REVIEW_LEDGER.md"
# A review ledger's row is taken when its last word on the finding is "taken" ("taken by …",
# "deferred then taken"); "not taken" is not. Only taken rows are in the code, so only they go.
TAKEN = re.compile(r"(?:.*\bthen\s+)?taken\b")
STATUS_COLUMNS = ("what happened", "status")
SEPARATOR = re.compile(r"^\|\s*:?-")      # |---|, | --- |, |:--|


def table_cells(line: str) -> list[str]:
    """A GFM table row's cells, as GitHub reads them: `\\|` is a literal pipe, and a `|` in
    backticks still splits."""
    s = line.strip()
    s = s[1:] if s.startswith("|") else s
    s = s[:-1] if s.endswith("|") and not s.endswith("\\|") else s
    return [c.strip().replace("\\|", "|") for c in re.split(r"(?<!\\)\|", s)]


def split_ledger(text: str) -> tuple[list[str], list[list[str]], int, list[str]]:
    """A review ledger without its taken rows: the whole text kept, the tables that have a
    status column (header, separator, untaken rows), how many rows were dropped, and the rows
    kept because their cell count isn't the header's."""
    lines, out, tables, dropped, malformed = text.splitlines(), [], [], 0, []
    col = width = None
    for i, line in enumerate(lines):
        cells = [c.lower() for c in table_cells(line)]
        if line.startswith("|") and i + 1 < len(lines) and SEPARATOR.match(lines[i + 1]):
            # A findings table names the finding before what happened to it; a status in the
            # first column is a tally of the statuses, not a finding.
            col = next((n for n, c in enumerate(cells) if c in STATUS_COLUMNS and n > 0), None)
            width = len(cells)
            if col is not None:
                tables.append([line, lines[i + 1]])
        elif not line.startswith("|"):
            col = None
        elif col is not None and not SEPARATOR.match(line):
            # A row of another width has its status in some other cell, or none: a guess
            # could drop an untaken finding, so it stays and is named.
            if len(cells) != width:
                malformed.append(f"{REVIEW_LEDGER}: row `{table_cells(line)[0]}` has {len(cells)} "
                                 f"cells, its header {width}: kept, check it")
            elif TAKEN.match(cells[col]):
                dropped += 1
                continue
            tables[-1].append(line)
        out.append(line)
    return out, tables, dropped, malformed


def ledger_step(root: Path) -> str:
    _, tables, dropped, malformed = split_ledger((root / REVIEW_LEDGER).read_text(errors="replace"))
    kept = sum(len(t) - 2 for t in tables) - len(malformed)
    return (f"{REVIEW_LEDGER} → {DEFERRED}: its {kept} untaken row{'s' if kept != 1 else ''} "
            f"(deferred, rejected, open) carry over, its {dropped} taken row"
            f"{'s' if dropped != 1 else ''} are dropped, {len(malformed)} malformed kept, and the "
            f"file is removed")


def ledger_warnings(root: Path) -> list[str]:
    return split_ledger((root / REVIEW_LEDGER).read_text(errors="replace"))[3]


def fold_ledger(root: Path, here: Path) -> None:
    text, tables, _, _ = split_ledger((root / REVIEW_LEDGER).read_text(errors="replace"))
    dest = root / DEFERRED
    if dest.exists():
        body = dest.read_text().rstrip("\n") + f"\n\n## From {REVIEW_LEDGER}\n"
        for table in tables:
            body += "\n" + "\n".join(table) + "\n"
    else:
        body = "\n".join(text) + "\n"
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text(body)
    git("rm", "-q", "--", REVIEW_LEDGER, check=True)
    git("add", "--", DEFERRED, check=True)


def board_slug(text: str) -> str:
    """The board a hardware page names on its `- MCU / board:` line, as a file name; empty
    while that line is still the template's TODO."""
    m = re.search(r"^- MCU / board:\s*(.+)$", text, re.M)
    board = m.group(1).strip() if m else ""
    if not board or board.startswith("TODO"):
        return ""
    return re.sub(r"[^a-z0-9]+", "-", board.split("(")[0].lower()).strip("-")


def board_home(root: Path, slug: str) -> str:
    """Where an old single board page goes: flat, docs/<board>.md, since it moves alone;
    into the board's folder where it has one already, with files or its page in it."""
    folder = f"docs/{slug}/{slug}.md"
    return folder if (root / f"docs/{slug}").is_dir() else f"docs/{slug}.md"


def hardware_rows(root: Path, files: list[str]) -> list[tuple[str, list[str]]]:
    """A root HARDWARE.md, an older init's single page, moves to its board's page, a system
    like any other; rewrite_board registers it in boards. Only one that names a board: a page
    of TODOs is listed for review instead."""
    if "HARDWARE.md" not in files:
        return []
    slug = board_slug((root / "HARDWARE.md").read_text(errors="replace"))
    return [(board_home(root, slug), ["HARDWARE.md"])] if slug else []


def handoff_rows(root: Path, files: list[str]) -> tuple[list[tuple[str, list[str]]], set[str]]:
    """A note a jig wrote at a `/` name's path, `.jig/handoffs/<prefix>/<name>-<date>.md`,
    moves flat under its file-safe name; with the subfolders it empties, for the cleanup.
    Only a note whose header names that same path: update itself moves older tools' handoff
    folders here whole, subfolders included, and those stay as they are."""
    top = f"{DIR}/handoffs/"
    taken, rows, folders = set(files), [], set()
    for f in sorted(files):
        rel = f[len(top):] if f.startswith(top) else ""
        m = re.fullmatch(r"(.+/.+)-\d{4}-\d{2}-\d{2}(?:-\d+)?\.md", rel)
        if not m:
            continue
        try:
            first = (root / f).read_text(errors="replace").split("\n", 1)[0]
        except OSError:
            continue
        if first != f"# Handoff: {m.group(1)}":
            continue
        new = top + file_safe(rel)
        # A clash takes the day's next free -N, as `jig handoff` would; the note's Commit: line,
        # not its file name, says what was gated.
        if new in taken:
            base, n = re.fullmatch(r"(.*-\d{4}-\d{2}-\d{2})(?:-(\d+))?\.md", new).groups()
            i = int(n or 1) + 1
            while f"{base}-{i}.md" in taken:
                i += 1
            new = f"{base}-{i}.md"
        taken.add(new)
        rows.append((new, [f]))
        folders.add(top + rel.split("/")[0] + "/")
    return rows, folders


def log_head(root: Path) -> str:
    """The log's header, above its first section: where the versioning lines are."""
    return read_raw(root / LOG).split("\n## ", 1)[0] if (root / LOG).is_file() else ""


def swap_log_head(root: Path, here: Path) -> None:
    # A metarepo's trunk takes its log only by merge (M4): there the swap is listed for a job.
    if (root / META).exists():
        return
    text = read_raw(root / LOG)
    for was in (OLD_LOG_HEAD, RULES_MD_LOG_HEAD):
        if was in log_head(root):
            write_raw(root / LOG, text.replace(was, LOG_HEAD, 1))
            git("add", "--", LOG, check=True)
            return


# The first line of the .gitignore jig wrote in staging/ and inbox/, as it read before the
# rulebook became rulesets: rewritten where it is jig's text, word for word.
OLD_IGNORE_LINES = {
    f"{DIR}/staging/.gitignore": ("# Staged files are never committed: see Staging in .jig/RULES.md.",
                                  "# Staged files are never committed: see .jig/rules/rules-staging.md."),
    f"{DIR}/inbox/.gitignore": ("# Messages are never committed: see Inbox in .jig/RULES.md.",
                                "# Messages are never committed: see .jig/rules/rules-inbox.md."),
}


def old_ignore_lines(root: Path) -> list[str]:
    return [f for f, (old, _) in OLD_IGNORE_LINES.items()
            if (root / f).is_file() and old in read_raw(root / f).splitlines()]


def rewrite_ignore_lines(root: Path, here: Path) -> None:
    for f in old_ignore_lines(root):
        old, new = OLD_IGNORE_LINES[f]
        write_raw(root / f, read_raw(root / f).replace(old, new, 1))
        git("add", "--", f, check=True, cwd=str(root))


def up_next_heading(text: str) -> bool:
    """Whether TEXT has an `## Up next` heading outside fenced code, as fold_up_next reads it."""
    fence = False
    for l in text.splitlines():
        if l.lstrip().startswith("```"):
            fence = not fence
        elif not fence and re.fullmatch(rf"##\s+{UP_NEXT}\s*", l, re.I):
            return True
    return False


def trunk_stamp(root: Path) -> int | None:
    """The STAMP of trunk's committed jig.py, the copy the hook runs; None when trunk has none."""
    text = git("show", f"{Board.trunk_name(root)}:{DIR}/jig.py", cwd=str(root))
    if not text:
        return None
    m = re.search(r"^STAMP = (\d+)", text, re.M)
    return int(m.group(1)) if m else 0


def md_with_list(text: str, items: list[str]) -> str:
    """The old roadmap.md TEXT with ITEMS appended under ## No phase, which is added when it has
    none: the Up next fold's, before the conversion."""
    lines = text.splitlines()
    heads, fence = [], False
    for n, l in enumerate(lines):
        if l.lstrip().startswith("```"):
            fence = not fence
        elif not fence and re.match(r"##\s+(.+?)\s*$", l):
            heads.append(n)
    at = next((n for n in heads if lines[n][2:].strip().lower() == NO_PHASE.lower()), None)
    if at is None:
        return "\n".join(trimmed(lines) + ["", f"## {NO_PHASE}", *items]).lstrip("\n") + "\n"
    end = next((n for n in heads if n > at), len(lines))
    while end > at + 1 and not lines[end - 1].strip():
        end -= 1
    return "\n".join(lines[:end] + items + lines[end:]) + "\n"


def fold_up_next(text: str) -> str:
    """TEXT with every `## Up next` section's lines moved under `## No phase`, ids, text and
    nested lines kept, the heading gone: the one list for work with no phase."""
    lines = text.splitlines()
    heads, fence = [], False
    for n, l in enumerate(lines):
        if l.lstrip().startswith("```"):
            fence = not fence
        elif not fence and re.match(r"##\s+(.+?)\s*$", l):
            heads.append(n)
    moved, keep, at = [], [], None
    for n, l in enumerate(lines):
        if n in heads:
            at = n if l[2:].strip().lower() == UP_NEXT.lower() else None
            if at is not None:
                continue
        (moved if at is not None else keep).append(l)
    items = trimmed(moved)
    return md_with_list("\n".join(keep), items) if items else "\n".join(trimmed(keep)) + "\n"


# The Commands line any agent reads to answer "show me the roadmap": update adds it where an
# AGENTS.md has a Commands list and no roadmap line.
ROADMAP_COMMAND = ("- roadmap: `python3 .jig/jig.py roadmap show` (the roadmap as a chart; run it "
                   "when asked to show the roadmap)")


def lacks_roadmap_command(root: Path, meta: bool = False) -> bool:
    """META: answer for a metarepo, whose AGENTS.md changes only in a job (M4): update lists
    the line there instead of adding it."""
    if (root / META).exists() != meta:
        return False
    f = root / "AGENTS.md"
    if not f.is_file():
        return False
    text = f.read_text(errors="replace")
    return bool(re.search(r"(?m)^## Commands[ \t]*$", text)) and not re.search(r"(?m)^- roadmap:", text)


def add_roadmap_command(root: Path, here: Path) -> None:
    """ROADMAP_COMMAND after the last item of AGENTS.md's Commands list; every other byte kept."""
    path = root / "AGENTS.md"
    lines = read_raw(path).splitlines(keepends=True)
    at = next(i for i, l in enumerate(lines) if re.fullmatch(r"## Commands[ \t]*\r?\n?", l))
    end = next((i for i in range(at + 1, len(lines)) if lines[i].startswith("#")), len(lines))
    last = max((i for i in range(at + 1, end) if lines[i].startswith("- ")), default=at)
    eol = "\r\n" if lines[last].endswith("\r\n") else "\n"
    if not lines[last].endswith(("\n", "\r")):
        lines[last] += eol
    lines.insert(last + 1, ROADMAP_COMMAND + eol)
    write_raw(path, "".join(lines))
    git("add", "--", "AGENTS.md", check=True)


def knows_roadmap_json(root: Path) -> bool:
    """Whether trunk's committed checker reads roadmap.json: an older one refuses the commit
    removing roadmap.md, so the conversion waits for the commit installing this one."""
    return (trunk_stamp(root) or 0) >= ROADMAP_JSON_STAMP


OPEN_HEADING = re.compile(r"^##[ \t]+Open[ \t]*$", re.I)


def fold_open(log: str, ideas: str) -> tuple[str, str]:
    """LOG with its `## Open` sections gone, and IDEAS with what they held appended, entry
    blocks byte for byte: the log keeps only decisions."""
    lines = log.split("\n")
    moved, keep, inside, cuts = [], [], False, []
    for l in lines:
        if l.startswith("## ") or l.startswith("##\t"):
            inside = bool(OPEN_HEADING.match(l.rstrip("\r")))
            if inside:
                cuts.append(len(keep))
                # A second ## Open's blocks follow the first's after one blank line.
                if trimmed(moved):
                    moved = trimmed(moved) + [""]
                continue
        (moved if inside else keep).append(l)
    body = "\n".join(trimmed(moved))
    ideas = ideas or IDEAS_SEED
    if body.strip():
        ideas = ideas.rstrip("\r\n") + "\n\n" + body + "\n"
    # Where a section left, the blank lines on either side become one; the rest stays as written.
    for c in reversed(cuts):
        a = c
        while a > 0 and not keep[a - 1].strip():
            a -= 1
        b = c
        while b < len(keep) and not keep[b].strip():
            b += 1
        # One blank line between what was before and after; at the end, the final newline.
        keep[a:b] = [""] if 0 < a and b < len(keep) else [""] if b == len(keep) and a > 0 else []
    return "\n".join(keep), ideas


def has_open(root: Path) -> bool:
    return (root / LOG).is_file() and any(OPEN_HEADING.match(l.rstrip("\r"))
                                          for l in read_raw(root / LOG).split("\n"))


def fold_ideas(root: Path, here: Path | None = None) -> list[str]:
    """Move the log's `## Open` entries into the ideas file, and stage both. The ids moved."""
    log, ideas = read_raw(root / LOG), read_raw(root / IDEAS) if (root / IDEAS).is_file() else ""
    prefix = log_prefix_of(log)
    ids = [e["id"] for e in log_entries(log, prefix) if e["section"] == "Open"]
    new_log, new_ideas = fold_open(log, ideas)
    write_raw(root / LOG, new_log)
    write_raw(root / IDEAS, new_ideas)
    git("add", "--", LOG, IDEAS, check=True)
    return ids


def cmd_fold_ideas(root: Path, apply: bool) -> int:
    """`jig update --fold-ideas`: the fold where `jig update --apply` can't make it, a metarepo,
    whose log changes only in a job (M4). Run in that job's worktree, or on trunk elsewhere."""
    if not has_open(root):
        print(f"{LOG} has no ## Open: nothing to fold")
        return 0
    trunk = Board.trunk_name(root)
    prefix = log_prefix_of(read_raw(root / LOG))
    ids = [e["id"] for e in log_entries(read_raw(root / LOG), prefix) if e["section"] == "Open"]
    print(f"Folding {LOG}'s ## Open into {IDEAS}: " + (", ".join(ids) or "no entries") + ", ids and blocks kept.")
    if not apply:
        print("Dry run: nothing changed. Run it again with --apply.")
        return 0
    if (root / META).exists() and git("branch", "--show-current") == trunk:
        die(f"in a metarepo the fold is a change to its log (M4): open a job sharing {LOG} and {IDEAS}, "
            f"run `jig update --apply --fold-ideas` in its worktree, and merge it", 2)
    fold_ideas(root)
    print(f"Staged {LOG} and {IDEAS}, nothing committed: commit them.")
    return 0


def later_lines(root: Path) -> list[tuple[str, str]]:
    """(spec, what its `Later:` line names) for each spec in ROOT carrying the retired line."""
    out = []
    for p in sorted((root / SPECS).glob("*.md")):
        f = p.relative_to(root).as_posix()
        if is_spec(f) and (m := later_line(read_raw(p))):
            out.append((f, m.group(0).removeprefix("Later:").strip() or "empty"))
    return out


def drop_later_lines(root: Path, here: Path) -> None:
    for f, _ in later_lines(root):
        text = read_raw(root / f)
        m = later_line(text)
        write_raw(root / f, text[:m.start()] + text[m.end():])
        git("add", "--", f, check=True, cwd=str(root))


def own_name(root: Path) -> str:
    """The name ROOT's repo goes by in its own records: its META's `name` in a metarepo, else its
    board's, else its folder's."""
    for f in (META, CONFIG):
        try:
            if (root / f).is_file() and (n := json.loads(read_raw(root / f) or "{}").get("name")):
                return n
        except (ValueError, AttributeError):
            pass
    return root.name


OWNER_FIELD = re.compile(r"^Owner:[ \t]*(.*?)[ \t]*$", re.M)


def owner_rewrites(root: Path) -> list[tuple[str, str]]:
    """(heading, repo) for each glossary heading carrying the `Owner:` line `Repo:` replaced:
    the repo its first backticks name, `this repo` as ROOT's own name."""
    text = read_raw(root / GLOSSARY) if (root / GLOSSARY).is_file() else ""
    out = []
    for e in glossary_entries(text):
        if "Owner" not in e["fields"]:
            continue
        v = e["fields"]["Owner"]
        named = re.search(r"`([^`]+)`", v)
        repo = named.group(1).strip() if named else own_name(root) if v.lower().startswith("this repo") else \
            v.rstrip(".").strip()
        out.append((e["name"], repo))
    return out


def rewrite_owners(root: Path, here: Path) -> None:
    """Each `Owner:` line as `Repo:`, plus `Kind: software` where its repo builds one product;
    where two products name one repo, `Repo:` on both and `Kind:` on neither, for the owner."""
    write_raw(root / GLOSSARY, owners_rewritten(root))
    git("add", "--", GLOSSARY, check=True, cwd=str(root))


def owners_rewritten(root: Path) -> str:
    """ROOT's glossary with rewrite_owners' rewrite made, written nowhere: what update's report
    of a glossary out of the form judges, so it names no problem the rewrite won't leave."""
    pairs = owner_rewrites(root)
    count = Counter(r.casefold() for _, r in pairs)
    lines = read_raw(root / GLOSSARY).splitlines(keepends=True)
    entries = {e["name"]: e for e in glossary_entries("".join(lines))}
    for name, repo in reversed(pairs):
        e = entries[name]
        for j in range(e["start"] + 1, e["end"]):
            if OWNER_FIELD.match(lines[j].strip()):
                end = "\r\n" if lines[j].endswith("\r\n") else "\n"
                lines[j] = f"Repo: {repo}{end}" + (f"Kind: software{end}" if count[repo.casefold()] == 1 else "")
                break
    return "".join(lines)


def owner_step_label(root: Path) -> str:
    pairs = owner_rewrites(root)
    count = Counter(r.casefold() for _, r in pairs)
    shared = sorted({r for _, r in pairs if count[r.casefold()] > 1})
    return (f"rewrite each `Owner:` line in {GLOSSARY} as `Repo:` and `Kind: software`: "
            + ", ".join(f"{n} → Repo: {r}" for n, r in pairs)
            + (f". {', '.join(shared)} names more than one product, so those get `Repo:` and no `Kind:`: "
               "the owner marks one `Kind: software` and the other `Kind: hardware`" if shared else ""))


def glossary_titled(text: str) -> str:
    """TEXT, a glossary, with the title written above its first heading where that is `# Basic
    terms`, 0.17.0's form, no other line changed; any other comes back as it is."""
    first = next(iter(glossary_entries(text)), None)
    if first is None or first["level"] != 1 or first["name"] != BASIC_TERMS:
        return text
    lines = text.splitlines(keepends=True)
    end = "\r\n" if lines[first["start"]].endswith("\r\n") else "\n"
    lines.insert(first["start"], f"# {GLOSSARY_TITLE}{end}{end}")
    return "".join(lines)


def lacks_glossary_title(root: Path) -> bool:
    if not (root / GLOSSARY).is_file():
        return False
    text = read_raw(root / GLOSSARY)
    return glossary_titled(text) != text


def knows_glossary_title(root: Path) -> bool:
    """Whether trunk's committed checker takes the glossary's title: an older one refuses the
    commit adding it, so the step waits for the commit installing this one."""
    return (trunk_stamp(root) or 0) >= GLOSSARY_TITLE_STAMP


def add_glossary_title(root: Path, here: Path) -> None:
    write_raw(root / GLOSSARY, glossary_titled(read_raw(root / GLOSSARY)))
    git("add", "--", GLOSSARY, check=True, cwd=str(root))


TITLE_STEP = (f"add the `# {GLOSSARY_TITLE}` heading to {GLOSSARY}, above `# {BASIC_TERMS}`: the glossary form's "
              "first heading; no other line changes")
# How trunk's update lists a metarepo's glossary change, which M4 keeps off trunk.
GLOSSARY_BY_JOB = (f"in a metarepo a job's (M4). Once this update is committed, open one sharing {GLOSSARY} and "
                   f"{LOG}, run `jig update --apply` in its worktree, and merge it with its changelog line")


def glossary_job_steps(root: Path) -> list[tuple]:
    """(label, action) for each glossary change `jig update` makes in a metarepo job's worktree,
    where M4 puts them; none anywhere else."""
    if not ((root / META).is_file() and (root / CONFIG).is_file()
            and Board.load(root).job_for_branch(git("branch", "--show-current"))[0]):
        return []
    steps = [(owner_step_label(root), rewrite_owners)] if owner_rewrites(root) else []
    if lacks_glossary_title(root) and knows_glossary_title(root):
        steps.append((TITLE_STEP, add_glossary_title))
    return steps


def cmd_glossary_job(root: Path, steps: list, apply: bool) -> int:
    """`jig update` in a metarepo job's worktree: the glossary's STEPS and nothing else, since the
    rest of an update is trunk's, which refuses to run while a job is open."""
    print("This metarepo job's glossary changes (M4):")
    for label, _ in steps:
        print(f"  {label}")
    if not apply:
        print("\nDry run: nothing changed. Run again with --apply.")
        return 0
    if git("status", "--porcelain", "--untracked-files=no"):
        die("commit or stash tracked changes first: update edits files by name", 2)
    for _, act in steps:
        act(root, Path(__file__).resolve().parent)
    print(f"\nStaged {GLOSSARY}, nothing committed: commit it here, its subject starting `GLOSSARY:`, "
          f"with a line under ## Unreleased in {LOG}.")
    return 0


def glossary_out_of_form(root: Path) -> list[str]:
    """The problems ROOT's glossary has in the one form once update's rewrite and title are made:
    reported, never re-formed, since its rebuild is the owner's."""
    if not (root / GLOSSARY).is_file():
        return []
    return [p for _, p in glossary_problems(glossary_titled(owners_rewritten(root)), (root / META).exists())]


def template_sources(root: Path, here: Path) -> dict[str, "Path | bytes"]:
    """{path under TEMPLATES: its source} for every template that applies to ROOT's kind: the
    prose ones from HERE's templates/ folder, the JSON records' one example from
    ROADMAP_RECORDS, and the buffer ledger's in a pararepo alone."""
    out: dict[str, Path | bytes] = {f"{TEMPLATES}/{n}": here / "templates" / n for n in TEMPLATE_FILES
                                    if (here / "templates" / n).is_file()}
    out |= {f"{TEMPLATES}/{n}": roadmap_dumps(ROADMAP_RECORDS[k]).encode() for n, k in JSON_TEMPLATES.items()}
    out[f"{TEMPLATES}/handoff.md"] = NOTE.format(
        job="<job>", head="<the commit it hands off>", today="<YYYY-MM-DD>", spec=f"{DIR}/specs/<task>.md",
        partial="", ran="", foldin="- [ ] <page> — updated / no change because ___").encode()
    if (root / PARA).is_file():
        out[f"{TEMPLATES}/buffer.md"] = BUFFER_TEMPLATE.encode()
    return out


def rules_stash(root: Path) -> Path:
    """Where this clone keeps the family rulesets its tree doesn't hold: inside .git/, so a
    regular repo carries none, while a later `jig init --meta` or `--para`, run from the repo's
    own copy of jig, still has the text to write."""
    common = git("rev-parse", "--path-format=absolute", "--git-common-dir", cwd=str(root))
    return Path(common or root / ".git") / "jig" / "rules"


def rules_sources(root: Path, here: Path) -> dict[str, Path]:
    """{path under RULES_DIR: its source} for every ruleset ROOT's kind follows: all of them,
    but a metarepo's only beside meta.json and a pararepo's beside para.json. The source is
    HERE's rules/ folder, or for a family ruleset it lacks, the clone's stash."""
    out = {}
    for n in RULE_FILES:
        if n in KIND_RULES and not (root / KIND_RULES[n]).is_file():
            continue
        src = here / "rules" / n
        if n in KIND_RULES and not src.is_file() and (rules_stash(root) / n).is_file():
            src = rules_stash(root) / n
        out[f"{RULES_DIR}/{n}"] = src
    return out


def stash_family_rules(root: Path, here: Path) -> None:
    """Keep HERE's family rulesets in the clone's stash, for a kind the repo may become."""
    for n in KIND_RULES:
        if (here / "rules" / n).is_file():
            rules_stash(root).mkdir(parents=True, exist_ok=True)
            shutil.copyfile(here / "rules" / n, rules_stash(root) / n)


def write_rules(root: Path) -> None:
    """`jig init`'s share of the rulesets: the copied folder brings them, so this writes only one
    it lacks, and takes out of the tree the family ruleset of a kind the repo isn't, kept in the
    stash. Run after `--meta` or `--para` has written its file, so the kind is known."""
    here = Path(__file__).resolve().parent
    stash_family_rules(root, here)
    for dest, src in rules_sources(root, here).items():
        if (root / dest).exists():
            continue
        if src.is_file():
            (root / dest).parent.mkdir(parents=True, exist_ok=True)
            # Quietly: it is jig's own folder, and init's last line is what to commit.
            shutil.copyfile(src, root / dest)
        else:
            print(f"{dest} not written: no copy beside this jig.py or in this clone; `jig update --apply`, "
                  "run from the plugin's jig.py, writes it")
    for name, kind in KIND_RULES.items():
        if not (root / kind).is_file():
            (root / RULES_DIR / name).unlink(missing_ok=True)


def blob_of(src: "Path | bytes") -> bytes:
    return src if isinstance(src, bytes) else src.read_bytes()


def write_templates(root: Path) -> None:
    """`jig init`'s share of the templates: those its copy of jig builds (the copied folder
    brings the rest), and none of a kind the repo isn't."""
    here = Path(__file__).resolve().parent
    for dest, src in template_sources(root, here).items():
        if not (root / dest).exists() or not isinstance(src, Path):
            (root / dest).parent.mkdir(parents=True, exist_ok=True)
            (root / dest).write_bytes(blob_of(src))
    if not (root / PARA).is_file():
        (root / TEMPLATES / "buffer.md").unlink(missing_ok=True)


OLD_LEDGER_NAMES = {f"{DIR}/ledgers/DEFERRED.md": DEFERRED, f"{DIR}/ledgers/WORKAROUNDS.md": WORKAROUNDS,
                    f"{DIR}/ledgers/BUFFER.md": BUFFER}


def ledger_header_stale(root: Path) -> bool:
    """The deferred ledger, at either name, still heads its second column `Lane / handoff`."""
    # Read where it is now: update's moves bring it here from an older layout first.
    return any((root / f).is_file() and "| Lane / handoff |" in read_raw(root / f)
               for f in (DEFERRED, f"{DIR}/ledgers/DEFERRED.md", "ledgers/DEFERRED.md",
                         "jig/ledgers/DEFERRED.md", ".aidev/ledgers/DEFERRED.md", "DEFERRED.md"))


def agents_old_ledgers(root: Path) -> bool:
    """AGENTS.md cites a ledger by its old capital name, in a repo whose trunk takes the edit:
    a metarepo's trunk takes none outside jig's folder (M4), so there it is a job's."""
    return (not (root / META).exists() and (root / "AGENTS.md").is_file()
            and any(o in read_raw(root / "AGENTS.md") for o in OLD_LEDGER_NAMES))


def rename_ledger_cites(root: Path, here: Path) -> None:
    """The ledgers' new names where jig wrote the old: the deferred ledger's header cell, and
    AGENTS.md's lines citing a ledger by path. No row changes."""
    if (root / DEFERRED).is_file():
        text = read_raw(root / DEFERRED)
        write_raw(root / DEFERRED, text.replace("| Lane / handoff |", "| Job / handoff |", 1))
        git("add", "--", DEFERRED, check=True, cwd=str(root))
    if agents_old_ledgers(root):
        text = read_raw(root / "AGENTS.md")
        for o, n in OLD_LEDGER_NAMES.items():
            text = text.replace(o, n)
        write_raw(root / "AGENTS.md", text)
        git("add", "--", "AGENTS.md", check=True, cwd=str(root))


